    async fn worker_session(
        &self,
        workspace_id: String,
        runtime_id: String,
        worker_id: String,
    ) -> std::result::Result<server_api::WorkspaceWorkerSessionResponse, server_api::ServerApiError>
    {
        let api = self.workspace_api().map_err(|_| {
            runtime_api::RuntimeApiError::new(
                StatusCode::NOT_FOUND.as_u16(),
                "workspace_not_found",
                "Workspace was not found",
            )
        })?;
        if workspace_id != api.config.workspace_id {
            return Err(runtime_api::RuntimeApiError::new(
                StatusCode::NOT_FOUND.as_u16(),
                "workspace_not_found",
                "Workspace was not found",
            ));
        }
        let worker = RuntimeWorkerRef::new(runtime_id.clone(), worker_id.clone());
        let operation_api = api.clone();
        let operation_workspace = workspace_id.clone();
        let runtime_result = api
            .host_executors
            .host()
            .map_err(runtime_execution_error)?
            .run(move || {
                Ok::<_, Error>(
                    operation_api
                        .runtime
                        .worker_session(&operation_workspace, &worker),
                )
            })
            .await
            .map_err(runtime_execution_error)?;
        let observation = runtime_result.map_err(|_error| {
            runtime_api::RuntimeApiError::new(
                StatusCode::BAD_GATEWAY.as_u16(),
                "worker_session_observation_failed",
                "Worker Session observation failed",
            )
        })?;
        Ok(server_api::WorkspaceWorkerSessionResponse {
            subject: server_api::WorkspaceWorkerSubject::RuntimeWorker {
                runtime_id,
                worker_id,
            },
            observation,
        })
    }

    async fn worker_session_history(
        &self,
        workspace_id: String,
        runtime_id: String,
        worker_id: String,
        query: server_api::WorkspaceWorkerSessionHistoryQuery,
    ) -> std::result::Result<
        server_api::WorkspaceWorkerSessionHistoryResponse,
        server_api::ServerApiError,
    > {
        let api = self.workspace_api().map_err(|_| {
            runtime_api::RuntimeApiError::new(
                StatusCode::NOT_FOUND.as_u16(),
                "workspace_not_found",
                "Workspace was not found",
            )
        })?;
        if workspace_id != api.config.workspace_id {
            return Err(runtime_api::RuntimeApiError::new(
                StatusCode::NOT_FOUND.as_u16(),
                "workspace_not_found",
                "Workspace was not found",
            ));
        }
        let worker = RuntimeWorkerRef::new(runtime_id.clone(), worker_id.clone());
        let operation_api = api.clone();
        let operation_workspace = workspace_id.clone();
        let runtime_result = api
            .host_executors
            .host()
            .map_err(runtime_execution_error)?
            .run(move || {
                Ok::<_, Error>(operation_api.runtime.worker_session_history(
                    &operation_workspace,
                    &worker,
                    query.cursor,
                    query.limit,
                ))
            })
            .await
            .map_err(runtime_execution_error)?;
        let observation = runtime_result.map_err(|_error| {
            runtime_api::RuntimeApiError::new(
                StatusCode::BAD_GATEWAY.as_u16(),
                "worker_session_history_failed",
                "Worker Session history request failed",
            )
        })?;
        Ok(server_api::WorkspaceWorkerSessionHistoryResponse {
            subject: server_api::WorkspaceWorkerSubject::RuntimeWorker {
                runtime_id,
                worker_id,
            },
            observation,
        })
    }

