    async fn ticket_assignment_answer(
        &self,
        context: server_api::ServerRequestContext,
        workspace_id: String,
        ticket_id: String,
        request: server_api::TicketAssignmentAnswerRequest,
    ) -> std::result::Result<
        server_api::TicketAssignmentAnswerResponse,
        server_api::RepositoryApiError,
    > {
        let api = self.workspace_api()?.clone();
        // Mixed live Runtime discovery, whole answer transaction, and committed-input
        // dispatch share one accepted finite Host owner, including waiter cancellation.
        // Neither Runtime I/O nor its completion waits on the sole DB worker.
        api.host_executors
            .host()?
            .run(move || {
                validate_workspace_scope(&api, &workspace_id)
                    .map_err(ApiError::from)
                    .map_err(ApiError::into_repository_api_error)?;
                let ticket_id = resolve_workspace_ticket_reference(&api, &workspace_id, &ticket_id)
                    .map_err(ApiError::from)
                    .map_err(ApiError::into_repository_api_error)?;
                let (actor, source) = authenticated_assignment_source(
                    &api,
                    &contract_request_headers(&context)?,
                    &context,
                )
                .map_err(ApiError::from)
                .map_err(ApiError::into_repository_api_error)?;
                let receipt = api
                    .store
                    .answer_ticket_assignment(
                        &workspace_id,
                        &ticket_id,
                        &request.0,
                        &source,
                        &actor,
                    )
                    .map_err(ApiError::from)
                    .map_err(ApiError::into_repository_api_error)?;
                // The entire event/audit/receipt transaction has committed. Response loss
                // retries the saved receipt; delivery scan deduplicates accepted inputs.
                recover_ticket_notifications(&api);
                Ok(server_api::TicketAssignmentAnswerResponse(receipt))
            })
            .await
    }
    async fn ticket_assignment_answer_browser(
        &self,
        context: server_api::ServerRequestContext,
        workspace_id: String,
        ticket_id: String,
        request: server_api::TicketAssignmentAnswerRequest,
    ) -> std::result::Result<
        server_api::TicketAssignmentAnswerResponse,
        server_api::RepositoryApiError,
    > {
        self.ticket_assignment_answer(context, workspace_id, ticket_id, request)
            .await
    }

    async fn ticket_implementation_result(
        &self,
        context: server_api::ServerRequestContext,
        workspace_id: String,
        ticket_id: String,
        request: server_api::TicketImplementationResultRequest,
    ) -> std::result::Result<
        server_api::TicketImplementationResultReceipt,
        server_api::RepositoryApiError,
    > {
        let api = self.workspace_api()?.clone();
        api.host_executors
            .host()?
            .run(move || {
                let result = (|| -> ApiResult<_> {
                    validate_workspace_scope(&api, &workspace_id)?;
                    let ticket =
                        resolve_workspace_ticket_reference(&api, &workspace_id, &ticket_id)?;
                    let source = context.runtime_source.as_ref().ok_or_else(|| {
                        Error::WorkspacePermissionDenied(
                            "Implementation results require an authenticated Runtime Worker".into(),
                        )
                    })?;
                    let worker = RuntimeWorkerRef::new(
                        &source.runtime_id,
                        source.worker_id.as_ref().ok_or_else(|| {
                            Error::WorkspacePermissionDenied(
                                "Implementation results require Worker identity".into(),
                            )
                        })?,
                    );
                    let receipt = api.config_store.record_implementation_result(
                        &workspace_id,
                        &ticket,
                        &request,
                        &worker,
                        &source.authentication_binding_id,
                    )?;
                    recover_ticket_notifications(&api);
                    Ok(receipt)
                })();
                result
                    .map_err(ApiError::from)
                    .map_err(ApiError::into_repository_api_error)
            })
            .await
    }

