fn runtime_execution_error(error: Error) -> runtime_api::RuntimeApiError {
    let code = match &error {
        Error::DbCapacityExceeded => "db_capacity_exceeded",
        Error::DbExecutorUnavailable => "db_executor_unavailable",
        Error::DbOperationOutcomeUnknown => "db_operation_outcome_unknown",
        _ => "backend_execution_failed",
    };
    runtime_api::RuntimeApiError::new(api_error_status(&error).as_u16(), code, error.to_string())
}

async fn scoped_worker_session_attachment(
    State(api): State<WorkspaceApi>,
    AxumPath((workspace_id, runtime_id, worker_id, session_id, attachment_id)): AxumPath<(
        String,
        String,
        String,
        String,
        String,
    )>,
    Extension(_actor): Extension<RequestActor>,
) -> Response {
    if workspace_id != api.config.workspace_id {
        return (
            StatusCode::NOT_FOUND,
            Json(serde_json::json!({"code": "workspace_not_found"})),
        )
            .into_response();
    }
    let worker = RuntimeWorkerRef::new(runtime_id, worker_id);
    let executor = match api.host_executors.host() {
        Ok(value) => value,
        Err(error) => return ApiError::from(error).into_response(),
    };
    let fetched = executor
        .run(move || {
            Ok::<_, Error>(api.runtime.worker_session_attachment(
                &workspace_id,
                &worker,
                &session_id,
                &attachment_id,
            ))
        })
        .await;
    let fetched = match fetched {
        Ok(value) => value,
        Err(error) => return ApiError::from(error).into_response(),
    };
    match fetched {
        Ok(attachment) => {
            let Ok(content_type) = HeaderValue::from_str(&attachment.media_type) else {
                return (
                    StatusCode::SERVICE_UNAVAILABLE,
                    Json(serde_json::json!({"code": "session_attachment_media_type_invalid"})),
                )
                    .into_response();
            };
            (
                [
                    (CONTENT_TYPE, content_type),
                    (
                        CACHE_CONTROL,
                        HeaderValue::from_static("private, max-age=3600"),
                    ),
                ],
                attachment.data,
            )
                .into_response()
        }
        Err(crate::hosts::RuntimeRegistryError::RuntimeOperationFailed {
            code, message, ..
        }) => {
            let status = match code.as_str() {
                "session_attachment_expired" => StatusCode::GONE,
                "session_attachment_not_found" => StatusCode::NOT_FOUND,
                "session_attachment_too_large" => StatusCode::PAYLOAD_TOO_LARGE,
                _ => StatusCode::BAD_GATEWAY,
            };
            (
                status,
                Json(serde_json::json!({"code": code, "message": message})),
            )
                .into_response()
        }
        Err(_) => (
            StatusCode::NOT_FOUND,
            Json(serde_json::json!({"code": "session_attachment_not_found"})),
        )
            .into_response(),
    }
}

fn build_inner_router(api: WorkspaceApi) -> Router {
    let contract_service = ServerApiContractService::Workspace(api.clone());
    let auth = generated_auth_contract_router(contract_service.clone());
    let workspace = Router::new();
    let workspace = server_api::server_support::websocket_route::<
        server_api::server_api_operations::ExternalWorkdirProviderWebSocket,
        _,
        _,
        _,
    >(workspace, scoped_external_workdir_provider_ws);
    let workspace = server_api::server_support::websocket_route::<
        server_api::server_api_operations::WorkspaceProtocolWebSocket,
        _,
        _,
        _,
    >(workspace, scoped_workspace_protocol_ws);
    let workspace = server_api::server_support::websocket_route::<
        server_api::server_api_operations::WorkerProtocolWebSocketAlias,
        _,
        _,
        _,
    >(workspace, worker_protocol_ws);
    let workspace = server_api::server_support::websocket_route::<
        server_api::server_api_operations::WorkspaceWorkerProtocolWebSocket,
        _,
        _,
        _,
    >(workspace, scoped_worker_protocol_ws)
    .route(
        "/api/w/{workspace_id}/runtimes/{runtime_id}/workers/{worker_id}/sessions/{session_id}/attachments/{attachment_id}",
        get(scoped_worker_session_attachment),
    )
    .route(
        "/api/w/{workspace_id}/workers/self/backend-job-result",
        post(scoped_submit_backend_job_result),
    )
    .route("/api/w/{workspace_id}/subjektiv/journal/release", post(subjektiv_journal::release_route))
    .route("/api/w/{workspace_id}/subjektiv/journal/compaction", post(subjektiv_journal::compaction_route))
    .route("/api/w/{workspace_id}/subjektiv/journal/startup", get(subjektiv_journal::startup_route))
    .route("/api/w/{workspace_id}/subjektiv/journal/recording", post(subjektiv_journal::recording_route))
    .route("/api/w/{workspace_id}/subjektiv/subjects/{subject_id}/journal-browser", post(subjektiv_journal_browser::route))
    .route("/api/w/{workspace_id}/subjektiv/journal/memory", post(subjektiv_memory_journal::route))
    .route("/api/w/{workspace_id}/subjektiv/journal/job", post(subjektiv_journal::job_route))
    .route("/api/w/{workspace_id}/subjektiv/journal/job/finish", post(subjektiv_journal::finish_route))
    .fallback(get(static_or_spa_fallback))
    .with_state(api)
    .merge(generated_workspace_contract_router(contract_service));
    auth.merge(workspace)
        .layer(middleware::from_fn(log_failed_api_response))
}

async fn log_failed_api_response(request: Request, next: Next) -> Response {
    let method = request.method().clone();
    let uri = request.uri().clone();
    let request_token_id_hash = request
        .extensions()
        .get::<crate::worker_source::VerifiedRuntimeRequestSource>()
        .and_then(|source| source.token_id_hash.clone());
    let response = next.run(request).await;
    let status = response.status();

    let is_api = uri.path().starts_with("/api/")
        || canonical_ticket_operation_workspace_id(uri.path()).is_some();
    if is_api && (status.is_client_error() || status.is_server_error()) {
        // Generated routes bypass ApiError::into_response; inspect their typed error, not the body.
        let generated_error = response
            .extensions()
            .get::<Arc<server_api::RepositoryApiError>>()
            .map(|error| ApiErrorLog::from_repository_error(error))
            .or_else(|| {
                response
                    .extensions()
                    .get::<Arc<server_api::WorkdirOperationApiError>>()
                    .map(|error| ApiErrorLog::from_workdir_operation_error(error, status))
            });
        let error = response
            .extensions()
            .get::<ApiErrorLog>()
            .or(generated_error.as_ref());
        let event = api_failure_log_event(&method, &uri, status, error);
        let context = error.and_then(|error| error.workdir_log.as_ref());
        let workdir_path = context.map(|_| bounded_auth_log_value(uri.path(), 512));
        let workdir_method = context.map(|_| bounded_auth_log_value(method.as_str(), 32));
        tracing::error!(
            target: "yoi::api",
            event = event.event,
            method = workdir_method.as_deref().unwrap_or(event.method),
            path = workdir_path.as_deref().unwrap_or(event.path),
            operation = context.map(|ctx| ctx.operation),
            workdir_stage = context.map(|ctx| ctx.stage),
            workspace_id_hash = context.map(|ctx| ctx.workspace_id_hash.as_str()),
            runtime_id_hash = context.and_then(|ctx| ctx.runtime_id_hash.as_deref()),
            worker_id_hash = context.and_then(|ctx| ctx.worker_id_hash.as_deref()),
            workdir_id_hash = context.and_then(|ctx| ctx.workdir_id_hash.as_deref()),
            attachment_alias_hash = context.map(|ctx| ctx.attachment_alias_hash.as_str()),
            request_token_id_hash = context.and(request_token_id_hash.as_deref()),
            denial_reason = error.and_then(|error| error.denial_reason).map(|reason| reason.as_str()),
            failure_reason = error.and_then(|error| error.failure_reason).map(|reason| reason.as_str()),
            failure_stage = error.and_then(|error| error.failure_reason).map(|reason| reason.stage().as_str()),
            status = event.status,
            kind = event.kind.unwrap_or("unknown"),
            message = event.message.unwrap_or(""),
            diagnostics = ?event.diagnostics.unwrap_or_default(),
        );
    }

    response
}

fn api_failure_log_event<'a>(
    method: &'a Method,
    uri: &'a Uri,
    status: StatusCode,
    error: Option<&'a ApiErrorLog>,
) -> ApiFailureLogEvent<'a> {
    ApiFailureLogEvent {
        event: "api_error",
        method: method.as_str(),
        path: uri.path(),
        status: status.as_u16(),
        kind: error.map(|error| error.kind.as_str()),
        message: error.map(|error| error.message.as_str()),
        diagnostics: error.map(|error| error.diagnostics.as_slice()),
    }
}

#[cfg(test)]
fn failed_api_log_json(
    method: &Method,
    uri: &Uri,
    status: StatusCode,
    error: Option<&ApiErrorLog>,
) -> String {
    let event = api_failure_log_event(method, uri, status, error);
    serde_json::to_string(&event).unwrap_or_else(|serialization_error| {
        format!(
            "{{\"event\":\"api_error\",\"status\":{},\"log_serialization_error\":{:?}}}",
            status.as_u16(),
            serialization_error.to_string()
        )
    })
}

#[derive(Serialize)]
struct ApiFailureLogEvent<'a> {
    event: &'static str,
    method: &'a str,
    path: &'a str,
    status: u16,
    #[serde(skip_serializing_if = "Option::is_none")]
    kind: Option<&'a str>,
    #[serde(skip_serializing_if = "Option::is_none")]
    message: Option<&'a str>,
    #[serde(skip_serializing_if = "Option::is_none")]
    diagnostics: Option<&'a [RuntimeDiagnostic]>,
}

pub async fn serve_workspace_catalog_with_shutdown<F>(
    template: ServerConfig,
    store: Arc<dyn ControlPlaneStore>,
    listener: TcpListener,
    shutdown: F,
) -> Result<()>
where
    F: std::future::Future<Output = ()> + Send + 'static,
{
    let api = WorkspaceServerApi::new(template, store);
    api.preload().await?;
    api.recover_workspace_deletions().await?;
    let result = axum::serve(listener, workspace_server_router(api.clone()))
        .with_graceful_shutdown(shutdown)
        .await;
    let storage_result = api.shutdown_feature_storage().await;
    result?;
    storage_result?;
    Ok(())
}

pub async fn serve_workspace_catalog(
    template: ServerConfig,
    store: Arc<dyn ControlPlaneStore>,
    listener: TcpListener,
) -> Result<()> {
    let api = WorkspaceServerApi::new(template, store);
    api.preload().await?;
    api.recover_workspace_deletions().await?;
    let result = axum::serve(listener, workspace_server_router(api.clone())).await;
    let storage_result = api.shutdown_feature_storage().await;
    result?;
    storage_result?;
    Ok(())
}

pub fn build_router(api: WorkspaceApi) -> Router {
    build_inner_router(api.clone()).layer(axum::middleware::from_fn_with_state(
        api,
        authorize_workspace_api_request,
    ))
}

pub async fn serve(
    config: ServerConfig,
    store: Arc<dyn ControlPlaneStore>,
    listener: TcpListener,
) -> Result<()> {
    let api = WorkspaceApi::new(config, store).await?;
    let orchestrator_hook = tokio::spawn(run_orchestrator_turn_end_hook(api.clone()));
    let result = axum::serve(listener, build_router(api.clone())).await;
    orchestrator_hook.abort();
    let _ = orchestrator_hook.await;
    let storage_result = shutdown_workspace_feature_storage(&api).await;
    result?;
    storage_result?;
    Ok(())
}

// Feature shutdown fences new operations and waits for synchronous connection
// holders. Accepted close retains ownership after its async waiter disappears.
async fn shutdown_workspace_feature_storage(api: &WorkspaceApi) -> Result<()> {
    // Aborting the async hook cannot cancel an already admitted Host closure.
    // Fence all delivery entry points and wait for their actual I/O owners first.
    api.notification_delivery_lifecycle.stop_and_drain().await;
    api.worker_projection.shutdown_async().await;
    let storage = api.feature_storage.clone();
    api.store
        .db_executor()
        .run(move || {
            storage.shutdown().map_err(|error| {
                Error::Store(format!("failed to shut down Feature storage: {error}"))
            })
        })
        .await
}

