    validate_workspace_scope(&api, &path.workspace_id)?;
    let workspace = api
        .store
        .get_workspace(&path.workspace_id)
        .await?
        .ok_or_else(|| Error::InvalidRecordId(path.workspace_id))?;
    Ok(Json(crate::profile_settings::workspace_metadata_settings(
        &workspace,
    )))
