async fn apply_clear_ticket_assignment(
    State(api): State<WorkspaceApi>,
    AxumPath((workspace_id, id, role)): AxumPath<(String, String, String)>,
    Query(query): Query<server_api::ClearTicketRoleAssignmentQuery>,
    author: String,
    source: Option<crate::store::TicketOrchestratorAssignmentSourceContext>,
) -> ApiResult<Json<server_api::TicketRoleAssignmentMutationResponse>> {
    api.host_executors
        .host()?
        .run(move || {
            validate_workspace_scope(&api, &workspace_id)?;
            let ticket = api.authority.ticket(&id)?;
            let role = parse_ticket_assignment_role(&role)?;
            let operation_id = query
                .operation_id
                .map(|value| require_ticket_assignment_value("operation_id", value))
                .transpose()?
                .ok_or_else(|| {
                    Error::TicketAssignmentConflict("unassign requires operation_id".to_string())
                })?;
            let assignment_id = query
                .assignment_id
                .map(|value| require_ticket_assignment_value("assignment_id", value))
                .transpose()?
                .ok_or_else(|| {
                    Error::TicketAssignmentConflict("unassign requires assignment_id".to_string())
                })?;
            let event_id = new_id("tasev");
            let occurred_at = Utc::now().to_rfc3339_opts(SecondsFormat::Secs, true);
            let reason = Some("role assignment removed from Ticket detail");
            let cleared = if role == TicketAssignmentRole::Orchestrator
                && let Some(source) = source.as_ref()
            {
                api.store.clear_current_ticket_orchestrator_assignment(
                    &workspace_id,
                    &ticket.id,
                    &assignment_id,
                    &event_id,
                    &operation_id,
                    &author,
                    &occurred_at,
                    reason,
                    source,
                )?
            } else {
                api.store.clear_current_ticket_role_assignment(
                    &workspace_id,
                    &ticket.id,
                    role,
                    &assignment_id,
                    &event_id,
                    &operation_id,
                    &author,
                    &occurred_at,
                    reason,
                )?
            };
            if !cleared {
                return Err(Error::TicketAssignmentConflict(format!(
                    "assignment `{assignment_id}` is not current for role `{}`",
                    role.as_str()
                ))
                .into());
            }
            Ok(Json(server_api::TicketRoleAssignmentMutationResponse {
                workspace_id,
                ticket_id: ticket.id,
                assignment: None,
            }))
        })
        .await
}

async fn scoped_cancel_ticket_implementation(
    State(api): State<WorkspaceApi>,
    AxumPath(path): AxumPath<ScopedRecordPath>,
    Json(request): Json<server_api::CancelTicketImplementationRequest>,
) -> ApiResult<Json<TicketDetail>> {
    validate_workspace_scope(&api, &path.workspace_id)?;
    // Runtime cancel and session cleanup are mixed work. One accepted Host
    // owner retains authority through the whole cancellation transaction/detail.
    run_host_workflow(api.host_executors.host()?, async move {
        let ticket = api.authority.ticket(&path.id)?;
        let operation_id = require_ticket_assignment_value("operation_id", request.operation_id)?;
        let assignment_id = require_ticket_assignment_value("assignment_id", request.assignment_id)?;
        let reason = require_ticket_assignment_value("reason", request.reason)?;
        if reason.len() > 512 {
            return Err(Error::InvalidInput(
                "implementation cancellation reason must be at most 512 bytes".to_string(),
            )
            .into());
        }

        let current = api.store.get_active_ticket_role_assignment(
            &path.workspace_id,
            &ticket.id,
            TicketAssignmentRole::Worker,
        )?;
        if let Some(assignment) = current.filter(|value| value.assignment_id == assignment_id)
            && let TicketAssignmentPrincipal::Worker {
                runtime_id,
                worker_id,
            } = assignment.principal
        {
            if api
                .store
                .get_ticket_assignment_operation(&path.workspace_id, &operation_id)?
                .is_some()
            {
                return Err(Error::TicketAssignmentConflict(format!(
                    "operation `{operation_id}` was already used for another Ticket assignment mutation"
                ))
                .into());
            }
            let worker = RuntimeWorkerRef::new(runtime_id, worker_id);
            cancel_ticket_worker(&api, &worker, &reason).await?;
        }

        let cancelled = api.store.cancel_current_ticket_worker_assignment(
            &path.workspace_id,
            &ticket.id,
            &assignment_id,
            &new_id("tasev"),
            &new_id("tev"),
            &operation_id,
            "workspace-web",
            &Utc::now().to_rfc3339_opts(SecondsFormat::Secs, true),
            &reason,
        )?;
        if !cancelled {
            return Err(Error::TicketAssignmentConflict(format!(
                "assignment `{assignment_id}` is not the current Coder implementation"
            ))
            .into());
        }
        browser_ticket_detail(&api, &ticket.id)
    })
    .await
}

async fn cancel_ticket_worker(
    api: &WorkspaceApi,
    worker: &RuntimeWorkerRef,
    reason: &str,
) -> ApiResult<()> {
    let session_lock = current_worker_session_lock(api, worker);
    let _session_guard = session_lock.lock().await;
    match api.runtime.cancel_worker(
        worker,
        WorkerLifecycleRequest {
            reason: Some(format!("Ticket implementation cancelled: {reason}")),
            ticket_assignment: None,
        },
    ) {
        Ok(result) if result.state == InternalWorkerOperationState::Accepted => {}
        Ok(result) => {
            return Err(ApiError::with_diagnostics(
                Error::RuntimeOperationFailed {
                    runtime_id: worker.runtime_id.clone(),
                    code: "workspace_ticket_implementation_cancel_rejected".to_string(),
                    message: "Runtime did not cancel the assigned Worker Worker".to_string(),
                },
                result.diagnostics,
            ));
        }
        Err(RuntimeRegistryError::UnknownWorker { .. }) => {}
        Err(error) => return Err(error.into_error().into()),
    }
    close_current_worker_session_locked(api, worker).await?;
    Ok(())
}

/// Observation-bound delegation for a new Ticket execution operation. This is
/// distinct from self-reported handling and from the Worker work assignment.
type TicketStartDelegation = (String, ticket::TicketAssignmentTrackingSourceContext);

fn ticket_start_delegation(
    source: Option<&crate::store::TicketOrchestratorAssignmentSourceContext>,
    observed_assignment_id: Option<&str>,
) -> Result<Option<TicketStartDelegation>> {
    use crate::store::TicketOrchestratorAssignmentSourceContext;
    match source {
        Some(TicketOrchestratorAssignmentSourceContext::Runtime {
            runtime_id,
            worker_id,
            agent_key,
            authentication_binding_id,
        }) => {
            let assignment_id = observed_assignment_id.filter(|id| !id.trim().is_empty())
                .ok_or_else(|| Error::TicketAssignmentConflict("Orchestrator Ticket start requires the observed orchestrator_assignment_id".into()))?;
            if assignment_id.len() > 1024 || assignment_id.chars().any(char::is_control) {
                return Err(Error::InvalidInput(
                    "orchestrator_assignment_id must be control-free and at most 1024 bytes".into(),
                ));
            }
            Ok(Some((
                assignment_id.to_owned(),
                ticket::TicketAssignmentTrackingSourceContext {
                    actor: format!("worker:{runtime_id}/{worker_id}"),
                    runtime_id: runtime_id.clone(),
                    worker_id: worker_id.clone(),
                    agent_key: agent_key.clone(),
                    authentication_binding_id: authentication_binding_id.clone(),
                },
            )))
        }
        _ if observed_assignment_id.is_some() => Err(Error::WorkspacePermissionDenied(
            "Only the authenticated current Orchestrator may start under a delegation".into(),
        )),
        _ => Ok(None),
    }
}

fn ticket_spawn_delegation(
    api: &WorkspaceApi,
    headers: &HeaderMap,
    context: Option<&server_api::ServerRequestContext>,
    observed_assignment_id: Option<&str>,
) -> Result<Option<TicketStartDelegation>> {
    if let Some(context) = context {
        // Generic authenticated Worker/manual starts are not implicit delegation.
        // Only the registered Orchestrator starts under its observed assignment.
        let worker = authenticated_ticket_worker_source(headers, context)?;
        if let Some(worker) = worker.as_ref() {
            api.store
                .require_current_worker_singleton_owner(&api.config.workspace_id, worker)?;
            if find_workspace_orchestrator(api).is_some_and(|current| current.worker == *worker) {
                let (_, source) = authenticated_assignment_source(api, headers, context)?;
                return ticket_start_delegation(Some(&source), observed_assignment_id);
            }
        }
        ticket_start_delegation(None, observed_assignment_id)
    } else {
        // Only direct test adapters omit middleware context. Production routes
        // must preserve the binding that actually authenticated the request.
        #[cfg(test)]
        {
            ticket_start_delegation(None, observed_assignment_id)
        }
        #[cfg(not(test))]
        {
            Err(Error::WorkspacePermissionDenied(
                "Ticket start requires Backend-authenticated context".into(),
            ))
        }
    }
}

fn reserve_ticket_start(
    api: &WorkspaceApi,
    operation_id: &str,
    ticket_id: &str,
    runtime_id: &str,
    worker_id: Option<&str>,
    fingerprint: &str,
    created_at: &str,
    delegation: Option<&TicketStartDelegation>,
) -> Result<bool> {
    if let Some((assignment_id, source)) = delegation {
        api.store
            .reserve_ticket_assignment_operation_for_orchestrator(
                &api.config.workspace_id,
                operation_id,
                ticket_id,
                runtime_id,
                worker_id,
                fingerprint,
                created_at,
                assignment_id,
                source,
            )
    } else {
        api.store.reserve_ticket_assignment_operation(
            &api.config.workspace_id,
            operation_id,
            ticket_id,
            runtime_id,
            worker_id,
            fingerprint,
            created_at,
        )
    }
}

fn validate_ticket_assignment_state(
    api: &WorkspaceApi,
    assignment: &WorkerTicketAssignmentRequest,
) -> Result<()> {
    let ticket = api.authority.ticket(&assignment.ticket_id)?;
    if ticket.state == server_api::BrowserTicketState::Closed {
        return Err(Error::TicketAssignmentConflict(format!(
            "Ticket {} is {}; reopen through an explicit lifecycle decision before starting work",
            ticket.id,
            ticket.state.as_str()
        )));
    }
    // Dependencies remain diagnostics for the caller's partial-work decision;
    // they are not authority, resource occupancy, or execution reservations.
    Ok(())
}

fn validate_ticket_assignment_spawn(
    api: &WorkspaceApi,
    runtime_id: &str,
    request: &WorkerSpawnRequest,
) -> Result<()> {
    let Some(assignment) = request.ticket_assignment.as_ref() else {
        return Ok(());
    };

    match &request.intent {
        WorkerSpawnIntent::TicketRole {
            ticket_id,
            role: TicketWorkerRole::Worker,
        } if ticket_id == &assignment.ticket_id => {}
        WorkerSpawnIntent::TicketRole {
            ticket_id,
            role: TicketWorkerRole::Worker,
        } => {
            return Err(Error::TicketAssignmentConflict(format!(
                "spawn intent Ticket {ticket_id} does not match assignment Ticket {}",
                assignment.ticket_id
            )));
        }
        _ => {
            return Err(Error::TicketAssignmentConflict(
                "ticket_assignment is accepted only for a Ticket-role Ticket Worker spawn"
                    .to_string(),
            ));
        }
    }
    if !request.workdir_attachment_requests.is_empty()
        || !request.resolved_workdir_attachment_requests.is_empty()
    {
        return Err(Error::TicketAssignmentConflict(
            "Ticket-assigned Ticket Worker spawn requires existing Workspace Workdir attachments; new materialization requests cannot carry persisted Ticket target capabilities"
                .to_string(),
        ));
    }
    validated_ticket_resource_targets(api, &assignment.ticket_id)
        .map_err(|error| Error::TicketAssignmentConflict(error.error.to_string()))?;
    validate_ticket_assignment_state(api, assignment)?;

    if let Some(current) = api
        .store
        .get_active_ticket_worker_assignment(&api.config.workspace_id, &assignment.ticket_id)?
    {
        let replay_matches = api
            .store
            .get_ticket_assignment_operation(&api.config.workspace_id, &assignment.operation_id)?
            .is_some_and(|operation| {
                operation.action == "assign"
                    && operation.ticket_id == assignment.ticket_id
                    && operation.runtime_id.as_deref() == Some(runtime_id)
                    && operation.assignment_id.as_deref() == Some(current.assignment_id.as_str())
                    && operation.worker.as_ref() == Some(&current.worker)
            });
        if !replay_matches {
            return Err(Error::TicketAssignmentConflict(format!(
                "Ticket {} is already assigned; use the explicit reassign operation",
                assignment.ticket_id
            )));
        }
    }
    Ok(())
}

fn optional_worker_mutation_source(
    api: &WorkspaceApi,
    workspace_id: &str,
    headers: &HeaderMap,
) -> Result<Option<WorkerMutationSource>> {
    let has_runtime = headers.contains_key("x-yoi-runtime-id");
    let has_worker = headers.contains_key("x-yoi-worker-id");
    if !has_runtime && !has_worker {
        return Ok(None);
    }
    authenticate_worker_mutation_source(api, workspace_id, headers).map(Some)
}

fn reject_orchestrator_generic_flow_spawn(
    api: &WorkspaceApi,
    source: Option<&WorkerMutationSource>,
    initial_submit: &[Segment],
    has_ticket_assignment: bool,
) -> Result<()> {
    let is_current_orchestrator = source.is_some_and(|source| {
        find_workspace_orchestrator(api).is_some_and(|orchestrator| orchestrator.worker == *source)
    });
    reject_orchestrator_generic_flow_spawn_for_source(
        is_current_orchestrator,
        initial_submit,
        has_ticket_assignment,
    )
}

fn reject_orchestrator_generic_flow_spawn_for_source(
    is_current_orchestrator: bool,
    initial_submit: &[Segment],
    has_ticket_assignment: bool,
) -> Result<()> {
    let has_flow = initial_submit
        .iter()
        .any(|segment| matches!(segment, Segment::Flow { .. }));
    if is_current_orchestrator && has_flow && !has_ticket_assignment {
        return Err(Error::TicketAssignmentConflict(
            "Workspace Orchestrator Flow spawn requires typed Ticket assignment; Ticket identity in initial text is not assignment authority"
                .to_string(),
        ));
    }
    Ok(())
}

fn assign_ticket_worker_from_lifecycle(
    api: &WorkspaceApi,
    assignment: &crate::hosts::WorkerTicketAssignmentRequest,
    runtime_id: &str,
    worker_id: &str,
) -> Result<TicketWorkerAssignmentRecord> {
    let ticket = api.authority.ticket(&assignment.ticket_id)?;
    let worker = RuntimeWorkerRef::new(runtime_id, worker_id);
    if let Some(operation) = api
        .store
        .get_ticket_assignment_operation(&api.config.workspace_id, &assignment.operation_id)?
        && let Some(assignment_id) = operation.assignment_id.as_ref()
    {
        if operation.action == "assign"
            && operation.ticket_id == assignment.ticket_id
            && operation.worker.as_ref() == Some(&worker)
            && let Some(current) = api.store.get_active_ticket_worker_assignment(
                &api.config.workspace_id,
                &assignment.ticket_id,
            )?
            && current.assignment_id == *assignment_id
            && current.worker == worker
        {
            return Ok(current);
        }
        return Err(Error::TicketAssignmentConflict(format!(
            "assignment operation {} is already bound to another assignment",
            assignment.operation_id
        )));
    }
    let assigned_at = Utc::now().to_rfc3339_opts(SecondsFormat::Secs, true);
    let record = TicketWorkerAssignmentRecord {
        workspace_id: api.config.workspace_id.clone(),
        ticket_id: ticket.id,
        assignment_id: new_id("tasg"),
        worker,
        assigned_by: "worker-lifecycle".to_string(),
        assigned_at,
    };
    Ok(api
        .store
        .set_current_ticket_worker_assignment(
            &record,
            None,
            &new_id("tasev"),
            &assignment.operation_id,
            false,
        )?
        .current)
}

fn accept_queued_ticket_after_worker_spawn(
    api: &WorkspaceApi,
    assignment: &crate::hosts::WorkerTicketAssignmentRequest,
) -> Result<()> {
    let ticket = api.authority.ticket(&assignment.ticket_id)?;
    if ticket.state != server_api::BrowserTicketState::Open {
        return Err(Error::TicketAssignmentConflict(format!(
            "Ticket {} was closed before explicit Worker spawn acceptance",
            ticket.id
        )));
    }
    // Claim/assignment receipts own execution acceptance. Never manufacture a
    // Ticket phase or revive a released identity from its retained assignee.
    Ok(())
}

fn existing_lifecycle_assignment_worker(
    api: &WorkspaceApi,
    assignment: &crate::hosts::WorkerTicketAssignmentRequest,
    runtime_id: &str,
) -> Result<Option<InternalWorkerSummary>> {
    let Some(operation) = api
        .store
        .get_ticket_assignment_operation(&api.config.workspace_id, &assignment.operation_id)?
    else {
        return Ok(None);
    };
    if operation.action != "assign"
        || operation.ticket_id != assignment.ticket_id
        || operation.runtime_id.as_deref() != Some(runtime_id)
    {
        return Err(Error::TicketAssignmentConflict(format!(
            "assignment operation {} was already used with different lifecycle input",
            assignment.operation_id
        )));
    }
    if operation.assignment_id.is_none() {
        return Ok(None);
    }
    let Some(worker_ref) = operation.worker else {
        return Ok(None);
    };
    let worker = api
        .runtime
        .worker(&worker_ref)
        .map_err(|error| error.into_error())?;
    if operation.assignment_id.is_none() && worker.state == "stopped" {
        return Ok(None);
    }
    Ok(Some(worker))
}

fn require_ticket_assignment_value(field: &str, value: String) -> Result<String> {
    let value = value.trim();
    if value.is_empty() {
        return Err(Error::RuntimeOperationFailed {
            runtime_id: "workspace-server".to_string(),
            code: "invalid_ticket_assignment".to_string(),
            message: format!("{field} must not be empty"),
        });
    }
    Ok(value.to_string())
}

#[derive(Clone)]
struct WorkspaceTicketTargetAuthority {
    api: WorkspaceApi,
}

impl ticket::TicketTargetAuthority for WorkspaceTicketTargetAuthority {
    fn resolve_target(
        &self,
        workspace_id: &str,
        repository_key: &str,
        ref_selector: Option<&str>,
    ) -> ticket::Result<ticket::ResolvedTicketTarget> {
        if workspace_id != self.api.config.workspace_id {
            return Err(ticket::TicketError::UnknownTargetRepository(
                repository_key.to_owned(),
            ));
        }
        let repository_key = repository_key.trim();
        if repository_key.is_empty() {
            return Err(ticket::TicketError::MissingTargetRepository);
        }
        let repository = self
            .api
            .store
            .get_repository_by_key(workspace_id, repository_key)
            .map_err(|error| ticket::TicketError::Conflict(error.to_string()))?
            .ok_or_else(|| {
                ticket::TicketError::UnknownTargetRepository(repository_key.to_owned())
            })?;
        let selector = ref_selector
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .or(repository.default_ref.as_deref())
            .map(str::to_owned);
        Ok(ticket::ResolvedTicketTarget {
            repository_key: repository.repository_key,
            ref_selector: selector,
            access: TicketTargetAccess::ReadOnly,
        })
    }
}

fn browser_ticket_backend(api: &WorkspaceApi) -> Result<SqliteTicketBackend> {
    Ok(SqliteTicketBackend::open_verified(
        api.config.database_path.clone(),
        api.config.workspace_id.clone(),
    )?
    .with_target_authority(Arc::new(WorkspaceTicketTargetAuthority {
        api: api.clone(),
    })))
}

fn browser_ticket_detail(api: &WorkspaceApi, ticket_id: &str) -> ApiResult<Json<TicketDetail>> {
    let backend = browser_ticket_backend(api)?;
    Ok(Json(api.authority.read_ticket_detail_with_backend(
        ticket_id,
        TicketShowRequest::default(),
        &backend,
    )?))
}

async fn scoped_edit_ticket_item(
    State(api): State<WorkspaceApi>,
    context: &server_api::ServerRequestContext,
    AxumPath(path): AxumPath<ScopedRecordPath>,
    Json(request): Json<server_api::BrowserEditTicketRequest>,
) -> ApiResult<Json<TicketDetail>> {
    let targets = request.target.map(|target| match target {
        server_api::BrowserTicketTargetEdit::Set { targets } => TicketTargetsEdit::Set {
            targets: targets
                .into_iter()
                .map(|target| ticket::TicketTarget {
                    repository_key: target.repository_key,
                    ref_selector: target.ref_selector,
                    access: target.access,
                })
                .collect(),
        },
        server_api::BrowserTicketTargetEdit::Clear => TicketTargetsEdit::Clear,
    });
    let body_replacement = match (request.old_string, request.new_string) {
        (Some(old_string), Some(new_string)) => Some(TicketBodyReplacement {
            old_string,
            new_string,
            replace_all: request.replace_all,
        }),
        (None, None) => None,
        _ => {
            return Err(settings_bad_request(
                "invalid_ticket_edit_replacement",
                "old_string and new_string must be provided together",
            ));
        }
    };
    execute_ticket_rest_operation_with_context(
        &api,
        &path.workspace_id,
        contract_request_headers(context).map_err(|error| Error::Config(error.message))?,
        Some(context),
        TicketBackendOperation::EditItem {
            id: TicketIdOrSlug::Query(path.id.clone()),
            edit: TicketItemEdit {
                title: request.title,
                body: request.body.map(MarkdownText::new),
                body_replacement,
                targets,
                author: request.author,
            },
        },
    )
    .await?;
    api.host_executors
        .host()?
        .run(move || browser_ticket_detail(&api, &path.id))
        .await
}

async fn scoped_append_ticket_event(
    State(api): State<WorkspaceApi>,
    context: &server_api::ServerRequestContext,
    AxumPath(path): AxumPath<ScopedRecordPath>,
    Json(request): Json<server_api::BrowserAppendTicketEventRequest>,
) -> ApiResult<Json<TicketDetail>> {
    let role = match request.role {
        server_api::BrowserTicketThreadRole::Comment => TicketEventKind::Comment,
        server_api::BrowserTicketThreadRole::Plan => TicketEventKind::Plan,
        server_api::BrowserTicketThreadRole::Decision => TicketEventKind::Decision,
        server_api::BrowserTicketThreadRole::ImplementationReport => {
            TicketEventKind::ImplementationReport
        }
    };
    let mut event = NewTicketEvent::new(role, request.body);
    event.author = request.author;
    execute_ticket_rest_operation_with_context(
        &api,
        &path.workspace_id,
        contract_request_headers(context).map_err(|error| Error::Config(error.message))?,
        Some(context),
        TicketBackendOperation::AddEvent {
            id: TicketIdOrSlug::Query(path.id.clone()),
            event,
        },
    )
    .await?;
    api.host_executors
        .host()?
        .run(move || browser_ticket_detail(&api, &path.id))
        .await
}

const TICKET_EDITABLE_POST_BODY_LIMIT: usize = 1024 * 1024;

fn authenticated_ticket_post_author(
    context: &server_api::ServerRequestContext,
    source: Option<&WorkerMutationSource>,
) -> Result<String> {
    if let Some(source) = source {
        return Ok(format!("worker:{}/{}", source.runtime_id, source.worker_id));
    }
    let actor = context.actor.as_ref().ok_or_else(|| {
        Error::WorkspacePermissionDenied("Ticket posts require an authenticated actor".into())
    })?;
    let identity = serde_json::to_string(&(&actor.account_id, &actor.user_id))
        .map_err(|error| Error::Config(format!("failed to encode post actor: {error}")))?;
    Ok(format!("workspace-user:{identity}"))
}

async fn scoped_get_ticket_post(
    api: WorkspaceApi,
    workspace_id: String,
    id: String,
    event_ref: String,
) -> ApiResult<server_api::TicketEventDetail> {
    api.host_executors
        .host()?
        .run(move || {
            validate_workspace_scope(&api, &workspace_id)?;
            let id = resolve_workspace_ticket_reference(&api, &workspace_id, &id)?;
            let ticket = browser_ticket_backend(&api)?
                .show(TicketIdOrSlug::Id(id))
                .map_err(Error::from)?;
            let (sequence, post) = ticket
                .events
                .iter()
                .enumerate()
                .find(|(_, post)| post.event_ref == event_ref)
                .ok_or_else(|| Error::Ticket(ticket::TicketError::NotFound(event_ref)))?;
            if post.body.as_str().len() > TICKET_EDITABLE_POST_BODY_LIMIT {
                return Err(settings_bad_request(
                    "ticket_post_too_large",
                    "Ticket post exceeds the full-post read limit",
                ));
            }
            let mut detail = crate::authority::ticket_event_detail(sequence, post);
            detail.body = Some(post.body.as_str().to_string());
            detail.body_truncated = false;
            Ok(detail)
        })
        .await
}

async fn scoped_edit_ticket_post(
    api: WorkspaceApi,
    context: server_api::ServerRequestContext,
    workspace_id: String,
    id: String,
    event_ref: String,
    request: server_api::TicketPostEditRequest,
) -> ApiResult<Json<TicketDetail>> {
    let headers =
        contract_request_headers(&context).map_err(|error| Error::Config(error.message))?;
    if request.body.len() > TICKET_EDITABLE_POST_BODY_LIMIT {
        return Err(settings_bad_request(
            "ticket_post_too_large",
            "Ticket post exceeds the edit limit",
        ));
    }
    api.host_executors
        .host()?
        .run(move || {
            validate_workspace_scope(&api, &workspace_id)?;
            let id = resolve_workspace_ticket_reference(&api, &workspace_id, &id)?;
            let backend = browser_ticket_backend(&api)?;
            let observed = backend
                .show(TicketIdOrSlug::Id(id.clone()))
                .map_err(Error::from)?;
            let post = observed
                .events
                .iter()
                .find(|post| post.event_ref == event_ref)
                .ok_or_else(|| Error::Ticket(ticket::TicketError::NotFound(event_ref.clone())))?;
            if crate::authority::ticket_post_body_digest(post.body.as_str())
                != request.expected_body_digest
            {
                return Err(Error::Ticket(ticket::TicketError::Conflict(
                    "stale Ticket post body digest".into(),
                ))
                .into());
            }
            // The digest is a transport observation; storage compares its exact body in the write transaction.
            let expected_body = post.body.clone();
            execute_ticket_rest_operation_on_host(
                &api,
                &workspace_id,
                headers,
                Some(&context),
                TicketBackendOperation::EditPost {
                    id: TicketIdOrSlug::Id(id.clone()),
                    edit: ticket::TicketPostEdit {
                        event_ref,
                        expected_body,
                        body: MarkdownText::new(request.body),
                        author: String::new(),
                    },
                },
            )?;
            browser_ticket_detail(&api, &id)
        })
        .await
}

async fn scoped_mark_ticket_ready_from_browser(
    State(api): State<WorkspaceApi>,
    headers: HeaderMap,
    AxumPath(path): AxumPath<ScopedRecordPath>,
    Json(request): Json<InternalTicketMarkReadyRequest>,
) -> ApiResult<Json<TicketDetail>> {
    validate_workspace_scope(&api, &path.workspace_id)?;
    api.host_executors
        .host()?
        .run(move || {
            let result = execute_ticket_rest_operation_on_host(
                &api,
                &path.workspace_id,
                headers,
                None,
                TicketBackendOperation::MarkReady {
                    id: TicketIdOrSlug::Query(path.id.clone()),
                    request: ticket::TicketMarkReady {
                        operation_key: request.operation_key,
                        reason: request.reason,
                        author: None,
                        intake_summary: request.intake_summary,
                    },
                },
            )?;
            // Preserve result validation before projecting the committed detail.
            let _ = ticket_rest_result(result, |result| match result {
                TicketBackendOperationResult::Ticket(ticket) => Some(ticket),
                _ => None,
            })?;
            browser_ticket_detail(&api, &path.id)
        })
        .await
}

async fn scoped_queue_ticket(
    State(api): State<WorkspaceApi>,
    headers: HeaderMap,
    AxumPath(path): AxumPath<ScopedRecordPath>,
    Json(_request): Json<server_api::BrowserQueueTicketRequest>,
) -> ApiResult<Json<ticket::TicketQueueOutcome>> {
    validate_workspace_scope(&api, &path.workspace_id)?;
    let result = execute_ticket_rest_operation(
        &api,
        &path.workspace_id,
        headers,
        TicketBackendOperation::QueueReady {
            id: TicketIdOrSlug::Id(path.id.clone()),
            queued_by: "workspace-web".to_string(),
        },
    )
    .await?;
    ticket_rest_result(result, |result| match result {
        TicketBackendOperationResult::QueueOutcome(outcome) => Some(outcome),
        _ => None,
    })
}

fn generic_ticket_state_change(operation: &TicketBackendOperation) -> Option<&TicketStateChange> {
    match operation {
        TicketBackendOperation::AddStateChanged { change, .. } => Some(change),
        _ => None,
    }
}

fn validate_ticket_target_repository_keys(
    api: &WorkspaceApi,
    workspace_id: &str,
    targets: &[ticket::TicketTarget],
) -> ApiResult<()> {
    let mut repositories = HashSet::new();
    for target in targets {
        server_api::validate_repository_key(&target.repository_key).map_err(|error| {
            ApiError::from(Error::InvalidInput(format!(
                "invalid Repository key: {error}"
            )))
        })?;
        let repository = api
            .store
            .get_repository_by_key(workspace_id, &target.repository_key)?
            .ok_or_else(|| {
                ApiError::from(Error::UnknownRepository(target.repository_key.clone()))
            })?;
        if !repositories.insert(repository.repository_id) {
            return Err(Error::InvalidInput(format!(
                "Ticket target Repository `{}` appears more than once",
                target.repository_key
            ))
            .into());
        }
    }
    Ok(())
}

fn validate_ticket_operation_repository_keys(
    api: &WorkspaceApi,
    workspace_id: &str,
    operation: &TicketBackendOperation,
) -> ApiResult<()> {
    match operation {
        TicketBackendOperation::Create { input } => {
            validate_ticket_target_repository_keys(api, workspace_id, &input.targets)
        }
        TicketBackendOperation::EditItem { edit, .. } => match edit.targets.as_ref() {
            Some(TicketTargetsEdit::Set { targets }) => {
                validate_ticket_target_repository_keys(api, workspace_id, targets)
            }
            Some(TicketTargetsEdit::Clear) | None => Ok(()),
        },
        _ => Ok(()),
    }
}

fn ticket_item_check_edit(
    operation: &TicketBackendOperation,
    before: Option<&ticket::Ticket>,
) -> Option<TicketItemCheckEdit> {
    match operation {
        TicketBackendOperation::Create { .. } => Some(TicketItemCheckEdit::Create),
        TicketBackendOperation::EditItem { edit, .. } => Some(TicketItemCheckEdit::Edit {
            title_changed: edit.title.is_some(),
            body_changed: edit.body.is_some() || edit.body_replacement.is_some(),
            previous_title: edit
                .title
                .as_ref()
                .and_then(|_| before.map(|ticket| ticket.meta.title.clone())),
            previous_body: (edit.body.is_some() || edit.body_replacement.is_some())
                .then(|| before.map(|ticket| ticket.document.body.as_str().to_string()))
                .flatten(),
            body_replacement: edit.body_replacement.as_ref().map(|replacement| {
                TicketItemCheckBodyReplacement {
                    old_string: replacement.old_string.clone(),
                    new_string: replacement.new_string.clone(),
                    replace_all: replacement.replace_all,
                }
            }),
        }),
        _ => None,
    }
}

fn ticket_item_checker_instruction(api: &WorkspaceApi) -> Result<String> {
    let config_state = api
        .config_store
        .load_workspace_config(&api.config.workspace_id)?
        .ok_or_else(|| Error::Config("Workspace config is unavailable".to_string()))?;
    let projection = api
        .prompt_projection_cache
        .resolve(&api.config.workspace_id, &config_state)
        .map_err(|error| Error::Config(format!("resolve Ticket item checker Prompt: {error}")))?;
    let catalog = worker::PromptCatalog::from_projection(projection.catalog().clone())
        .map_err(|error| Error::Config(format!("load Ticket item checker Prompt: {error}")))?;
    catalog
        .ticket_item_checker()
        .map_err(|error| Error::Config(format!("render Ticket item checker Prompt: {error}")))
}

fn schedule_ticket_item_check(
    api: &WorkspaceApi,
    ticket: &ticket::Ticket,
    edit: TicketItemCheckEdit,
    source_worker: RuntimeWorkerRef,
) {
    let request = ticket_item_checker_instruction(api).and_then(|instruction| {
        ticket_item_checker::request(ticket, edit, source_worker, instruction)
    });
    let request = match request {
        Ok(request) => request,
        Err(error) => {
            tracing::warn!(
                ticket_id = %ticket.meta.id,
                %error,
                "Ticket item was saved but its asynchronous checker could not be prepared"
            );
            return;
        }
    };
    let now = Utc::now().to_rfc3339_opts(SecondsFormat::Nanos, true);
    let reservation = match api
        .store
        .reserve_backend_job(&api.config.workspace_id, &request, &now)
    {
        Ok(reservation) => reservation,
        Err(error) => {
            tracing::warn!(
                ticket_id = %ticket.meta.id,
                input_digest = ?request.input_digest(),
                %error,
                "Ticket item was saved but its asynchronous checker could not be reserved"
            );
            return;
        }
    };
    let api = api.clone();
    let admission = api.host_executors.host().and_then(|executor| {
        executor.dispatch(move || {
            if let Err(error) = api.dispatch_backend_job_reservation(reservation) {
                tracing::warn!(
                    job_id = %request.job_id,
                    ticket_input_digest = ?request.input_digest(),
                    %error,
                    "asynchronous Ticket item checker dispatch failed"
                );
                if !matches!(error, Error::DbOperationOutcomeUnknown) {
                    api.drain_reserved_backend_jobs();
                }
            }
        })
    });
    if let Err(error) = admission {
        tracing::warn!(%error, "Ticket checker was not admitted; its reservation remains durable");
    }
}

async fn execute_ticket_rest_operation(
    api: &WorkspaceApi,
    workspace_id: &str,
    headers: HeaderMap,
    operation: TicketBackendOperation,
) -> ApiResult<TicketBackendOperationResult> {
    execute_ticket_rest_operation_with_context(api, workspace_id, headers, None, operation).await
}

async fn execute_ticket_rest_operation_with_context(
    api: &WorkspaceApi,
    workspace_id: &str,
    headers: HeaderMap,
    context: Option<&server_api::ServerRequestContext>,
    operation: TicketBackendOperation,
) -> ApiResult<TicketBackendOperationResult> {
    validate_workspace_scope(api, workspace_id)?;
    if let TicketBackendOperation::UpdateCase { ticket, request } = operation {
        let context = context.ok_or_else(|| {
            Error::WorkspacePermissionDenied(
                "Ticket case decisions require verified request context".into(),
            )
        })?;
        let Json(updated) = scoped_ticket_case_update_with_context(
            State(api.clone()),
            headers,
            context,
            AxumPath((workspace_id.to_string(), ticket)),
            Json(request),
        )
        .await?;
        return Ok(TicketBackendOperationResult::Ticket(updated));
    }
    let job_api = api.clone();
    let workspace_id = workspace_id.to_owned();
    let context = context.cloned();
    api.host_executors
        .host()?
        .run(move || {
            let api = &job_api;
            let workspace_id = workspace_id.as_str();
            let context = context.as_ref();
            execute_ticket_rest_operation_on_host(api, workspace_id, headers, context, operation)
        })
        .await
}

// Already-owned callers must not re-admit to the occupied Host lane.
fn execute_ticket_rest_operation_on_host(
    api: &WorkspaceApi,
    workspace_id: &str,
    headers: HeaderMap,
    context: Option<&server_api::ServerRequestContext>,
    mut operation: TicketBackendOperation,
) -> ApiResult<TicketBackendOperationResult> {
    validate_ticket_operation_repository_keys(api, workspace_id, &operation)?;
    let mut backend = SqliteTicketBackend::open_verified(
        api.config.database_path.clone(),
        api.config.workspace_id.clone(),
    )
    .map_err(Error::from)?
    .with_target_authority(Arc::new(WorkspaceTicketTargetAuthority {
        api: api.clone(),
    }));
    let operation_kind = ticket_mutation_operation_kind(&operation);
    let is_mutation = operation_kind != "read";
    let target = ticket_mutation_target(&operation).cloned();
    // Human clients are authorized by the Workspace route boundary. Runtime-forwarded Worker
    // calls carry source headers; when either header is present, the complete pair is required
    // and authenticated before source attribution is attached.
    let hinted_source = optional_worker_mutation_source(api, workspace_id, &headers)?;
    // The signed Workspace request carries verified identity in the middleware
    // extension, independently of optional legacy source hints. Classification
    // receipts and audit must not collapse distinct Workers into a human/no-source
    // identity just because those redundant headers are absent.
    let verified_source = context
        .and_then(|context| context.runtime_source.as_ref())
        .map(|source| {
            let worker_id = source.worker_id.as_ref().ok_or_else(|| {
                Error::WorkspacePermissionDenied(
                    "Classification requests require a verified Runtime Worker identity".into(),
                )
            })?;
            Ok::<_, Error>(RuntimeWorkerRef::new(&source.runtime_id, worker_id))
        })
        .transpose()?;
    if let (Some(verified), Some(hinted)) = (&verified_source, &hinted_source)
        && verified != hinted
    {
        return Err(Error::WorkspacePermissionDenied(
            "Classification source hints do not match the verified Runtime Worker".into(),
        )
        .into());
    }
    let source = if let Some(context) = context {
        authenticated_ticket_worker_source(&headers, context)?
    } else {
        verified_source.or(hinted_source)
    };
    if matches!(
        operation,
        TicketBackendOperation::Create { .. }
            | TicketBackendOperation::EditItem { .. }
            | TicketBackendOperation::EditPost { .. }
            | TicketBackendOperation::AddEvent { .. }
    ) && let Some(context) = context
    {
        let author = authenticated_ticket_post_author(context, source.as_ref())?;
        match &mut operation {
            TicketBackendOperation::Create { input } => input.author = Some(author),
            TicketBackendOperation::EditItem { edit, .. } => edit.author = Some(author),
            TicketBackendOperation::EditPost { edit, .. } => edit.author = author,
            TicketBackendOperation::AddEvent { event, .. } => event.author = Some(author),
            _ => unreachable!(),
        }
    }
    validate_ticket_repository_operation(api, &operation)?;
    let before = target.as_ref().and_then(|id| backend.show(id.clone()).ok());
    let mut ticket_item_check = source
        .as_ref()
        .cloned()
        .zip(ticket_item_check_edit(&operation, before.as_ref()));
    let previous_state = before
        .as_ref()
        .map(|ticket| ticket.meta.workflow_state.as_str().to_string())
        .unwrap_or_else(|| ticket_operation_initial_state(&operation));
    let mut event_attributes = BTreeMap::new();
    if source.is_none()
        && let Some(actor) = context.and_then(|context| context.actor.as_ref())
    {
        event_attributes.insert("source_account_id".into(), actor.account_id.clone());
        event_attributes.insert("source_user_id".into(), actor.user_id.clone());
    }
    if matches!(operation, TicketBackendOperation::QueueReady { .. }) {
        let ticket = before.as_ref().ok_or_else(|| {
            Error::TicketAssignmentConflict(
                "Queue requires an existing Ticket with an active Orchestrator assignment"
                    .to_string(),
            )
        })?;
        let mut assignment_ids = BTreeMap::new();
        if let Some(assignment) =
            active_orchestrator_assignment(api, workspace_id, &ticket.meta.id)?
        {
            assignment_ids.insert(ticket.meta.id.clone(), assignment.assignment_id);
        }
        let assignment_json = serde_json::to_string(&assignment_ids).map_err(|error| {
            Error::Config(format!("failed to encode Queue assignment fence: {error}"))
        })?;
        let operation_id = new_id("tqueue");
        let fingerprint = Sha256::digest(format!(
            "ticket-queue:v2\0{workspace_id}\0{}\0{}\0{assignment_json}",
            ticket.meta.id,
            ticket.meta.workflow_state.as_str(),
        ))
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect::<String>();
        if !assignment_ids.is_empty() {
            event_attributes.insert("queue_orchestrator_assignments".into(), assignment_json);
        }
        event_attributes.extend([
            (
                "routing_principal".to_string(),
                "workspace-orchestrator".to_string(),
            ),
            ("routing_operation_id".to_string(), operation_id),
            ("routing_request_fingerprint".to_string(), fingerprint),
        ]);
    }
    if let Some(source) = source.as_ref() {
        bind_worker_ticket_operation_source(source, &mut operation);
        let source_context =
            worker_ticket_source_context(api, workspace_id, source, before.as_ref());
        event_attributes.extend(source_context.attributes(operation_kind));
    }
    if !event_attributes.is_empty() {
        backend = backend.with_event_attributes(event_attributes);
    }

    if generic_ticket_state_change(&operation).is_some() {
        return Err(Error::InvalidInput(
            "Ticket case decisions require TicketCaseUpdate with explicit content/state/closure-key CAS and replay key".into()
        ).into());
    }

    let (result, created_ticket) = match operation {
        TicketBackendOperation::Create { input } => {
            if let Some(source) = source.as_ref() {
                subject_authorization::authorize(
                    api,
                    &RuntimeWorkerRef::new(&source.runtime_id, &source.worker_id),
                    &server_api::authorization::OperationAuthorizationRequest {
                        operation: "ticket.create".into(),
                        resource: server_api::authorization::PermissionResource::Workspace {
                            workspace_id: workspace_id.into(),
                        },
                    },
                )?;
            }
            let (reference, ticket) = backend.create_with_snapshot(input).map_err(Error::from)?;
            (
                TicketBackendOperationResult::TicketRef(reference),
                Some(ticket),
            )
        }
        TicketBackendOperation::EditItem { id, edit } => {
            let (previous, ticket) = backend
                .edit_item_with_snapshots(id, edit)
                .map_err(Error::from)?;
            if let Some((
                _,
                TicketItemCheckEdit::Edit {
                    title_changed,
                    body_changed,
                    previous_title,
                    previous_body,
                    ..
                },
            )) = ticket_item_check.as_mut()
            {
                *previous_title = (*title_changed).then(|| previous.meta.title.clone());
                *previous_body =
                    (*body_changed).then(|| previous.document.body.as_str().to_string());
            }
            (TicketBackendOperationResult::Ticket(ticket), None)
        }
        TicketBackendOperation::EditPost { id, edit } => {
            let event_ref = edit.event_ref.clone();
            let (previous, current) = backend
                .edit_post_with_snapshots(id, edit)
                .map_err(Error::from)?;
            // Check only an initial post, using the transaction's actual preimage.
            ticket_item_check = source.clone().and_then(|source| {
                previous
                    .events
                    .iter()
                    .find(|post| post.event_ref == event_ref && post.is_initial)
                    .map(|_| {
                        (
                            source,
                            TicketItemCheckEdit::Edit {
                                title_changed: false,
                                body_changed: true,
                                previous_title: None,
                                previous_body: Some(previous.document.body.as_str().to_string()),
                                body_replacement: None,
                            },
                        )
                    })
            });
            (
                TicketBackendOperationResult::TicketSnapshots { previous, current },
                None,
            )
        }
        operation => (
            execute_ticket_backend_operation(&backend, operation).map_err(Error::from)?,
            None,
        ),
    };
    // All committed facts enter the same routing policy, including reasons for
    // non-notification. Waking the dispatcher is not itself a request to a Worker.
    if is_mutation {
        if let TicketBackendOperationResult::QueueOutcome(outcome) = &result {
            for ticket_id in &outcome.queued_tickets {
                notify_ticket_recipients(
                    api,
                    workspace_id,
                    ticket_id,
                    "open",
                    "open",
                    source.clone(),
                );
            }
        } else if let TicketBackendOperationResult::TicketSnapshots { previous, current } = &result
        {
            notify_ticket_recipients(
                api,
                workspace_id,
                &current.meta.id,
                previous.meta.workflow_state.as_str(),
                current.meta.workflow_state.as_str(),
                source.clone(),
            );
        } else if let Some(target) = target
            && let Ok(ticket) = backend.show(target)
        {
            notify_ticket_recipients(
                api,
                workspace_id,
                &ticket.meta.id,
                &previous_state,
                ticket.meta.workflow_state.as_str(),
                source.clone(),
            );
        }
    }
    if let Some((source_worker, edit)) = ticket_item_check {
        let checked_ticket = created_ticket.or_else(|| match &result {
            TicketBackendOperationResult::Ticket(ticket) => Some(ticket.clone()),
            TicketBackendOperationResult::TicketSnapshots { current, .. } => Some(current.clone()),
            _ => None,
        });
        if let Some(ticket) = checked_ticket {
            schedule_ticket_item_check(api, &ticket, edit, source_worker);
        }
    }
    Ok(result)
}

#[cfg(test)]
async fn execute_worker_ticket_test_operation(
    State(api): State<WorkspaceApi>,
    AxumPath(path): AxumPath<ScopedWorkspacePath>,
    headers: HeaderMap,
    Json(operation): Json<TicketBackendOperation>,
) -> ApiResult<Json<TicketBackendOperationResult>> {
    execute_ticket_rest_operation(&api, &path.workspace_id, headers, operation)
        .await
        .map(Json)
}

fn ticket_rest_result<T>(
    result: TicketBackendOperationResult,
    extract: impl FnOnce(TicketBackendOperationResult) -> Option<T>,
) -> ApiResult<Json<T>> {
    extract(result).map(Json).ok_or_else(|| {
        Error::Config("Ticket REST handler received an unexpected backend result".to_string())
            .into()
    })
}

fn ticket_rest_unit(result: TicketBackendOperationResult) -> ApiResult<StatusCode> {
    match result {
        TicketBackendOperationResult::Unit => Ok(StatusCode::NO_CONTENT),
        _ => Err(Error::Config(
            "Ticket REST handler received an unexpected backend result".to_string(),
        )
        .into()),
    }
}

#[derive(Debug, Deserialize)]
struct InternalDefaultIntakeReadyBodyRequest {
    from: String,
}

