type WorkerMutationSource = RuntimeWorkerRef;

fn ticket_mutation_target(operation: &TicketBackendOperation) -> Option<&TicketIdOrSlug> {
    match operation {
        TicketBackendOperation::EditItem { id, .. }
        | TicketBackendOperation::EditPost { id, .. }
        | TicketBackendOperation::AddEvent { id, .. }
        | TicketBackendOperation::AddStateChanged { id, .. }
        | TicketBackendOperation::AddIntakeSummary { id, .. }
        | TicketBackendOperation::MarkReady { id, .. }
        | TicketBackendOperation::QueueReady { id, .. }
        | TicketBackendOperation::SetTicketTags { id, .. }
        | TicketBackendOperation::AddTicketRelation { id, .. }
        | TicketBackendOperation::RemoveTicketRelation { id, .. }
        | TicketBackendOperation::AddOrchestrationPlanRecord { id, .. } => Some(id),
        _ => None,
    }
}

fn validate_ticket_repository_operation(
    api: &WorkspaceApi,
    operation: &TicketBackendOperation,
) -> ApiResult<()> {
    let targets: &[ticket::TicketTarget] = match operation {
        TicketBackendOperation::Create { input } => &input.targets,
        TicketBackendOperation::EditItem { edit, .. } => match edit.targets.as_ref() {
            Some(TicketTargetsEdit::Set { targets }) => targets,
            Some(TicketTargetsEdit::Clear) | None => &[],
        },
        _ => &[],
    };
    for target in targets {
        api.require_configured_workspace_repository_by_key(&target.repository_key)?;
    }
    Ok(())
}

fn bind_worker_ticket_operation_source(
    source: &WorkerMutationSource,
    operation: &mut TicketBackendOperation,
) {
    let author = format!("worker:{}/{}", source.runtime_id, source.worker_id);
    match operation {
        TicketBackendOperation::Create { input } => input.author = Some(author),
        TicketBackendOperation::EditItem { edit, .. } => edit.author = Some(author),
        TicketBackendOperation::EditPost { edit, .. } => edit.author = author,
        TicketBackendOperation::AddEvent { event, .. } => event.author = Some(author),
        TicketBackendOperation::AddStateChanged { change, .. } => change.author = Some(author),
        TicketBackendOperation::AddIntakeSummary { summary, .. } => summary.author = Some(author),
        TicketBackendOperation::MarkReady { request, .. } => {
            request.author = Some(author.clone());
            if let Some(summary) = request.intake_summary.as_mut() {
                summary.author = Some(author);
            }
        }
        TicketBackendOperation::QueueReady { queued_by, .. } => *queued_by = author,
        TicketBackendOperation::AddTicketRelation { relation, .. } => {
            relation.author = Some(author)
        }
        TicketBackendOperation::AddOrchestrationPlanRecord { record, .. } => {
            record.author = Some(author)
        }
        _ => {}
    }
}

fn ticket_mutation_operation_kind(operation: &TicketBackendOperation) -> &'static str {
    match operation {
        TicketBackendOperation::Create { .. } => "create",
        TicketBackendOperation::EditItem { .. } => "edit_item",
        TicketBackendOperation::EditPost { .. } => "edit_post",
        TicketBackendOperation::AddEvent { .. } => "add_event",
        TicketBackendOperation::AddStateChanged { .. } => "add_state_changed",
        TicketBackendOperation::UpdateCase { .. } => "case_update",
        TicketBackendOperation::AddIntakeSummary { .. } => "add_intake_summary",
        TicketBackendOperation::MarkReady { .. } => "mark_ready",
        TicketBackendOperation::QueueReady { .. } => "queue_ready",
        TicketBackendOperation::MutateWorkspaceTag { .. } => "mutate_workspace_tag",
        TicketBackendOperation::SetTicketTags { .. } => "set_ticket_tags",
        TicketBackendOperation::AddTicketRelation { .. } => "add_relation",
        TicketBackendOperation::RemoveTicketRelation { .. } => "remove_relation",
        TicketBackendOperation::AddOrchestrationPlanRecord { .. } => "add_plan_record",
        _ => "read",
    }
}

fn ticket_operation_initial_state(operation: &TicketBackendOperation) -> String {
    match operation {
        TicketBackendOperation::Create { input } => input
            .workflow_state
            .as_ref()
            .map(|state| state.as_str().to_string())
            .unwrap_or_else(|| TicketState::Open.as_str().to_string()),
        _ => TicketState::Open.as_str().to_string(),
    }
}

#[derive(Debug, Clone)]
struct WorkerTicketSourceContext {
    worker: RuntimeWorkerRef,
    actor_role: String,
    assignment_id: Option<String>,
}

impl WorkerTicketSourceContext {
    fn attributes(&self, operation_kind: &str) -> BTreeMap<String, String> {
        let mut attributes = BTreeMap::from([
            (
                "source_runtime_id".to_string(),
                self.worker.runtime_id.clone(),
            ),
            (
                "source_worker_id".to_string(),
                self.worker.worker_id.clone(),
            ),
            ("source_actor_role".to_string(), self.actor_role.clone()),
            (
                "source_operation_kind".to_string(),
                operation_kind.to_string(),
            ),
        ]);
        if let Some(assignment_id) = &self.assignment_id {
            attributes.insert("source_assignment_id".to_string(), assignment_id.clone());
        }
        attributes
    }
}

fn worker_source_actor_role(is_current_assignment: bool, is_orchestrator: bool) -> &'static str {
    if is_current_assignment {
        "ticket_worker"
    } else if is_orchestrator {
        "orchestrator"
    } else {
        "worker"
    }
}

fn active_orchestrator_assignment(
    api: &WorkspaceApi,
    workspace_id: &str,
    ticket_id: &str,
) -> Result<Option<TicketRoleAssignmentRecord>> {
    let assignment = api.store.get_active_ticket_role_assignment(
        workspace_id,
        ticket_id,
        TicketAssignmentRole::Orchestrator,
    )?;
    match assignment {
        Some(assignment)
            if matches!(
                assignment.principal,
                TicketAssignmentPrincipal::WorkspaceAgent { ref agent_key }
                    if agent_key == "workspace-orchestrator"
            ) =>
        {
            Ok(Some(assignment))
        }
        Some(_) => Err(Error::TicketAssignmentConflict(
            "Orchestrator role must reference the registered workspace-orchestrator principal"
                .to_string(),
        )),
        None => Ok(None),
    }
}

fn worker_ticket_source_context(
    api: &WorkspaceApi,
    workspace_id: &str,
    source: &WorkerMutationSource,
    ticket: Option<&ticket::Ticket>,
) -> WorkerTicketSourceContext {
    let assignment = ticket.and_then(|ticket| {
        api.store
            .get_active_ticket_worker_assignment(workspace_id, &ticket.meta.id)
            .ok()
            .flatten()
    });
    let orchestrator = find_workspace_orchestrator(api);
    let is_current_assignment = assignment
        .as_ref()
        .is_some_and(|assignment| &assignment.worker == source);
    let is_orchestrator = active_orchestrator_assignment(
        api,
        workspace_id,
        ticket
            .map(|ticket| ticket.meta.id.as_str())
            .unwrap_or_default(),
    )
    .ok()
    .flatten()
    .is_some()
        && orchestrator
            .as_ref()
            .is_some_and(|worker| worker.worker == *source);
    let actor_role = worker_source_actor_role(is_current_assignment, is_orchestrator);
    WorkerTicketSourceContext {
        worker: source.clone(),
        actor_role: actor_role.to_string(),
        assignment_id: assignment.and_then(|assignment| {
            (assignment.worker == *source).then_some(assignment.assignment_id)
        }),
    }
}

fn canonical_ticket_resource_key(resource_key: &str) -> Option<&str> {
    let sequence = resource_key.strip_prefix("T-")?;
    (!sequence.is_empty() && sequence.bytes().all(|byte| byte.is_ascii_digit()))
        .then_some(resource_key)
}

#[cfg(test)]
fn ticket_notification_content(
    resource_key: &str,
    previous_state: &str,
    current_state: &str,
) -> String {
    if previous_state == current_state {
        return format!(
            "Ticket {resource_key} has new activity while {current_state}. Reread the current Ticket before acting."
        );
    }
    format!(
        "Ticket {resource_key} changed state from {previous_state} to {current_state}. Reread the current Ticket before acting."
    )
}

#[derive(Debug, Clone, Serialize, PartialEq, Eq)]
struct TicketNotificationDeliveryWarning {
    level: &'static str,
    event: &'static str,
    workspace_id: String,
    ticket_id: String,
    current_state: String,
    recipient_runtime_id: String,
    recipient_worker_id: String,
    error_category: &'static str,
}

impl TicketNotificationDeliveryWarning {
    fn new(
        workspace_id: &str,
        ticket_id: &str,
        current_state: &str,
        recipient: &RuntimeWorkerRef,
        error_category: &'static str,
    ) -> Self {
        Self {
            level: "warning",
            event: "ticket_notification_delivery_failed",
            workspace_id: workspace_id.to_string(),
            ticket_id: ticket_id.to_string(),
            current_state: current_state.to_string(),
            recipient_runtime_id: recipient.runtime_id.clone(),
            recipient_worker_id: recipient.worker_id.clone(),
            error_category,
        }
    }
}

#[cfg(test)]
static TICKET_NOTIFICATION_DELIVERY_WARNING_CAPTURE: Mutex<Vec<TicketNotificationDeliveryWarning>> =
    Mutex::new(Vec::new());

fn ticket_notification_delivery_error_category(
    result: &std::result::Result<WorkerInputResult, RuntimeRegistryError>,
) -> Option<&'static str> {
    match result {
        Ok(result) if result.disposition == WorkerInputDisposition::Unknown => {
            Some("acceptance_unknown")
        }
        Ok(result) => match result.state {
            InternalWorkerOperationState::Accepted => None,
            InternalWorkerOperationState::Rejected => Some("runtime_rejected"),
            InternalWorkerOperationState::Unsupported => Some("runtime_unsupported"),
        },
        Err(RuntimeRegistryError::InvalidIdentifier { .. }) => Some("invalid_identifier"),
        Err(RuntimeRegistryError::UnknownRuntime(_)) => Some("unknown_runtime"),
        Err(RuntimeRegistryError::UnknownHost(_)) => Some("unknown_host"),
        Err(RuntimeRegistryError::UnknownWorker { .. }) => Some("unknown_worker"),
        Err(
            RuntimeRegistryError::WorkdirSessionOpenFailed { .. }
            | RuntimeRegistryError::RuntimeOperationFailed { .. },
        ) => Some("runtime_operation_failed"),
    }
}

fn emit_ticket_notification_delivery_warning(warning: TicketNotificationDeliveryWarning) {
    let serialized = serde_json::to_string(&warning)
        .expect("Ticket notification delivery warnings serialize from bounded string fields");
    eprintln!(
        "{} yoi-server {serialized}",
        Utc::now().to_rfc3339_opts(SecondsFormat::Millis, true)
    );
    #[cfg(test)]
    TICKET_NOTIFICATION_DELIVERY_WARNING_CAPTURE
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .push(warning);
}

fn notify_ticket_recipients(
    api: &WorkspaceApi,
    _workspace_id: &str,
    _ticket_id: &str,
    _previous_state: &str,
    _current_state: &str,
    _source: Option<RuntimeWorkerRef>,
) {
    // Source identity and recipients were captured by the domain transaction.
    // Call-site state strings and current Worker observations are not routing authority.
    recover_ticket_notifications(api);
}

fn authenticate_worker_mutation_source(
    api: &WorkspaceApi,
    workspace_id: &str,
    headers: &HeaderMap,
) -> Result<WorkerMutationSource> {
    let runtime_id = headers
        .get("x-yoi-runtime-id")
        .and_then(|value| value.to_str().ok())
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| Error::WorkerSourceIdentity("missing Runtime id".to_string()))?;
    let worker_id = headers
        .get("x-yoi-worker-id")
        .and_then(|value| value.to_str().ok())
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| {
            Error::WorkerSourceIdentity("missing Runtime-bound Worker id".to_string())
        })?;
    let worker = RuntimeWorkerRef::new(runtime_id, worker_id);
    let summary = api.runtime.worker(&worker).map_err(|_| {
        Error::WorkerSourceIdentity("Runtime-bound Worker identity does not exist".to_string())
    })?;
    if summary.workspace.workspace_id.as_deref() != Some(workspace_id) {
        return Err(Error::WorkerSourceIdentity(format!(
            "Runtime-bound Worker is not scoped to Workspace {workspace_id}"
        )));
    }
    Ok(worker)
}

async fn authenticate_worker_mutation_source_owned(
    api: &WorkspaceApi,
    workspace_id: &str,
    headers: &HeaderMap,
) -> Result<WorkerMutationSource> {
    let api = api.clone();
    let workspace_id = workspace_id.to_owned();
    let headers = headers.clone();
    api.host_executors
        .host()?
        .run(move || authenticate_worker_mutation_source(&api, &workspace_id, &headers))
        .await
}

fn current_worker_identity(
    api: &WorkspaceApi,
    workspace_id: &str,
    headers: &HeaderMap,
) -> Result<RuntimeWorkerRef> {
    authenticate_worker_mutation_source(api, workspace_id, headers)
}

fn current_worker_session_lock(
    api: &WorkspaceApi,
    worker: &RuntimeWorkerRef,
) -> Arc<tokio::sync::Mutex<()>> {
    api.workdir_session_locks
        .lock()
        .expect("Workdir session lock registry poisoned")
        .entry(worker.clone())
        .or_insert_with(|| Arc::new(tokio::sync::Mutex::new(())))
        .clone()
}

fn runtime_local_owner_worker_id<'a>(
    caller: &'a RuntimeWorkerRef,
    target_runtime_id: &str,
) -> Option<&'a str> {
    (caller.runtime_id == target_runtime_id).then_some(caller.worker_id.as_str())
}

// Locked async workflows stay on Tokio. Each accepted synchronous mutation
// retains this same owned guard through execution and discarded-result cleanup.
async fn run_worker_workdir_db_stage_locked<T, E>(
    api: &WorkspaceApi,
    session_guard: &Arc<tokio::sync::OwnedMutexGuard<()>>,
    operation: impl FnOnce(WorkspaceApi) -> std::result::Result<T, E> + Send + 'static,
) -> std::result::Result<T, E>
where
    T: Send + 'static,
    E: From<Error> + Send + 'static,
{
    let stage_api = api.clone();
    let stage_guard = session_guard.clone();
    let (outcome, _session_guard) = api
        .store
        .db_executor()
        .run(move || {
            let outcome = operation(stage_api);
            // Keep the guard with the outcome, including errors. If the waiter was
            // cancelled, the job drops the outcome before releasing this guard.
            Ok::<_, E>((outcome, stage_guard))
        })
        .await?;
    outcome
}

async fn open_current_worker_workdir_session_locked(
    api: &WorkspaceApi,
    worker: &RuntimeWorkerRef,
    link: &WorkerWorkdirLinkRecord,
    session_guard: &Arc<tokio::sync::OwnedMutexGuard<()>>,
) -> Result<WorkdirSessionHandle> {
    let stage_api = api.clone();
    let stage_worker = worker.clone();
    let stage_link = link.clone();
    let (workdir, effective_capabilities) = api
        .store
        .db_executor()
        .run(move || {
            let workdir = stage_api
                .store
                .list_workdir_registry(&stage_api.config.workspace_id, 10_000)?
                .into_iter()
                .find(|workdir| workdir.workdir_id == stage_link.workdir_id)
                .ok_or_else(|| Error::RuntimeOperationFailed {
                    runtime_id: stage_worker.runtime_id.clone(),
                    code: "working_directory_not_found".to_string(),
                    message: format!(
                        "attached Workdir {} is not registered in this Workspace",
                        stage_link.workdir_id
                    ),
                })?;
            if matches!(
                workdir.source,
                WorkdirRegistrySource::WorkspaceConfig { .. }
            ) {
                return Err(Error::WorkspacePermissionDenied(
                    "Logical config has no filesystem session".into(),
                ));
            }
            let capabilities = effective_worker_workdir_capabilities(
                &stage_api,
                &stage_worker,
                &workdir,
                stage_link.capabilities,
            )?;
            Ok((workdir, capabilities))
        })
        .await?;
    if let WorkdirRegistrySource::ExternalGrant { grant_id } = &workdir.source {
        close_current_worker_attachment_session_locked(api, worker).await?;
        let stage_api = api.clone();
        let stage_grant_id = grant_id.clone();
        let mut grant = api
            .store
            .db_executor()
            .run(move || {
                stage_api
                    .store
                    .get_external_workdir_grant(&stage_api.config.workspace_id, &stage_grant_id)?
                    .ok_or_else(|| Error::RuntimeOperationFailed {
                        runtime_id: "workspace-backend".to_string(),
                        code: "external_workdir_grant_not_found".to_string(),
                        message: "External Workdir grant is unavailable".to_string(),
                    })
            })
            .await?;
        let expired = external_workdir_grant_is_expired(&grant)?;
        if expired {
            grant = fence_external_workdir_grant_expired(api, grant_id)
                .await
                .map_err(|error| error.error)?;
        }
        if matches!(grant.status.as_str(), "revoked" | "expired") {
            cleanup_external_workdir_attachments_with_lock(
                api,
                &grant.workdir_id,
                Some((worker, session_guard)),
            )
            .await
            .map_err(|error| error.error)?;
            cancel_external_workdir_expiry(api, grant_id);
        }
        if grant.status != "online" {
            return Err(Error::RuntimeOperationFailed {
                runtime_id: "workspace-backend".to_string(),
                code: format!("external_workdir_provider_{}", grant.status),
                message: "External Workdir provider is not online".to_string(),
            });
        }
        let connection = api
            .external_workdir_providers
            .lock()
            .expect("External Workdir provider registry poisoned")
            .connection(grant_id)
            .filter(|connection| {
                connection.generation == grant.generation
                    && connection.provider_instance_id == grant.provider_instance_id
                    && connection.workdir_id == workdir.workdir_id
            })
            .ok_or_else(|| Error::RuntimeOperationFailed {
                runtime_id: "workspace-backend".to_string(),
                code: "external_workdir_provider_offline".to_string(),
                message: "External Workdir provider connection is unavailable".to_string(),
            })?;
        let source: WorkdirSessionHandle = Arc::new(ExternalProviderWorkdirSession::new(
            connection,
            Some(ExternalProviderAuditContext {
                store: api.store.clone(),
                workspace_id: api.config.workspace_id.clone(),
                actor_key: format!("{}:{}", worker.runtime_id, worker.worker_id),
                attachment_alias: link.alias.clone(),
            }),
        ));
        let session = workdir::WorkdirToolBroker::with_capabilities(source, effective_capabilities)
            .tool_session();
        let replaced = api
            .workdir_sessions
            .lock()
            .expect("Workdir session registry lock poisoned")
            .insert_attachment(worker.clone(), session.clone());
        if let Some(replaced) = replaced {
            replaced
                .close()
                .await
                .map_err(|error| Error::RuntimeOperationFailed {
                    runtime_id: worker.runtime_id.clone(),
                    code: "duplicate_workdir_session_close_failed".to_string(),
                    message: error.to_string(),
                })?;
        }
        return Ok(session);
    }
    let (runtime_id, repository_id) = match &workdir.source {
        WorkdirRegistrySource::Repository {
            runtime_id,
            repository_id,
        } => (runtime_id.as_str(), repository_id.as_str()),
        WorkdirRegistrySource::ExternalGrant { .. }
        | WorkdirRegistrySource::WorkspaceConfig { .. } => {
            return Err(Error::RuntimeOperationFailed {
                runtime_id: "workspace-backend".to_string(),
                code: "external_workdir_provider_unavailable".to_string(),
                message: "External Workdir provider is not connected".to_string(),
            });
        }
    };
    let stage_api = api.clone();
    let stage_repository_id = repository_id.to_string();
    let repository = api
        .store
        .db_executor()
        .run(move || {
            stage_api
                .require_configured_workspace_repository(&stage_repository_id)
                .map_err(|error| error.error)
        })
        .await?;
    let repository_requires_access =
        repository.source.kind == server_api::RepositorySourceKind::Ssh;
    if repository_requires_access {
        close_current_worker_attachment_session_locked(api, worker).await?;
        let stage_api = api.clone();
        let stage_runtime_id = runtime_id.to_string();
        let stage_workdir_id = workdir.workdir_id.clone();
        let operation_id = format!(
            "workdir-session:{}:{}:{}",
            worker.runtime_id, worker.worker_id, workdir.workdir_id
        );
        let stage_guard = session_guard.clone();
        let access = api
            .store
            .db_executor()
            .run(move || {
                let _session_guard = stage_guard;
                repository_access_request_for_workdir(
                    &stage_api,
                    &stage_runtime_id,
                    &stage_workdir_id,
                    &operation_id,
                )
                .map_err(|error| error.error)?
                .ok_or_else(|| Error::RuntimeOperationFailed {
                    runtime_id: stage_runtime_id,
                    code: "working_directory_remote_repository_access_required".to_string(),
                    message: "current Repository SSH access authority is unavailable".to_string(),
                })
            })
            .await?;
        let stage_api = api.clone();
        let stage_runtime_id = runtime_id.to_string();
        // The accepted Runtime authorization must retain the actual session lock,
        // not just the async waiter that submitted it.
        let stage_guard = session_guard.clone();
        api.host_executors
            .host()?
            .run(move || {
                let _session_guard = stage_guard;
                stage_api
                    .runtime
                    .authorize_working_directory_repository_access(&stage_runtime_id, access)
                    .map_err(RuntimeRegistryError::into_error)
            })
            .await?;
    } else {
        // The registry is an operation-session cache, not routing authority.
        // Close any prior alias session before opening the explicitly selected
        // attachment so multiple aliases can never share one provider namespace.
        close_current_worker_attachment_session_locked(api, worker).await?;
    }
    let owner_worker_id = runtime_local_owner_worker_id(worker, runtime_id);
    let source = api
        .runtime
        .open_workdir_session(runtime_id, &workdir.workdir_id, owner_worker_id)
        .await
        .map_err(|error| error.into_error())?;
    let session = workdir::WorkdirToolBroker::with_capabilities(source, effective_capabilities)
        .tool_session();
    let replaced = api
        .workdir_sessions
        .lock()
        .expect("Workdir session registry lock poisoned")
        .insert_attachment(worker.clone(), session.clone());
    if let Some(replaced) = replaced {
        replaced
            .close()
            .await
            .map_err(|error| Error::RuntimeOperationFailed {
                runtime_id: worker.runtime_id.clone(),
                code: "duplicate_workdir_session_close_failed".to_string(),
                message: error.to_string(),
            })?;
    }
    Ok(session)
}

async fn close_current_worker_attachment_session_locked(
    api: &WorkspaceApi,
    worker: &RuntimeWorkerRef,
) -> Result<()> {
    let session = api
        .workdir_sessions
        .lock()
        .expect("Workdir session registry lock poisoned")
        .remove_attachment(worker);
    if let Some(session) = session {
        if let Err(error) = session.close().await {
            api.workdir_sessions
                .lock()
                .expect("Workdir session registry lock poisoned")
                .insert_attachment(worker.clone(), session);
            return Err(Error::RuntimeOperationFailed {
                runtime_id: worker.runtime_id.clone(),
                code: "workdir_session_close_failed".to_string(),
                message: error.to_string(),
            });
        }
    }
    Ok(())
}

async fn close_current_worker_command_sessions_for_alias_locked(
    api: &WorkspaceApi,
    worker: &RuntimeWorkerRef,
    attachment_alias: &str,
) -> Result<()> {
    close_worker_workdir_command_sessions_for_alias(&api.workdir_sessions, worker, attachment_alias)
        .await
        .map_err(|message| Error::RuntimeOperationFailed {
            runtime_id: worker.runtime_id.clone(),
            code: "workdir_session_close_failed".to_string(),
            message,
        })
}

async fn close_current_worker_session_locked(
    api: &WorkspaceApi,
    worker: &RuntimeWorkerRef,
) -> Result<()> {
    close_worker_workdir_sessions(&api.workdir_sessions, worker)
        .await
        .map_err(|message| Error::RuntimeOperationFailed {
            runtime_id: worker.runtime_id.clone(),
            code: "workdir_session_close_failed".to_string(),
            message,
        })
}

fn restore_logical_workdir_attachments(
    api: &WorkspaceApi,
    worker: &RuntimeWorkerRef,
) -> ApiResult<Vec<LogicalWorkdirAttachment>> {
    let mut attachments = Vec::new();
    for link in api
        .store
        .list_worker_workdir_links(&api.config.workspace_id, worker)?
        .into_iter()
        .filter(|link| link.unlinked_at.is_none())
    {
        if api
            .store
            .get_workdir_registry(&api.config.workspace_id, &link.workdir_id)?
            .is_some_and(|record| {
                matches!(record.source, WorkdirRegistrySource::WorkspaceConfig { .. })
            })
        {
            continue;
        }
        attachments.push(LogicalWorkdirAttachment {
            alias: workdir::WorkdirAttachmentAlias::new(link.alias)
                .map_err(|error| Error::InvalidInput(error.to_string()))?,
            working_directory_id: link.workdir_id,
            capabilities: link.capabilities,
        });
    }
    Ok(attachments)
}

fn prepare_runtime_worker_workdir_attachments(
    api: &WorkspaceApi,
    worker: &RuntimeWorkerRef,
) -> ApiResult<Vec<LogicalWorkdirAttachment>> {
    let attachments = api
        .store
        .list_worker_workdir_links(&api.config.workspace_id, worker)?
        .into_iter()
        .filter(|link| link.unlinked_at.is_none())
        .filter(|link| {
            api.store
                .get_workdir_registry(&api.config.workspace_id, &link.workdir_id)
                .ok()
                .flatten()
                .is_none_or(|record| {
                    !matches!(record.source, WorkdirRegistrySource::WorkspaceConfig { .. })
                })
        })
        .map(|mut link| {
            let workdir = api
                .store
                .get_workdir_registry(&api.config.workspace_id, &link.workdir_id)?
                .ok_or_else(|| {
                    Error::RegistryInconsistency(format!(
                        "Worker attachment references unknown Workdir {}",
                        link.workdir_id
                    ))
                })?;
            let capabilities = link
                .capabilities
                .intersection(workdir_source_capabilities(api, &workdir)?)
                .intersection(ticket_target_capabilities_for_workdir(
                    api, worker, &workdir,
                )?);
            if capabilities != link.capabilities {
                link.capabilities = capabilities;
                api.store.attach_worker_workdir(&link)?;
            }
            Ok(LogicalWorkdirAttachment {
                alias: workdir::WorkdirAttachmentAlias::new(link.alias)
                    .map_err(|error| Error::InvalidInput(error.to_string()))?,
                working_directory_id: link.workdir_id,
                capabilities,
            })
        })
        .collect::<Result<Vec<_>>>()?;
    Ok(attachments)
}

fn replace_runtime_worker_workdir_attachments(
    api: &WorkspaceApi,
    worker: &RuntimeWorkerRef,
    attachments: Vec<LogicalWorkdirAttachment>,
) -> ApiResult<()> {
    let result = api
        .runtime
        .replace_worker_workdir_attachments(worker, attachments)
        .map_err(RuntimeRegistryError::into_error)?;
    if result.state != InternalWorkerOperationState::Accepted {
        return Err(Error::RuntimeOperationFailed {
            runtime_id: worker.runtime_id.clone(),
            code: "worker_workdir_attachments_replace_failed".to_string(),
            message: result
                .diagnostics
                .first()
                .map(|diagnostic| diagnostic.message.clone())
                .unwrap_or_else(|| "Runtime rejected Workdir attachment persistence".to_string()),
        }
        .into());
    }
    Ok(())
}

#[cfg(test)]
fn sync_runtime_worker_workdir_attachments(
    api: &WorkspaceApi,
    worker: &RuntimeWorkerRef,
) -> ApiResult<()> {
    let attachments = prepare_runtime_worker_workdir_attachments(api, worker)?;
    replace_runtime_worker_workdir_attachments(api, worker, attachments)
}

async fn sync_runtime_worker_workdir_attachments_locked(
    api: &WorkspaceApi,
    worker: &RuntimeWorkerRef,
    session_guard: &Arc<tokio::sync::OwnedMutexGuard<()>>,
) -> ApiResult<()> {
    let stage_api = api.clone();
    let stage_worker = worker.clone();
    let stage_guard = session_guard.clone();
    let attachments = api
        .store
        .db_executor()
        .run(move || {
            let _session_guard = stage_guard;
            prepare_runtime_worker_workdir_attachments(&stage_api, &stage_worker)
        })
        .await?;
    let stage_api = api.clone();
    let stage_worker = worker.clone();
    let stage_guard = session_guard.clone();
    api.host_executors
        .host()?
        .run(move || {
            let _session_guard = stage_guard;
            replace_runtime_worker_workdir_attachments(&stage_api, &stage_worker, attachments)
        })
        .await
}

async fn refresh_current_worker_session_locked(
    api: &WorkspaceApi,
    worker: &RuntimeWorkerRef,
    session_guard: &Arc<tokio::sync::OwnedMutexGuard<()>>,
) -> Result<()> {
    close_current_worker_attachment_session_locked(api, worker).await?;
    let stage_api = api.clone();
    let stage_worker = worker.clone();
    let remaining = api
        .store
        .db_executor()
        .run(move || active_filesystem_workdir_links(&stage_api, &stage_worker))
        .await?;
    if remaining.len() == 1 {
        open_current_worker_workdir_session_locked(api, worker, &remaining[0], session_guard)
            .await?;
    }
    Ok(())
}

fn active_filesystem_workdir_links(
    api: &WorkspaceApi,
    worker: &RuntimeWorkerRef,
) -> Result<Vec<WorkerWorkdirLinkRecord>> {
    Ok(api
        .store
        .list_worker_workdir_links(&api.config.workspace_id, worker)?
        .into_iter()
        .filter(|link| link.unlinked_at.is_none())
        .filter(|link| {
            api.store
                .get_workdir_registry(&api.config.workspace_id, &link.workdir_id)
                .ok()
                .flatten()
                .is_none_or(|record| {
                    !matches!(record.source, WorkdirRegistrySource::WorkspaceConfig { .. })
                })
        })
        .collect())
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct SubmitBackendJobResultRequest {
    result: serde_json::Value,
}

async fn scoped_submit_backend_job_result(
    State(api): State<WorkspaceApi>,
    AxumPath(path): AxumPath<ScopedWorkspacePath>,
    headers: HeaderMap,
    Json(request): Json<SubmitBackendJobResultRequest>,
) -> ApiResult<Json<BackendJobResultAcceptance>> {
    api.host_executors
        .host()?
        .run(move || {
            validate_workspace_scope(&api, &path.workspace_id)?;
            let worker = current_worker_identity(&api, &path.workspace_id, &headers)?;
            let binding = api
                .store
                .worker_registry_projection(&api.config.workspace_id, &worker)?
                .and_then(|projection| projection.job)
                .ok_or_else(|| {
                    Error::InvalidInput(
                        "current Worker is not bound to an active Backend Job attempt".to_string(),
                    )
                })?;
            let attempt = api
                .store
                .get_backend_job_attempt(
                    &api.config.workspace_id,
                    &binding.job_id,
                    &binding.attempt_id,
                )?
                .ok_or_else(|| {
                    Error::Store("Backend Job attempt binding disappeared".to_string())
                })?;
            let acceptance = api.accept_backend_job_result(
                &worker,
                &BackendJobResultSubmission {
                    job_id: binding.job_id,
                    attempt_id: binding.attempt_id,
                    input_digest: attempt.input_digest,
                    result: request.result,
                },
            )?;
            Ok(Json(acceptance))
        })
        .await
}

async fn detach_worker_workdir_stage_locked(
    api: &WorkspaceApi,
    worker: &RuntimeWorkerRef,
    workdir_id: &str,
    session_guard: &Arc<tokio::sync::OwnedMutexGuard<()>>,
) -> Result<Option<WorkerWorkdirLinkRecord>> {
    let worker = worker.clone();
    let workdir_id = workdir_id.to_string();
    run_worker_workdir_db_stage_locked(api, session_guard, move |api| {
        api.store.detach_worker_workdir(
            &api.config.workspace_id,
            &worker,
            Some(&workdir_id),
            &Utc::now().to_rfc3339_opts(SecondsFormat::Millis, true),
        )
    })
    .await
}

async fn import_current_worker_workdir_observation(
    api: &WorkspaceApi,
    worker: &RuntimeWorkerRef,
    session_guard: Option<&Arc<tokio::sync::OwnedMutexGuard<()>>>,
) -> ApiResult<()> {
    let stage_api = api.clone();
    let stage_worker = worker.clone();
    let has_history = api
        .store
        .db_executor()
        .run(move || {
            stage_api
                .store
                .worker_workdir_link_history_exists(&stage_api.config.workspace_id, &stage_worker)
        })
        .await?;
    if !has_history {
        let stage_api = api.clone();
        let stage_worker = worker.clone();
        let stage_guard = session_guard.cloned();
        let observed_worker = api
            .host_executors
            .host()?
            .run(move || {
                let _session_guard = stage_guard;
                stage_api
                    .runtime
                    .worker(&stage_worker)
                    .map_err(RuntimeRegistryError::into_error)
            })
            .await?;
        if !observed_worker.workdir_attachments.is_empty() {
            let stage_api = api.clone();
            let stage_guard = session_guard.cloned();
            api.store
                .db_executor()
                .run(move || {
                    let _session_guard = stage_guard;
                    sync_worker_observation(&stage_api, &observed_worker)
                })
                .await?;
        }
    }
    Ok(())
}

// The Backend proxy has root-coordinate operations even before its provider is
// opened. Multiple attachments must remain attachable without opening every
// provider: a pending/offline provider is checked when an operation selects it.
async fn current_worker_attachment_environment_locked(
    api: &WorkspaceApi,
    worker: &RuntimeWorkerRef,
    link: &WorkerWorkdirLinkRecord,
    capabilities: workdir::WorkdirSessionCapabilities,
    open_if_single: bool,
    session_guard: &Arc<tokio::sync::OwnedMutexGuard<()>>,
) -> Result<workdir::WorkdirSessionEnvironment> {
    if open_if_single {
        let stage_api = api.clone();
        let stage_worker = worker.clone();
        let count = api
            .store
            .db_executor()
            .run(move || {
                active_filesystem_workdir_links(&stage_api, &stage_worker).map(|links| links.len())
            })
            .await?;
        if count == 1 {
            return Ok(open_current_worker_workdir_session_locked(
                api,
                worker,
                link,
                session_guard,
            )
            .await?
            .environment());
        }
    }
    if let Some(mut environment) = api
        .workdir_sessions
        .lock()
        .expect("Workdir session registry lock poisoned")
        .attachments
        .get(worker)
        .filter(|source| source.workdir().id().as_str() == link.workdir_id)
        .map(|source| source.environment())
    {
        environment.capabilities = environment.capabilities.intersection(capabilities);
        return Ok(environment);
    }
    let mut environment = workdir::WorkdirSessionEnvironment::root(capabilities);
    environment.restrictions.push("Backend proxy: provider scope and availability are checked when each operation selects this attachment".into());
    Ok(environment)
}

async fn scoped_attach_current_worker_workdir(
    State(api): State<WorkspaceApi>,
    AxumPath(path): AxumPath<ScopedWorkspacePath>,
    headers: HeaderMap,
    Json(request): Json<AttachCurrentWorkerWorkdirRequest>,
) -> ApiResult<Json<server_api::CurrentWorkerWorkdirAttachmentResponse>> {
    let stage_api = api.clone();
    let worker = api
        .host_executors
        .host()?
        .run(move || -> ApiResult<_> {
            validate_workspace_scope(&stage_api, &path.workspace_id)?;
            Ok(current_worker_identity(
                &stage_api,
                &path.workspace_id,
                &headers,
            )?)
        })
        .await?;
    let alias = workdir::WorkdirAttachmentAlias::new(request.alias)
        .map_err(|error| Error::InvalidInput(error.to_string()))?;
    let workdir_id = request.working_directory_id.trim();
    if workdir_id.is_empty() || workdir_id.chars().any(char::is_control) {
        return Err(Error::InvalidRecordId(request.working_directory_id).into());
    }
    let stage_api = api.clone();
    let stage_worker = worker.clone();
    let stage_workdir_id = workdir_id.to_string();
    let capabilities = api
        .store
        .db_executor()
        .run(move || -> ApiResult<_> {
            let api = stage_api;
            let worker = stage_worker;
            let workdir_id = stage_workdir_id.as_str();
            let workdir = api
                .store
                .list_workdir_registry(&api.config.workspace_id, 10_000)?
                .into_iter()
                .find(|workdir| workdir.workdir_id == workdir_id)
                .ok_or_else(|| Error::RuntimeOperationFailed {
                    runtime_id: worker.runtime_id.clone(),
                    code: "working_directory_not_found".to_string(),
                    message: format!("unknown Workdir `{workdir_id}`"),
                })?;
            // A failed removal must not prevent its owner from attaching a still usable
            // repository checkout to resolve current blockers. Runtime binding validates
            // the actual checkout; durable pending-removal reservations still fence this
            // mutation. Other sources and missing/corrupted materializations stay denied.
            let repository_retry = workdir.materialization_status == "pending"
                && matches!(workdir.source, WorkdirRegistrySource::Repository { .. });
            if workdir.materialization_status != "present" && !repository_retry {
                return Err(Error::WorkdirAttachmentConflict(format!(
                    "Workdir `{workdir_id}` is not available for attachment ({})",
                    workdir.materialization_status
                ))
                .into());
            }
            match &workdir.source {
                WorkdirRegistrySource::Repository { .. } => {}
                WorkdirRegistrySource::WorkspaceConfig { .. } => {
                    return Err(Error::WorkspacePermissionDenied(
                        "Use the grant-bound Workspace config attachment operation".into(),
                    )
                    .into());
                }
                WorkdirRegistrySource::ExternalGrant { grant_id } => {
                    let grant = api
                        .store
                        .get_external_workdir_grant(&api.config.workspace_id, grant_id)?
                        .ok_or_else(|| Error::RuntimeOperationFailed {
                            runtime_id: "external-workdir-provider".to_string(),
                            code: "external_workdir_unavailable".to_string(),
                            message: "External Workdir grant is unavailable".to_string(),
                        })?;
                    let grant_expired = external_workdir_grant_is_expired(&grant)?;
                    let online = api
                        .external_workdir_providers
                        .lock()
                        .expect("External Workdir provider registry poisoned")
                        .connection(grant_id)
                        .is_some_and(|connection| {
                            connection.generation == grant.generation
                                && connection.provider_instance_id == grant.provider_instance_id
                                && connection.workdir_id == workdir.workdir_id
                                && connection
                                    .expires_at
                                    .is_none_or(|expires_at| expires_at > Utc::now())
                        });
                    if grant.status != "online" || grant_expired || !online {
                        return Err(Error::RuntimeOperationFailed {
                            runtime_id: "external-workdir-provider".to_string(),
                            code: "external_workdir_unavailable".to_string(),
                            message: "External Workdir provider is offline or expired".to_string(),
                        }
                        .into());
                    }
                }
            }
            Ok(ticket_target_capabilities_for_workdir(
                &api, &worker, &workdir,
            )?)
        })
        .await?;
    let session_lock = current_worker_session_lock(&api, &worker);
    let _session_guard = Arc::new(session_lock.lock_owned().await);
    import_current_worker_workdir_observation(&api, &worker, Some(&_session_guard)).await?;
    let stage_worker = worker.clone();
    let stage_alias = alias.to_string();
    let stage_workdir_id = workdir_id.to_string();
    let existing =
        run_worker_workdir_db_stage_locked(&api, &_session_guard, move |api| -> ApiResult<_> {
            let existing = api
                .store
                .list_worker_workdir_links(&api.config.workspace_id, &stage_worker)?
                .into_iter()
                .find(|link| link.unlinked_at.is_none() && link.alias == stage_alias);
            if let Some(existing) = existing {
                if existing.workdir_id != stage_workdir_id {
                    return Err(Error::WorkdirAttachmentConflict(format!(
                    "Worker {}:{} attachment alias `{stage_alias}` is already bound to Workdir {}",
                    stage_worker.runtime_id, stage_worker.worker_id, existing.workdir_id
                )).into());
                }
                let effective_capabilities = existing.capabilities.intersection(capabilities);
                if effective_capabilities != existing.capabilities {
                    let mut attenuated = existing.clone();
                    attenuated.capabilities = effective_capabilities;
                    api.store.attach_worker_workdir(&attenuated)?;
                }
                Ok(Some((existing, effective_capabilities)))
            } else {
                Ok(None)
            }
        })
        .await?;
    if let Some((link, effective_capabilities)) = existing {
        sync_runtime_worker_workdir_attachments_locked(&api, &worker, &_session_guard).await?;
        api.worker_projection
            .refresh_async(&worker)
            .await
            .map_err(ApiError::from)?;
        return Ok(Json(server_api::CurrentWorkerWorkdirAttachmentResponse {
            workspace_id: api.config.workspace_id.clone(),
            alias: alias.to_string(),
            working_directory_id: workdir_id.to_string(),
            capabilities: effective_capabilities,
            environment: Some(
                current_worker_attachment_environment_locked(
                    &api,
                    &worker,
                    &link,
                    effective_capabilities,
                    false,
                    &_session_guard,
                )
                .await?,
            ),
            attached: true,
        }));
    }
    close_current_worker_attachment_session_locked(&api, &worker).await?;
    let new_link = WorkerWorkdirLinkRecord {
        connection_id: String::new(),
        workspace_id: api.config.workspace_id.clone(),
        worker: worker.clone(),
        workdir_id: workdir_id.to_string(),
        alias: alias.to_string(),
        capabilities,
        linked_at: Utc::now().to_rfc3339_opts(SecondsFormat::Nanos, true),
        unlinked_at: None,
    };
    let link = run_worker_workdir_db_stage_locked(&api, &_session_guard, move |api| {
        api.store.attach_worker_workdir(&new_link)
    })
    .await?;
    if let Err(error) =
        sync_runtime_worker_workdir_attachments_locked(&api, &worker, &_session_guard).await
    {
        let _ =
            detach_worker_workdir_stage_locked(&api, &worker, workdir_id, &_session_guard).await;
        return Err(error);
    }
    let environment = match current_worker_attachment_environment_locked(
        &api,
        &worker,
        &link,
        capabilities,
        true,
        &_session_guard,
    )
    .await
    {
        Ok(environment) => environment,
        Err(error) => {
            let _ = detach_worker_workdir_stage_locked(&api, &worker, workdir_id, &_session_guard)
                .await;
            let _ = sync_runtime_worker_workdir_attachments_locked(&api, &worker, &_session_guard)
                .await;
            return Err(error.into());
        }
    };
    if let Err(error) = api
        .worker_projection
        .refresh_async(&worker)
        .await
        .map_err(ApiError::from)
    {
        detach_worker_workdir_stage_locked(&api, &worker, workdir_id, &_session_guard).await?;
        sync_runtime_worker_workdir_attachments_locked(&api, &worker, &_session_guard).await?;
        refresh_current_worker_session_locked(&api, &worker, &_session_guard).await?;
        return Err(error);
    }
    Ok(Json(server_api::CurrentWorkerWorkdirAttachmentResponse {
        workspace_id: api.config.workspace_id.clone(),
        alias: alias.to_string(),
        working_directory_id: workdir_id.to_string(),
        capabilities,
        environment: Some(environment),
        attached: true,
    }))
}

#[cfg(test)]
fn list_current_worker_workdir_catalog(
    api: &WorkspaceApi,
    query: server_api::CurrentWorkerWorkdirCatalogQuery,
) -> ApiResult<server_api::CurrentWorkerWorkdirCatalogResponse> {
    list_current_worker_workdir_catalog_for_worker(
        api,
        &RuntimeWorkerRef::new("catalog-test", "ungranted"),
        query,
    )
}

fn list_current_worker_workdir_catalog_for_worker(
    api: &WorkspaceApi,
    worker: &RuntimeWorkerRef,
    query: server_api::CurrentWorkerWorkdirCatalogQuery,
) -> ApiResult<server_api::CurrentWorkerWorkdirCatalogResponse> {
    // No Runtime inventory refresh: both projection inputs and complete digest are authoritative
    // Backend records captured by the store in one read transaction.
    let page = api.store.workdir_catalog_page(
        &api.config.workspace_id,
        query.limit.unwrap_or(50),
        query.cursor.as_deref(),
    )?;
    let items = page
        .entries
        .into_iter()
        .filter_map(|entry| {
            if let WorkdirRegistrySource::WorkspaceConfig { grant_id } = &entry.record.source {
                if !workspace_config::granted_to(api, worker, grant_id) {
                    return None;
                }
                let grant = api
                    .store
                    .get_workspace_config_grant(&api.config.workspace_id, grant_id)
                    .ok()
                    .flatten()?;
                let mut summary = workspace_config::summary(&grant, &entry.record);
                summary.occupied_by = entry.occupied_by.map(Into::into);
                return Some(summary);
            }
            if matches!(
                entry.record.source,
                WorkdirRegistrySource::ExternalGrant { .. }
            ) && entry.external_grant_permissions.is_none()
            {
                return None;
            }
            let mut summary = workdir_summary_from_record(
                &entry.record,
                entry.repository_key.as_deref(),
                entry.external_grant_permissions,
            );
            summary.occupied_by = entry.occupied_by;
            Some(server_api::WorkingDirectorySummary::from(summary))
        })
        .collect();
    Ok(server_api::CurrentWorkerWorkdirCatalogResponse {
        workspace_id: api.config.workspace_id.clone(),
        items,
        next_cursor: page.next_cursor,
        digest: page.catalog_digest,
    })
}

fn list_current_worker_workdir_attachments(
    api: &WorkspaceApi,
    worker: &RuntimeWorkerRef,
    query: server_api::CurrentWorkerWorkdirAttachmentListQuery,
) -> ApiResult<server_api::CurrentWorkerWorkdirAttachmentListResponse> {
    let limit = query.limit.unwrap_or(50);
    let offset = query.offset.unwrap_or(0);
    if limit == 0 || limit > 100 {
        return Err(
            Error::InvalidInput("attachment page limit must be 1..=100".to_string()).into(),
        );
    }
    let (mut links, digest) = api.store.list_worker_workdir_links_page_with_digest(
        &api.config.workspace_id,
        worker,
        limit + 1,
        offset,
        query.connection_id.as_deref(),
    )?;
    let next_offset =
        if links.len() > limit as usize {
            Some(offset.checked_add(limit).ok_or_else(|| {
                Error::InvalidInput("attachment page offset overflow".to_string())
            })?)
        } else {
            None
        };
    links.truncate(limit as usize);
    Ok(server_api::CurrentWorkerWorkdirAttachmentListResponse {
        workspace_id: api.config.workspace_id.clone(),
        items: links
            .into_iter()
            .map(|link| server_api::CurrentWorkerWorkdirAttachmentItem {
                alias: link.alias,
                working_directory_id: link.workdir_id,
                capabilities: link.capabilities,
                connection_id: link.connection_id,
            })
            .collect(),
        next_offset,
        digest,
    })
}

async fn scoped_detach_current_worker_workdir(
    State(api): State<WorkspaceApi>,
    AxumPath((workspace_id, alias)): AxumPath<(String, String)>,
    headers: HeaderMap,
    query: server_api::CurrentWorkerWorkdirDetachQuery,
) -> ApiResult<Json<server_api::CurrentWorkerWorkdirAttachmentResponse>> {
    validate_workspace_scope(&api, &workspace_id)?;
    let alias = workdir::WorkdirAttachmentAlias::new(alias)
        .map_err(|error| Error::InvalidInput(error.to_string()))?;
    let stage_api = api.clone();
    let worker = api
        .host_executors
        .host()?
        .run(move || current_worker_identity(&stage_api, &workspace_id, &headers))
        .await?;
    detach_current_worker_workdir(
        &api,
        &worker,
        alias.as_str(),
        query.expected_connection_id.as_deref(),
    )
    .await
    .map(Json)
}

async fn restore_worker_workdir_connection_stage_locked(
    api: &WorkspaceApi,
    link: &WorkerWorkdirLinkRecord,
    session_guard: &Arc<tokio::sync::OwnedMutexGuard<()>>,
) -> Result<()> {
    let link = link.clone();
    run_worker_workdir_db_stage_locked(api, session_guard, move |api| {
        api.store.restore_worker_workdir_connection(&link)
    })
    .await
}

async fn detach_current_worker_workdir(
    api: &WorkspaceApi,
    worker: &RuntimeWorkerRef,
    alias: &str,
    expected_connection_id: Option<&str>,
) -> ApiResult<server_api::CurrentWorkerWorkdirAttachmentResponse> {
    let session_lock = current_worker_session_lock(api, worker);
    let _session_guard = Arc::new(session_lock.lock_owned().await);
    let stage_api = api.clone();
    let stage_worker = worker.clone();
    let stage_alias = alias.to_string();
    let expected_connection_id = expected_connection_id.map(str::to_string);
    let link = api
        .store
        .db_executor()
        .run(move || -> ApiResult<_> {
            let link = stage_api
                .store
                .list_worker_workdir_links(&stage_api.config.workspace_id, &stage_worker)?
                .into_iter()
                .find(|link| link.unlinked_at.is_none() && link.alias == stage_alias)
                .ok_or_else(|| {
                    Error::WorkdirAttachmentConflict(format!(
                        "Worker {}:{} has no Workdir attachment `{stage_alias}`",
                        stage_worker.runtime_id, stage_worker.worker_id
                    ))
                })?;
            if expected_connection_id
                .as_ref()
                .is_some_and(|expected| *expected != link.connection_id)
            {
                return Err(Error::WorkdirAttachmentConflict(format!(
                    "Workdir attachment `{stage_alias}` connection changed during detach"
                ))
                .into());
            }
            Ok(link)
        })
        .await?;
    close_current_worker_attachment_session_locked(api, worker).await?;
    close_current_worker_command_sessions_for_alias_locked(api, worker, alias).await?;
    // Even unconditional HTTP requests condition the mutation on the lifetime just read
    // under the session lock, so a concurrent ledger replacement cannot be removed.
    let stage_link = link.clone();
    run_worker_workdir_db_stage_locked(api, &_session_guard, move |api| {
        api.store.detach_worker_workdir_connection(
            &api.config.workspace_id,
            &stage_link.worker,
            &stage_link.alias,
            &stage_link.connection_id,
            &Utc::now().to_rfc3339_opts(SecondsFormat::Millis, true),
        )
    })
    .await?;
    if let Err(error) =
        sync_runtime_worker_workdir_attachments_locked(api, worker, &_session_guard).await
    {
        restore_worker_workdir_connection_stage_locked(api, &link, &_session_guard).await?;
        return Err(error);
    }
    let stage_api = api.clone();
    let stage_worker = worker.clone();
    let remaining = api
        .store
        .db_executor()
        .run(move || active_filesystem_workdir_links(&stage_api, &stage_worker))
        .await?;
    if remaining.len() == 1
        && let Err(error) =
            open_current_worker_workdir_session_locked(api, worker, &remaining[0], &_session_guard)
                .await
    {
        restore_worker_workdir_connection_stage_locked(api, &link, &_session_guard).await?;
        let _ = sync_runtime_worker_workdir_attachments_locked(api, worker, &_session_guard).await;
        return Err(error.into());
    }
    if let Err(error) = api
        .worker_projection
        .refresh_async(&worker)
        .await
        .map_err(ApiError::from)
    {
        restore_worker_workdir_connection_stage_locked(api, &link, &_session_guard).await?;
        sync_runtime_worker_workdir_attachments_locked(api, worker, &_session_guard).await?;
        refresh_current_worker_session_locked(api, worker, &_session_guard).await?;
        return Err(error);
    }
    Ok(server_api::CurrentWorkerWorkdirAttachmentResponse {
        workspace_id: api.config.workspace_id.clone(),
        alias: alias.to_string(),
        working_directory_id: link.workdir_id,
        capabilities: workdir::WorkdirSessionCapabilities::EMPTY,
        environment: None,
        attached: false,
    })
}

async fn validated_current_worker_attachment_async(
    api: &WorkspaceApi,
    worker: &RuntimeWorkerRef,
    target_workdir: &str,
    session_guard: Option<&Arc<tokio::sync::OwnedMutexGuard<()>>>,
) -> ApiResult<WorkerWorkdirLinkRecord> {
    for imported in [false, true] {
        let stage_api = api.clone();
        let stage_worker = worker.clone();
        let stage_alias = target_workdir.to_string();
        let link = api
            .store
            .db_executor()
            .run(move || -> Result<_> {
                Ok(stage_api
                    .store
                    .list_worker_workdir_links(&stage_api.config.workspace_id, &stage_worker)?
                    .into_iter()
                    .find(|link| link.unlinked_at.is_none() && link.alias == stage_alias))
            })
            .await?;
        if let Some(link) = link {
            return Ok(link);
        }
        if !imported {
            // A Runtime may start the Worker before the outer spawn handler
            // projects its reserved aliases. Import that exact set only once.
            import_current_worker_workdir_observation(api, worker, session_guard).await?;
        }
    }
    Err(Error::WorkdirAttachmentConflict(format!(
        "Worker {}:{} has no Workdir attachment alias `{target_workdir}`",
        worker.runtime_id, worker.worker_id
    ))
    .into())
}

#[derive(Debug)]
enum InternalWorkdirOperationError {
    Api(ApiError),
    Provider(WorkdirTransportError),
    Contextual {
        error: Box<InternalWorkdirOperationError>,
        context: server_api::WorkdirOperationLogContext,
    },
}

impl InternalWorkdirOperationError {
    fn into_contract_error(self) -> server_api::WorkdirOperationApiError {
        match self {
            Self::Api(error) => {
                let reason = match &error.error {
                    Error::WorkdirSessionOpenFailed { transport, .. } => transport.denial_reason,
                    _ => None,
                };
                let failure_reason = match &error.error {
                    Error::WorkdirSessionOpenFailed { transport, .. } => transport.failure_reason,
                    _ => None,
                };
                let mut error =
                    server_api::WorkdirOperationApiError::api(error.into_repository_api_error());
                error.denial_reason = reason;
                error.failure_reason = failure_reason;
                error
            }
            Self::Provider(error) => server_api::WorkdirOperationApiError::provider(error),
            Self::Contextual { error, context } => {
                let mut error = error.into_contract_error();
                error.workdir_log = Some(context);
                error
            }
        }
    }
}

impl From<ApiError> for InternalWorkdirOperationError {
    fn from(error: ApiError) -> Self {
        Self::Api(error)
    }
}

impl From<Error> for InternalWorkdirOperationError {
    fn from(error: Error) -> Self {
        Self::Api(error.into())
    }
}

impl From<WorkdirTransportError> for InternalWorkdirOperationError {
    fn from(error: WorkdirTransportError) -> Self {
        Self::Provider(error)
    }
}

impl IntoResponse for InternalWorkdirOperationError {
    fn into_response(self) -> Response {
        let error = self.into_contract_error();
        let status = StatusCode::from_u16(api_macros::HttpError::status_code(&error))
            .expect("Workdir error status is valid");
        let log = ApiErrorLog::from_workdir_operation_error(&error, status);
        let mut response = (status, Json(error)).into_response();
        response.extensions_mut().insert(log);
        response
    }
}

fn workdir_operation_label(operation: &WorkdirSessionOperation) -> &'static str {
    match operation {
        WorkdirSessionOperation::AuthorizeScope(_) => "authorize_scope",
        WorkdirSessionOperation::ScopeRulesOverlap(_) => "scope_rules_overlap",
        WorkdirSessionOperation::CheckoutSearch(_) => "checkout_search",
        WorkdirSessionOperation::CheckoutObserve(_) => "checkout_observe",
        WorkdirSessionOperation::CheckoutExecute(_) => "checkout_execute",
        WorkdirSessionOperation::Stat(_) => "stat",
        WorkdirSessionOperation::Read(_) => "read",
        WorkdirSessionOperation::ReadBytes(_) => "read_bytes",
        WorkdirSessionOperation::Write(_) => "write",
        WorkdirSessionOperation::Edit(_) => "edit",
        WorkdirSessionOperation::List(_) => "list",
        WorkdirSessionOperation::Glob(_) => "glob",
        WorkdirSessionOperation::Grep(_) => "grep",
        WorkdirSessionOperation::CommandStart(_) => "command_start",
        WorkdirSessionOperation::CommandStatus(_) => "command_status",
        WorkdirSessionOperation::CommandOutput(_) => "command_output",
        WorkdirSessionOperation::CommandCancel(_) => "command_cancel",
    }
}

async fn scoped_execute_current_worker_workdir_operation(
    State(api): State<WorkspaceApi>,
    AxumPath(path): AxumPath<ScopedWorkspacePath>,
    headers: HeaderMap,
    Json(request): Json<WorkspaceWorkdirSessionOperationRequest>,
) -> std::result::Result<Json<WorkdirSessionOperationResult>, InternalWorkdirOperationError> {
    let mut context = server_api::WorkdirOperationLogContext {
        operation: workdir_operation_label(&request.operation),
        workspace_id_hash: crate::worker_source::diagnostic_id_hash(&path.workspace_id),
        attachment_alias_hash: crate::worker_source::diagnostic_id_hash(&request.target_workdir),
        ..Default::default()
    };
    let result = async {
    context.stage = "workspace_scope";
    validate_workspace_scope(&api, &path.workspace_id)?;
    context.stage = "worker_identity";
    let stage_api = api.clone();
    let worker = api.host_executors.host()?.run(move || {
        current_worker_identity(&stage_api, &path.workspace_id, &headers)
    }).await?;
    context.runtime_id_hash = Some(crate::worker_source::diagnostic_id_hash(&worker.runtime_id));
    context.worker_id_hash = Some(crate::worker_source::diagnostic_id_hash(&worker.worker_id));
    let target_workdir = request.target_workdir;
    context.stage = "attachment_validation";
    let permission_link = validated_current_worker_attachment_async(&api, &worker, &target_workdir, None).await?;
    context.workdir_id_hash = Some(crate::worker_source::diagnostic_id_hash(&permission_link.workdir_id));
    context.stage = "operation_authorization";
    workdir_authorization::authorize(&api, &worker, &permission_link, &request.operation)?;
    let result = match request.operation {
        WorkdirSessionOperation::CommandStart(command) => {
            let session_lock = current_worker_session_lock(&api, &worker);
            let _session_guard = Arc::new(session_lock.lock_owned().await);
            context.stage = "attachment_validation";
            let link = validated_current_worker_attachment_async(
                &api, &worker, &target_workdir, Some(&_session_guard),
            ).await?;
            context.workdir_id_hash = Some(crate::worker_source::diagnostic_id_hash(&link.workdir_id));
            if api.workdir_sessions.lock().unwrap().active_command_count(&worker) >= MAX_ACTIVE_SERVER_COMMANDS {
                return Err(InternalWorkdirOperationError::Provider(workdir_operation_transport_error(workdir::WorkdirError::Unavailable("Worker active command limit reached".to_string()))));
            }
            context.stage = "session_open";
            let source = open_current_worker_workdir_session_locked(&api, &worker, &link, &_session_guard).await?;
            context.stage = "provider_dispatch";
            let provider_handle = source
                .start_command(command)
                .await
                .map_err(workdir_operation_transport_error)?;
            context.stage = "command_registration";
            let registered_source = api
                .workdir_sessions
                .lock()
                .expect("Workdir session registry lock poisoned")
                .remove_attachment(&worker)
                .ok_or_else(|| Error::RuntimeOperationFailed {
                    runtime_id: worker.runtime_id.clone(),
                    code: "workdir_session_registration_failed".to_string(),
                    message: "started command session was not registered as the active attachment session"
                        .to_string(),
                })?;
            let external_handle = api
                .workdir_sessions
                .lock()
                .expect("Workdir session registry lock poisoned")
                .register_command(
                    worker.clone(),
                    target_workdir.clone(),
                    registered_source,
                    provider_handle,
                );
            WorkdirSessionOperationResult::CommandStart(external_handle)
        }
        WorkdirSessionOperation::CommandStatus(external_handle) => {
            let (session, provider_handle) =
                current_worker_command_session(&api, &worker, &target_workdir, &external_handle, &mut context).await?;
            session
                .command_status(provider_handle)
                .await
                .map(WorkdirSessionOperationResult::CommandStatus)
                .map_err(workdir_operation_transport_error)?
        }
        WorkdirSessionOperation::CommandOutput(mut output) => {
            let external_handle = output.handle.clone();
            let (session, provider_handle) =
                current_worker_command_session(&api, &worker, &target_workdir, &external_handle, &mut context).await?;
            output.handle = provider_handle;
            let page = session.command_output(output).await.map_err(workdir_operation_transport_error)?;
            if page.terminal.is_some() {
                // Retain the binding for a retry after an unknown HTTP outcome.
                api.workdir_sessions.lock().unwrap().mark_terminal(&worker, &external_handle);
            }
            WorkdirSessionOperationResult::CommandOutput(page)
        }
        WorkdirSessionOperation::CommandCancel(external_handle) => {
            let (session, provider_handle) =
                current_worker_command_session(&api, &worker, &target_workdir, &external_handle, &mut context).await?;
            session
                .cancel_command(provider_handle)
                .await
                .map(|()| WorkdirSessionOperationResult::CommandCancel)
                .map_err(workdir_operation_transport_error)?
        }
        operation @ (WorkdirSessionOperation::AuthorizeScope(_)
        | WorkdirSessionOperation::ScopeRulesOverlap(_)
        | WorkdirSessionOperation::CheckoutObserve(_)
        | WorkdirSessionOperation::CheckoutExecute(_)
        | WorkdirSessionOperation::CheckoutSearch(_)
        | WorkdirSessionOperation::Stat(_)
        | WorkdirSessionOperation::Read(_)
        | WorkdirSessionOperation::ReadBytes(_)
        | WorkdirSessionOperation::Write(_)
        | WorkdirSessionOperation::Edit(_)
        | WorkdirSessionOperation::List(_)
        | WorkdirSessionOperation::Glob(_)
        | WorkdirSessionOperation::Grep(_)) => {
            let session_lock = current_worker_session_lock(&api, &worker);
            let _session_guard = Arc::new(session_lock.lock_owned().await);
            context.stage = "attachment_validation";
            let link = validated_current_worker_attachment_async(
                &api, &worker, &target_workdir, Some(&_session_guard),
            ).await?;
            context.workdir_id_hash = Some(crate::worker_source::diagnostic_id_hash(&link.workdir_id));
            context.stage = "session_open";
            let source = open_current_worker_workdir_session_locked(&api, &worker, &link, &_session_guard).await?;
            context.stage = "provider_dispatch";
            let source = worker::authorized_workdir::authorized_workdir_session(source, subject_authorization::bind_operation_client(&api, &worker), link.workdir_id.clone());
            execute_workdir_session_operation(&source, operation)
                .await
                .map_err(workdir_operation_transport_error)?
        }
    };
    Ok(Json(result))
    }.await;
    result.map_err(|error| InternalWorkdirOperationError::Contextual {
        error: Box::new(error),
        context,
    })
}

async fn current_worker_command_session(
    api: &WorkspaceApi,
    worker: &RuntimeWorkerRef,
    target_workdir: &str,
    external_handle: &CommandHandle,
    context: &mut server_api::WorkdirOperationLogContext,
) -> std::result::Result<(WorkdirSessionHandle, CommandHandle), InternalWorkdirOperationError> {
    context.stage = "attachment_validation";
    let link = validated_current_worker_attachment_async(api, worker, target_workdir, None).await?;
    context.workdir_id_hash = Some(crate::worker_source::diagnostic_id_hash(&link.workdir_id));
    context.stage = "command_lookup";
    let command = api
        .workdir_sessions
        .lock()
        .expect("Workdir session registry lock poisoned")
        .command(worker, target_workdir, external_handle)
        .ok_or_else(|| {
            InternalWorkdirOperationError::Provider(workdir_operation_transport_error(
                workdir::WorkdirError::UnknownCommand(external_handle.0.clone()),
            ))
        })?;
    context.stage = "provider_dispatch";
    Ok((command.source, command.provider_handle))
}

fn workdir_operation_transport_error(error: workdir::WorkdirError) -> WorkdirTransportError {
    WorkdirTransportError::from_workdir_error(&error)
}

async fn execute_workdir_session_operation(
    session: &WorkdirSessionHandle,
    operation: WorkdirSessionOperation,
) -> std::result::Result<WorkdirSessionOperationResult, workdir::WorkdirError> {
    match operation {
        WorkdirSessionOperation::AuthorizeScope(request) => session
            .authorize_scope_path(request)
            .await
            .map(|()| WorkdirSessionOperationResult::AuthorizeScope),
        WorkdirSessionOperation::ScopeRulesOverlap(request) => session
            .scope_rules_overlap(request)
            .await
            .map(|overlaps| WorkdirSessionOperationResult::ScopeRulesOverlap { overlaps }),
        WorkdirSessionOperation::CheckoutObserve(path) => session
            .checkout_observe(path)
            .await
            .map(WorkdirSessionOperationResult::CheckoutObserve),
        WorkdirSessionOperation::CheckoutExecute(request) => session
            .checkout_execute(request)
            .await
            .map(WorkdirSessionOperationResult::CheckoutExecute),
        WorkdirSessionOperation::CheckoutSearch(request) => session
            .checkout_search(request)
            .await
            .map(WorkdirSessionOperationResult::CheckoutSearch),
        WorkdirSessionOperation::Stat(request) => session
            .stat(request)
            .await
            .map(WorkdirSessionOperationResult::Stat),
        WorkdirSessionOperation::Read(request) => session
            .read(request)
            .await
            .map(WorkdirSessionOperationResult::Read),
        WorkdirSessionOperation::ReadBytes(request) => session
            .read_bytes(request)
            .await
            .map(WorkdirSessionOperationResult::ReadBytes),
        WorkdirSessionOperation::Write(request) => session
            .write(request)
            .await
            .map(WorkdirSessionOperationResult::Write),
        WorkdirSessionOperation::Edit(request) => session
            .edit(request)
            .await
            .map(WorkdirSessionOperationResult::Edit),
        WorkdirSessionOperation::List(request) => session
            .list(request)
            .await
            .map(WorkdirSessionOperationResult::List),
        WorkdirSessionOperation::Glob(request) => session
            .glob(request)
            .await
            .map(WorkdirSessionOperationResult::Glob),
        WorkdirSessionOperation::Grep(request) => session
            .grep(request)
            .await
            .map(WorkdirSessionOperationResult::Grep),
        WorkdirSessionOperation::CommandStart(request) => session
            .start_command(request)
            .await
            .map(WorkdirSessionOperationResult::CommandStart),
        WorkdirSessionOperation::CommandStatus(handle) => session
            .command_status(handle)
            .await
            .map(WorkdirSessionOperationResult::CommandStatus),
        WorkdirSessionOperation::CommandOutput(request) => session
            .command_output(request)
            .await
            .map(WorkdirSessionOperationResult::CommandOutput),
        WorkdirSessionOperation::CommandCancel(handle) => session
            .cancel_command(handle)
            .await
            .map(|()| WorkdirSessionOperationResult::CommandCancel),
    }
}

async fn run_orchestrator_turn_end_hook(api: WorkspaceApi) {
    // Fixed, bounded recovery independent of unrelated Ticket updates. A missed
    // tick is skipped rather than accumulated; rounds do not overlap on this owner.
    let mut recovery = tokio::time::interval(std::time::Duration::from_secs(30));
    recovery.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
    let mut subscription: Option<crate::runtime_subscription::BrokerSubscription> = None;
    let mut worker_states = HashMap::new();
    loop {
        let update = tokio::select! {
            _ = recovery.tick() => {
                if subscription.is_none() {
                    subscription = api.runtime_subscription_broker.subscribe(
                        EMBEDDED_WORKER_RUNTIME_ID,
                        protocol::subscription::EventSubscriptionSelector::RuntimeWorkers,
                    ).ok();
                }
                None
            }
            update = async {
                match subscription.as_mut() {
                    Some(subscription) => subscription.recv().await,
                    None => std::future::pending().await,
                }
            } => {
                if update.is_none() { subscription = None; }
                update
            }
        };
        let stage_api = api.clone();
        let states = std::mem::take(&mut worker_states);
        let result = match api.host_executors.host() {
            Ok(executor) => {
                executor
                    .run(move || -> Result<_> {
                        let mut states = states;
                        let keep_subscription = if let Some(update) = update {
                            observe_orchestrator_turn_end(&stage_api, &mut states, update)
                        } else {
                            recover_ticket_notifications(&stage_api);
                            true
                        };
                        Ok((keep_subscription, states))
                    })
                    .await
            }
            Err(error) => Err(error),
        };
        match result {
            Ok((keep_subscription, states)) => {
                worker_states = states;
                if !keep_subscription {
                    subscription = None;
                }
            }
            Err(error) => {
                tracing::warn!(%error, "notification recovery round failed; retry on the next bounded tick");
            }
        }
    }
}

// A subscription snapshot establishes an observation baseline, not a lifecycle
// event. Reconnection deliberately discards the old baseline.
fn observe_orchestrator_turn_end(
    api: &WorkspaceApi,
    worker_states: &mut HashMap<String, protocol::subscription::SubscriptionWorkerState>,
    update: crate::runtime_subscription::BrokerSubscriptionEvent,
) -> bool {
    match update {
        crate::runtime_subscription::BrokerSubscriptionEvent::Snapshot { snapshot, .. } => {
            if let protocol::subscription::SubscriptionSnapshot::Workers { workers } = snapshot {
                worker_states.clear();
                for worker in workers {
                    let worker_id = worker.worker_id.to_string();
                    worker_states.insert(worker_id, worker.state);
                }
            }
        }
        crate::runtime_subscription::BrokerSubscriptionEvent::Event { payload, .. } => {
            match payload {
                protocol::subscription::SubscriptionEventPayload::WorkerUpserted { worker } => {
                    let worker_id = worker.worker_id.to_string();
                    let previous = worker_states.insert(worker_id.clone(), worker.state);
                    maybe_dispatch_orchestrator_turn_end(api, &worker_id, previous, worker.state);
                }
                protocol::subscription::SubscriptionEventPayload::WorkerRemoved {
                    worker_id,
                    ..
                } => {
                    worker_states.remove(worker_id.as_str());
                }
                _ => {}
            }
        }
        crate::runtime_subscription::BrokerSubscriptionEvent::Disconnected { .. } => {
            worker_states.clear();
        }
        crate::runtime_subscription::BrokerSubscriptionEvent::Rejected { .. }
        | crate::runtime_subscription::BrokerSubscriptionEvent::Closed { .. } => return false,
    }
    true
}

fn maybe_dispatch_orchestrator_turn_end(
    api: &WorkspaceApi,
    worker_id: &str,
    previous: Option<protocol::subscription::SubscriptionWorkerState>,
    current: protocol::subscription::SubscriptionWorkerState,
) {
    use protocol::subscription::SubscriptionWorkerState;

    if current != SubscriptionWorkerState::Idle
        || previous != Some(SubscriptionWorkerState::Running)
    {
        return;
    }
    let Some(orchestrator) = find_workspace_orchestrator(api) else {
        return;
    };
    if orchestrator.worker.runtime_id == EMBEDDED_WORKER_RUNTIME_ID
        && orchestrator.worker.worker_id == worker_id
    {
        // Idle can be a reentrant consequence of this very Runtime send. It is
        // not evidence of a new input and must not retry a failed send forever.
        // Concurrent committed-input notifications independently defer a check.
        with_orchestrator_attention_reservation(
            api,
            &orchestrator.worker,
            false,
            |state, pending| {
                check_orchestrator_assignment_attention(api, &orchestrator.worker, state, pending);
            },
        );
    }
}

fn enqueue_orchestrator_assignment_attention(
    api: &WorkspaceApi,
) -> Option<tokio::sync::oneshot::Receiver<()>> {
    let api = api.clone();
    let (done, completion) = tokio::sync::oneshot::channel();
    match api.host_executors.host().and_then(|executor| {
        executor.dispatch(move || {
            recover_ticket_notifications(&api);
            let _ = done.send(());
        })
    }) {
        Ok(()) => Some(completion),
        Err(error) => {
            tracing::warn!(%error, "Assign notification was not admitted; input remains durable");
            None
        }
    }
}

fn dispatch_orchestrator_assignment_attention(api: &WorkspaceApi, worker: &RuntimeWorkerRef) {
    with_orchestrator_attention_reservation(api, worker, true, |state, pending| {
        check_orchestrator_assignment_attention(api, worker, state, pending);
    });
}

/// Process-local send exclusion is not backlog authority. Coalesce committed-input/startup/
/// Restore triggers during a scan and drain them on release, even after an empty snapshot or
/// accepted pending retry. Reentrant idle observations must not loop on a failed send. Losing
/// this cache loses no delegation; the durable scan recovers only unacknowledged inputs.
fn with_orchestrator_attention_reservation(
    api: &WorkspaceApi,
    worker: &RuntimeWorkerRef,
    defer_input_check_if_reserved: bool,
    mut check: impl FnMut(
        &Arc<Mutex<OrchestratorAttentionState>>,
        Option<OrchestratorAttentionDelivery>,
    ),
) {
    let Some(_permit) = api.notification_delivery_lifecycle.begin() else {
        return;
    };
    let state = orchestrator_attention_state(api, worker);
    loop {
        let pending = {
            let mut state = state.lock().unwrap_or_else(|p| p.into_inner());
            if state.sending {
                // A no-op scan may already have read its empty snapshot. Retain
                // committed input/startup/Restore triggers until its completion.
                state.input_recheck |= defer_input_check_if_reserved;
                return;
            }
            state.sending = true;
            state.pending.clone()
        };
        let reservation = OrchestratorAttentionReservation(Some(state.clone()));
        check(&state, pending);
        if !reservation.complete() {
            return;
        }
        // Drain coalesced input triggers even when the first scan was a no-op.
        // No recheck is created by a failed send or its own idle observation.
    }
}

fn orchestrator_delivery_target(
    api: &WorkspaceApi,
    worker: &RuntimeWorkerRef,
) -> Result<ticket::TicketAssignmentTrackingSourceContext> {
    if !find_online_workspace_orchestrator(api).is_some_and(|current| current.worker == *worker) {
        return Err(Error::WorkspacePermissionDenied(
            "Delivery target is not the current registered Orchestrator".into(),
        ));
    }
    let binding = api
        .config_store
        .get_workspace_runtime_binding(&api.config.workspace_id, &worker.runtime_id)?
        .filter(|binding| binding.revoked_at.is_none())
        .ok_or_else(|| {
            Error::WorkspacePermissionDenied("Delivery target has no active Runtime binding".into())
        })?;
    Ok(ticket::TicketAssignmentTrackingSourceContext {
        actor: "backend:assignment-delivery".into(),
        runtime_id: worker.runtime_id.clone(),
        worker_id: worker.worker_id.clone(),
        agent_key: "workspace-orchestrator".into(),
        authentication_binding_id: binding.binding_id,
    })
}

fn check_orchestrator_assignment_attention(
    api: &WorkspaceApi,
    worker: &RuntimeWorkerRef,
    state: &Arc<Mutex<OrchestratorAttentionState>>,
    pending: Option<OrchestratorAttentionDelivery>,
) {
    let inputs = match api
        .store
        .list_pending_ticket_assignment_deliveries(&api.config.workspace_id, 20)
    {
        Ok(inputs) => inputs,
        Err(error) => {
            tracing::warn!(%error, "assignment notification scan failed");
            return;
        }
    };
    let target = match orchestrator_delivery_target(api, worker) {
        Ok(target) => target,
        Err(_) => {
            for input in inputs {
                record_notification_failure(
                    api,
                    &assignment_delivery_key(&input),
                    notification_delivery::orchestrator_target_failure(api, worker),
                );
            }
            return;
        }
    };
    let retried_id = pending
        .as_ref()
        .map(|delivery| delivery.input.delivery_id.clone());
    if let Some(delivery) = pending {
        // The saved bytes are useful on retry, but process memory is never backlog authority.
        send_orchestrator_attention(api, worker, state, delivery);
    }
    for input in inputs {
        if api.notification_delivery_lifecycle.stopped() {
            break;
        }
        if retried_id.as_deref() == Some(&input.delivery_id) {
            continue;
        }
        let key = assignment_delivery_key(&input);
        let input = match api.store.reserve_ticket_assignment_delivery(
            &api.config.workspace_id,
            &input.assignment_id,
            &input.input_event_id,
            &target,
        ) {
            Ok(input) => input,
            Err(error) => {
                record_notification_failure(
                    api,
                    &key,
                    match error {
                        Error::TicketAssignmentConflict(_) => {
                            NotificationFailureCode::AssignmentChanged
                        }
                        _ => NotificationFailureCode::PreparationFailed,
                    },
                );
                continue;
            }
        };
        let config_state = match api
            .config_store
            .load_workspace_config(&api.config.workspace_id)
        {
            Ok(Some(config)) => config,
            _ => {
                record_notification_failure(
                    api,
                    &key,
                    NotificationFailureCode::ConfigurationUnavailable,
                );
                continue;
            }
        };
        let catalog = api
            .prompt_projection_cache
            .resolve(&api.config.workspace_id, &config_state)
            .and_then(|projection| {
                worker::PromptCatalog::from_projection(projection.catalog().clone())
                    .map_err(|error| Error::Config(error.to_string()))
            });
        let catalog = match catalog {
            Ok(catalog) => catalog,
            Err(_) => {
                record_notification_failure(
                    api,
                    &key,
                    NotificationFailureCode::ConfigurationUnavailable,
                );
                continue;
            }
        };
        let ticket = match api.authority.ticket(&input.ticket_id) {
            Ok(ticket) => ticket,
            Err(_) => {
                record_notification_failure(api, &key, NotificationFailureCode::SourceLookupFailed);
                continue;
            }
        };
        let projected = match worker::OrchestratorQueueAttentionTicket::new(
            ticket.resource_key,
            ticket.title,
        ) {
            Ok(ticket) => ticket,
            Err(_) => {
                record_notification_failure(api, &key, NotificationFailureCode::SourceLookupFailed);
                continue;
            }
        };
        let context =
            worker::OrchestratorQueueAttentionContext::new(vec![projected.with_assignment_input(
                &input.assignment_id,
                &input.input_event_id,
                input.waiting_reason.as_deref(),
                input.next_action.as_deref(),
            )]);
        let content = match catalog.orchestrator_queue_attention(
            worker::OrchestratorQueueAttentionPrompt::Server,
            &context,
        ) {
            Ok(content) => content,
            Err(_) => {
                record_notification_failure(api, &key, NotificationFailureCode::RenderingFailed);
                continue;
            }
        };
        let content = match api.store.prepare_ticket_assignment_delivery_content(
            &api.config.workspace_id,
            &input.delivery_id,
            &content,
            &target,
        ) {
            Ok(content) => content,
            Err(_) => {
                record_notification_failure(api, &key, NotificationFailureCode::PreparationFailed);
                continue;
            }
        };
        let delivery = OrchestratorAttentionDelivery {
            fingerprint: input.delivery_id.clone(),
            request_id: input.request_id.clone(),
            content,
            input,
        };
        state.lock().unwrap_or_else(|p| p.into_inner()).pending = Some(delivery.clone());
        send_orchestrator_attention(api, worker, state, delivery);
        // Continue other recipients/inputs even after a failure. Unacknowledged
        // requests remain in SQLite, including those not kept in this small cache.
    }
}

fn send_orchestrator_attention(
    api: &WorkspaceApi,
    worker: &RuntimeWorkerRef,
    state: &Mutex<OrchestratorAttentionState>,
    delivery: OrchestratorAttentionDelivery,
) {
    tracing::debug!(delivery_id = %delivery.fingerprint, assignment_id = %delivery.input.assignment_id, "dispatch committed assignment input");
    let key = assignment_delivery_key(&delivery.input);
    for _ in 0..2 {
        if api.notification_delivery_lifecycle.stopped() {
            return;
        }
        let target = match orchestrator_delivery_target(api, worker) {
            Ok(target) => target,
            Err(_) => {
                record_notification_failure(
                    api,
                    &key,
                    notification_delivery::orchestrator_target_failure(api, worker),
                );
                return;
            }
        };
        if let Err(error) = api.store.reserve_ticket_assignment_delivery(
            &api.config.workspace_id,
            &delivery.input.assignment_id,
            &delivery.input.input_event_id,
            &target,
        ) {
            record_notification_failure(
                api,
                &key,
                match error {
                    Error::TicketAssignmentConflict(_) => {
                        NotificationFailureCode::AssignmentChanged
                    }
                    _ => NotificationFailureCode::PreparationFailed,
                },
            );
            state.lock().unwrap_or_else(|p| p.into_inner()).pending = None;
            return;
        }
        let result = api.runtime.send_input(
            worker,
            WorkerInputRequest {
                kind: WorkerInputKind::Notify,
                content: delivery.content.clone(),
                submission_request_id: Some(delivery.request_id.clone()),
                segments: None,
            },
        );
        if notification_delivery::notification_failure(&result).is_none() {
            if api
                .store
                .ack_ticket_assignment_delivery(
                    &api.config.workspace_id,
                    &delivery.input.delivery_id,
                    &target,
                )
                .is_ok()
            {
                let mut state = state.lock().unwrap_or_else(|p| p.into_inner());
                state.accepted = Some(delivery);
                state.pending = None;
            } else {
                record_notification_failure(
                    api,
                    &key,
                    NotificationFailureCode::AcknowledgementFailed,
                );
            }
            return;
        }
        let failure = notification_delivery::notification_failure(&result)
            .expect("non-accepted delivery has a classified failure");
        record_notification_failure(api, &key, failure);
        if let Some(error_category) = ticket_notification_delivery_error_category(&result) {
            tracing::warn!(
                event = "ticket_assignment_delivery_pending",
                workspace_id = %api.config.workspace_id,
                assignment_id = %delivery.input.assignment_id,
                input_event_id = %delivery.input.input_event_id,
                delivery_id = %delivery.input.delivery_id,
                recipient_runtime_id = %worker.runtime_id,
                recipient_worker_id = %worker.worker_id,
                error_category,
                "committed delegation input remains pending; retry the saved request"
            );
            emit_ticket_notification_delivery_warning(TicketNotificationDeliveryWarning::new(
                &api.config.workspace_id,
                &delivery.input.ticket_id,
                "open",
                worker,
                error_category,
            ));
        }
    }
}

#[cfg(test)]
fn orchestrator_queue_attention_context(
    expected_workspace_id: &str,
    candidate_workspace_id: &str,
    tickets: &[ticket::TicketSummary],
) -> std::result::Result<worker::OrchestratorQueueAttentionContext, &'static str> {
    if candidate_workspace_id != expected_workspace_id {
        return Err("foreign_workspace_ticket_projection");
    }
    let tickets = tickets
        .iter()
        .map(|ticket| {
            let resource_key = ticket
                .resource_key
                .clone()
                .ok_or("missing_ticket_resource_key")?;
            worker::OrchestratorQueueAttentionTicket::new(resource_key, ticket.title.clone())
                .map_err(|_| "invalid_ticket_resource_key")
        })
        .collect::<std::result::Result<Vec<_>, _>>()?;
    Ok(worker::OrchestratorQueueAttentionContext::new(tickets))
}

fn require_online_workspace_orchestrator_source(
    api: &WorkspaceApi,
    source: &WorkerMutationSource,
) -> Result<()> {
    let orchestrator = find_online_workspace_orchestrator(api).ok_or_else(|| {
        Error::TicketAssignmentConflict(
            "Workspace has no current online Workspace Orchestrator".into(),
        )
    })?;
    if orchestrator.worker != *source {
        return Err(Error::TicketAssignmentConflict(
            "Merge Request completion requires the current online Workspace Orchestrator".into(),
        ));
    }
    Ok(())
}

fn find_online_workspace_orchestrator(api: &WorkspaceApi) -> Option<InternalWorkerSummary> {
    let owner = api
        .store
        .current_worker_singleton_owner(
            &api.config.workspace_id,
            crate::hosts::WORKSPACE_ORCHESTRATOR_SINGLETON_KEY,
        )
        .ok()
        .flatten()?;
    let mut worker = api.runtime.worker(&owner.worker).ok()?;
    worker.singleton_key = Some(owner.key);
    (is_dedicated_workspace_orchestrator(&worker, &api.config.workspace_id)
        && matches!(worker.state.as_str(), "idle" | "running" | "paused"))
    .then_some(worker)
}

fn find_workspace_orchestrator(api: &WorkspaceApi) -> Option<InternalWorkerSummary> {
    let owner = api
        .store
        .current_worker_singleton_owner(
            &api.config.workspace_id,
            crate::hosts::WORKSPACE_ORCHESTRATOR_SINGLETON_KEY,
        )
        .ok()
        .flatten()?;
    let mut worker = api.runtime.worker(&owner.worker).ok()?;
    worker.singleton_key = Some(owner.key);
    is_dedicated_workspace_orchestrator(&worker, &api.config.workspace_id).then_some(worker)
}

fn is_dedicated_workspace_orchestrator(worker: &InternalWorkerSummary, workspace_id: &str) -> bool {
    worker.workspace.workspace_id.as_deref() == Some(workspace_id)
        && worker.singleton_key.as_deref()
            == Some(crate::hosts::WORKSPACE_ORCHESTRATOR_SINGLETON_KEY)
        && worker.tags.iter().any(|tag| tag == "orchestrator")
        && worker.tags.iter().any(|tag| tag == "singleton")
}

async fn scoped_get_memory_document(
    State(api): State<WorkspaceApi>,
    AxumPath(path): AxumPath<ScopedWorkspacePath>,
) -> ApiResult<Json<MemoryDocumentResponse>> {
    api.store
        .db_executor()
        .run(move || {
            validate_workspace_scope(&api, &path.workspace_id)?;
            let document = api.authority.memory_document()?;
            Ok(Json(MemoryDocumentResponse {
                bytes: document.body_md.len(),
                body_md: document.body_md,
                created_at: document.created_at,
                updated_at: document.updated_at,
                record_source: document.record_source,
            }))
        })
        .await
}

async fn scoped_reset_legacy_memory(
    State(api): State<WorkspaceApi>,
    AxumPath(path): AxumPath<ScopedWorkspacePath>,
    Extension(actor): Extension<RequestActor>,
    Json(request): Json<server_api::LegacyMemoryResetRequest>,
) -> ApiResult<Json<server_api::LegacyMemoryResetResponse>> {
    require_workspace_owner(
        &api,
        &path.workspace_id,
        &actor,
        "Legacy Workspace Memory reset",
    )
    .await?;
    let expected = format!("RESET LEGACY MEMORY {}", path.workspace_id);
    if request.confirmation != expected {
        return Err(Error::InvalidInput(format!(
            "legacy Memory reset confirmation must exactly equal `{expected}`"
        ))
        .into());
    }
    api.store
        .db_executor()
        .run(move || {
            let counts = api.store.reset_legacy_memory(&path.workspace_id)?;
            Ok(Json(server_api::LegacyMemoryResetResponse {
                workspace_id: path.workspace_id,
                documents_deleted: counts.documents,
                staging_records_deleted: counts.staging_records,
                staging_resolutions_deleted: counts.staging_resolutions,
            }))
        })
        .await
}

async fn scoped_list_memory_staging(
    State(api): State<WorkspaceApi>,
    AxumPath(path): AxumPath<ScopedWorkspacePath>,
    Query(query): Query<server_api::MemoryStagingQuery>,
) -> ApiResult<Json<MemoryStagingListResponse>> {
    api.store
        .db_executor()
        .run(move || {
            validate_workspace_scope(&api, &path.workspace_id)?;
            Ok(Json(list_memory_staging_from_authority(
                &api.authority,
                query.limit.map(usize::try_from).transpose().map_err(|_| {
                    Error::InvalidInput(
                        "Memory staging limit exceeds this host's usize range".to_string(),
                    )
                })?,
            )?))
        })
        .await
}

async fn scoped_memory_backend_operation(
    State(api): State<WorkspaceApi>,
    AxumPath(path): AxumPath<ScopedWorkspacePath>,
    _context: server_api::ServerRequestContext,
    Json(operation): Json<MemoryBackendOperation>,
) -> ApiResult<Json<MemoryBackendHttpResponse>> {
    api.store
        .db_executor()
        .run(move || {
            validate_workspace_scope(&api, &path.workspace_id)?;
            // The legacy memory document edit is a read/replace/write across store
            // calls. Keep that resource atomic without serializing unrelated requests.
            let _memory_guard = api
                .memory_operation_lock
                .lock()
                .expect("Memory operation lock poisoned");
            let result = execute_memory_backend_operation_with_authority(&api.authority, operation);
            let response = match result {
                Ok(result) => MemoryBackendHttpResponse::Ok { result },
                Err(error) => MemoryBackendHttpResponse::Error {
                    message: sanitize_backend_error(&error.to_string()),
                },
            };
            Ok(Json(response))
        })
        .await
}

const SUBJEKTIV_SINGLETON_PREFIX: &str = crate::subjektiv::SUBJECT_WORKER_SINGLETON_PREFIX;
const SUBJEKTIV_CONSOLIDATION_SINGLETON_PREFIX: &str =
    crate::hosts::SUBJEKTIV_CONSOLIDATION_SINGLETON_PREFIX;
const SUBJEKTIV_MEMORY_CONSOLIDATION_PROFILE: &str = "subjektiv-memory-consolidation";

/// Finite Host and cleanup owners, each independent of the pure DB callback lane.
/// Runtime/network workflows must not monopolize the sole DB worker or re-admit to their
/// own Host lane, even indirectly via a mandatory Runtime callback. Transactions end before
/// I/O. Teardown uses cleanup so waits cannot starve ordinary Host stop/control operations.
/// Production shares these owners; fixture constructors inject a lazy owner shared by child
/// Workspaces and weak adapters, never a process-global fixture cache.
#[derive(Clone, Default)]
struct HostExecutors {
    host: Arc<std::sync::OnceLock<Option<crate::db_executor::DbExecutor>>>,
    cleanup: Arc<std::sync::OnceLock<Option<crate::db_executor::DbExecutor>>>,
}

impl HostExecutors {
    fn shared() -> Self {
        static SHARED: std::sync::OnceLock<HostExecutors> = std::sync::OnceLock::new();
        SHARED.get_or_init(Self::default).clone()
    }

    fn lane(
        owner: &std::sync::OnceLock<Option<crate::db_executor::DbExecutor>>,
    ) -> Result<crate::db_executor::DbExecutor> {
        owner
            .get_or_init(|| {
                crate::db_executor::DbExecutor::new(crate::db_executor::DbExecutorLimits {
                    workers: std::num::NonZeroUsize::new(2).unwrap(),
                    queued: std::num::NonZeroUsize::new(16).unwrap(),
                })
                .ok()
            })
            .clone()
            .ok_or(Error::DbExecutorUnavailable)
    }

    fn host(&self) -> Result<crate::db_executor::DbExecutor> {
        Self::lane(&self.host)
    }
    fn cleanup(&self) -> Result<crate::db_executor::DbExecutor> {
        Self::lane(&self.cleanup)
    }
}

/// Poll mixed lifecycle workflows on finite Host ownership using the original Tokio handle,
/// never a replacement runtime for cached services. Resource/control/session guards belong
/// to the accepted job; cancelling its waiter releases neither guards nor ownership.
/// Keep commit, ordered local publication and response observation in that same job; admit
/// before mutation so overload cannot commit a change then fail on response admission.
/// No SQL transaction contains an await/Runtime call. Already-owned workflows call their
/// on-Host helpers directly rather than awaiting nested admission to this lane.
async fn run_host_workflow<T, E>(
    executor: crate::db_executor::DbExecutor,
    future: impl std::future::Future<Output = std::result::Result<T, E>> + Send + 'static,
) -> std::result::Result<T, E>
where
    T: Send + 'static,
    E: From<Error> + Send + 'static,
{
    let runtime =
        tokio::runtime::Handle::try_current().map_err(|_| E::from(Error::DbExecutorUnavailable))?;
    executor.run(move || runtime.block_on(future)).await
}

fn open_subjektiv_store(api: &WorkspaceApi) -> ApiResult<crate::subjektiv::SubjektivStore> {
    crate::subjektiv::SubjektivStore::open(&api.feature_storage, &api.subjektiv_registration)
        .map_err(|error| ApiError::from(Error::Store(error.to_string())))
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SubjektivWorkerAuthority {
    Subject,
    Consolidation,
}

fn subjektiv_scope_from_singleton_key(key: &str) -> ApiResult<(&str, SubjektivWorkerAuthority)> {
    let (subject_id, authority) = if let Some(subject_id) =
        key.strip_prefix(SUBJEKTIV_SINGLETON_PREFIX)
    {
        (subject_id, SubjektivWorkerAuthority::Subject)
    } else if let Some(subject_id) = key.strip_prefix(SUBJEKTIV_CONSOLIDATION_SINGLETON_PREFIX) {
        (subject_id, SubjektivWorkerAuthority::Consolidation)
    } else {
        return Err(Error::WorkspacePermissionDenied(
            "current Worker is not connected to a subjektiv subject".to_string(),
        )
        .into());
    };
    if subject_id.is_empty()
        || subject_id.chars().any(char::is_control)
        || subject_id.trim() != subject_id
    {
        return Err(Error::WorkspacePermissionDenied(
            "current Worker is not connected to a subjektiv subject".to_string(),
        )
        .into());
    }
    Ok((subject_id, authority))
}

fn is_dedicated_subjektiv_consolidation_worker(
    worker: &InternalWorkerSummary,
    workspace_id: &str,
    singleton_key: &str,
) -> bool {
    let profile_matches = worker.profile.as_deref().is_some_and(|profile| {
        profile.strip_prefix("builtin:").unwrap_or(profile)
            == SUBJEKTIV_MEMORY_CONSOLIDATION_PROFILE
    });
    let profile_tag = format!("profile:{SUBJEKTIV_MEMORY_CONSOLIDATION_PROFILE}");
    worker.workspace.workspace_id.as_deref() == Some(workspace_id)
        && worker.singleton_key.as_deref() == Some(singleton_key)
        && singleton_key.starts_with(SUBJEKTIV_CONSOLIDATION_SINGLETON_PREFIX)
        && profile_matches
        && worker.tags.iter().any(|tag| tag == &profile_tag)
}

fn require_dedicated_subjektiv_consolidation_worker(
    worker: &InternalWorkerSummary,
    workspace_id: &str,
    singleton_key: &str,
) -> ApiResult<()> {
    if is_dedicated_subjektiv_consolidation_worker(worker, workspace_id, singleton_key) {
        Ok(())
    } else {
        Err(Error::WorkspacePermissionDenied(
            "subject Memory consolidation requires a Backend-managed dedicated Worker".to_string(),
        )
        .into())
    }
}

/// Store-only scope authority for Subject, Job consolidation and legacy consolidation.
/// Mandatory Session attribution and Subject-only memory use independent DB ownership and
/// reject both consolidation roles before Runtime profile/tag lookup. A create/restore parent
/// can hold Host while awaiting these callbacks, so resident context must not queue behind it.
/// Mixed legacy consolidation, public session reads/search, response projection and general
/// memory staging remain on Host when they can call Runtime/network outside transactions.
/// This separation grants no new permission to reenter Workspace deletion drain.
enum SubjektivStoredScopeAuthority {
    Subject,
    JobConsolidation,
    LegacyConsolidation { singleton_key: String },
}

struct SubjektivStoredWorkerScope {
    subject_id: String,
    worker: RuntimeWorkerRef,
    authority: SubjektivStoredScopeAuthority,
}

fn subjektiv_worker_scope_from_store(
    api: &WorkspaceApi,
    workspace_id: &str,
    context: &server_api::ServerRequestContext,
) -> ApiResult<SubjektivStoredWorkerScope> {
    let source = context.runtime_source.as_ref().ok_or_else(|| {
        Error::WorkspacePermissionDenied(
            "subjektiv operations require authenticated Runtime-owned source authority".to_string(),
        )
    })?;
    let worker_id = source.worker_id.as_deref().ok_or_else(|| {
        Error::WorkspacePermissionDenied(
            "subjektiv operations require Runtime-bound Worker identity".to_string(),
        )
    })?;
    let worker = RuntimeWorkerRef::new(&source.runtime_id, worker_id);
    if let Some(grant) = subjektiv_job::active_grant(api, workspace_id, &worker)? {
        return Ok(SubjektivStoredWorkerScope {
            subject_id: grant.subject_id,
            worker,
            authority: SubjektivStoredScopeAuthority::JobConsolidation,
        });
    }
    let lease = api
        .store
        .require_current_worker_singleton_owner(workspace_id, &worker)?
        .ok_or_else(|| {
            Error::WorkspacePermissionDenied(
                "current Worker has no keyed singleton ownership".to_string(),
            )
        })?;
    let (subject_id, authority) = subjektiv_scope_from_singleton_key(&lease.key)?;
    let authority = match authority {
        SubjektivWorkerAuthority::Subject => SubjektivStoredScopeAuthority::Subject,
        SubjektivWorkerAuthority::Consolidation => {
            SubjektivStoredScopeAuthority::LegacyConsolidation {
                singleton_key: lease.key.clone(),
            }
        }
    };
    Ok(SubjektivStoredWorkerScope {
        subject_id: subject_id.to_owned(),
        worker,
        authority,
    })
}

// Mixed callers run this complete policy boundary on Host. Only legacy
// consolidation authority needs synchronous Runtime profile/tag verification.
fn subjektiv_subject_scope(
    api: &WorkspaceApi,
    workspace_id: &str,
    context: &server_api::ServerRequestContext,
) -> ApiResult<(String, RuntimeWorkerRef, SubjektivWorkerAuthority)> {
    let scope = subjektiv_worker_scope_from_store(api, workspace_id, context)?;
    let authority = match scope.authority {
        SubjektivStoredScopeAuthority::Subject => SubjektivWorkerAuthority::Subject,
        SubjektivStoredScopeAuthority::JobConsolidation => SubjektivWorkerAuthority::Consolidation,
        SubjektivStoredScopeAuthority::LegacyConsolidation { singleton_key } => {
            let mut summary = api
                .runtime
                .worker(&scope.worker)
                .map_err(|error| error.into_error())?;
            summary.singleton_key = Some(singleton_key.clone());
            require_dedicated_subjektiv_consolidation_worker(
                &summary,
                workspace_id,
                &singleton_key,
            )?;
            SubjektivWorkerAuthority::Consolidation
        }
    };
    Ok((scope.subject_id, scope.worker, authority))
}

// Resolve Subject identity through the existing Host binding before calling this
// boundary. Model arguments and Feature configuration never choose its resource.
fn authorize_subjektiv_operation(
    api: &WorkspaceApi,
    worker: &RuntimeWorkerRef,
    workspace_id: &str,
    subject_id: &str,
    operation: &str,
) -> ApiResult<Option<server_api::authorization::PermissionResource>> {
    let resource = server_api::authorization::PermissionResource::Subject {
        workspace_id: workspace_id.into(),
        subject_id: subject_id.into(),
    };
    subject_authorization::authorize_scope(
        api,
        worker,
        &server_api::authorization::OperationAuthorizationRequest {
            operation: operation.into(),
            resource: resource.clone(),
        },
    )
    // The binding query returns only the authorized concrete target, never a
    // wildcard ceiling or a broader permission that happened to cover it.
    .map(|scope| scope.map(|_| resource))
}

fn require_subjektiv_worker_authority(
    actual: SubjektivWorkerAuthority,
    expected: SubjektivWorkerAuthority,
    operation: &str,
) -> ApiResult<()> {
    if actual == expected {
        Ok(())
    } else {
        Err(Error::WorkspacePermissionDenied(format!(
            "subjektiv {operation} is not authorized for this Worker role"
        ))
        .into())
    }
}

fn subjektiv_session_attribution(
    api: &WorkspaceApi,
    workspace_id: &str,
    context: &server_api::ServerRequestContext,
    session_id: &str,
) -> ApiResult<crate::subjektiv::SubjectSessionAttribution> {
    let scope = subjektiv_worker_scope_from_store(api, workspace_id, context)?;
    if !matches!(scope.authority, SubjektivStoredScopeAuthority::Subject) {
        return Err(Error::WorkspacePermissionDenied(
            "subject Session attribution requires the current subject Worker".into(),
        )
        .into());
    }
    let session_id = session_id.trim();
    if session_id.is_empty() || session_id.chars().any(char::is_control) {
        return Err(Error::InvalidInput("committed session_id is invalid".to_string()).into());
    }
    crate::subjektiv::SubjectSessionAttribution::new(
        scope.subject_id,
        scope.worker.runtime_id,
        scope.worker.worker_id,
        session_id,
    )
    .map_err(|error| Error::InvalidInput(error.to_string()).into())
}

fn require_existing_subjektiv_session_attribution(
    api: &WorkspaceApi,
    workspace_id: &str,
    context: &server_api::ServerRequestContext,
    session_id: &str,
) -> ApiResult<crate::subjektiv::SubjectSessionAttribution> {
    let expected = subjektiv_session_attribution(api, workspace_id, context, session_id)?;
    let existing = open_subjektiv_store(api)?
        .session_attribution(&expected.session_id)
        .map_err(subjektiv_store_error)?
        .ok_or_else(|| {
            Error::RepositoryConflict(format!(
                "subjektiv_session_attribution_incomplete: Session {} has not completed its Host attribution lifecycle",
                expected.session_id
            ))
        })?;
    if existing.subject_id != expected.subject_id
        || existing.runtime_id != expected.runtime_id
        || existing.worker_id != expected.worker_id
    {
        return Err(Error::WorkspacePermissionDenied(
            "existing Session attribution does not match the authorized subject Worker".to_string(),
        )
        .into());
    }
    Ok(existing)
}

fn subjektiv_subject_response(
    api: &WorkspaceApi,
    subject: crate::subjektiv::SubjectRecord,
) -> ApiResult<server_api::SubjektivSubjectResponse> {
    let memory_fingerprint = open_subjektiv_store(api)?
        .memory_fingerprint(&subject.id)
        .map_err(subjektiv_store_error)?;
    let current_worker = crate::subjektiv::subject_worker_singleton_key(&subject.id)
        .ok()
        .and_then(|key| {
            api.store
                .current_worker_singleton_owner(&api.config.workspace_id, &key)
                .ok()
                .flatten()
        })
        .and_then(|lease| api.runtime.worker(&lease.worker).ok())
        .map(worker_launch_worker_summary);
    Ok(server_api::SubjektivSubjectResponse {
        id: subject.id,
        role: subject.role.as_str().to_string(),
        behavior_md: subject.behavior_md,
        memory_fingerprint,
        state: match subject.state {
            crate::subjektiv::SubjectState::Active => server_api::SubjektivSubjectState::Active,
            crate::subjektiv::SubjectState::LegacyRetired => {
                server_api::SubjektivSubjectState::LegacyRetired
            }
        },
        created_at: subject.created_at,
        updated_at: subject.updated_at,
        current_worker,
    })
}

