#[derive(Debug, Serialize)]
struct WorkerRemoveSuccessResponse<'a> {
    removed: bool,
    runtime_id: &'a str,
    worker_id: &'a str,
}

#[derive(Debug, Serialize)]
struct WorkerRemoveErrorResponse<'a> {
    code: &'a str,
    message: &'a str,
}

fn worker_remove_success_response(worker: &RuntimeWorkerRef) -> worker::WorkspaceResponse {
    let body = serde_json::to_string(&WorkerRemoveSuccessResponse {
        removed: true,
        runtime_id: &worker.runtime_id,
        worker_id: &worker.worker_id,
    })
    .unwrap_or_else(|_| r#"{"removed":true}"#.to_string());
    worker::WorkspaceResponse {
        status: StatusCode::OK.as_u16(),
        body,
    }
}

fn worker_remove_error_response(
    status: StatusCode,
    code: &str,
    message: &str,
) -> worker::WorkspaceResponse {
    let body =
        serde_json::to_string(&WorkerRemoveErrorResponse { code, message }).unwrap_or_else(|_| {
            r#"{"code":"worker_remove_failed","message":"Worker removal failed"}"#.to_string()
        });
    worker::WorkspaceResponse {
        status: status.as_u16(),
        body,
    }
}

// Preserve the Runtime cause through WorkerRemove, cleanup, and API logging.
// Runtime errors can contain private paths or credentials; do not publish their
// raw Display. Keep the operation and OS failure text for diagnosis.
fn runtime_retention_failure_response(
    target: &RuntimeWorkerRef,
    operation_id: &str,
    phase: &str,
    error: &RuntimeRegistryError,
) -> worker::WorkspaceResponse {
    let detail = retention_failure_detail(&error.clone().into_error().to_string());
    worker_remove_error_response(
        StatusCode::SERVICE_UNAVAILABLE,
        "runtime_retention_failed",
        &format!(
            "Runtime retention {phase} failed for Worker {}:{} (operation {operation_id}): {detail}; removal can be retried",
            target.runtime_id, target.worker_id,
        ),
    )
}

fn retention_failure_detail(message: &str) -> String {
    let mut redact_next = false;
    let mut detail = String::new();
    for word in message.split_whitespace() {
        let label = word
            .trim_matches(|c: char| !c.is_ascii_alphanumeric())
            .to_ascii_lowercase();
        let secret_label = matches!(
            label.as_str(),
            "bearer" | "credential" | "password" | "secret" | "token" | "key"
        );
        let sensitive = redact_next
            || (word.contains('/') && label != "i/o")
            || word.contains('\\')
            || (!secret_label
                && ["credential", "password", "secret", "token", "key"]
                    .iter()
                    .any(|marker| label.contains(marker)));
        redact_next = secret_label;
        let word = if sensitive { "[redacted]" } else { word };
        if !detail.is_empty() {
            detail.push(' ');
        }
        let remaining = 1024usize.saturating_sub(detail.len());
        let mut end = word.len().min(remaining);
        while !word.is_char_boundary(end) {
            end -= 1;
        }
        detail.push_str(&word[..end]);
        if end < word.len() || detail.len() >= 1024 {
            detail.push('…');
            break;
        }
    }
    detail
}

fn worker_retention_error_response(
    error: crate::retention::WorkerRetentionError,
) -> worker::WorkspaceResponse {
    match error {
        crate::retention::WorkerRetentionError::WorkerNotFound
        | crate::retention::WorkerRetentionError::CrossWorkspace => worker_remove_error_response(
            StatusCode::NOT_FOUND,
            "worker_not_found",
            "Worker was not found in this Workspace",
        ),
        crate::retention::WorkerRetentionError::PolicyDigestConflict { .. }
        | crate::retention::WorkerRetentionError::StalePlan { .. }
        | crate::retention::WorkerRetentionError::OperationFingerprintConflict { .. } => {
            worker_remove_error_response(
                StatusCode::CONFLICT,
                "worker_removal_conflict",
                "Worker removal state changed; retry the operation",
            )
        }
        crate::retention::WorkerRetentionError::Blocked(_) => worker_remove_error_response(
            StatusCode::CONFLICT,
            "worker_removal_blocked",
            "Worker removal is blocked by unfinished Ticket work, hold, or retention policy",
        ),
        crate::retention::WorkerRetentionError::Invalid(_) => worker_remove_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_worker_remove",
            "Worker removal request is invalid",
        ),
        crate::retention::WorkerRetentionError::PolicyMissing { .. }
        | crate::retention::WorkerRetentionError::Store(_) => worker_remove_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "worker_removal_authority_unavailable",
            "Worker removal authority is unavailable; removal can be retried",
        ),
    }
}

fn worker_remove_repository_error(
    error: server_api::RepositoryApiError,
) -> server_api::WorkerRemoveApiError {
    server_api::WorkerRemoveApiError::new(
        StatusCode::INTERNAL_SERVER_ERROR.as_u16(),
        Some(error.error),
        None,
        Some(error.message),
        Some(error.diagnostics),
    )
}

async fn worker_remove_contract(
    api: &WorkspaceApi,
    context: server_api::ServerRequestContext,
    workspace_id: String,
    request: server_api::WorkerRemoveRequest,
) -> std::result::Result<server_api::WorkerRemoveResponse, server_api::WorkerRemoveApiError> {
    if workspace_id != api.config.workspace_id {
        return Err(server_api::WorkerRemoveApiError::new(
            StatusCode::NOT_FOUND.as_u16(),
            Some("workspace_not_found".to_owned()),
            None,
            Some("Workspace was not found".to_owned()),
            None,
        ));
    }
    let headers = contract_request_headers(&context).map_err(worker_remove_repository_error)?;
    let proof =
        crate::worker_source::presented_worker_remove_source(&headers, None).map_err(|error| {
            server_api::WorkerRemoveApiError::new(
                StatusCode::UNAUTHORIZED.as_u16(),
                Some(error.to_string()),
                None,
                None,
                None,
            )
        })?;
    let source = crate::worker_source::verify_worker_remove_source(
        api,
        proof,
        &request.target_runtime_id,
        &request.target_worker_id,
    )
    .await
    .map_err(|error| {
        let status = match error {
            crate::worker_source::WorkerMutationSourceProofError::Replay => StatusCode::CONFLICT,
            crate::worker_source::WorkerMutationSourceProofError::Unavailable => {
                StatusCode::SERVICE_UNAVAILABLE
            }
            crate::worker_source::WorkerMutationSourceProofError::Authority(_) => {
                StatusCode::INTERNAL_SERVER_ERROR
            }
            _ => StatusCode::FORBIDDEN,
        };
        server_api::WorkerRemoveApiError::new(
            status.as_u16(),
            Some(error.to_string()),
            None,
            None,
            None,
        )
    })?;
    let worker =
        WorkspaceWorker::resolve_async(api, &request.target_runtime_id, &request.target_worker_id)
            .await
            .map_err(|error| match error {
                Error::UnknownWorker { .. } => server_api::WorkerRemoveApiError::new(
                    StatusCode::NOT_FOUND.as_u16(),
                    None,
                    Some("unknown_worker".into()),
                    Some("The target Worker is not known in this Workspace".into()),
                    None,
                ),
                error => worker_remove_repository_error(
                    ApiError::from(error).into_repository_api_error(),
                ),
            })?;
    let response = worker
        .remove(source, &request.reason)
        .await
        .unwrap_or_else(|_| {
            worker_remove_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "worker_remove_failed",
                "Worker removal failed before lifecycle execution",
            )
        });
    if (200..300).contains(&response.status) {
        return serde_json::from_str(&response.body).map_err(|error| {
            server_api::WorkerRemoveApiError::new(
                StatusCode::INTERNAL_SERVER_ERROR.as_u16(),
                Some("worker_remove_invalid_response".to_owned()),
                None,
                Some(error.to_string()),
                None,
            )
        });
    }
    let body: serde_json::Value = serde_json::from_str(&response.body).unwrap_or_default();
    Err(server_api::WorkerRemoveApiError::new(
        response.status,
        body.get("error")
            .and_then(serde_json::Value::as_str)
            .map(str::to_owned),
        body.get("code")
            .and_then(serde_json::Value::as_str)
            .map(str::to_owned),
        body.get("message")
            .and_then(serde_json::Value::as_str)
            .map(str::to_owned),
        body.get("diagnostics")
            .cloned()
            .and_then(|value| serde_json::from_value(value).ok()),
    ))
}

async fn scoped_get_workspace_worker(
    State(api): State<WorkspaceApi>,
    AxumPath(path): AxumPath<ScopedWorkspaceWorkerReferencePath>,
) -> ApiResult<Json<server_api::WorkerSummary>> {
    api.host_executors
        .host()?
        .run(move || {
            validate_workspace_scope(&api, &path.workspace_id)?;
            let worker_ref = api
                .store
                .resolve_worker_resource_reference(&api.config.workspace_id, &path.worker_ref)?
                .ok_or_else(|| Error::UnknownWorker {
                    worker: RuntimeWorkerRef::new("unknown", &path.worker_ref),
                })?;
            let workers = workers_response(api.clone())?;
            workers
                .items
                .into_iter()
                .find(|worker| {
                    worker.runtime_id == worker_ref.runtime_id
                        && worker.worker_id == worker_ref.worker_id
                })
                .map(Json)
                .ok_or_else(|| Error::UnknownWorker { worker: worker_ref }.into())
        })
        .await
}

async fn discover_workspace_workers(
    api: WorkspaceApi,
    workspace_id: String,
    query: server_api::WorkspaceWorkerDiscoveryQuery,
    verified_runtime_source: bool,
) -> std::result::Result<WorkspaceWorkerDiscoveryPage, ApiError> {
    if !verified_runtime_source {
        return Err(ApiError::from(Error::WorkspacePermissionDenied(
            "workspace_worker_discovery_source_required".to_string(),
        )));
    }
    validate_workspace_scope(&api, &workspace_id)?;
    let limit = query.limit.unwrap_or(50).clamp(1, 100);
    let cursor = query.cursor.clone();
    let query = match query.query.as_deref().map(str::trim) {
        Some("") | None => None,
        Some(query) if query.len() <= 128 => Some(query),
        Some(_) => {
            return Err(ApiError::from(Error::InvalidInput(
                "invalid_workspace_worker_discovery_query".to_string(),
            )));
        }
    };
    let filter_fingerprint = workspace_worker_discovery_filter_fingerprint(query);
    let offset = query_cursor_offset(cursor.as_deref(), filter_fingerprint).map_err(|()| {
        ApiError::from(Error::InvalidInput(
            "invalid_workspace_worker_discovery_cursor".to_string(),
        ))
    })?;
    let workers = api
        .store
        .db_executor()
        .run(move || workers_response(api))
        .await?;
    Ok(workspace_worker_discovery_page(
        workers.items,
        query,
        offset,
        limit,
        filter_fingerprint,
    ))
}

fn workspace_worker_discovery_page(
    workers: Vec<server_api::WorkerSummary>,
    query: Option<&str>,
    offset: usize,
    limit: usize,
    filter_fingerprint: u64,
) -> WorkspaceWorkerDiscoveryPage {
    let mut workers = workers
        .into_iter()
        .filter(|worker| worker.workspace.visibility == "workspace_scoped")
        .filter(|worker| {
            query.is_none_or(|query| {
                worker.resource_key == query
                    || worker.display_name == query
                    || worker.label == query
            })
        })
        .collect::<Vec<_>>();
    workers.sort_by(|left, right| left.resource_key.cmp(&right.resource_key));
    let total = workers.len();
    let page = workers
        .into_iter()
        .skip(offset)
        .take(limit)
        .map(|worker| WorkspaceWorkerDiscoveryItem {
            subject: WorkspaceWorkerSubject::RuntimeWorker {
                runtime_id: worker.runtime_id,
                worker_id: worker.worker_id,
            },
            resource_key: worker.resource_key,
            display_name: worker.display_name,
            profile: worker.profile,
            status: Some(worker.state),
        })
        .collect::<Vec<_>>();
    let next_offset = offset.saturating_add(page.len());
    WorkspaceWorkerDiscoveryPage {
        workers: page,
        next_cursor: (next_offset < total)
            .then(|| format!("v1:{next_offset}:{filter_fingerprint:016x}")),
    }
}

fn query_cursor_offset(
    cursor: Option<&str>,
    filter_fingerprint: u64,
) -> std::result::Result<usize, ()> {
    let Some(cursor) = cursor else {
        return Ok(0);
    };
    let mut parts = cursor.split(':');
    match (parts.next(), parts.next(), parts.next(), parts.next()) {
        (Some("v1"), Some(offset), Some(fingerprint), None)
            if u64::from_str_radix(fingerprint, 16).ok() == Some(filter_fingerprint) =>
        {
            offset.parse().map_err(|_| ())
        }
        _ => Err(()),
    }
}

fn workspace_worker_discovery_filter_fingerprint(query: Option<&str>) -> u64 {
    use std::hash::{Hash, Hasher};

    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    query.hash(&mut hasher);
    hasher.finish()
}

