async fn spawn_known_worker_authenticated_on_host(
    State(api): State<WorkspaceApi>,
    AxumPath(path): AxumPath<ScopedWorkspacePath>,
    headers: HeaderMap,
    Json(mut request): Json<CreateWorkspaceWorkerRequest>,
    context: Option<&server_api::ServerRequestContext>,
) -> ApiResult<Json<BrowserCreateWorkerResponse>> {
    validate_workspace_scope(&api, &path.workspace_id)?;
    let source = authenticate_worker_mutation_source(&api, &path.workspace_id, &headers)?;
    resolve_workspace_worker_ticket_assignment(
        &api,
        &path.workspace_id,
        &mut request.ticket_assignment,
    )?;
    let relation = if request.ticket_assignment.is_some() {
        "assigned"
    } else {
        "spawned"
    };
    let operation_id = request
        .control_operation_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| Error::InvalidInput("control_operation_id is required".to_string()))?
        .to_string();
    let controller = RuntimeWorkerRef::new(&source.runtime_id, &source.worker_id);
    let fingerprint_input = serde_json::to_vec(&serde_json::json!({
        "controller": &controller,
        "request": &request,
    }))
    .map_err(|error| Error::InvalidInput(format!("invalid Worker spawn input: {error}")))?;
    let input_fingerprint = format!(
        "sha256:{}",
        Sha256::digest(&fingerprint_input)
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<String>()
    );
    let resolved_control_operation = Some(WorkerControlOperation {
        operation_id: scoped_worker_control_operation_id(&controller, &operation_id),
        input_fingerprint,
    });
    let response = create_workspace_worker_authenticated_on_host(
        api.clone(),
        headers,
        request,
        resolved_control_operation,
        context,
    )
    .await?;
    // Creation has now committed the real registry row. Keep reply-grant failure
    // outside spawn compensation so an exact operation replay repairs only the
    // missing grant, without a second Worker or repeated initial Submit.
    subject_authorization::persist_reply_grant(
        &api,
        &controller,
        &RuntimeWorkerRef::new(&response.0.runtime_id, &response.0.worker_id),
        &scoped_worker_control_operation_id(&controller, &operation_id),
    )?;
    if let Err(error) = api
        .store
        .create_worker_control_grant(&WorkerControlGrantRecord {
            workspace_id: path.workspace_id.clone(),
            grant_id: new_id("wcg"),
            controller,
            subject: RuntimeWorkerRef::new(&response.0.runtime_id, &response.0.worker_id),
            relation: relation.to_string(),
            origin: "worker_spawn".to_string(),
            permissions: vec![
                "send_input".to_string(),
                "notify".to_string(),
                "cancel".to_string(),
                "stop".to_string(),
                "restore".to_string(),
                "remove".to_string(),
                "observe".to_string(),
            ],
            operation_id,
            created_at: Utc::now().to_rfc3339_opts(SecondsFormat::Secs, true),
            revoked_at: None,
        })
    {
        // Runtime creation is idempotent under the trusted control operation.
        // Preserve the unacknowledged Worker/assignment so a retry converges on
        // the same subject and can finish grant persistence without creating a
        // second Worker or leaving assignment cleanup races.
        return Err(ApiError::from(error));
    }
    Ok(response)
}

fn worker_control_lock(api: &WorkspaceApi, grant_id: &str) -> Arc<tokio::sync::Mutex<()>> {
    let mut locks = api
        .worker_control_locks
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    Arc::clone(
        locks
            .entry(grant_id.to_string())
            .or_insert_with(|| Arc::new(tokio::sync::Mutex::new(()))),
    )
}

fn worker_control_denied_response(error: Error) -> worker::WorkspaceResponse {
    // Keep removal's existing opaque target-grant refusal; operation-policy
    // refusals remain distinct and do not impersonate an unknown target.
    if matches!(&error, Error::UnknownWorker { .. })
        || matches!(&error, Error::InvalidInput(message)
            if message.starts_with("worker control permission "))
    {
        return worker_remove_error_response(
            StatusCode::NOT_FOUND,
            "unknown_worker",
            "The target Worker is not known to the current Worker",
        );
    }
    worker_remove_error_response(
        api_error_status(&error),
        "worker_control_denied",
        &error.to_string(),
    )
}

fn authorize_known_worker_permission(
    api: &WorkspaceApi,
    workspace_id: &str,
    controller: &RuntimeWorkerRef,
    subject: &RuntimeWorkerRef,
    permission: &str,
) -> Result<WorkerControlGrantRecord> {
    if workspace_id != api.workspace_id() {
        return Err(Error::WorkspacePermissionDenied(
            "resource belongs to another Workspace".into(),
        ));
    }
    subject_authorization::WorkerAuthorityView::from(api)
        .authorize_control_permission(controller, subject, permission)
}

async fn send_known_worker_input(
    State(api): State<WorkspaceApi>,
    AxumPath(path): AxumPath<ScopedRuntimeWorkerPath>,
    headers: HeaderMap,
    Json(request): Json<server_api::RuntimeWorkerInputRequest>,
) -> ApiResult<Json<server_api::RuntimeWorkerInputResult>> {
    validate_workspace_scope(&api, &path.workspace_id)?;
    let source =
        authenticate_worker_mutation_source_owned(&api, &path.workspace_id, &headers).await?;
    let context = WorkerOperationContext::WorkerControl {
        controller: RuntimeWorkerRef::new(&source.runtime_id, &source.worker_id),
    };
    let worker =
        WorkspaceWorker::resolve_async(&api, &path.worker.runtime_id, &path.worker.worker_id)
            .await?;
    let request = worker_input_request_from_api(request)?;
    let idle_only = request.kind == WorkerInputKind::User;
    let result = worker.input(&context, request).await?;
    let outcome_unknown = result.disposition == WorkerInputDisposition::Unknown;
    let result = worker_input_result_to_api(result);
    if result.state != server_api::WorkerOperationState::Accepted && !outcome_unknown {
        let detail = result
            .diagnostics
            .iter()
            .map(|diagnostic| diagnostic.message.as_str())
            .collect::<Vec<_>>()
            .join("; ");
        let message = if idle_only {
            format!(
                "WorkerSendInput requires an Idle Worker and never queues input. Use WorkerNotify for information about work already in progress. {detail}"
            )
        } else {
            detail
        };
        return Err(Error::InvalidInput(message).into());
    }
    Ok(Json(result))
}

