async fn scoped_list_worker_observation_sessions(
    State(api): State<WorkspaceApi>,
    AxumPath(path): AxumPath<ScopedWorkspacePath>,
    headers: HeaderMap,
) -> ApiResult<Json<server_api::WorkerObservationSessionsResponse>> {
    api.host_executors
        .host()?
        .run(move || {
            validate_workspace_scope(&api, &path.workspace_id)?;
            let source = authenticate_worker_mutation_source(&api, &path.workspace_id, &headers)?;
            let controller = RuntimeWorkerRef::new(&source.runtime_id, &source.worker_id);
            subject_authorization::authorize(
                &api,
                &controller,
                &server_api::authorization::OperationAuthorizationRequest {
                    operation: "worker.observe.list".into(),
                    resource: server_api::authorization::PermissionResource::Workspace {
                        workspace_id: path.workspace_id.clone(),
                    },
                },
            )?;
            let sessions = api
                .store
                .list_active_worker_control_grants(&path.workspace_id, &controller, 100)?
                .into_iter()
                .filter(|grant| {
                    grant
                        .permissions
                        .iter()
                        .any(|permission| permission == "observe")
                })
                .filter_map(|grant| {
                    authorize_known_worker_permission(
                        &api,
                        &path.workspace_id,
                        &controller,
                        &grant.subject,
                        "observe",
                    )
                    .ok()?;
                    let worker = api.runtime.worker(&grant.subject).ok()?;
                    if matches!(
                        worker.state.as_str(),
                        "stopped" | "failed" | "rejected" | "disconnected"
                    ) {
                        return None;
                    }
                    Some(server_api::WorkerObservationSubject {
                        subject: server_api::WorkerObservationSubjectRef::RuntimeWorker {
                            runtime_id: grant.subject.runtime_id,
                            worker_id: grant.subject.worker_id,
                        },
                        display_name: worker.display_name,
                        relation: grant.relation,
                        status: worker.state,
                    })
                })
                .collect::<Vec<_>>();
            Ok(Json(server_api::WorkerObservationSessionsResponse {
                sessions,
            }))
        })
        .await
}

async fn scoped_capture_worker_observation_session(
    State(api): State<WorkspaceApi>,
    AxumPath(path): AxumPath<ScopedWorkspacePath>,
    headers: HeaderMap,
    Json(subject): Json<server_api::WorkerObservationSubjectRef>,
) -> ApiResult<Json<server_api::WorkerObservationCaptureResponse>> {
    validate_workspace_scope(&api, &path.workspace_id)?;
    let source =
        authenticate_worker_mutation_source_owned(&api, &path.workspace_id, &headers).await?;
    let server_api::WorkerObservationSubjectRef::RuntimeWorker {
        runtime_id,
        worker_id,
    } = subject
    else {
        return Err(ApiError::from(Error::UnknownWorker {
            worker: RuntimeWorkerRef::new("subworker", "inaccessible"),
        }));
    };
    let target = RuntimeWorkerRef::new(runtime_id, worker_id);
    let controller = RuntimeWorkerRef::new(&source.runtime_id, &source.worker_id);
    let grant_api = api.clone();
    let grant_controller = controller.clone();
    let grant_target = target.clone();
    let workspace_id = path.workspace_id.clone();
    let grant = api
        .store
        .db_executor()
        .run(move || {
            authorize_known_worker_permission(
                &grant_api,
                &workspace_id,
                &grant_controller,
                &grant_target,
                "observe",
            )
        })
        .await?;
    let lock = worker_control_lock(&api, &grant.grant_id);
    let guard = lock.lock_owned().await;
    let lookup_api = api.clone();
    let lookup_target = target.clone();
    let (_guard, target_summary) = api
        .host_executors
        .host()?
        .run(move || {
            // Retain the control guard during the actual re-fence and live lookup,
            // even if the observation caller cancels its wait.
            authorize_known_worker_permission(
                &lookup_api,
                &path.workspace_id,
                &controller,
                &lookup_target,
                "observe",
            )?;
            let target_summary = lookup_api
                .runtime
                .worker(&lookup_target)
                .map_err(|error| error.into_error())?;
            Ok::<_, Error>((guard, target_summary))
        })
        .await?;
    if matches!(
        target_summary.state.as_str(),
        "stopped" | "failed" | "rejected" | "disconnected"
    ) {
        return Err(ApiError::from(Error::UnknownWorker { worker: target }));
    }

    let mut connection = connect_workspace_worker_protocol(&api, &target, None).await?;
    let event = tokio::time::timeout(std::time::Duration::from_secs(10), connection.events.recv())
        .await
        .map_err(|_| {
            ApiError::from(Error::RuntimeOperationFailed {
                runtime_id: target.runtime_id.clone(),
                code: "worker_observation_timeout".to_string(),
                message: "timed out waiting for the committed session snapshot".to_string(),
            })
        })?
        .ok_or_else(|| {
            ApiError::from(Error::RuntimeOperationFailed {
                runtime_id: target.runtime_id.clone(),
                code: "worker_observation_closed".to_string(),
                message: "worker protocol closed before the session snapshot".to_string(),
            })
        })?;
    let protocol::Event::Snapshot { session, .. } = event else {
        return Err(ApiError::from(Error::RuntimeOperationFailed {
            runtime_id: target.runtime_id.clone(),
            code: "worker_observation_missing_snapshot".to_string(),
            message: "worker protocol did not begin with a committed session snapshot".to_string(),
        }));
    };
    Ok(Json(server_api::WorkerObservationCaptureResponse {
        segment_id: format!("runtime:{}:worker:{}", target.runtime_id, target.worker_id),
        session,
    }))
}

fn diagnostics_indicate_unrecoverable_pending_workspace_restore(
    diagnostics: &[RuntimeDiagnostic],
) -> bool {
    diagnostics.iter().any(|diagnostic| {
        diagnostic.code == "embedded_worker_execution_rejected"
            && diagnostic.message.to_ascii_lowercase().contains(
                "pending workspace worker restore requires operation-owned launch material",
            )
    })
}

async fn scoped_start_workspace_orchestrator(
    State(api): State<WorkspaceApi>,
    AxumPath(path): AxumPath<ScopedWorkspacePath>,
) -> ApiResult<Json<BrowserWorkspaceOrchestratorResponse>> {
    api.host_executors.host()?.run(move || {
    #[cfg(test)]
    tests::seed_test_delivery_binding(&api);
    validate_workspace_scope(&api, &path.workspace_id)?;
    let _guard = api.orchestrator_spawn_lock.lock().map_err(|_| {
        ApiError::with_diagnostics(
            Error::RuntimeOperationFailed {
                runtime_id: EMBEDDED_WORKER_RUNTIME_ID.to_string(),
                code: "workspace_orchestrator_spawn_lock_poisoned".to_string(),
                message: "Workspace Orchestrator launch lock is unavailable".to_string(),
            },
            Vec::new(),
        )
    })?;

    let mut disposition = "created";
    if let Some(existing) = find_workspace_orchestrator(&api) {
        if workspace_orchestrator_is_online(&existing) {
            drop(_guard);
            // Already-online creation uses the same committed-input scan; neither
            // local cache loss nor handled status alone creates new work.
            dispatch_orchestrator_assignment_attention(&api, &existing.worker);
            return Ok(Json(workspace_orchestrator_response(&api, "existing")));
        }
        let attention = orchestrator_attention_state(&api, &existing.worker);
        let before_restore = attention
            .lock()
            .unwrap_or_else(|p| p.into_inner())
            .accepted
            .as_ref()
            .map(|delivery| delivery.request_id.clone());
        let restored =
            restore_internal_observed_worker(&api, &existing, "orchestrator-restore".to_owned())?;
        if restored.state == server_api::WorkerRestoreState::Accepted {
            {
                let mut attention = attention.lock().unwrap_or_else(|p| p.into_inner());
                // Retire only pre-Restore success. Concurrent reservations, unknown
                // outcomes and newly accepted deliveries must survive Restore.
                if attention.pending.is_none()
                    && attention.accepted.as_ref().map(|d| &d.request_id) == before_restore.as_ref()
                {
                    attention.accepted = None;
                }
            }
            drop(_guard);
            dispatch_orchestrator_assignment_attention(&api, &existing.worker);
            return Ok(Json(workspace_orchestrator_response(&api, "restored")));
        }
        if !diagnostics_indicate_unrecoverable_pending_workspace_restore(&restored.diagnostics) {
            return Err(ApiError::with_diagnostics(
                Error::RuntimeOperationFailed {
                    runtime_id: existing.worker.runtime_id.clone(),
                    code: "workspace_orchestrator_restore_rejected".to_string(),
                    message: "Runtime rejected Workspace Orchestrator restore".to_string(),
                },
                restored.diagnostics,
            ));
        }
        let deleted = api
            .runtime
            .delete_worker(&existing.worker)
            .map_err(|error| error.into_error())?;
        if deleted.state != InternalWorkerOperationState::Accepted || !deleted.deleted {
            return Err(ApiError::with_diagnostics(
                Error::RuntimeOperationFailed {
                    runtime_id: existing.worker.runtime_id.clone(),
                    code: "workspace_orchestrator_replacement_delete_rejected".to_string(),
                    message: "Embedded Runtime rejected replacement of an unrecoverable pending Workspace Orchestrator".to_string(),
                },
                deleted.diagnostics,
            ));
        }
        api.worker_projection.publish_ordered(|| {
            api.store
                .delete_worker_registry(&api.config.workspace_id, &existing.worker)
                .map(|commit| ((), commit))
        })?;
        disposition = "recreated";
    }

    let result = api.spawn_workspace_worker(
        EMBEDDED_WORKER_RUNTIME_ID,
        WorkerSpawnRequest {
            requested_worker_name: Some(
                crate::hosts::WORKSPACE_ORCHESTRATOR_SINGLETON_KEY.to_string(),
            ),
            singleton_key: Some(crate::hosts::WORKSPACE_ORCHESTRATOR_SINGLETON_KEY.to_string()),
            intent: WorkerSpawnIntent::WorkspaceOrchestrator,
            acceptance: WorkerSpawnAcceptanceRequirement::RunAccepted {
                expected_segments: 0,
            },
            profile: ProfileSelector::Builtin("builtin:orchestrator".to_string()),
            ticket_assignment: None,
            initial_submit: Vec::new(),
            workdir_attachment_requests: Vec::new(),
            resolved_workdir_attachment_requests: Vec::new(),
            resolved_workdir_attachments: Vec::new(),
            resolved_config_bundle: None,
            resolved_worker_observation_enabled: true,
            resolved_worker_observation_grants: Vec::new(),
            resolved_workspace_api: None,
            resolved_memory_settings: None,
            resolved_subjektiv_attached: false,
            resolved_control_operation: None,
            resolved_execution_grant: None,
        },
    )?;
    if result.state != InternalWorkerOperationState::Accepted || result.worker.is_none() {
        return Err(ApiError::with_diagnostics(
            Error::RuntimeOperationFailed {
                runtime_id: EMBEDDED_WORKER_RUNTIME_ID.to_string(),
                code: "workspace_orchestrator_spawn_rejected".to_string(),
                message: "Embedded Runtime rejected Workspace Orchestrator launch".to_string(),
            },
            result.diagnostics,
        ));
    }
    let worker = result.worker.as_ref().expect("accepted Worker was checked");
    record_worker_summary(
        &api,
        worker,
        &worker.display_name,
        Some("builtin:orchestrator".to_string()),
        WorkerRegistryDisplayNamePolicy::UseProvided,
    )?;
    drop(_guard);
    dispatch_orchestrator_assignment_attention(&api, &worker.worker);
    Ok(Json(workspace_orchestrator_response(&api, disposition)))

    }).await
}

fn worker_launch_worker_summary(worker: InternalWorkerSummary) -> WorkerLaunchWorkerSummary {
    WorkerLaunchWorkerSummary {
        runtime_id: worker.worker.runtime_id,
        worker_id: worker.worker.worker_id,
        host_id: worker.host_id,
        display_name: worker.display_name,
        label: worker.label,
        profile: worker.profile,
        singleton_key: worker.singleton_key,
        tags: worker.tags,
        workspace: server_api::WorkerWorkspaceSummary {
            visibility: worker.workspace.visibility,
            identity: worker.workspace.identity,
            workspace_id: worker.workspace.workspace_id,
        },
        state: worker.state,
        last_seen_at: worker.last_seen_at,
        pinned: worker.pinned,
        retention_state: worker.retention_state,
        implementation: server_api::WorkerImplementationSummary {
            kind: worker.implementation.kind,
            display_hint: worker.implementation.display_hint,
        },
        workdir_attachments: worker
            .workdir_attachments
            .into_iter()
            .map(
                |attachment| server_api::RuntimeWorkerWorkdirAttachmentSummary {
                    alias: attachment.alias.to_string(),
                    working_directory: attachment.working_directory.summary.into(),
                },
            )
            .collect(),
        diagnostics: worker
            .diagnostics
            .into_iter()
            .map(server_api::Diagnostic::from)
            .collect(),
    }
}

fn workspace_orchestrator_response(
    api: &WorkspaceApi,
    disposition: &str,
) -> BrowserWorkspaceOrchestratorResponse {
    let worker = find_workspace_orchestrator(api);
    let online = worker
        .as_ref()
        .is_some_and(workspace_orchestrator_is_online);
    let diagnostics = worker
        .as_ref()
        .map(|worker| {
            worker
                .diagnostics
                .iter()
                .cloned()
                .map(server_api::Diagnostic::from)
                .collect()
        })
        .unwrap_or_default();
    BrowserWorkspaceOrchestratorResponse {
        workspace_id: api.config.workspace_id.clone(),
        online,
        disposition: disposition.to_string(),
        worker: worker.map(worker_launch_worker_summary),
        diagnostics,
    }
}

fn workspace_orchestrator_is_online(worker: &InternalWorkerSummary) -> bool {
    matches!(worker.state.as_str(), "idle" | "running" | "paused")
}

#[cfg(test)]
async fn scoped_create_workspace_worker(
    State(api): State<WorkspaceApi>,
    AxumPath(path): AxumPath<ScopedWorkspacePath>,
    headers: HeaderMap,
    Json(request): Json<CreateWorkspaceWorkerRequest>,
) -> ApiResult<Json<BrowserCreateWorkerResponse>> {
    validate_workspace_scope(&api, &path.workspace_id)?;
    create_workspace_worker(State(api), headers, Json(request)).await
}

async fn scoped_get_worker_launch_options(
    State(api): State<WorkspaceApi>,
    AxumPath(path): AxumPath<ScopedWorkspacePath>,
) -> ApiResult<Json<WorkerLaunchOptionsResponse>> {
    validate_workspace_scope(&api, &path.workspace_id)?;
    get_worker_launch_options(State(api)).await
}

fn working_directory_diagnostics(
    diagnostics: Vec<RuntimeDiagnostic>,
) -> Vec<server_api::Diagnostic> {
    diagnostics
        .into_iter()
        .map(|diagnostic| server_api::Diagnostic {
            code: diagnostic.code,
            severity: match diagnostic.severity {
                HostDiagnosticSeverity::Info => server_api::DiagnosticSeverity::Info,
                HostDiagnosticSeverity::Warning => server_api::DiagnosticSeverity::Warning,
                HostDiagnosticSeverity::Error => server_api::DiagnosticSeverity::Error,
            },
            message: diagnostic.message,
        })
        .collect()
}

async fn require_active_workspace_runtime_binding(
    api: &WorkspaceApi,
    runtime_id: &str,
) -> ApiResult<()> {
    let binding = api
        .store
        .get_workspace_runtime_binding(&api.config.workspace_id, runtime_id)
        .await?
        .ok_or_else(|| Error::UnknownRuntime(runtime_id.to_string()))?;
    if binding.revoked_at.is_some() {
        return Err(Error::UnknownRuntime(runtime_id.to_string()).into());
    }
    Ok(())
}

async fn scoped_list_runtime_working_directories(
    State(api): State<WorkspaceApi>,
    AxumPath(path): AxumPath<ScopedRuntimePath>,
) -> ApiResult<Json<BrowserWorkingDirectoryListResponse>> {
    validate_workspace_scope(&api, &path.workspace_id)?;
    require_active_workspace_runtime_binding(&api, &path.runtime_id).await?;
    api.host_executors
        .host()?
        .run(move || {
            let (items, diagnostics) = runtime_working_directory_summaries(&api, &path.runtime_id)?;
            let items = items.into_iter().map(Into::into).collect();
            Ok(Json(BrowserWorkingDirectoryListResponse {
                workspace_id: api.config.workspace_id.clone(),
                items,
                diagnostics: working_directory_diagnostics(diagnostics),
            }))
        })
        .await
}

async fn scoped_create_runtime_working_directory(
    State(api): State<WorkspaceApi>,
    AxumPath(path): AxumPath<ScopedRuntimePath>,
    Json(request): Json<BrowserWorkingDirectoryCreateRequest>,
) -> ApiResult<(StatusCode, Json<BrowserWorkingDirectoryCreateResponse>)> {
    require_active_workspace_runtime_binding(&api, &path.runtime_id).await?;
    create_workspace_working_directory(
        &api,
        &path.workspace_id,
        Some(path.runtime_id.as_str()),
        request,
    )
    .await
}

async fn scoped_runtime_working_directory_detail(
    State(api): State<WorkspaceApi>,
    AxumPath(path): AxumPath<ScopedRuntimeWorkingDirectoryPath>,
) -> ApiResult<Json<BrowserWorkingDirectoryDetailResponse>> {
    validate_workspace_scope(&api, &path.workspace_id)?;
    require_active_workspace_runtime_binding(&api, &path.runtime_id).await?;
    api.host_executors
        .host()?
        .run(move || {
            working_directory_detail_for_runtime(api, &path.runtime_id, &path.working_directory_id)
        })
        .await
}

fn workdir_removal_source_actor(
    worker_source: Option<(&str, &str)>,
    request_actor: Option<&RequestActor>,
) -> ApiResult<String> {
    if let Some((runtime_id, worker_id)) = worker_source {
        Ok(format!("worker:{runtime_id}:{worker_id}"))
    } else if let Some(actor) = request_actor {
        Ok(format!("account:{}", actor.account_id))
    } else {
        Err(ApiError::from(Error::WorkspacePermissionDenied(
            "Workdir removal requires authenticated source authority".to_string(),
        )))
    }
}

fn contract_workdir_removal_source_actor(
    context: &server_api::ServerRequestContext,
) -> ApiResult<String> {
    let worker_source = context
        .worker_source
        .as_ref()
        .map(|source| (source.runtime_id.as_str(), source.worker_id.as_str()))
        .or_else(|| {
            context.runtime_source.as_ref().and_then(|source| {
                source
                    .worker_id
                    .as_deref()
                    .map(|worker_id| (source.runtime_id.as_str(), worker_id))
            })
        });
    workdir_removal_source_actor(worker_source, context.actor.as_ref())
}

async fn cleanup_runtime_working_directory_contract(
    api: WorkspaceApi,
    workspace_id: String,
    runtime_id: String,
    working_directory_id: String,
    context: server_api::ServerRequestContext,
    request: WorkingDirectoryRemovalRequest,
) -> ApiResult<WorkingDirectoryRemovalResponse> {
    let source_actor = contract_workdir_removal_source_actor(&context)?;
    cleanup_runtime_working_directory(
        api,
        ScopedRuntimeWorkingDirectoryPath {
            workspace_id,
            runtime_id,
            working_directory_id,
        },
        source_actor,
        request,
    )
    .await
}

async fn cleanup_working_directory_contract(
    api: WorkspaceApi,
    workspace_id: String,
    working_directory_id: String,
    context: server_api::ServerRequestContext,
    request: WorkingDirectoryRemovalRequest,
) -> ApiResult<WorkingDirectoryRemovalResponse> {
    let source_actor = contract_workdir_removal_source_actor(&context)?;
    cleanup_working_directory(
        api,
        ScopedWorkingDirectoryPath {
            workspace_id,
            working_directory_id,
        },
        source_actor,
        request,
    )
    .await
}

async fn cleanup_runtime_working_directory(
    api: WorkspaceApi,
    path: ScopedRuntimeWorkingDirectoryPath,
    source_actor: String,
    request: WorkingDirectoryRemovalRequest,
) -> ApiResult<WorkingDirectoryRemovalResponse> {
    validate_workspace_scope(&api, &path.workspace_id)?;
    require_active_workspace_runtime_binding(&api, &path.runtime_id).await?;
    api.host_executors
        .host()?
        .run(move || {
            let registered_runtime =
                registered_workdir_runtime_id(&api, &path.working_directory_id)?;
            if registered_runtime != path.runtime_id {
                return Err(ApiError::from(Error::WorkspacePermissionDenied(
                    "Workdir does not belong to the requested Runtime".to_string(),
                )));
            }
            execute_workdir_removal(
                &api,
                &path.working_directory_id,
                &source_actor,
                &request.reason,
            )
            .map_err(ApiError::from)
        })
        .await
}

fn external_workdir_expires_at(
    grant: &ExternalWorkdirGrantRecord,
) -> Result<Option<chrono::DateTime<Utc>>> {
    grant
        .expires_at
        .as_deref()
        .map(|value| {
            chrono::DateTime::parse_from_rfc3339(value)
                .map(|value| value.with_timezone(&Utc))
                .map_err(|_| Error::Store("External Workdir grant has invalid expiry".to_string()))
        })
        .transpose()
}

fn external_workdir_grant_is_expired(grant: &ExternalWorkdirGrantRecord) -> Result<bool> {
    Ok(external_workdir_expires_at(grant)?.is_some_and(|expires_at| expires_at <= Utc::now()))
}

fn schedule_external_workdir_expiry(
    api: &WorkspaceApi,
    grant: &ExternalWorkdirGrantRecord,
) -> Result<()> {
    let Some(expires_at) = external_workdir_expires_at(grant)? else {
        cancel_external_workdir_expiry(api, &grant.grant_id);
        return Ok(());
    };
    let grant_id = grant.grant_id.clone();
    let task_api = api.clone();
    let task_grant_id = grant_id.clone();
    let task_id = Uuid::now_v7();
    let task_instance_id = task_id;
    let (start_sender, start_receiver) = tokio::sync::oneshot::channel();
    let handle = tokio::spawn(async move {
        if start_receiver.await.is_err() {
            return;
        }
        let delay = (expires_at - Utc::now()).to_std().unwrap_or_default();
        tokio::time::sleep(delay).await;
        loop {
            match expire_external_workdir_grant(&task_api, &task_grant_id).await {
                Ok(true) => break,
                Ok(false) => {
                    // Wall time may have moved backwards after the monotonic
                    // sleep was calculated. Keep ownership and recheck without
                    // detaching an active grant.
                    tokio::time::sleep(std::time::Duration::from_secs(1)).await;
                }
                Err(error) => {
                    tracing::error!(grant_id = %task_grant_id, error = ?error, "Backend External Workdir expiry cleanup requires retry");
                    let stage_api = task_api.clone();
                    let stage_grant_id = task_grant_id.clone();
                    let retryable = task_api
                        .store
                        .db_executor()
                        .run(move || {
                            stage_api.store.get_external_workdir_grant(
                                &stage_api.config.workspace_id,
                                &stage_grant_id,
                            )
                        })
                        .await
                        .map_or(true, |grant| grant.is_some());
                    if !retryable {
                        break;
                    }
                    tokio::time::sleep(std::time::Duration::from_secs(5)).await;
                }
            }
        }
        let mut tasks = task_api
            .external_workdir_expiry_tasks
            .lock()
            .expect("External Workdir expiry task registry poisoned");
        if tasks
            .get(&task_grant_id)
            .is_some_and(|task| task.task_id == task_instance_id)
        {
            tasks.remove(&task_grant_id);
        }
    });
    let mut tasks = api
        .external_workdir_expiry_tasks
        .lock()
        .expect("External Workdir expiry task registry poisoned");
    if let Some(existing) = tasks.insert(grant_id, ExternalWorkdirExpiryTask { task_id, handle }) {
        existing.handle.abort();
    }
    drop(tasks);
    let _ = start_sender.send(());
    Ok(())
}

fn cancel_external_workdir_expiry(api: &WorkspaceApi, grant_id: &str) {
    if let Some(task) = api
        .external_workdir_expiry_tasks
        .lock()
        .expect("External Workdir expiry task registry poisoned")
        .remove(grant_id)
    {
        task.handle.abort();
    }
}

async fn stop_external_workdir_provider(
    api: &WorkspaceApi,
    grant: &ExternalWorkdirGrantRecord,
    reason: workdir::external::ExternalWorkdirRevokeReason,
) {
    let connection = {
        api.external_workdir_providers
            .lock()
            .expect("External Workdir provider registry poisoned")
            .disconnect(&grant.grant_id, grant.generation)
    };
    if let Some(connection) = connection {
        let _ = connection
            .sender
            .send(ExternalProviderCommand::Revoke { reason })
            .await;
    }
}

async fn fence_external_workdir_grant_expired(
    api: &WorkspaceApi,
    grant_id: &str,
) -> ApiResult<ExternalWorkdirGrantRecord> {
    let stage_api = api.clone();
    let grant_id = grant_id.to_string();
    api.store
        .db_executor()
        .run(move || fence_external_workdir_grant_expired_stage(&stage_api, &grant_id))
        .await
}

fn fence_external_workdir_grant_expired_stage(
    api: &WorkspaceApi,
    grant_id: &str,
) -> ApiResult<ExternalWorkdirGrantRecord> {
    loop {
        let mut grant = api
            .store
            .get_external_workdir_grant(&api.config.workspace_id, grant_id)?
            .ok_or_else(|| Error::InvalidInput("Unknown External Workdir grant".to_string()))?;
        if matches!(grant.status.as_str(), "revoked" | "expired") {
            return Ok(grant);
        }
        let Some(expires_at) = external_workdir_expires_at(&grant)? else {
            return Ok(grant);
        };
        if expires_at > Utc::now() {
            return Ok(grant);
        }
        let updated_at = Utc::now().to_rfc3339_opts(SecondsFormat::Nanos, true);
        if !api.store.update_external_workdir_grant_state(
            &grant.workspace_id,
            &grant.grant_id,
            &grant.provider_instance_id,
            grant.generation,
            "expired",
            &updated_at,
        )? {
            // A reconnect may advance generation between the read and fence.
            continue;
        }
        api.store.record_external_workdir_audit(
            &grant.workspace_id,
            "system",
            "workspace-backend",
            "external_workdir_grant_expired",
            &grant.grant_id,
            None,
            "expired",
            &format!(
                "workdir_id={} generation={}",
                grant.workdir_id, grant.generation
            ),
            &updated_at,
        )?;
        grant.status = "expired".to_string();
        grant.updated_at = updated_at;
        return Ok(grant);
    }
}

async fn expire_external_workdir_grant(api: &WorkspaceApi, grant_id: &str) -> ApiResult<bool> {
    let grant = fence_external_workdir_grant_expired(api, grant_id).await?;
    if !matches!(grant.status.as_str(), "revoked" | "expired") {
        return Ok(false);
    }
    let cleanup = cleanup_external_workdir_attachments(api, &grant.workdir_id).await;
    stop_external_workdir_provider(
        api,
        &grant,
        workdir::external::ExternalWorkdirRevokeReason::Expired,
    )
    .await;
    cleanup?;
    Ok(true)
}

async fn scoped_create_external_workdir_grant(
    State(api): State<WorkspaceApi>,
    AxumPath(path): AxumPath<ScopedWorkspacePath>,
    Extension(actor): Extension<RequestActor>,
    Json(request): Json<ExternalWorkdirGrantCreateRequest>,
) -> ApiResult<(StatusCode, Json<ExternalWorkdirGrantResponse>)> {
    api.store.db_executor().run(move || {

    validate_workspace_scope(&api, &path.workspace_id)?;
    let display_name = request.display_name.trim();
    if display_name.is_empty()
        || display_name.len() > 100
        || display_name.chars().any(char::is_control)
    {
        return Err(Error::InvalidInput(
            "External Workdir display name must be between 1 and 100 bytes and contain no control characters".to_string(),
        ).into());
    }
    if request
        .ttl_seconds
        .is_some_and(|ttl_seconds| !(60..=86_400).contains(&ttl_seconds))
    {
        return Err(Error::InvalidInput(
            "External Workdir ttl_seconds must be omitted or between 60 and 86400".to_string(),
        )
        .into());
    }
    ExternalProviderInstanceId::new(request.provider_instance_id.clone())
        .map_err(Error::InvalidInput)?;
    let now = Utc::now();
    let created_at = now.to_rfc3339_opts(SecondsFormat::Nanos, true);
    let expires_at = request
        .ttl_seconds
        .map(|ttl_seconds| now + Duration::seconds(ttl_seconds as i64))
        .map(|expires_at| expires_at.to_rfc3339_opts(SecondsFormat::Nanos, true));
    let permissions = persist_external_workdir_permissions(request.permissions)?;
    let grant_id = format!("ewg-{}", Uuid::now_v7());
    let workdir_id = format!("external-{}", Uuid::now_v7());
    let grant = ExternalWorkdirGrantRecord {
        grant_id: grant_id.clone(),
        workspace_id: api.config.workspace_id.clone(),
        workdir_id: workdir_id.clone(),
        provider_instance_id: request.provider_instance_id,
        display_name: display_name.to_string(),
        permissions: permissions.to_string(),
        created_by: actor.account_id,
        created_at: created_at.clone(),
        expires_at: expires_at.clone(),
        generation: 1,
        status: "pending".to_string(),
        updated_at: created_at.clone(),
    };
    let workdir = WorkdirRegistryRecord {
        workspace_id: api.config.workspace_id.clone(),
        workdir_id: workdir_id.clone(),
        display_name: Some(display_name.to_string()),
        source: WorkdirRegistrySource::ExternalGrant {
            grant_id: grant_id.clone(),
        },
        creation_selector: None,
        creation_ref: None,
        creation_tree: None,
        current_selector: None,
        current_ref: None,
        current_tree: None,
        observed_at_epoch_seconds: None,
        materialization_status: "pending".to_string(),
        cleanliness: "unknown".to_string(),
        created_at,
        updated_at: grant.updated_at.clone(),
    };
    api.store.create_external_workdir_grant(&grant, &workdir)?;
    schedule_external_workdir_expiry(&api, &grant)?;
    Ok((
        StatusCode::CREATED,
        Json(external_workdir_grant_response(&grant)?),
    ))

    }).await
}

fn external_workdir_grant_response(
    grant: &ExternalWorkdirGrantRecord,
) -> Result<ExternalWorkdirGrantResponse> {
    Ok(ExternalWorkdirGrantResponse {
        grant_id: grant.grant_id.clone(),
        workspace_id: grant.workspace_id.clone(),
        working_directory_id: grant.workdir_id.clone(),
        provider_instance_id: grant.provider_instance_id.clone(),
        display_name: grant.display_name.clone(),
        permissions: external_workdir_permissions(&grant.permissions)?,
        expires_at: grant.expires_at.clone(),
        generation: grant.generation,
        status: grant.status.clone(),
    })
}

async fn scoped_external_workdir_provider_ws(
    State(api): State<WorkspaceApi>,
    Extension(actor): Extension<RequestActor>,
    AxumPath((workspace_id, grant_id)): AxumPath<(String, String)>,
    ws: WebSocketUpgrade,
) -> ApiResult<Response> {
    let stage_api = api.clone();
    let stage_workspace_id = workspace_id.clone();
    let stage_grant_id = grant_id.clone();
    let mut grant = api.store.db_executor().run(move || -> ApiResult<_> {
        validate_workspace_scope(&stage_api, &stage_workspace_id)?;
        let grant = stage_api.store
            .get_external_workdir_grant(&stage_workspace_id, &stage_grant_id)?
            .ok_or_else(|| Error::InvalidInput("Unknown External Workdir grant".to_string()))?;
        if grant.created_by != actor.account_id {
            return Err(Error::WorkspacePermissionDenied(
                "External Workdir provider connection must use the grant creator's authenticated client".to_string(),
            ).into());
        }
        Ok(grant)
    }).await?;
    let expired = external_workdir_grant_is_expired(&grant)?;
    if expired {
        grant = fence_external_workdir_grant_expired(&api, &grant_id).await?;
    }
    if matches!(grant.status.as_str(), "revoked" | "expired") {
        cleanup_external_workdir_attachments(&api, &grant.workdir_id).await?;
        cancel_external_workdir_expiry(&api, &grant_id);
        return Err(
            Error::InvalidInput(format!("External Workdir grant is {}", grant.status)).into(),
        );
    }
    Ok(ws
        .max_message_size(workdir::external::MAX_EXTERNAL_PROVIDER_FRAME_BYTES)
        .max_frame_size(workdir::external::MAX_EXTERNAL_PROVIDER_FRAME_BYTES)
        .on_upgrade(move |socket| serve_external_workdir_provider(api, grant, socket)))
}

async fn send_external_workdir_server_frame(
    socket: &mut WebSocket,
    frame: &ExternalWorkdirServerFrame,
) -> bool {
    let Ok(text) = serde_json::to_string(frame) else {
        return false;
    };
    matches!(
        tokio::time::timeout(
            std::time::Duration::from_secs(5),
            socket.send(WsMessage::Text(text.into())),
        )
        .await,
        Ok(Ok(()))
    )
}

async fn reject_external_workdir_provider(socket: &mut WebSocket, code: u16, mut reason: String) {
    const MAX_CLOSE_REASON_BYTES: usize = 123;
    if reason.len() > MAX_CLOSE_REASON_BYTES {
        reason.truncate(MAX_CLOSE_REASON_BYTES);
    }
    let _ = socket
        .send(WsMessage::Close(Some(CloseFrame {
            code,
            reason: reason.into(),
        })))
        .await;
}

fn external_workdir_registration_parse_error(text: &str) -> String {
    let actual_version = serde_json::from_str::<serde_json::Value>(text)
        .ok()
        .and_then(|value| value.get("version")?.as_u64());
    match actual_version {
        Some(actual)
            if actual != workdir::external::EXTERNAL_WORKDIR_PROVIDER_PROTOCOL_VERSION as u64 =>
        {
            format!(
                "unsupported External Workdir protocol version {actual}; Backend requires {}",
                workdir::external::EXTERNAL_WORKDIR_PROVIDER_PROTOCOL_VERSION
            )
        }
        _ => "invalid External Workdir provider registration".to_string(),
    }
}

async fn serve_external_workdir_provider(
    api: WorkspaceApi,
    initial_grant: ExternalWorkdirGrantRecord,
    mut socket: WebSocket,
) {
    let registration_text =
        match tokio::time::timeout(std::time::Duration::from_secs(10), socket.next()).await {
            Ok(Some(Ok(WsMessage::Text(text)))) if text.len() <= 64 * 1024 => text,
            _ => {
                reject_external_workdir_provider(
                    &mut socket,
                    1008,
                    "External Workdir provider registration was missing or oversized".to_string(),
                )
                .await;
                return;
            }
        };
    let registration_frame =
        match serde_json::from_str::<ExternalWorkdirProviderFrame>(&registration_text) {
            Ok(frame) => frame,
            Err(_) => {
                let reason = external_workdir_registration_parse_error(&registration_text);
                reject_external_workdir_provider(&mut socket, 1002, reason).await;
                return;
            }
        };
    let ExternalWorkdirProviderFrame {
        message: ExternalWorkdirProviderMessage::Register { registration },
        ..
    } = registration_frame
    else {
        reject_external_workdir_provider(
            &mut socket,
            1008,
            "expected External Workdir provider registration".to_string(),
        )
        .await;
        return;
    };
    let expected_capabilities = match external_workdir_capabilities(&initial_grant.permissions) {
        Ok(capabilities) => capabilities,
        Err(_) => {
            reject_external_workdir_provider(
                &mut socket,
                1011,
                "Backend could not validate External Workdir capabilities".to_string(),
            )
            .await;
            return;
        }
    };
    if registration.read_limits != workdir::BoundedReadLimits::EXTERNAL_DEFAULT {
        let required = workdir::BoundedReadLimits::EXTERNAL_DEFAULT;
        reject_external_workdir_provider(
            &mut socket,
            1008,
            format!(
                "provider read limits source={} response={}; Backend requires source={} response={}",
                registration.read_limits.max_source_bytes,
                registration.read_limits.max_response_bytes,
                required.max_source_bytes,
                required.max_response_bytes,
            ),
        )
        .await;
        return;
    }
    if registration.grant_id.as_str() != initial_grant.grant_id
        || registration.workdir_id.as_str() != initial_grant.workdir_id
        || registration.provider_instance_id.as_str() != initial_grant.provider_instance_id
        || registration.capabilities != expected_capabilities
        || registration.generation == 0
    {
        reject_external_workdir_provider(
            &mut socket,
            1008,
            "External Workdir provider registration does not match the grant".to_string(),
        )
        .await;
        return;
    }
    let stage_api = api.clone();
    let stage_grant = initial_grant.clone();
    let registration_generation = registration.generation;
    let registration_capabilities = registration.capabilities;
    let activation = api
        .store
        .db_executor()
        .run(move || -> Result<_> {
            let api = stage_api;
            let initial_grant = stage_grant;
            let now = Utc::now().to_rfc3339_opts(SecondsFormat::Nanos, true);
            if !api
                .store
                .activate_external_workdir_grant(
                    &initial_grant.workspace_id,
                    &initial_grant.grant_id,
                    &initial_grant.provider_instance_id,
                    registration_generation,
                    &now,
                )
                .unwrap_or(false)
            {
                return Ok(None);
            }
            if let Err(error) = api.store.record_external_workdir_audit(
                &initial_grant.workspace_id,
                "account",
                &initial_grant.created_by,
                "external_workdir_provider_connected",
                &initial_grant.grant_id,
                None,
                "online",
                &format!(
                    "workdir_id={} generation={}",
                    initial_grant.workdir_id, registration_generation
                ),
                &now,
            ) {
                let _ = api.store.update_external_workdir_grant_state(
                    &initial_grant.workspace_id,
                    &initial_grant.grant_id,
                    &initial_grant.provider_instance_id,
                    registration_generation,
                    "offline",
                    &now,
                );
                tracing::error!(
                    grant_id = %initial_grant.grant_id,
                    generation = registration_generation,
                    %error,
                    "failed to audit External Workdir provider activation"
                );
                return Ok(None);
            }
            let expires_at = match external_workdir_expires_at(&initial_grant) {
                Ok(value) => value,
                Err(_) => return Ok(None),
            };
            let (sender, commands) = tokio::sync::mpsc::channel(32);
            let connection = Arc::new(ExternalProviderConnection {
                grant_id: initial_grant.grant_id.clone(),
                workdir_id: initial_grant.workdir_id.clone(),
                provider_instance_id: initial_grant.provider_instance_id.clone(),
                generation: registration_generation,
                expires_at,
                capabilities: registration_capabilities,
                admission: Arc::new(tokio::sync::Semaphore::new(16)),
                shutdown_confirmed: Arc::new(std::sync::atomic::AtomicBool::new(false)),
                sender,
            });
            // Publish with the accepted activation stage, never in its cancellable waiter.
            if api
                .external_workdir_providers
                .lock()
                .expect("External Workdir provider registry poisoned")
                .connected(connection.clone())
                .is_some()
            {
                return Ok(None);
            }
            Ok(Some((connection, commands)))
        })
        .await;
    let (connection, mut commands) = match activation {
        Ok(Some(activated)) => activated,
        Ok(None) => {
            let _ = socket.close().await;
            return;
        }
        Err(error) => {
            tracing::error!(grant_id = %initial_grant.grant_id, %error,
                "External Workdir provider activation stage failed");
            let _ = socket.close().await;
            return;
        }
    };
    let registered =
        ExternalWorkdirServerFrame::current(ExternalWorkdirServerMessage::Registered {
            generation: connection.generation,
            heartbeat_interval_ms: 10_000,
            max_in_flight_operations: 16,
        });
    if !send_external_workdir_server_frame(&mut socket, &registered).await {
        let stage_api = api.clone();
        let stage_grant = initial_grant.clone();
        let stage_connection = connection.clone();
        if let Err(error) = api
            .store
            .db_executor()
            .run(move || {
                stage_api
                    .external_workdir_providers
                    .lock()
                    .expect("External Workdir provider registry poisoned")
                    .disconnect(&stage_connection.grant_id, stage_connection.generation);
                stage_api.store.update_external_workdir_grant_state(
                    &stage_grant.workspace_id,
                    &stage_grant.grant_id,
                    &stage_connection.provider_instance_id,
                    stage_connection.generation,
                    "offline",
                    &Utc::now().to_rfc3339_opts(SecondsFormat::Nanos, true),
                )
            })
            .await
        {
            // Rejected admission must not leave a dead socket discoverable.
            // The generation-bound in-memory fence is safe even for an unknown
            // DB outcome; it neither guesses nor retries the durable mutation.
            api.external_workdir_providers
                .lock()
                .expect("External Workdir provider registry poisoned")
                .disconnect(&connection.grant_id, connection.generation);
            tracing::error!(
                grant_id = %initial_grant.grant_id,
                generation = connection.generation,
                %error,
                "failed to persist External Workdir provider registration disconnect"
            );
        }
        return;
    }

    let mut pending = HashMap::<
        String,
        tokio::sync::oneshot::Sender<
            std::result::Result<WorkdirSessionOperationResult, WorkdirTransportError>,
        >,
    >::new();
    let mut heartbeat = tokio::time::interval(std::time::Duration::from_secs(10));
    heartbeat.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Delay);
    let mut heartbeat_sequence = 0_u64;
    let mut last_heartbeat_ack = tokio::time::Instant::now();
    let mut revoking = false;
    let terminal_status = loop {
        tokio::select! {
            _ = heartbeat.tick() => {
                if last_heartbeat_ack.elapsed() > std::time::Duration::from_secs(30) {
                    break "offline";
                }
                heartbeat_sequence = heartbeat_sequence.saturating_add(1);
                let frame = ExternalWorkdirServerFrame::current(ExternalWorkdirServerMessage::Heartbeat {
                    generation: connection.generation,
                    sequence: heartbeat_sequence,
                });
                if !send_external_workdir_server_frame(&mut socket, &frame).await {
                    break "offline";
                }
            }
            command = commands.recv() => match command {
                Some(ExternalProviderCommand::Operation { operation_id, operation, response }) => {
                    if revoking {
                        let _ = response.send(Err(WorkdirTransportError {
                            failure_reason: None,
                            denial_reason: None,
                            code: workdir::http::WorkdirTransportErrorCode::Unavailable,
                            message: "External Workdir provider shutdown is in progress".to_string(),
                        }));
                        continue;
                    }
                    let pending_limit = if matches!(&operation, WorkdirSessionOperation::CommandCancel(_)) {
                        16 + MAX_ACTIVE_SERVER_COMMANDS
                    } else {
                        16
                    };
                    if pending.len() >= pending_limit {
                        let _ = response.send(Err(WorkdirTransportError {
                            failure_reason: None,
                            denial_reason: None,
                            code: workdir::http::WorkdirTransportErrorCode::Unavailable,
                            message: "External Workdir provider is at its in-flight operation limit".to_string(),
                        }));
                        continue;
                    }
                    let id = operation_id.as_str().to_string();
                    let operation = match ExternalWorkdirOperation::try_from(operation) {
                        Ok(operation) => operation,
                        Err(message) => {
                            let _ = response.send(Err(WorkdirTransportError {
                                failure_reason: None,
                                denial_reason: None,
                                code: workdir::http::WorkdirTransportErrorCode::InvalidRequest,
                                message,
                            }));
                            continue;
                        }
                    };
                    let frame = ExternalWorkdirServerFrame::current(ExternalWorkdirServerMessage::Operation {
                        generation: connection.generation,
                        operation_id,
                        operation,
                    });
                    pending.insert(id.clone(), response);
                    if !send_external_workdir_server_frame(&mut socket, &frame).await {
                        pending.remove(&id);
                        break "offline";
                    }
                }
                Some(ExternalProviderCommand::Cancel { operation_id }) => {
                    pending.remove(operation_id.as_str());
                    let frame = ExternalWorkdirServerFrame::current(ExternalWorkdirServerMessage::Cancel {
                        generation: connection.generation,
                        operation_id,
                    });
                    if !send_external_workdir_server_frame(&mut socket, &frame).await {
                        break "offline";
                    }
                }
                Some(ExternalProviderCommand::Revoke { reason }) => {
                    if revoking {
                        continue;
                    }
                    let frame = ExternalWorkdirServerFrame::current(ExternalWorkdirServerMessage::Revoke {
                        generation: connection.generation,
                        reason,
                    });
                    if !send_external_workdir_server_frame(&mut socket, &frame).await {
                        break "offline";
                    }
                    revoking = true;
                }
                None => break "offline",
            },
            incoming = socket.next() => match incoming {
                Some(Ok(WsMessage::Text(text)))
                    if text.len() <= workdir::external::MAX_EXTERNAL_PROVIDER_FRAME_BYTES => {
                    let Ok(frame) = serde_json::from_str::<ExternalWorkdirProviderFrame>(&text) else { break "offline"; };
                    match frame.message {
                        ExternalWorkdirProviderMessage::OperationResult { generation, operation_id, outcome }
                            if generation == connection.generation => {
                                if let Some(response) = pending.remove(operation_id.as_str()) {
                                    let result = match outcome {
                                        ExternalWorkdirOperationOutcome::Completed { result } => Ok(result.into_inner()),
                                        ExternalWorkdirOperationOutcome::Failed { error } => {
                                            Err(error.into_transport_error())
                                        }
                                        ExternalWorkdirOperationOutcome::Cancelled => Err(WorkdirTransportError {
                                            failure_reason: None,
                                            denial_reason: None,
                                            code: workdir::http::WorkdirTransportErrorCode::Unavailable,
                                            message: "External Workdir operation was cancelled".to_string(),
                                        }),
                                    };
                                    let _ = response.send(result);
                                }
                            }
                        ExternalWorkdirProviderMessage::Heartbeat { generation, sequence }
                            if generation == connection.generation && sequence == heartbeat_sequence => {
                                last_heartbeat_ack = tokio::time::Instant::now();
                            }
                        ExternalWorkdirProviderMessage::RevokeAcknowledged { generation }
                            if revoking && generation == connection.generation => {
                                connection.shutdown_confirmed.store(true, Ordering::Release);
                                break "revoked";
                            }
                        _ => break "offline",
                    }
                }
                Some(Ok(WsMessage::Ping(bytes))) => {
                    let _ = tokio::time::timeout(
                        std::time::Duration::from_secs(5),
                        socket.send(WsMessage::Pong(bytes)),
                    )
                    .await;
                }
                Some(Ok(WsMessage::Close(_))) | None | Some(Err(_)) => break "offline",
                _ => {}
            }
        }
    };
    pending.clear();
    let stage_api = api.clone();
    let stage_grant = initial_grant.clone();
    let stage_connection = connection.clone();
    let terminal_update = api
        .store
        .db_executor()
        .run(move || -> Result<_> {
            let api = stage_api;
            let initial_grant = stage_grant;
            let connection = stage_connection;
            let _ = api
                .external_workdir_providers
                .lock()
                .expect("External Workdir provider registry poisoned")
                .disconnect(&connection.grant_id, connection.generation);
            let state_updated = match api.store.update_external_workdir_grant_state(
                &initial_grant.workspace_id,
                &initial_grant.grant_id,
                &connection.provider_instance_id,
                connection.generation,
                terminal_status,
                &Utc::now().to_rfc3339_opts(SecondsFormat::Nanos, true),
            ) {
                Ok(updated) => updated,
                Err(error) => {
                    tracing::error!(
                        grant_id = %initial_grant.grant_id,
                        generation = connection.generation,
                        status = terminal_status,
                        %error,
                        "failed to persist External Workdir provider terminal state"
                    );
                    false
                }
            };
            if state_updated
                && let Err(error) = api.store.record_external_workdir_audit(
                    &initial_grant.workspace_id,
                    "account",
                    &initial_grant.created_by,
                    "external_workdir_provider_disconnected",
                    &initial_grant.grant_id,
                    None,
                    terminal_status,
                    &format!(
                        "workdir_id={} generation={}",
                        initial_grant.workdir_id, connection.generation
                    ),
                    &Utc::now().to_rfc3339_opts(SecondsFormat::Nanos, true),
                )
            {
                tracing::error!(
                    grant_id = %initial_grant.grant_id,
                    generation = connection.generation,
                    status = terminal_status,
                    %error,
                    "failed to audit External Workdir provider terminal state"
                );
            }
            Ok(state_updated)
        })
        .await;
    let state_updated = match terminal_update {
        Ok(updated) => updated,
        Err(error) => {
            api.external_workdir_providers
                .lock()
                .expect("External Workdir provider registry poisoned")
                .disconnect(&connection.grant_id, connection.generation);
            tracing::error!(grant_id = %initial_grant.grant_id,
                generation = connection.generation, status = terminal_status, %error,
                "External Workdir provider terminal stage failed");
            false
        }
    };
    if state_updated
        && matches!(terminal_status, "expired" | "revoked")
        && let Err(error) =
            cleanup_external_workdir_attachments(&api, &initial_grant.workdir_id).await
    {
        tracing::error!(
            grant_id = %initial_grant.grant_id,
            workdir_id = %initial_grant.workdir_id,
            error = ?error,
            "External Workdir terminal attachment cleanup requires retry"
        );
    }
}

async fn scoped_get_external_workdir_grant(
    State(api): State<WorkspaceApi>,
    Extension(actor): Extension<RequestActor>,
    AxumPath((workspace_id, grant_id)): AxumPath<(String, String)>,
) -> ApiResult<Json<ExternalWorkdirGrantResponse>> {
    let stage_api = api.clone();
    let stage_workspace_id = workspace_id.clone();
    let stage_grant_id = grant_id.clone();
    let mut grant = api
        .store
        .db_executor()
        .run(move || -> ApiResult<_> {
            validate_workspace_scope(&stage_api, &stage_workspace_id)?;
            let grant = stage_api
                .store
                .get_external_workdir_grant(&stage_workspace_id, &stage_grant_id)?
                .ok_or_else(|| Error::InvalidInput("Unknown External Workdir grant".to_string()))?;
            if grant.created_by != actor.account_id {
                return Err(Error::WorkspacePermissionDenied(
                    "External Workdir grant inspection requires the grant creator".to_string(),
                )
                .into());
            }
            Ok(grant)
        })
        .await?;
    let expired = !matches!(grant.status.as_str(), "revoked" | "expired")
        && external_workdir_grant_is_expired(&grant)?;
    if expired {
        grant = fence_external_workdir_grant_expired(&api, &grant_id).await?;
    }
    // Terminal cleanup is retryable: a prior expiry/revoke may have committed
    // its fence before Runtime/session projection completed.
    if matches!(grant.status.as_str(), "expired" | "revoked") {
        let cleanup = cleanup_external_workdir_attachments(&api, &grant.workdir_id).await;
        let reason = if grant.status == "expired" {
            workdir::external::ExternalWorkdirRevokeReason::Expired
        } else {
            workdir::external::ExternalWorkdirRevokeReason::UserRequested
        };
        stop_external_workdir_provider(&api, &grant, reason).await;
        cleanup?;
        cancel_external_workdir_expiry(&api, &grant_id);
    }
    Ok(Json(external_workdir_grant_response(&grant)?))
}

async fn scoped_revoke_external_workdir_grant(
    State(api): State<WorkspaceApi>,
    Extension(actor): Extension<RequestActor>,
    AxumPath((workspace_id, grant_id)): AxumPath<(String, String)>,
) -> ApiResult<Json<ExternalWorkdirGrantResponse>> {
    let stage_api = api.clone();
    let stage_workspace_id = workspace_id.clone();
    let stage_grant_id = grant_id.clone();
    let grant = api
        .store
        .db_executor()
        .run(move || -> ApiResult<_> {
            let api = stage_api;
            let workspace_id = stage_workspace_id;
            let grant_id = stage_grant_id;
            validate_workspace_scope(&api, &workspace_id)?;
            let mut grant = api
                .store
                .get_external_workdir_grant(&workspace_id, &grant_id)?
                .ok_or_else(|| Error::InvalidInput("Unknown External Workdir grant".to_string()))?;
            if grant.created_by != actor.account_id {
                return Err(Error::WorkspacePermissionDenied(
                    "External Workdir revoke requires the grant creator".to_string(),
                )
                .into());
            }
            let updated_at = Utc::now().to_rfc3339_opts(SecondsFormat::Nanos, true);
            if !matches!(grant.status.as_str(), "revoked" | "expired") {
                api.store.update_external_workdir_grant_state(
                    &workspace_id,
                    &grant_id,
                    &grant.provider_instance_id,
                    grant.generation,
                    "revoked",
                    &updated_at,
                )?;
                grant.status = "revoked".to_string();
                grant.updated_at = updated_at;
                api.store.record_external_workdir_audit(
                    &workspace_id,
                    "account",
                    &actor.account_id,
                    "external_workdir_grant_revoked",
                    &grant_id,
                    None,
                    "revoked",
                    &format!(
                        "workdir_id={} generation={}",
                        grant.workdir_id, grant.generation
                    ),
                    &grant.updated_at,
                )?;
            }
            Ok(grant)
        })
        .await?;
    // Cleanup is deliberately retried for terminal grants. A prior revoke may
    // have committed its fence before a Runtime/session projection failure.
    let cleanup = cleanup_external_workdir_attachments(&api, &grant.workdir_id).await;
    stop_external_workdir_provider(
        &api,
        &grant,
        workdir::external::ExternalWorkdirRevokeReason::UserRequested,
    )
    .await;
    cleanup?;
    cancel_external_workdir_expiry(&api, &grant_id);
    Ok(Json(external_workdir_grant_response(&grant)?))
}

async fn cleanup_external_workdir_attachments(
    api: &WorkspaceApi,
    workdir_id: &str,
) -> ApiResult<()> {
    cleanup_external_workdir_attachments_with_lock(api, workdir_id, None).await
}

async fn cleanup_external_workdir_attachments_with_lock(
    api: &WorkspaceApi,
    workdir_id: &str,
    already_locked_worker: Option<(&RuntimeWorkerRef, &Arc<tokio::sync::OwnedMutexGuard<()>>)>,
) -> ApiResult<()> {
    let stage_api = api.clone();
    let stage_workdir_id = workdir_id.to_string();
    let stage_guard = already_locked_worker.map(|(_, guard)| guard.clone());
    let grant_id = api
        .store
        .db_executor()
        .run(move || -> Result<_> {
            let _session_guard = stage_guard;
            let workdir = stage_api
                .store
                .get_workdir_registry(&stage_api.config.workspace_id, &stage_workdir_id)?
                .ok_or_else(|| Error::InvalidInput("Unknown External Workdir".to_string()))?;
            let grant_id = workdir
                .source
                .external_grant_id()
                .ok_or_else(|| {
                    Error::InvalidInput("Workdir is not backed by an External grant".to_string())
                })?
                .to_string();
            stage_api.store.update_external_workdir_cleanup_state(
                &stage_api.config.workspace_id,
                &grant_id,
                "pending",
                None,
                &Utc::now().to_rfc3339_opts(SecondsFormat::Nanos, true),
            )?;
            Ok(grant_id)
        })
        .await?;

    let release =
        release_external_workdir_attachments(api, workdir_id, already_locked_worker).await;
    let stage_api = api.clone();
    let stage_workdir_id = workdir_id.to_string();
    let succeeded = release.is_ok();
    let stage_guard = already_locked_worker.map(|(_, guard)| guard.clone());
    api.store
        .db_executor()
        .run(move || -> Result<()> {
            let _session_guard = stage_guard;
            let now = Utc::now().to_rfc3339_opts(SecondsFormat::Nanos, true);
            let (state, category, event, outcome, detail) = if succeeded {
                (
                    "completed",
                    None,
                    "external_workdir_cleanup_completed",
                    "completed",
                    format!("workdir_id={stage_workdir_id}"),
                )
            } else {
                (
                    "retry_required",
                    Some("attachment_release_failed"),
                    "external_workdir_cleanup_attention_required",
                    "attention_required",
                    format!("workdir_id={stage_workdir_id} category=attachment_release_failed"),
                )
            };
            stage_api.store.update_external_workdir_cleanup_state(
                &stage_api.config.workspace_id,
                &grant_id,
                state,
                category,
                &now,
            )?;
            stage_api.store.record_external_workdir_audit(
                &stage_api.config.workspace_id,
                "system",
                "workspace-backend",
                event,
                &grant_id,
                None,
                outcome,
                &detail,
                &now,
            )?;
            Ok(())
        })
        .await?;
    release
}

#[cfg(test)]
fn external_workdir_cleanup_failure_slot() -> &'static Mutex<Option<String>> {
    use std::sync::OnceLock;

    static INJECTED_WORKDIR: OnceLock<Mutex<Option<String>>> = OnceLock::new();
    INJECTED_WORKDIR.get_or_init(|| Mutex::new(None))
}

#[cfg(test)]
fn inject_external_workdir_cleanup_failure(workdir_id: &str) {
    *external_workdir_cleanup_failure_slot()
        .lock()
        .expect("External cleanup injection lock poisoned") = Some(workdir_id.to_string());
}

#[cfg(test)]
fn take_external_workdir_cleanup_failure(workdir_id: &str) -> bool {
    let mut injected = external_workdir_cleanup_failure_slot()
        .lock()
        .expect("External cleanup injection lock poisoned");
    if injected.as_deref() == Some(workdir_id) {
        *injected = None;
        true
    } else {
        false
    }
}

#[cfg(test)]
fn external_workdir_cleanup_reconciliations() -> &'static Mutex<HashMap<String, usize>> {
    use std::sync::OnceLock;

    static RECONCILIATIONS: OnceLock<Mutex<HashMap<String, usize>>> = OnceLock::new();
    RECONCILIATIONS.get_or_init(|| Mutex::new(HashMap::new()))
}

#[cfg(test)]
fn record_external_workdir_cleanup_reconciliation(workdir_id: &str) {
    let mut reconciliations = external_workdir_cleanup_reconciliations()
        .lock()
        .expect("External cleanup reconciliation lock poisoned");
    *reconciliations.entry(workdir_id.to_string()).or_default() += 1;
}

#[cfg(test)]
fn external_workdir_cleanup_reconciliation_count(workdir_id: &str) -> usize {
    external_workdir_cleanup_reconciliations()
        .lock()
        .expect("External cleanup reconciliation lock poisoned")
        .get(workdir_id)
        .copied()
        .unwrap_or_default()
}

async fn release_external_workdir_attachment_locked(
    api: &WorkspaceApi,
    workdir_id: &str,
    link: &WorkerWorkdirLinkRecord,
    session_guard: &Arc<tokio::sync::OwnedMutexGuard<()>>,
) -> ApiResult<()> {
    if link.unlinked_at.is_none() {
        close_current_worker_attachment_session_locked(api, &link.worker).await?;
        close_current_worker_command_sessions_for_alias_locked(api, &link.worker, &link.alias)
            .await?;
        let stage_api = api.clone();
        let stage_worker = link.worker.clone();
        let stage_workdir_id = workdir_id.to_string();
        let stage_guard = session_guard.clone();
        api.store
            .db_executor()
            .run(move || {
                let _session_guard = stage_guard;
                stage_api.store.detach_worker_workdir(
                    &stage_api.config.workspace_id,
                    &stage_worker,
                    Some(&stage_workdir_id),
                    &Utc::now().to_rfc3339_opts(SecondsFormat::Nanos, true),
                )
            })
            .await?;
        #[cfg(test)]
        if take_external_workdir_cleanup_failure(workdir_id) {
            return Err(Error::RuntimeOperationFailed {
                runtime_id: "workspace-backend".to_string(),
                code: "injected_external_workdir_cleanup_failure".to_string(),
                message: "injected External Workdir attachment cleanup failure".to_string(),
            }
            .into());
        }
    }
    // Reconcile even an already-unlinked durable link. A previous cleanup may
    // have committed detach before Runtime persistence or projection failed.
    #[cfg(test)]
    record_external_workdir_cleanup_reconciliation(workdir_id);
    sync_runtime_worker_workdir_attachments_locked(api, &link.worker, session_guard).await?;
    api.worker_projection
        .refresh_async(&link.worker)
        .await
        .map_err(ApiError::from)?;
    Ok(())
}

async fn release_external_workdir_attachments(
    api: &WorkspaceApi,
    workdir_id: &str,
    already_locked_worker: Option<(&RuntimeWorkerRef, &Arc<tokio::sync::OwnedMutexGuard<()>>)>,
) -> ApiResult<()> {
    let stage_api = api.clone();
    let stage_workdir_id = workdir_id.to_string();
    let Some(link) = api
        .store
        .db_executor()
        .run(move || {
            stage_api
                .store
                .latest_workdir_worker_link(&stage_api.config.workspace_id, &stage_workdir_id)
        })
        .await?
    else {
        return Ok(());
    };
    // The newest link is the only possible active attachment and remains the
    // durable reconciliation target if detach committed before Runtime update.
    // Missing/ambiguous Runtime state remains a retryable cleanup failure.
    if let Some((worker, guard)) =
        already_locked_worker.filter(|(worker, _)| *worker == &link.worker)
    {
        debug_assert_eq!(worker, &link.worker);
        release_external_workdir_attachment_locked(api, workdir_id, &link, guard).await?;
    } else {
        let lock = current_worker_session_lock(api, &link.worker);
        let guard = Arc::new(lock.lock_owned().await);
        release_external_workdir_attachment_locked(api, workdir_id, &link, &guard).await?;
    }
    Ok(())
}

async fn scoped_list_working_directories(
    State(api): State<WorkspaceApi>,
    AxumPath(path): AxumPath<ScopedWorkspacePath>,
) -> ApiResult<Json<BrowserWorkingDirectoryListResponse>> {
    api.host_executors
        .host()?
        .run(move || {
            validate_workspace_scope(&api, &path.workspace_id)?;
            let (items, diagnostics) = working_directory_summaries(&api)?;
            let items = items.into_iter().map(Into::into).collect();
            Ok(Json(BrowserWorkingDirectoryListResponse {
                workspace_id: api.config.workspace_id.clone(),
                items,
                diagnostics: working_directory_diagnostics(diagnostics),
            }))
        })
        .await
}

async fn scoped_create_working_directory(
    State(api): State<WorkspaceApi>,
    AxumPath(path): AxumPath<ScopedWorkspacePath>,
    Json(request): Json<BrowserWorkingDirectoryCreateRequest>,
) -> ApiResult<(StatusCode, Json<BrowserWorkingDirectoryCreateResponse>)> {
    create_workspace_working_directory(&api, &path.workspace_id, None, request).await
}

async fn scoped_working_directory_detail(
    State(api): State<WorkspaceApi>,
    AxumPath(path): AxumPath<ScopedWorkingDirectoryPath>,
) -> ApiResult<Json<BrowserWorkingDirectoryDetailResponse>> {
    api.host_executors
        .host()?
        .run(move || {
            validate_workspace_scope(&api, &path.workspace_id)?;
            let record = api
                .store
                .get_workdir_registry(&api.config.workspace_id, &path.working_directory_id)?
                .ok_or_else(|| Error::RuntimeOperationFailed {
                    runtime_id: "workspace-backend".to_string(),
                    code: "working_directory_not_found".to_string(),
                    message: format!("Unknown Workdir `{}`", path.working_directory_id),
                })?;
            if let WorkdirRegistrySource::WorkspaceConfig { grant_id } = &record.source {
                let grant = api
                    .store
                    .get_workspace_config_grant(&api.config.workspace_id, grant_id)?
                    .ok_or_else(|| {
                        Error::WorkspacePermissionDenied(
                            "Workspace config grant unavailable".into(),
                        )
                    })?;
                return Ok(Json(BrowserWorkingDirectoryDetailResponse {
                    workspace_id: api.config.workspace_id.clone(),
                    runtime_id: None,
                    item: workspace_config::summary(&grant, &record),
                    diagnostics: vec![],
                }));
            }
            if let Some(runtime_id) = record.source.runtime_id().map(str::to_string) {
                working_directory_detail_for_runtime(api, &runtime_id, &path.working_directory_id)
            } else {
                let item = projected_workdir_summary_from_record(&api, &record)?;
                Ok(Json(BrowserWorkingDirectoryDetailResponse {
                    workspace_id: api.config.workspace_id.clone(),
                    runtime_id: None,
                    item: item.into(),
                    diagnostics: Vec::new(),
                }))
            }
        })
        .await
}

async fn cleanup_working_directory(
    api: WorkspaceApi,
    path: ScopedWorkingDirectoryPath,
    source_actor: String,
    request: WorkingDirectoryRemovalRequest,
) -> ApiResult<WorkingDirectoryRemovalResponse> {
    validate_workspace_scope(&api, &path.workspace_id)?;
    api.host_executors
        .host()?
        .run(move || {
            execute_workdir_removal(
                &api,
                &path.working_directory_id,
                &source_actor,
                &request.reason,
            )
            .map_err(ApiError::from)
        })
        .await
}

fn registered_workdir_runtime_id(
    api: &WorkspaceApi,
    working_directory_id: &str,
) -> ApiResult<String> {
    api.store
        .get_workdir_registry(&api.config.workspace_id, working_directory_id)?
        .and_then(|record| record.source.runtime_id().map(str::to_string))
        .ok_or_else(|| {
            ApiError::with_diagnostics(
                Error::RuntimeOperationFailed {
                    runtime_id: "workspace-backend".to_string(),
                    code: "working_directory_not_found".to_string(),
                    message: format!("Unknown Workdir `{working_directory_id}`"),
                },
                Vec::new(),
            )
        })
}

fn workdir_runtime_failure_code(error: &RuntimeRegistryError) -> String {
    match error {
        RuntimeRegistryError::UnknownRuntime(_) | RuntimeRegistryError::UnknownHost(_) => {
            "runtime_unavailable".to_string()
        }
        RuntimeRegistryError::WorkdirSessionOpenFailed { .. } => {
            "workdir_session_open_failed".to_string()
        }
        RuntimeRegistryError::RuntimeOperationFailed { code, .. } => code.clone(),
        RuntimeRegistryError::InvalidIdentifier { .. } => "invalid_runtime".to_string(),
        RuntimeRegistryError::UnknownWorker { .. } => "runtime_workdir_lookup_failed".to_string(),
    }
}

fn workdir_rejection_failure_code(diagnostics: &[RuntimeDiagnostic]) -> String {
    diagnostics
        .iter()
        .find(|diagnostic| {
            diagnostic.severity == HostDiagnosticSeverity::Error
                && !diagnostic.code.is_empty()
                && diagnostic.code.len() <= 128
                && diagnostic
                    .code
                    .bytes()
                    .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'_')
        })
        .map(|diagnostic| diagnostic.code.clone())
        .unwrap_or_else(|| "runtime_workdir_create_failed".to_string())
}

fn finish_rejected_workdir_create_operation(
    store: &crate::SqliteWorkspaceStore,
    workspace_id: &str,
    operation_id: &str,
    request_fingerprint: &str,
    diagnostics: &[RuntimeDiagnostic],
    updated_at: &str,
) -> Result<String> {
    let failure_code = workdir_rejection_failure_code(diagnostics);
    store.finish_workdir_create_operation(
        workspace_id,
        operation_id,
        request_fingerprint,
        false,
        Some(&failure_code),
        updated_at,
    )?;
    Ok(failure_code)
}

async fn fail_workdir_create_stage(
    api: &WorkspaceApi,
    reserved: &WorkdirCreateOperationRecord,
    request_fingerprint: &str,
    failure: &str,
    remove_registry: bool,
) -> Result<WorkdirCreateOperationRecord> {
    let stage_api = api.clone();
    let reserved = reserved.clone();
    let request_fingerprint = request_fingerprint.to_string();
    let failure = failure.to_string();
    api.store
        .db_executor()
        .run(move || {
            if remove_registry {
                let _ = stage_api.store.delete_workdir_registry(
                    &reserved.workspace_id,
                    &reserved.working_directory_id,
                );
            }
            stage_api.config_store.finish_workdir_create_operation(
                &reserved.workspace_id,
                &reserved.operation_id,
                &request_fingerprint,
                false,
                Some(&failure),
                &now_registry_timestamp(),
            )
        })
        .await
}

fn prepare_workspace_workdir_create(
    api: &WorkspaceApi,
    workspace_id: &str,
    route_runtime_id: Option<&str>,
    mut request: BrowserWorkingDirectoryCreateRequest,
) -> ApiResult<(
    WorkingDirectoryRequest,
    String,
    String,
    WorkdirCreateOperationRecord,
)> {
    validate_workspace_scope(api, workspace_id)?;
    request.display_name = request
        .display_name
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|value| {
            if value.len() > 80 || value.chars().any(char::is_control) {
                return Err(Error::InvalidInput(
                    "display_name must contain no control characters and be at most 80 bytes"
                        .to_string(),
                ));
            }
            Ok(value.to_string())
        })
        .transpose()?;
    if let (Some(route_runtime_id), Some(request_runtime_id)) =
        (route_runtime_id, request.runtime_id.as_deref())
        && route_runtime_id != request_runtime_id
    {
        return Err(Error::InvalidInput(
            "runtime_id does not match the runtime-scoped route".to_string(),
        )
        .into());
    }
    let requested_runtime_id = route_runtime_id
        .map(str::to_string)
        .or_else(|| request.runtime_id.clone());
    let mut working_directory_request =
        working_directory_request_for_browser(api, request.clone())?;
    let operation_id = request
        .operation_id
        .clone()
        .unwrap_or_else(|| Uuid::now_v7().to_string());
    if operation_id.trim().is_empty() || operation_id.len() > 256 {
        return Err(Error::InvalidInput(
            "operation_id must be non-empty and at most 256 bytes".to_string(),
        )
        .into());
    }
    let existing = api
        .config_store
        .load_workdir_create_operation(workspace_id, &operation_id)?;
    if let Some(existing) = existing.as_ref() {
        working_directory_request.repository.selector =
            crate::workdir_create_operations::selector_for_retry(
                request.selector.as_deref(),
                existing.selector.as_deref(),
                working_directory_request.repository.selector.as_deref(),
            )
            .map(RuntimeRepositorySelector::from);
        if let (Some(kind), Some(uri), Some(fingerprint)) = (
            existing.source_kind.as_deref(),
            existing.source_uri.clone(),
            existing.source_fingerprint.clone(),
        ) {
            let kind = match kind {
                "local_path" => server_api::RepositorySourceKind::LocalPath,
                "file" => server_api::RepositorySourceKind::File,
                "https" => server_api::RepositorySourceKind::Https,
                "http" | "invalid" => server_api::RepositorySourceKind::Invalid,
                "ssh" => server_api::RepositorySourceKind::Ssh,
                _ => {
                    return Err(settings_bad_request(
                        "working_directory_repository_source_invalid",
                        "persisted Workdir create Repository source kind is invalid",
                    ));
                }
            };
            working_directory_request.repository.source =
                server_api::RepositorySource { kind, uri };
            working_directory_request.repository.source_fingerprint = fingerprint;
        }
    }
    let selector = working_directory_request
        .repository
        .selector
        .as_ref()
        .map(|selector| selector.as_ref().to_string());
    let request_fingerprint = crate::workdir_create_operations::request_fingerprint_for_replay(
        &request.repository_key,
        selector.as_deref(),
        requested_runtime_id.as_deref(),
        working_directory_request.display_name.as_deref(),
        &working_directory_request.repository.source_fingerprint,
        existing.as_ref().map(|r| r.request_fingerprint.as_str()),
    )?;
    let reserved = if let Some(existing) = existing {
        existing
    } else {
        let config_state = api
            .config_store
            .load_workspace_config(workspace_id)?
            .ok_or_else(|| {
                Error::RegistryInconsistency(format!(
                    "Workspace {workspace_id} has no active configuration"
                ))
            })?;
        let runtime_projection = crate::runtime_settings::project_runtime_from_workspace_config(
            workspace_id,
            &config_state,
        )?;
        let resolved_runtime_id = requested_runtime_id
            .clone()
            .or(runtime_projection.default_runtime_id.clone())
            .ok_or_else(|| {
                ApiError::with_diagnostics(
                    Error::InvalidInput(
                        "runtime_id was omitted and Workspace configuration has no runtime.default_runtime_id"
                            .to_string(),
                    ),
                    vec![RuntimeDiagnostic {
                        code: "default_runtime_not_configured".to_string(),
                        severity: HostDiagnosticSeverity::Error,
                        message: "Workspace default Runtime is not configured".to_string(),
                    }],
                )
            })?;
        let now = now_registry_timestamp();
        api.config_store
            .reserve_workdir_create_operation(&WorkdirCreateOperationRecord {
                workspace_id: workspace_id.to_string(),
                operation_id: operation_id.clone(),
                request_fingerprint: request_fingerprint.clone(),
                repository_id: working_directory_request.repository.id.clone(),
                selector,
                requested_runtime_id,
                resolved_runtime_id,
                config_projection_digest: runtime_projection.projection_digest,
                source_kind: Some(
                    working_directory_request
                        .repository
                        .source
                        .kind
                        .as_str()
                        .to_string(),
                ),
                source_uri: Some(working_directory_request.repository.source.uri.clone()),
                source_fingerprint: Some(
                    working_directory_request
                        .repository
                        .source_fingerprint
                        .clone(),
                ),
                credential_id: None,
                credential_fingerprint: None,
                host_trust_id: None,
                host_trust_fingerprint: None,
                repository_access_mode: None,
                credential_candidates: Vec::new(),
                working_directory_id: next_backend_workdir_id(&request.repository_key),
                state: "pending".to_string(),
                failure: None,
                created_at: now.clone(),
                updated_at: now,
            })?
    };

    Ok((
        working_directory_request,
        operation_id,
        request_fingerprint,
        reserved,
    ))
}

async fn create_workspace_working_directory(
    api: &WorkspaceApi,
    workspace_id: &str,
    route_runtime_id: Option<&str>,
    request: BrowserWorkingDirectoryCreateRequest,
) -> ApiResult<(StatusCode, Json<BrowserWorkingDirectoryCreateResponse>)> {
    let stage_api = api.clone();
    let stage_workspace_id = workspace_id.to_string();
    let route_runtime_id = route_runtime_id.map(str::to_string);
    let (mut working_directory_request, operation_id, request_fingerprint, reserved) = api
        .store
        .db_executor()
        .run(move || {
            prepare_workspace_workdir_create(
                &stage_api,
                &stage_workspace_id,
                route_runtime_id.as_deref(),
                request,
            )
        })
        .await?;

    if reserved.state == "succeeded" {
        let stage_api = api.clone();
        return api
            .host_executors
            .host()?
            .run(move || {
                working_directory_detail_for_runtime(
                    stage_api,
                    &reserved.resolved_runtime_id,
                    &reserved.working_directory_id,
                )
                .map(|Json(response)| {
                    (
                        StatusCode::OK,
                        Json(BrowserWorkingDirectoryCreateResponse {
                            workspace_id: response.workspace_id,
                            runtime_id: response
                                .runtime_id
                                .expect("Repository Workdir detail has Runtime"),
                            item: response.item,
                            diagnostics: response.diagnostics,
                            http_status: StatusCode::OK.as_u16(),
                        }),
                    )
                })
            })
            .await;
    }
    let reserved = if reserved.state == "failed" {
        let stage_api = api.clone();
        let stage_workspace_id = workspace_id.to_string();
        let stage_operation_id = operation_id.clone();
        let stage_fingerprint = request_fingerprint.clone();
        api.store
            .db_executor()
            .run(move || {
                stage_api.config_store.begin_failed_workdir_create_retry(
                    &stage_workspace_id,
                    &stage_operation_id,
                    &stage_fingerprint,
                    &now_registry_timestamp(),
                )
            })
            .await?
    } else {
        reserved
    };

    let stage_api = api.clone();
    let stage_runtime_id = reserved.resolved_runtime_id.clone();
    let runtime = match api
        .host_executors
        .host()?
        .run(move || {
            Ok::<_, Error>(
                stage_api
                    .runtime
                    .list_runtimes(usize::MAX)
                    .items
                    .into_iter()
                    .find(|runtime| runtime.runtime_id == stage_runtime_id),
            )
        })
        .await?
    {
        Some(runtime) => runtime,
        None => {
            fail_workdir_create_stage(
                api,
                &reserved,
                &request_fingerprint,
                "runtime_unavailable",
                false,
            )
            .await?;
            return Err(ApiError::with_diagnostics(
                Error::UnknownRuntime(reserved.resolved_runtime_id),
                vec![RuntimeDiagnostic {
                    code: "runtime_unavailable".to_string(),
                    severity: HostDiagnosticSeverity::Error,
                    message: "Selected Runtime is not available".to_string(),
                }],
            ));
        }
    };
    if runtime.kind == "remote_http" && runtime.status != "connected" {
        fail_workdir_create_stage(
            api,
            &reserved,
            &request_fingerprint,
            "runtime_unavailable",
            false,
        )
        .await?;
        return Err(ApiError::with_diagnostics(
            Error::RuntimeOperationFailed {
                runtime_id: reserved.resolved_runtime_id,
                code: "runtime_unavailable".to_string(),
                message: "Selected Runtime is not connected".to_string(),
            },
            vec![RuntimeDiagnostic {
                code: "runtime_unavailable".to_string(),
                severity: HostDiagnosticSeverity::Error,
                message: "Selected Runtime is not available".to_string(),
            }],
        ));
    }

    let stage_api = api.clone();
    let stage_reserved = reserved.clone();
    let stage_fingerprint = request_fingerprint.clone();
    let (authorization, mut working_directory_request) = api
        .store
        .db_executor()
        .run(move || {
            let authorization = authorize_repository_materialization_operation(
                &stage_api,
                &stage_reserved,
                &stage_fingerprint,
                &mut working_directory_request,
            );
            Ok::<_, Error>((authorization, working_directory_request))
        })
        .await?;
    if let Err(error) = authorization {
        fail_workdir_create_stage(
            api,
            &reserved,
            &request_fingerprint,
            "working_directory_remote_repository_access_required",
            false,
        )
        .await?;
        return Err(error);
    }
    working_directory_request.backend_workdir_id = Some(reserved.working_directory_id.clone());
    let stage_api = api.clone();
    let stage_reserved = reserved.clone();
    let existing = match api
        .host_executors
        .host()?
        .run(move || {
            Ok::<_, Error>(stage_api.runtime.working_directory(
                &stage_reserved.resolved_runtime_id,
                &stage_reserved.working_directory_id,
            ))
        })
        .await?
    {
        Ok(existing) => existing,
        Err(error) => {
            let failure_code = workdir_runtime_failure_code(&error);
            fail_workdir_create_stage(api, &reserved, &request_fingerprint, &failure_code, false)
                .await?;
            return Err(ApiError::with_diagnostics(
                error.into_error(),
                vec![RuntimeDiagnostic {
                    code: failure_code,
                    severity: HostDiagnosticSeverity::Error,
                    message: "Selected Runtime could not inspect the reserved Workdir".to_string(),
                }],
            ));
        }
    };
    let result = if existing.working_directory.is_some() {
        existing
    } else {
        let stage_api = api.clone();
        let stage_runtime_id = reserved.resolved_runtime_id.clone();
        match api
            .host_executors
            .host()?
            .run(move || {
                Ok::<_, Error>(
                    stage_api
                        .runtime
                        .create_working_directory(&stage_runtime_id, working_directory_request),
                )
            })
            .await?
        {
            Ok(result) => result,
            Err(error) => {
                let failure_code = workdir_runtime_failure_code(&error);
                fail_workdir_create_stage(
                    api,
                    &reserved,
                    &request_fingerprint,
                    &failure_code,
                    true,
                )
                .await?;
                return Err(ApiError::with_diagnostics(
                    error.into_error(),
                    vec![RuntimeDiagnostic {
                        code: failure_code,
                        severity: HostDiagnosticSeverity::Error,
                        message: "Selected Runtime rejected Workdir creation".to_string(),
                    }],
                ));
            }
        }
    };
    let Some(working_directory) = result.working_directory else {
        let mut diagnostics = result.diagnostics;
        let stage_api = api.clone();
        let stage_reserved = reserved.clone();
        let stage_fingerprint = request_fingerprint.clone();
        let (failure_code, returned_diagnostics) = api
            .store
            .db_executor()
            .run(move || -> Result<_> {
                let _ = stage_api.store.delete_workdir_registry(
                    &stage_reserved.workspace_id,
                    &stage_reserved.working_directory_id,
                );
                let failure_code = finish_rejected_workdir_create_operation(
                    &stage_api.config_store,
                    &stage_reserved.workspace_id,
                    &stage_reserved.operation_id,
                    &stage_fingerprint,
                    &diagnostics,
                    &now_registry_timestamp(),
                )?;
                Ok((failure_code, diagnostics))
            })
            .await?;
        diagnostics = returned_diagnostics;
        if !diagnostics.iter().any(|diagnostic| {
            diagnostic.severity == HostDiagnosticSeverity::Error && diagnostic.code == failure_code
        }) {
            diagnostics.insert(
                0,
                RuntimeDiagnostic {
                    code: failure_code.clone(),
                    severity: HostDiagnosticSeverity::Error,
                    message: "Runtime did not create the reserved Workdir".to_string(),
                },
            );
        }
        return Err(ApiError::with_diagnostics(
            Error::RuntimeOperationFailed {
                runtime_id: reserved.resolved_runtime_id,
                code: failure_code,
                message: "Runtime did not create working directory".to_string(),
            },
            diagnostics,
        ));
    };
    let stage_api = api.clone();
    let stage_reserved = reserved.clone();
    let summary = api
        .store
        .db_executor()
        .run(move || -> ApiResult<_> {
            let record = workdir_record_from_summary(
                &stage_api,
                &stage_reserved.resolved_runtime_id,
                &working_directory.summary,
            );
            stage_api.store.upsert_workdir_registry(&record)?;
            stage_api.config_store.finish_workdir_create_operation(
                &stage_reserved.workspace_id,
                &stage_reserved.operation_id,
                &request_fingerprint,
                true,
                None,
                &now_registry_timestamp(),
            )?;
            Ok(projected_workdir_summary_from_record(&stage_api, &record)?)
        })
        .await?;
    Ok((
        StatusCode::CREATED,
        Json(BrowserWorkingDirectoryCreateResponse {
            workspace_id: workspace_id.to_string(),
            runtime_id: reserved.resolved_runtime_id,
            item: summary.into(),
            diagnostics: working_directory_diagnostics(result.diagnostics),
            http_status: StatusCode::CREATED.as_u16(),
        }),
    ))
}

fn working_directory_detail_for_runtime(
    api: WorkspaceApi,
    runtime_id: &str,
    working_directory_id: &str,
) -> ApiResult<Json<BrowserWorkingDirectoryDetailResponse>> {
    let existing = api
        .store
        .get_workdir_registry(&api.config.workspace_id, working_directory_id)?
        .ok_or_else(|| {
            ApiError::with_diagnostics(
                Error::RuntimeOperationFailed {
                    runtime_id: "workspace-backend".to_string(),
                    code: "working_directory_not_found".to_string(),
                    message: format!("Unknown Workdir `{working_directory_id}`"),
                },
                Vec::new(),
            )
        })?;
    if existing.source.runtime_id() != Some(runtime_id) {
        return Err(ApiError::from(Error::WorkspacePermissionDenied(
            "Workdir does not belong to the requested Runtime".to_string(),
        )));
    }
    let result = api
        .runtime
        .working_directory(runtime_id, working_directory_id)
        .map_err(|err| err.into_error())?;
    if let Some(working_directory) = result.working_directory {
        let mut record = workdir_record_from_summary(&api, runtime_id, &working_directory.summary);
        preserve_workdir_identity_for_corrupted_summary(&mut record, Some(&existing));
        api.store.upsert_workdir_registry(&record)?;
        let summary = projected_workdir_summary_from_record(&api, &record)?;
        return Ok(Json(BrowserWorkingDirectoryDetailResponse {
            workspace_id: api.config.workspace_id.clone(),
            runtime_id: Some(runtime_id.to_string()),
            item: summary.into(),
            diagnostics: working_directory_diagnostics(result.diagnostics),
        }));
    }
    Ok(Json(BrowserWorkingDirectoryDetailResponse {
        workspace_id: api.config.workspace_id.clone(),
        runtime_id: Some(runtime_id.to_string()),
        item: projected_workdir_summary_from_record(&api, &existing)?.into(),
        diagnostics: working_directory_diagnostics(result.diagnostics),
    }))
}

fn workdir_removal_response(
    operation: &WorkdirRemovalOperation,
) -> WorkingDirectoryRemovalResponse {
    let disposition = match operation.disposition {
        Some(WorkdirRemovalDisposition::Removed) => WorkingDirectoryRemovalDisposition::Removed,
        Some(WorkdirRemovalDisposition::Retained) => WorkingDirectoryRemovalDisposition::Retained,
        Some(WorkdirRemovalDisposition::AttentionRequired) | None => {
            WorkingDirectoryRemovalDisposition::AttentionRequired
        }
    };
    WorkingDirectoryRemovalResponse {
        working_directory_id: operation.working_directory_id.clone(),
        disposition,
        retryable: operation.retryable,
        failure_category: operation.failure_category.clone(),
    }
}

fn runtime_reports_workdir_not_found(result: &crate::hosts::RuntimeWorkingDirectoryResult) -> bool {
    result.working_directory.is_none()
        && result
            .diagnostics
            .iter()
            .any(|diagnostic| diagnostic.code == "working_directory_not_found")
}

fn classify_workdir_provider_error(error: &RuntimeRegistryError) -> (&'static str, bool) {
    match error {
        RuntimeRegistryError::WorkdirSessionOpenFailed { .. } => ("provider_unavailable", true),
        RuntimeRegistryError::UnknownRuntime(_) => ("runtime_unavailable", true),
        RuntimeRegistryError::RuntimeOperationFailed { code, .. } => {
            let category =
                workdir_cleanup_diagnostic_category(code).unwrap_or("provider_unavailable");
            (category, category != "unsupported_target")
        }
        RuntimeRegistryError::InvalidIdentifier { .. }
        | RuntimeRegistryError::UnknownHost(_)
        | RuntimeRegistryError::UnknownWorker { .. } => ("authority_invalid", false),
    }
}

// Only bounded classifications cross the public removal boundary. Provider
// messages may contain OS paths or credentials and are never persisted here.
fn workdir_cleanup_failure_category(
    result: &crate::hosts::RuntimeWorkingDirectoryResult,
) -> &'static str {
    result
        .diagnostics
        .iter()
        .find_map(|diagnostic| workdir_cleanup_diagnostic_category(&diagnostic.code))
        .unwrap_or("provider_cleanup_failed")
}

fn workdir_cleanup_diagnostic_category(code: &str) -> Option<&'static str> {
    Some(match code {
        "working_directory_unsupported" => "unsupported_target",
        "working_directory_cleanup_mount_present" => "mount_present",
        "working_directory_cleanup_mount_check_unavailable" => "mount_check_unavailable",
        "working_directory_cleanup_permission_denied" => "permission_denied",
        "working_directory_cleanup_resource_busy" => "resource_busy",
        "working_directory_cleanup_storage_unavailable" => "storage_unavailable",
        "working_directory_cleanup_ownership_unknown" => "ownership_unknown",
        "working_directory_cleanup_changes_present" => "changes_present",
        "working_directory_cleanup_changes_unknown" => "changes_unknown",
        "working_directory_cleanup_target_invalid"
        | "working_directory_cleanup_escape_rejected" => "ownership_unknown",
        _ => return None,
    })
}

fn workdir_removal_failure_guidance(category: &str) -> &'static str {
    match category {
        "mount_present" => {
            "A mount remains inside the Workdir. Confirm its owner and usage, have that owner safely release it, then retry deletion. Yoi does not unmount external resources."
        }
        "mount_check_unavailable" => {
            "Runtime cannot inspect mount boundaries. Restore mount inspection before retrying deletion."
        }
        "permission_denied" => {
            "Runtime lacks permission to remove the Workdir. Have its owner resolve access safely, then retry; do not force-clean or change shared resource permissions."
        }
        "resource_busy" => {
            "A resource is busy. Have its owner stop or release it safely, then retry deletion."
        }
        "storage_unavailable" => {
            "Runtime storage is unavailable. Restore storage access, then retry deletion."
        }
        "ownership_unknown" | "provider_identity_changed" | "authority_changed" => {
            "Workdir identity or ownership could not be confirmed. Verify the target with its owner before retrying."
        }
        "changes_present" | "dirty_or_unknown" => {
            "Current Workdir changes are protected. Preserve or resolve them before retrying deletion."
        }
        "changes_unknown" => {
            "Runtime cannot verify remaining Workdir changes. Restore repository inspection or preserve remaining files before retrying."
        }
        "blocked_by_live_authority" => {
            "Workdir has a current attachment, reservation or retention hold. Release the owning authority before retrying deletion."
        }
        "runtime_unavailable" | "provider_unavailable" => {
            "Runtime is unavailable. Reconnect it, then retry deletion; the Workdir registry is retained."
        }
        "provider_observation_unknown" | "provider_cleanup_outcome_unknown" => {
            "Runtime has not confirmed deletion. Retry to re-observe the target; the Workdir registry is retained."
        }
        "unsupported_target" => "This provider does not support Workdir deletion.",
        _ => {
            "Runtime cleanup failed. Inspect correlated Runtime diagnostics, resolve the cause, then retry deletion."
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum WorkdirRemovalOwnerObservation {
    Running { process_start_marker: u64 },
    Missing,
    Unobservable,
}

fn current_workdir_removal_attempt_owner() -> Result<WorkdirRemovalAttemptOwner> {
    let process_id = std::process::id();
    match observe_workdir_removal_owner(process_id) {
        WorkdirRemovalOwnerObservation::Running {
            process_start_marker,
        } => Ok(WorkdirRemovalAttemptOwner {
            process_id,
            process_start_marker,
        }),
        WorkdirRemovalOwnerObservation::Missing | WorkdirRemovalOwnerObservation::Unobservable => {
            Err(Error::Config(
                "current Server process identity is unavailable for durable Workdir removal"
                    .to_string(),
            ))
        }
    }
}

fn workdir_removal_attempt_is_orphaned(operation: &WorkdirRemovalOperation) -> Result<bool> {
    let Some(owner) = operation.attempt_owner else {
        return Ok(operation.attempt_id.is_none());
    };
    match observe_workdir_removal_owner(owner.process_id) {
        WorkdirRemovalOwnerObservation::Running {
            process_start_marker,
        } if process_start_marker == owner.process_start_marker => Ok(false),
        WorkdirRemovalOwnerObservation::Running { .. }
        | WorkdirRemovalOwnerObservation::Missing => Ok(true),
        WorkdirRemovalOwnerObservation::Unobservable => Err(Error::RegistryInconsistency(
            "prior Workdir removal attempt owner liveness is unobservable".to_string(),
        )),
    }
}

#[cfg(target_os = "linux")]
fn observe_workdir_removal_owner(process_id: u32) -> WorkdirRemovalOwnerObservation {
    let stat = match std::fs::read_to_string(format!("/proc/{process_id}/stat")) {
        Ok(stat) => stat,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            return if process_id != std::process::id()
                && std::fs::read_to_string("/proc/self/stat")
                    .ok()
                    .and_then(|stat| parse_linux_process_start_marker(&stat))
                    .is_some()
            {
                WorkdirRemovalOwnerObservation::Missing
            } else {
                WorkdirRemovalOwnerObservation::Unobservable
            };
        }
        Err(_) => return WorkdirRemovalOwnerObservation::Unobservable,
    };
    parse_linux_process_start_marker(&stat)
        .map(
            |process_start_marker| WorkdirRemovalOwnerObservation::Running {
                process_start_marker,
            },
        )
        .unwrap_or(WorkdirRemovalOwnerObservation::Unobservable)
}

#[cfg(target_os = "linux")]
fn parse_linux_process_start_marker(stat: &str) -> Option<u64> {
    let (_, tail) = stat.rsplit_once(") ")?;
    tail.split_whitespace().nth(19)?.parse().ok()
}

#[cfg(not(target_os = "linux"))]
fn observe_workdir_removal_owner(process_id: u32) -> WorkdirRemovalOwnerObservation {
    if process_id == std::process::id() {
        WorkdirRemovalOwnerObservation::Running {
            process_start_marker: 0,
        }
    } else {
        WorkdirRemovalOwnerObservation::Unobservable
    }
}

trait WorkdirRemovalRuntimeProvider: Send + Sync {
    fn observe_workdir(
        &self,
        runtime_id: &str,
        working_directory_id: &str,
    ) -> std::result::Result<crate::hosts::RuntimeWorkingDirectoryResult, RuntimeRegistryError>;

    fn cleanup_workdir(
        &self,
        runtime_id: &str,
        working_directory_id: &str,
    ) -> std::result::Result<crate::hosts::RuntimeWorkingDirectoryResult, RuntimeRegistryError>;
}

impl WorkdirRemovalRuntimeProvider for RuntimeRegistry {
    fn observe_workdir(
        &self,
        runtime_id: &str,
        working_directory_id: &str,
    ) -> std::result::Result<crate::hosts::RuntimeWorkingDirectoryResult, RuntimeRegistryError>
    {
        self.working_directory(runtime_id, working_directory_id)
    }

    fn cleanup_workdir(
        &self,
        runtime_id: &str,
        working_directory_id: &str,
    ) -> std::result::Result<crate::hosts::RuntimeWorkingDirectoryResult, RuntimeRegistryError>
    {
        self.cleanup_working_directory(runtime_id, working_directory_id)
    }
}

fn execute_reserved_workdir_removal(
    api: &WorkspaceApi,
    operation: WorkdirRemovalOperation,
    recovery: bool,
) -> Result<WorkdirRemovalOperation> {
    execute_reserved_workdir_removal_with_provider(api, operation, recovery, api.runtime.as_ref())
}

fn execute_reserved_workdir_removal_with_provider(
    api: &WorkspaceApi,
    operation: WorkdirRemovalOperation,
    recovery: bool,
    provider: &dyn WorkdirRemovalRuntimeProvider,
) -> Result<WorkdirRemovalOperation> {
    if operation.state == WorkdirRemovalOperationState::Completed
        && operation.disposition == Some(WorkdirRemovalDisposition::Removed)
    {
        return Ok(operation);
    }
    let operation = if recovery && operation.state == WorkdirRemovalOperationState::Pending {
        if !workdir_removal_attempt_is_orphaned(&operation)? {
            return Err(Error::WorkdirAttachmentConflict(format!(
                "Workdir removal operation `{}` still has a live attempt owner",
                operation.operation_id
            )));
        }
        api.config_store
            .reclaim_workdir_removal_attempt_for_recovery(
                &operation.workspace_id,
                &operation.operation_id,
                &operation.request_fingerprint,
                api.workdir_remove_attempt_owner,
                operation.attempt_owner,
                operation.attempt_id.as_deref(),
            )?
    } else {
        api.config_store.begin_workdir_removal_attempt(
            &operation.workspace_id,
            &operation.operation_id,
            &operation.request_fingerprint,
            api.workdir_remove_attempt_owner,
        )?
    };
    let guards = match api.config_store.workdir_removal_guards(&operation) {
        Ok(guards) => guards,
        Err(
            Error::InvalidInput(_)
            | Error::WorkdirAttachmentConflict(_)
            | Error::RegistryInconsistency(_),
        ) => {
            return api.config_store.fail_workdir_removal_operation(
                &operation,
                "authority_changed",
                false,
            );
        }
        Err(error) => return Err(error),
    };
    if !guards.is_empty() {
        return api.config_store.complete_workdir_removal_retained(
            &operation,
            WorkdirRemovalDisposition::Retained,
            "blocked_by_live_authority",
        );
    }

    // Runtime observation is the provider's publication/removal authority. A
    // missing summary without the exact not-found diagnostic is unknown, not a
    // successful delete.
    let observed = provider.observe_workdir(&operation.runtime_id, &operation.working_directory_id);
    let observed = match observed {
        Ok(observed) => observed,
        Err(error) => {
            let (category, retryable) = classify_workdir_provider_error(&error);
            return api
                .config_store
                .fail_workdir_removal_operation(&operation, category, retryable);
        }
    };
    if runtime_reports_workdir_not_found(&observed) {
        return api.config_store.commit_workdir_removal_removed(&operation);
    }
    let Some(status) = observed.working_directory.as_ref() else {
        let category = workdir_cleanup_failure_category(&observed);
        let category = if category == "provider_cleanup_failed" {
            "provider_observation_unknown"
        } else {
            category
        };
        return api.config_store.fail_workdir_removal_operation(
            &operation,
            category,
            category != "unsupported_target",
        );
    };
    // A provider summary is not permission to remove a different materialization.
    // Unknown/corrupted metadata is delegated to Runtime's guarded cleanup, never
    // repaired into a fabricated identity here.
    let summary = &status.summary;
    if summary.occupied_by.is_some() {
        return api.config_store.complete_workdir_removal_retained(
            &operation,
            WorkdirRemovalDisposition::Retained,
            "blocked_by_live_authority",
        );
    }
    if summary.working_directory_id != operation.working_directory_id
        || (summary.repository_id == "unknown"
            && summary.status != WorkingDirectoryStatusKind::Corrupted)
        || (summary.repository_id != "unknown"
            && crate::workdir_removal::workdir_materialization_fingerprint(
                &workdir_record_from_summary(api, &operation.runtime_id, summary),
            ) != operation.materialization_fingerprint)
    {
        return api.config_store.fail_workdir_removal_operation(
            &operation,
            "provider_identity_changed",
            true,
        );
    }
    // Past lifecycle failure is not a current dirtiness observation. Runtime
    // must revalidate unknown/partial checkouts at the actual deletion boundary.
    if summary.cleanliness.as_deref() == Some("dirty") {
        return api.config_store.complete_workdir_removal_retained(
            &operation,
            WorkdirRemovalDisposition::Retained,
            "dirty_or_unknown",
        );
    }

    let deleted = provider.cleanup_workdir(&operation.runtime_id, &operation.working_directory_id);
    let deleted = match deleted {
        Ok(deleted) => deleted,
        Err(error) => {
            let (category, retryable) = classify_workdir_provider_error(&error);
            return api
                .config_store
                .fail_workdir_removal_operation(&operation, category, retryable);
        }
    };
    let deletion_confirmed = runtime_reports_workdir_not_found(&deleted)
        || (deleted.state == InternalWorkerOperationState::Accepted
            && deleted.working_directory.as_ref().is_some_and(|status| {
                status.summary.working_directory_id == operation.working_directory_id
                    && status.summary.status == WorkingDirectoryStatusKind::NotFound
            }));
    if !deletion_confirmed {
        let category = if deleted.state == InternalWorkerOperationState::Accepted {
            "provider_cleanup_outcome_unknown"
        } else {
            workdir_cleanup_failure_category(&deleted)
        };
        tracing::warn!(
            workdir_id = %operation.working_directory_id,
            operation_id = %operation.operation_id,
            runtime_id = %operation.runtime_id,
            category,
            "Runtime did not confirm Workdir removal; registry retained"
        );
        return api.config_store.fail_workdir_removal_operation(
            &operation,
            category,
            category != "unsupported_target",
        );
    }
    api.config_store.commit_workdir_removal_removed(&operation)
}

fn workdir_removal_execution_lock(
    api: &WorkspaceApi,
    working_directory_id: &str,
) -> Result<Arc<std::sync::Mutex<()>>> {
    let mut locks = api
        .workdir_remove_locks
        .lock()
        .map_err(|_| Error::Store("Workdir removal lock registry was poisoned".to_string()))?;
    Ok(locks
        .entry(working_directory_id.to_string())
        .or_insert_with(|| Arc::new(std::sync::Mutex::new(())))
        .clone())
}

fn execute_workdir_removal(
    api: &WorkspaceApi,
    working_directory_id: &str,
    source_actor: &str,
    reason: &str,
) -> Result<WorkingDirectoryRemovalResponse> {
    let reason = reason.trim();
    if reason.is_empty() || reason.len() > 500 {
        return Err(Error::InvalidInput(
            "Workdir removal reason must be between 1 and 500 bytes".to_string(),
        ));
    }
    let lock = workdir_removal_execution_lock(api, working_directory_id)?;
    let _guard = lock
        .lock()
        .map_err(|_| Error::Store("Workdir removal lock was poisoned".to_string()))?;

    let operation = if let Some(existing) =
        api.config_store.find_workdir_removal_operation_by_intent(
            api.workspace_id(),
            working_directory_id,
            source_actor,
            reason,
        )? {
        existing
    } else {
        let workdir = api
            .config_store
            .get_workdir_registry(api.workspace_id(), working_directory_id)?
            .ok_or_else(|| {
                Error::InvalidInput(format!("Unknown Workdir `{working_directory_id}`"))
            })?;
        let intent = workdir_removal_intent(&workdir, source_actor, reason)?;
        api.config_store
            .reserve_workdir_removal_operation(&intent)?
    };
    execute_reserved_workdir_removal(api, operation, false)
        .map(|operation| workdir_removal_response(&operation))
}

fn execute_workdir_removal_for_workspace_deletion(
    api: &WorkspaceApi,
    working_directory_id: &str,
    parent_operation_id: &str,
) -> Result<WorkdirRemovalOperation> {
    let source_actor = format!("workspace-deletion:{parent_operation_id}");
    let reason = "Workspace deletion";
    let lock = workdir_removal_execution_lock(api, working_directory_id)?;
    let _guard = lock
        .lock()
        .map_err(|_| Error::Store("Workdir removal lock was poisoned".to_string()))?;
    let operation = if let Some(existing) =
        api.config_store.find_workdir_removal_operation_by_intent(
            api.workspace_id(),
            working_directory_id,
            &source_actor,
            reason,
        )? {
        existing
    } else {
        let workdir = api
            .config_store
            .get_workdir_registry(api.workspace_id(), working_directory_id)?
            .ok_or_else(|| {
                Error::InvalidInput(format!("Unknown Workdir `{working_directory_id}`"))
            })?;
        let intent = workdir_removal_intent(&workdir, &source_actor, reason)?;
        api.config_store
            .reserve_workdir_removal_operation(&intent)?
    };
    api.config_store
        .append_workspace_deletion_child_operation(parent_operation_id, &operation.operation_id)?;
    execute_reserved_workdir_removal(api, operation, false)
}

fn recover_workdir_removals(api: &WorkspaceApi) -> Result<()> {
    for operation in api
        .config_store
        .recoverable_workdir_removal_operations(api.workspace_id(), 100)?
    {
        let result =
            workdir_removal_execution_lock(api, &operation.working_directory_id).and_then(|lock| {
                let _guard = lock
                    .lock()
                    .map_err(|_| Error::Store("Workdir removal lock was poisoned".to_string()))?;
                execute_reserved_workdir_removal(api, operation.clone(), true)
            });
        if let Err(error) = result {
            tracing::warn!(
                workspace_id = %api.workspace_id(),
                workdir_id = %operation.working_directory_id,
                operation_id = %operation.operation_id,
                category = "workdir_removal_recovery_failed",
                "durable Workdir removal recovery failed: {error}"
            );
        }
    }
    Ok(())
}

#[cfg(test)]
async fn set_worker_retention(
    api: WorkspaceApi,
    runtime_id: String,
    runtime_worker_id: String,
    pinned: bool,
) -> ApiResult<Json<WorkerRetentionResponse>> {
    let worker = WorkspaceWorker::resolve_async(&api, &runtime_id, &runtime_worker_id).await?;
    Ok(Json(
        worker
            .set_pinned(&WorkerOperationContext::Backend, pinned)
            .await?,
    ))
}

fn cleanup_workdir_decision(
    file_status: CleanupWorkdirFileStatus,
    cleanliness: CleanupWorkdirCleanliness,
    running_linked: bool,
    pinned_linked: bool,
) -> (CleanupTargetKind, Option<String>) {
    let action = if cleanup_workdir_file_status_is_record_only(file_status) {
        CleanupTargetKind::WorkdirRecordDelete
    } else if !matches!(cleanliness, CleanupWorkdirCleanliness::Dirty) {
        CleanupTargetKind::WorkdirCleanCleanup
    } else {
        CleanupTargetKind::WorkdirDirtyDiscard
    };
    let blocking_reason = if running_linked {
        Some("workdir is linked to a running Worker".to_string())
    } else if pinned_linked {
        Some("workdir is linked to a pinned Worker/history".to_string())
    } else {
        None
    };
    (action, blocking_reason)
}

fn build_runtime_cleanup_plan(
    api: &WorkspaceApi,
    runtime_id: &str,
) -> ApiResult<RuntimeCleanupPlanResponse> {
    let workers = workers_response(api.clone())?;
    let live_running_worker_ids: HashSet<RuntimeWorkerRef> = workers
        .items
        .iter()
        .filter(|worker| worker.state == "running")
        .map(|worker| RuntimeWorkerRef::new(&worker.runtime_id, &worker.worker_id))
        .collect();
    let (workdir_summaries, mut diagnostics) =
        match runtime_working_directory_summaries(api, runtime_id) {
            Ok(result) => result,
            Err(error) => {
                let mut diagnostics = error.diagnostics;
                if diagnostics.is_empty() {
                    diagnostics.push(RuntimeDiagnostic {
                        code: "workspace_cleanup_runtime_observation_unavailable".to_string(),
                        severity: HostDiagnosticSeverity::Warning,
                        message: sanitize_backend_error(&error.error.to_string()),
                    });
                }
                (Vec::new(), diagnostics)
            }
        };
    let workdir_records = api
        .store
        .list_workdir_registry(&api.config.workspace_id, 500)?;
    let worker_records = api
        .store
        .list_worker_registry(&api.config.workspace_id, 500)?;
    let worker_by_id: HashMap<_, _> = worker_records
        .iter()
        .map(|record| (record.worker.clone(), record.clone()))
        .collect();
    let observed_workdirs: HashMap<_, _> = workdir_summaries
        .into_iter()
        .map(|summary| (summary.working_directory_id.clone(), summary))
        .collect();

    let mut worker_candidates = Vec::new();
    for record in worker_records
        .iter()
        .filter(|record| record.worker.runtime_id == runtime_id)
    {
        let links = api
            .store
            .list_worker_workdir_links(&api.config.workspace_id, &record.worker)?;
        let active_assignment = api.store.get_active_ticket_role_assignment_for_worker(
            &api.config.workspace_id,
            &record.worker,
        )?;
        let is_running = live_running_worker_ids.contains(&record.worker);
        let pinned = record.retention_state == "pinned";
        let pending_claim = api
            .store
            .get_pending_ticket_assignment_operation_for_worker(
                &api.config.workspace_id,
                &record.worker,
            )?;
        let blocking_reason = if let Some(claim) = pending_claim {
            Some(format!(
                "worker has pending claim {} for Ticket {}",
                claim.operation_id, claim.ticket_id
            ))
        } else if let Some(assignment) = active_assignment {
            Some(format!(
                "worker has unfinished work for Ticket `{}` (`{}`)",
                assignment.ticket_id,
                assignment.role.as_str()
            ))
        } else if pinned {
            Some("worker is pinned".to_string())
        } else if is_running {
            Some("worker is running".to_string())
        } else {
            None
        };
        worker_candidates.push(CleanupWorkerCandidate {
            target_id: format!(
                "worker:{}:{}",
                encode_path_segment(record.worker.runtime_id.as_str()),
                encode_path_segment(&record.worker.worker_id)
            ),
            action: CleanupTargetKind::WorkerDelete,
            worker_id: record.worker.worker_id.clone(),
            runtime_worker_id: record.worker.worker_id.clone(),
            runtime_id: record.worker.runtime_id.clone(),
            reason: if blocking_reason.is_some() {
                "Worker cannot be deleted until blocking conditions are cleared".to_string()
            } else {
                "Stopped or missing Worker can be manually deleted".to_string()
            },
            blocking_reason,
            pinned,
            retention_state: record.retention_state.clone(),
            linked_workdir_ids: links.iter().map(|link| link.workdir_id.clone()).collect(),
            running_linked: is_running,
            estimated_reclaim_bytes: None,
        });
    }

    let mut workdir_candidates = Vec::new();
    for record in &workdir_records {
        let WorkdirRegistrySource::Repository {
            runtime_id: record_runtime_id,
            repository_id,
        } = &record.source
        else {
            continue;
        };
        if record_runtime_id != runtime_id {
            continue;
        }
        let links = api
            .store
            .list_workdir_worker_links(&api.config.workspace_id, record.workdir_id.as_str())?;
        let linked_workers = links
            .iter()
            .filter_map(|link| worker_by_id.get(&link.worker))
            .collect::<Vec<_>>();
        let linked_worker_ids = links
            .iter()
            .map(|link| link.worker.worker_id.clone())
            .collect::<Vec<_>>();
        let linked_running_worker_ids = linked_workers
            .iter()
            .filter(|worker| live_running_worker_ids.contains(&worker.worker))
            .map(|worker| worker.worker.worker_id.clone())
            .collect::<Vec<_>>();
        let pinned_linked = linked_workers
            .iter()
            .any(|worker| worker.retention_state == "pinned");
        let running_linked = !linked_running_worker_ids.is_empty();
        let observed_status = observed_workdirs
            .get(record.workdir_id.as_str())
            .map(|summary| cleanup_workdir_file_status_from_runtime(&summary.status));
        let file_status = observed_status.unwrap_or_else(|| {
            cleanup_workdir_file_status_from_registry(&record.materialization_status)
        });
        let cleanliness = observed_workdirs
            .get(record.workdir_id.as_str())
            .map(|summary| cleanup_workdir_cleanliness_from_runtime(summary.cleanliness.as_deref()))
            .unwrap_or_else(|| cleanup_workdir_cleanliness_from_registry(&record.cleanliness));
        let (action, blocking_reason) =
            cleanup_workdir_decision(file_status, cleanliness, running_linked, pinned_linked);
        let repository_key = api
            .store
            .get_repository(&api.config.workspace_id, repository_id)?
            .map(|repository| repository.repository_key)
            .ok_or_else(|| Error::UnknownRepository(repository_id.clone()))?;
        workdir_candidates.push(CleanupWorkdirCandidate {
            target_id: format!("workdir:{}", record.workdir_id),
            action,
            workdir_id: record.workdir_id.clone(),
            runtime_id: record_runtime_id.clone(),
            repository_key,
            reason: if blocking_reason.is_some() {
                "Workdir cleanup is blocked until linked Worker state is safe".to_string()
            } else if cleanup_workdir_file_status_is_record_only(file_status) {
                "Not-found Workdir record can be deleted from the Backend registry".to_string()
            } else if cleanup_workdir_file_status_is_corrupted(file_status) {
                "Runtime will verify remaining files and removal authority for this incomplete Workdir"
                    .to_string()
            } else if matches!(cleanliness, CleanupWorkdirCleanliness::Dirty) {
                "Dirty Workdir is protected; preserve or resolve current changes before retrying".to_string()
            } else if matches!(cleanliness, CleanupWorkdirCleanliness::Unknown) {
                "Runtime will recheck current changes, identity and removal blockers before deleting"
                    .to_string()
            } else {
                "Clean Workdir can be manually cleaned up".to_string()
            },
            blocking_reason,
            linked_worker_ids,
            linked_running_worker_ids,
            running_linked,
            pinned_linked,
            file_status,
            cleanliness,
            estimated_reclaim_bytes: None,
        });
    }
    worker_candidates.sort_by(|left, right| left.target_id.cmp(&right.target_id));
    workdir_candidates.sort_by(|left, right| left.target_id.cmp(&right.target_id));
    diagnostics.truncate(16);
    let generated_at = now_registry_timestamp();
    let digest = cleanup_plan_digest(&worker_candidates, &workdir_candidates)?;
    Ok(RuntimeCleanupPlanResponse {
        workspace_id: api.config.workspace_id.clone(),
        runtime_id: runtime_id.to_string(),
        generated_at,
        digest,
        workers: worker_candidates,
        workdirs: workdir_candidates,
        diagnostics: diagnostics.into_iter().map(Into::into).collect(),
    })
}

fn cleanup_plan_digest(
    workers: &[CleanupWorkerCandidate],
    workdirs: &[CleanupWorkdirCandidate],
) -> ApiResult<String> {
    let bytes = serde_json::to_vec(&(workers, workdirs)).map_err(|error| {
        cleanup_api_error(
            "backend",
            "workspace_cleanup_plan_digest_failed",
            &format!("failed to serialize cleanup plan: {error}"),
        )
    })?;
    let mut hasher = Sha256::new();
    hasher.update(bytes);
    let bytes = hasher.finalize();
    let digest = bytes
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect::<String>();
    Ok(format!("sha256:{digest}"))
}

#[cfg(test)]
async fn execute_runtime_cleanup(
    api: &WorkspaceApi,
    runtime_id: &str,
    request: ExecuteRuntimeCleanupRequest,
) -> ApiResult<RuntimeCleanupExecutionResponse> {
    execute_runtime_cleanup_with_context(api, runtime_id, request, &WorkerOperationContext::Backend)
        .await
}

async fn execute_runtime_cleanup_with_context(
    api: &WorkspaceApi,
    runtime_id: &str,
    request: ExecuteRuntimeCleanupRequest,
    context: &WorkerOperationContext,
) -> ApiResult<RuntimeCleanupExecutionResponse> {
    if matches!(context, WorkerOperationContext::WorkerControl { .. }) {
        return Err(Error::WorkspacePermissionDenied(
            "Worker control uses target-bound WorkerRemove authority, not aggregate cleanup".into(),
        )
        .into());
    }

    context.authorize_workspace(api).await?;
    let plan_api = api.clone();
    let plan_runtime = runtime_id.to_owned();
    let plan = api
        .host_executors
        .host()?
        .run(move || build_runtime_cleanup_plan(&plan_api, &plan_runtime))
        .await?;
    // Rebuild the actual candidate set immediately before executing. The digest
    // binds targets, dependencies and blockers; per-target authority is checked again below.
    if request.expected_plan_digest != plan.digest {
        return Err(cleanup_api_error(
            runtime_id,
            "workspace_cleanup_plan_stale",
            "cleanup candidates or blockers changed; refresh the preview before executing",
        ));
    }
    let worker_targets: HashSet<_> = request.worker_target_ids.iter().cloned().collect();
    let workdir_targets: HashSet<_> = request.workdir_target_ids.iter().cloned().collect();
    let mut results = Vec::new();

    for candidate in plan
        .workers
        .iter()
        .filter(|candidate| worker_targets.contains(candidate.target_id.as_str()))
    {
        let worker = RuntimeWorkerRef::new(
            candidate.runtime_id.clone(),
            candidate.runtime_worker_id.clone(),
        );
        let authority_api = api.clone();
        let target = worker.clone();
        let (claim, assignment) = api
            .store
            .db_executor()
            .run(move || -> Result<_> {
                Ok((
                    authority_api
                        .store
                        .get_pending_ticket_assignment_operation_for_worker(
                            &authority_api.config.workspace_id,
                            &target,
                        )?,
                    authority_api
                        .store
                        .get_active_ticket_role_assignment_for_worker(
                            &authority_api.config.workspace_id,
                            &target,
                        )?,
                ))
            })
            .await?;
        if let Some(claim) = claim {
            return Err(cleanup_api_error(
                runtime_id,
                "workspace_cleanup_worker_claim_pending",
                &format!("Worker has pending Ticket claim {}", claim.operation_id),
            ));
        }
        if let Some(assignment) = assignment {
            return Err(cleanup_api_error(
                runtime_id,
                "workspace_cleanup_worker_assigned",
                &format!(
                    "Worker has unfinished work for Ticket `{}` as `{}` and cannot be deleted",
                    assignment.ticket_id,
                    assignment.role.as_str()
                ),
            ));
        }
        if let Some(reason) = &candidate.blocking_reason {
            return Err(cleanup_api_error(
                runtime_id,
                "workspace_cleanup_worker_blocked",
                reason,
            ));
        }
        if candidate.pinned {
            return Err(cleanup_api_error(
                runtime_id,
                "workspace_cleanup_worker_pinned",
                "pinned Worker/history cannot be deleted",
            ));
        }
        parse_runtime_worker_id_for_registry(&candidate.runtime_worker_id)?;
        WorkspaceWorker::resolve_async(api, &worker.runtime_id, &worker.worker_id)
            .await?
            .delete_from_plan(context, candidate)
            .await?;
        api.workdir_session_locks
            .lock()
            .expect("Workdir session lock registry poisoned")
            .remove(&worker);
        results.push(RuntimeCleanupExecutionResult {
            target_id: candidate.target_id.clone(),
            action: candidate.action.clone(),
            status: "deleted".to_string(),
            message: "Worker deleted from Runtime and Backend registry".to_string(),
        });
    }

    for candidate in plan
        .workdirs
        .iter()
        .filter(|candidate| workdir_targets.contains(candidate.target_id.as_str()))
    {
        if let Some(reason) = &candidate.blocking_reason {
            return Err(cleanup_api_error(
                runtime_id,
                "workspace_cleanup_workdir_blocked",
                reason,
            ));
        }
        match candidate.action {
            CleanupTargetKind::WorkdirDirtyDiscard => {
                results.push(RuntimeCleanupExecutionResult {
                    target_id: candidate.target_id.clone(),
                    action: candidate.action.clone(),
                    status: "retained".to_string(),
                    message:
                        "Dirty or unknown Workdir was retained; forced deletion is not supported"
                            .to_string(),
                });
            }
            CleanupTargetKind::WorkdirCleanCleanup | CleanupTargetKind::WorkdirRecordDelete => {
                let removal_api = api.clone();
                let removal_candidate = candidate.clone();
                let requester = format!("runtime-cleanup:{runtime_id}");
                let removal = api
                    .host_executors
                    .host()?
                    .run(move || {
                        execute_workdir_removal(
                            &removal_api,
                            removal_candidate.workdir_id.as_str(),
                            &requester,
                            &format!("cleanup target {}", removal_candidate.target_id),
                        )
                    })
                    .await?;
                let (status, message) = match removal.disposition {
                    WorkingDirectoryRemovalDisposition::Removed => (
                        "deleted",
                        "Workdir removed through the durable Backend operation",
                    ),
                    WorkingDirectoryRemovalDisposition::Retained => (
                        "retained",
                        "Workdir retained after live authority revalidation",
                    ),
                    WorkingDirectoryRemovalDisposition::AttentionRequired => (
                        "attention_required",
                        "Workdir removal requires attention and may be retried",
                    ),
                };
                results.push(RuntimeCleanupExecutionResult {
                    target_id: candidate.target_id.clone(),
                    action: candidate.action.clone(),
                    status: status.to_string(),
                    message: removal.failure_category.as_deref().map_or_else(
                        || message.to_string(),
                        |category| {
                            format!("{category}: {}", workdir_removal_failure_guidance(category))
                        },
                    ),
                });
            }
            CleanupTargetKind::WorkerDelete => {
                return Err(cleanup_api_error(
                    runtime_id,
                    "workspace_cleanup_invalid_target_kind",
                    "worker delete action cannot be executed as a Workdir target",
                ));
            }
        }
    }

    let requested_target_count = worker_targets.len() + workdir_targets.len();
    if requested_target_count > 0 && results.len() != requested_target_count {
        return Err(cleanup_api_error(
            runtime_id,
            "workspace_cleanup_target_not_executed",
            "one or more selected cleanup targets were not present in the current cleanup plan",
        ));
    }

    let plan_api = api.clone();
    let plan_runtime = runtime_id.to_owned();
    let plan_after = api
        .host_executors
        .host()?
        .run(move || build_runtime_cleanup_plan(&plan_api, &plan_runtime))
        .await?;
    let executed_at = now_registry_timestamp();
    Ok(RuntimeCleanupExecutionResponse {
        workspace_id: api.config.workspace_id.clone(),
        runtime_id: runtime_id.to_string(),
        executed_at,
        results,
        diagnostics: plan_after.diagnostics.clone(),
        plan_after,
    })
}

fn cleanup_api_error(runtime_id: &str, code: &str, message: &str) -> ApiError {
    Error::RuntimeOperationFailed {
        runtime_id: runtime_id.to_string(),
        code: code.to_string(),
        message: message.to_string(),
    }
    .into()
}

