async fn scoped_update_remote_runtime(
    State(api): State<WorkspaceApi>,
    AxumPath(path): AxumPath<ScopedRuntimePath>,
    Extension(actor): Extension<RequestActor>,
    Json(request): Json<UpdateRemoteRuntimeRequest>,
) -> ApiResult<Json<WorkspaceRuntimeDetail>> {
    validate_workspace_scope(&api, &path.workspace_id)?;
    require_workspace_owner(
        &api,
        &path.workspace_id,
        &actor,
        "manage Workspace Runtimes",
    )
    .await?;
    if path.runtime_id == EMBEDDED_WORKER_RUNTIME_ID {
        return Err(settings_bad_request(
            "embedded_runtime_not_config_managed",
            "the embedded Runtime is built in and cannot be edited",
        ));
    }
    let endpoint =
        validate_runtime_metadata(request.display_name.as_deref(), &request.endpoint).await?;
    let display_name = request
        .display_name
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or(&path.runtime_id)
        .to_owned();
    update_remote_runtime_metadata_owned(
        api,
        path.workspace_id,
        path.runtime_id,
        display_name,
        endpoint.as_str().trim_end_matches('/').to_owned(),
    )
    .await
}

// Post-auth mutation boundary: cancellation cannot split SQL completion from
// publication or discard the accepted workflow's request/resource authority.
async fn update_remote_runtime_metadata_owned(
    api: WorkspaceApi,
    workspace_id: String,
    runtime_id: String,
    display_name: String,
    endpoint: String,
) -> ApiResult<Json<WorkspaceRuntimeDetail>> {
    run_host_workflow(api.host_executors.host()?, async move {
        let binding = api
            .store
            .update_workspace_runtime_binding_metadata(
                &workspace_id,
                &runtime_id,
                &display_name,
                &endpoint,
                &Utc::now().to_rfc3339(),
            )
            .await?;
        publish_workspace_runtime_binding(&api, binding)?;
        Ok(Json(
            workspace_runtime_detail_on_host(&api, &workspace_id, &runtime_id).await?,
        ))
    })
    .await
}

