/// Account creation requires a verified new-account ceremony. The old bootstrap
/// endpoint must not reserve handles or make an existing identity enrollable.
async fn post_auth_bootstrap_user(
    State(_api): State<ServerAuthApi>,
    Json(_request): Json<AuthBootstrapUserRequest>,
) -> ApiResult<Json<AuthUserResponse>> {
    Err(auth_error(
        "verified_registration_required",
        "use new-account passkey registration",
    )
    .into())
}

/// Tagged state deliberately rejects pre-separation bare WebAuthn states. They
/// carry no enrollment purpose or current-auth binding and cannot be upgraded safely.
/// A caller can obtain new options and repeat new-account enrollment only for an
/// unused, unpersisted handle. Existing credential/current authenticated authority
/// instead permits login and actor-derived addition.
///
/// Old options could already have persisted an Account/User without credentials.
/// Credential absence is not ownership proof: that existing handle cannot be
/// claimed anonymously or restarted as a new account. Use a different unused
/// handle or a separately authorized future recovery flow. Preserve those rows;
/// no DB edits, automatic deletion, bare-state conversion or new recovery/admin
/// feature is part of this migration.
#[derive(Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct PasskeyRegistrationEnvelope {
    target: PasskeyRegistrationTarget,
    verifier: PasskeyRegistration,
}

/// An account gets one stable WebAuthn user handle, without storing a new schema
/// field. Legacy identified-account login accepts original random handles or no
/// returned handle, always requiring the saved credential's signature. Normal
/// discoverable login additionally requires the saved owner's stable handle.
/// Random registration handles were never stored, so they cannot be recovered
/// or safely mapped by trusting the unsigned assertion. Preserve these keys and
/// use explicit legacy login to authenticate before adding a stable-handle RK.
/// Merely having a stable handle does not prove the old key is discoverable.
fn passkey_user_handle(account_id: &str) -> Uuid {
    let digest = Sha256::digest(account_id.as_bytes());
    Uuid::from_bytes(
        digest[..16]
            .try_into()
            .expect("SHA256 has at least 16 bytes"),
    )
}

async fn post_passkey_registration_options(
    State(api): State<ServerAuthApi>,
    headers: HeaderMap,
    Json(request): Json<PasskeyRegistrationOptionsRequest>,
) -> ApiResult<Json<PasskeyRegistrationOptionsResponse>> {
    api.store
        .db_executor()
        .run(move || {
            require_self_registration(&api)?;
            let user = allocate_new_user(&api, &request.handle, request.display_name.as_deref())?;
            start_passkey_registration(
                &api,
                &headers,
                request.browser_origin.as_deref(),
                PasskeyRegistrationTarget::NewAccount { user },
            )
            .map(Json)
        })
        .await
}

/// Re-resolves transport credentials instead of trusting a context actor snapshot.
/// Cookie additions require the exact configured Origin even at direct API entry;
/// browser_origin in a JSON body is not CSRF evidence.
fn passkey_addition_authority(
    api: &ServerAuthApi,
    headers: &HeaderMap,
) -> ApiResult<(UserRecord, PasskeyAuthenticationBinding)> {
    passkey_owner_authority(api, headers, true)
}

fn passkey_owner_authority(
    api: &ServerAuthApi,
    headers: &HeaderMap,
    require_origin: bool,
) -> ApiResult<(UserRecord, PasskeyAuthenticationBinding)> {
    let auth = auth_public_config(&api.config);
    let actor = crate::auth::resolve_request_actor_sync(
        api.store.as_ref(),
        crate::auth::parse_bearer(headers),
        parse_cookie(headers, &auth.cookie_name),
    )?
    .ok_or_else(|| {
        auth_error(
            "auth_required",
            "passkey addition requires current authentication",
        )
    })?;
    let binding = match actor.auth_method {
        ActorAuthMethod::BrowserSession => {
            if require_origin && request_origin(headers).as_deref() != Some(auth.origin.as_str()) {
                return Err(Error::WorkspacePermissionDenied(
                    "cookie-authenticated passkey addition requires the configured Browser origin"
                        .into(),
                )
                .into());
            }
            PasskeyAuthenticationBinding::BrowserSession(token_hash(
                &parse_cookie(headers, &auth.cookie_name)
                    .ok_or_else(|| auth_error("auth_required", "missing browser credential"))?,
            ))
        }
        ActorAuthMethod::ApiToken => PasskeyAuthenticationBinding::ApiToken(token_hash(
            &crate::auth::parse_bearer(headers)
                .ok_or_else(|| auth_error("auth_required", "missing API credential"))?,
        )),
    };
    let user = api
        .store
        .get_user(&actor.user_id)?
        .filter(|user| user.account_id == actor.account_id)
        .ok_or_else(|| auth_error("auth_required", "authenticated user no longer exists"))?;
    if api.store.is_user_pending_activation(&user.user_id)? {
        return Err(auth_error(
            "passkey_activation_required",
            "initial passkey activation is required",
        )
        .into());
    }
    Ok((user, binding))
}

fn require_expected_passkey_owner(
    user: &UserRecord,
    binding: &PasskeyAuthenticationBinding,
    expected_user_id: &str,
    expected_account_id: &str,
    expected_authentication_reference: &str,
) -> ApiResult<()> {
    if user.user_id != expected_user_id
        || user.account_id != expected_account_id
        || binding.reference() != expected_authentication_reference
    {
        return Err(auth_error(
            "passkey_authentication_changed",
            "authentication changed; refresh account before starting another operation",
        )
        .into());
    }
    Ok(())
}

fn start_passkey_registration(
    api: &ServerAuthApi,
    headers: &HeaderMap,
    browser_origin: Option<&str>,
    target: PasskeyRegistrationTarget,
) -> ApiResult<PasskeyRegistrationOptionsResponse> {
    let (user, exclude_credentials) = match &target {
        PasskeyRegistrationTarget::NewAccount { user }
        | PasskeyRegistrationTarget::Activation { user, .. } => (user, Vec::new()),
        PasskeyRegistrationTarget::Addition { user, .. } => (
            user,
            passkeys_for_user(api, &user.user_id)?
                .into_iter()
                .map(|passkey| passkey.cred_id().clone())
                .collect(),
        ),
    };
    let header_origin = request_origin(headers);
    let auth = auth_config_for_origin(&api.config, browser_origin.or(header_origin.as_deref()))?;
    let webauthn = webauthn_for_auth(&auth)?;
    let (mut public_key, verifier) = webauthn
        .start_passkey_registration(
            passkey_user_handle(&user.account_id),
            &user.handle,
            &user.display_name,
            Some(exclude_credentials),
        )
        .map_err(|error| auth_error("webauthn_registration_options_failed", &error.to_string()))?;
    // webauthn-rs passkeys require UV but do not request residency by default.
    // These public protocol fields request an RK on conforming clients; residency
    // itself is not remotely attestable. Keep the library's UV/verifier state.
    let selection = public_key
        .public_key
        .authenticator_selection
        .as_mut()
        .ok_or_else(|| {
            auth_error(
                "webauthn_registration_options_failed",
                "authenticator selection is missing",
            )
        })?;
    selection.resident_key = Some(webauthn_rs_proto::ResidentKeyRequirement::Required);
    selection.require_resident_key = true;
    let challenge_id = new_id("webauthn-registration");
    // New users do not exist yet, so the nullable FK remains empty. The complete
    // target (including its allocated user ID) is inside the purpose-tagged state.
    let user_id = match &target {
        PasskeyRegistrationTarget::NewAccount { .. } => None,
        PasskeyRegistrationTarget::Addition { user, .. }
        | PasskeyRegistrationTarget::Activation { user, .. } => Some(user.user_id.clone()),
    };
    api.store.put_auth_challenge(&AuthChallengeRecord {
        challenge_id: challenge_id.clone(),
        ceremony: "passkey_registration".into(),
        challenge: challenge_id.clone(),
        user_id,
        rp_id: auth.rp_id,
        origin: auth.origin,
        state_json: Some(
            serde_json::to_string(&PasskeyRegistrationEnvelope { target, verifier }).map_err(
                |error| auth_error("webauthn_state_serialize_failed", &error.to_string()),
            )?,
        ),
        expires_at: rfc3339_after(Duration::minutes(5)),
        created_at: crate::auth::now_rfc3339(),
        consumed_at: None,
    })?;
    Ok(PasskeyRegistrationOptionsResponse {
        challenge_id,
        public_key,
    })
}

/// One-use ceremonies bind purpose, target, RP, origin and verifier state. A
/// consumed challenge is never restored on failure. Only verified credentials
/// reach the insert-only transaction; a concurrent handle winner cannot become
/// an addition.
///
/// Credential commit precedes session issuance. If issuing the session or
/// delivering the response fails, the credential can already exist: log in with
/// that key rather than overwriting it or replaying the consumed completion.
/// Own additions save a receipt atomically with the credential: a currently
/// authenticated same owner can inspect it using the original operation binding
/// reference even if the response body was lost after Set-Cookie took effect.
/// This read does not authorize a completion or prove current session health.
/// For unknown new-account outcomes, try login first. Restart new-account
/// enrollment with fresh options only for an unused handle with no persisted
/// identity; legacy pre-created identities follow the migration policy on
/// [`PasskeyRegistrationEnvelope`]. Neither recovery path requires DB edits.
fn complete_passkey_registration(
    api: &ServerAuthApi,
    request: PasskeyRegistrationCompleteRequest,
) -> ApiResult<(AuthUserResponse, server_api::SetCookieHeader)> {
    complete_passkey_enrollment(api, request, EnrollmentCompletion::NewAccount)
}

/// Completion endpoints select a purpose, not a caller-controlled body field.
/// Activation authority never satisfies the public registration or addition path.
enum EnrollmentCompletion<'a> {
    NewAccount,
    Addition(&'a HeaderMap),
    Activation,
}

fn complete_passkey_enrollment(
    api: &ServerAuthApi,
    request: PasskeyRegistrationCompleteRequest,
    completion: EnrollmentCompletion<'_>,
) -> ApiResult<(AuthUserResponse, server_api::SetCookieHeader)> {
    let is_addition = matches!(&completion, EnrollmentCompletion::Addition(_));
    let authority = match completion {
        EnrollmentCompletion::Addition(headers) => Some(passkey_addition_authority(api, headers)?),
        _ => None,
    };
    let challenge = api
        .store
        .consume_auth_challenge_by_id(
            &request.challenge_id,
            "passkey_registration",
            &crate::auth::now_rfc3339(),
        )?
        .ok_or_else(|| {
            auth_error(
                "invalid_passkey_challenge",
                "passkey registration challenge is invalid or already consumed",
            )
        })?;
    if is_expired(&challenge.expires_at) {
        return Err(auth_error(
            "expired_passkey_challenge",
            "passkey registration challenge expired",
        )
        .into());
    }
    let envelope: PasskeyRegistrationEnvelope =
        serde_json::from_str(challenge.state_json.as_deref().ok_or_else(|| {
            auth_error(
                "missing_webauthn_state",
                "registration state was not persisted",
            )
        })?)
        .map_err(|_| {
            auth_error(
                "invalid_registration_state",
                "registration requires purpose-bound state",
            )
        })?;
    let user = match (&envelope.target, authority, completion) {
        (
            PasskeyRegistrationTarget::NewAccount { user },
            None,
            EnrollmentCompletion::NewAccount,
        ) if challenge.user_id.is_none() => {
            require_self_registration(api)?;
            user.clone()
        }
        (
            PasskeyRegistrationTarget::Addition {
                user,
                authentication,
            },
            Some((current, binding)),
            EnrollmentCompletion::Addition(_),
        ) if user.user_id == current.user_id
            && user.account_id == current.account_id
            && *authentication == binding
            && challenge.user_id.as_deref() == Some(user.user_id.as_str()) =>
        {
            current
        }
        (
            PasskeyRegistrationTarget::Activation { user, .. },
            None,
            EnrollmentCompletion::Activation,
        ) if challenge.user_id.as_deref() == Some(user.user_id.as_str()) => {
            // The verified credential transaction rechecks the live pending row,
            // issuance, code expiry and attempts before atomically activating it.
            user.clone()
        }
        _ => {
            return Err(auth_error(
                "passkey_registration_binding_mismatch",
                "registration purpose, target or authentication does not match",
            )
            .into());
        }
    };
    let passkey = webauthn_for_challenge(&api.config, &challenge)?
        .finish_passkey_registration(&request.credential, &envelope.verifier)
        .map_err(|error| {
            auth_error(
                "webauthn_registration_verification_failed",
                &error.to_string(),
            )
        })?;
    api.store.register_verified_passkey_with_result(
        &envelope.target,
        &PasskeyCredentialRecord {
            credential_id: passkey_credential_id(&passkey)?,
            user_id: user.user_id.clone(),
            public_key_cose: serde_json::to_string(&passkey).map_err(|error| {
                auth_error("webauthn_passkey_serialize_failed", &error.to_string())
            })?,
            transports_json: None,
            sign_count: 0,
            created_at: crate::auth::now_rfc3339(),
            last_used_at: None,
        },
        is_addition.then_some(request.challenge_id.as_str()),
    )?;
    issue_browser_session(api, user)
}

/// Normal login has no preselected identity. Explicit handle requests are the
/// legacy migration path, not an automatic fallback. Non-resident keys and keys
/// with old random user handles can authenticate there, then add an RK from the
/// live account. No saved key or owner is rewritten. Existing stable-handle RKs
/// can already use normal login; discoverability cannot be inferred from storage.
#[derive(Serialize, Deserialize)]
#[serde(tag = "mode", content = "verifier", rename_all = "snake_case")]
enum PasskeyLoginState {
    Discoverable(webauthn_rs::prelude::DiscoverableAuthentication),
    Legacy(PasskeyAuthentication),
}

async fn post_passkey_login_options(
    State(api): State<ServerAuthApi>,
    headers: HeaderMap,
    Json(request): Json<PasskeyLoginOptionsRequest>,
) -> ApiResult<Json<PasskeyLoginOptionsResponse>> {
    api.store
        .db_executor()
        .run(move || {
            let header_origin = request_origin(&headers);
            let auth = auth_config_for_origin(
                &api.config,
                request
                    .browser_origin
                    .as_deref()
                    .or(header_origin.as_deref()),
            )?;
            let webauthn = webauthn_for_auth(&auth)?;
            let (public_key, state, user_id) =
                if let Some(handle) = request.handle.as_deref() {
                    let user = api
                        .store
                        .get_user_by_handle(&normalize_handle(handle)?)?
                        .ok_or_else(|| {
                            auth_error("unknown_auth_user", "no matching user account exists")
                        })?;
                    if api.store.is_user_pending_activation(&user.user_id)? {
                        return Err(auth_error(
                            "passkey_activation_required",
                            "initial passkey activation is required",
                        )
                        .into());
                    }
                    let passkeys = passkeys_for_user(&api, &user.user_id)?;
                    if passkeys.is_empty() {
                        return Err(auth_error(
                            "passkey_not_registered",
                            "user has no registered passkey credentials",
                        )
                        .into());
                    }
                    let (options, state) = webauthn
                        .start_passkey_authentication(&passkeys)
                        .map_err(|error| {
                            auth_error("webauthn_login_options_failed", &error.to_string())
                        })?;
                    (
                        options,
                        PasskeyLoginState::Legacy(state),
                        Some(user.user_id),
                    )
                } else {
                    let (mut options, state) = webauthn
                        .start_discoverable_authentication()
                        .map_err(|error| {
                            auth_error("webauthn_login_options_failed", &error.to_string())
                        })?;
                    // The feature exposes a conditional-UI builder. Use its empty allow
                    // list and required UV verifier with an explicit user gesture, not
                    // conditional/autofill mediation. No account inventory is returned.
                    options.mediation = None;
                    (options, PasskeyLoginState::Discoverable(state), None)
                };
            let challenge_id = new_id("webauthn-login");
            api.store.put_auth_challenge(&AuthChallengeRecord {
                challenge_id: challenge_id.clone(),
                ceremony: "passkey_login".into(),
                challenge: challenge_id.clone(),
                user_id,
                rp_id: auth.rp_id,
                origin: auth.origin,
                state_json: Some(serde_json::to_string(&state).map_err(|error| {
                    auth_error("webauthn_state_serialize_failed", &error.to_string())
                })?),
                expires_at: rfc3339_after(Duration::minutes(5)),
                created_at: crate::auth::now_rfc3339(),
                consumed_at: None,
            })?;
            Ok(Json(PasskeyLoginOptionsResponse {
                challenge_id,
                public_key,
            }))
        })
        .await
}

fn complete_passkey_login(
    api: &ServerAuthApi,
    request: PasskeyLoginCompleteRequest,
) -> ApiResult<(AuthUserResponse, server_api::SetCookieHeader)> {
    let challenge = api
        .store
        .consume_auth_challenge_by_id(
            &request.challenge_id,
            "passkey_login",
            &crate::auth::now_rfc3339(),
        )?
        .ok_or_else(|| {
            auth_error(
                "invalid_passkey_challenge",
                "passkey login challenge is invalid or already consumed",
            )
        })?;
    if is_expired(&challenge.expires_at) {
        return Err(auth_error(
            "expired_passkey_challenge",
            "passkey login challenge expired",
        )
        .into());
    }
    let state: PasskeyLoginState =
        serde_json::from_str(challenge.state_json.as_deref().ok_or_else(|| {
            auth_error(
                "missing_webauthn_state",
                "passkey login state was not persisted",
            )
        })?)
        .map_err(|error| auth_error("webauthn_state_deserialize_failed", &error.to_string()))?;
    let credential_id = serde_json::to_value(webauthn_rs::prelude::Base64UrlSafeData::from(
        request.credential.get_credential_id().to_vec(),
    ))
    .ok()
    .and_then(|value| value.as_str().map(ToOwned::to_owned))
    .ok_or_else(|| auth_error("invalid_webauthn_credential_id", "credential id is invalid"))?;
    let stored = api
        .store
        .get_passkey_credential(&credential_id)?
        .ok_or_else(|| {
            auth_error(
                "unknown_passkey_credential",
                "passkey credential is not registered",
            )
        })?;
    let user = api
        .store
        .get_user(&stored.user_id)?
        .ok_or_else(|| auth_error("unknown_auth_user", "passkey user does not exist"))?;
    if api.store.is_user_pending_activation(&user.user_id)? {
        return Err(auth_error(
            "passkey_activation_required",
            "initial passkey activation is required",
        )
        .into());
    }
    let mut passkey: Passkey = serde_json::from_str(&stored.public_key_cose)
        .map_err(|error| auth_error("webauthn_passkey_deserialize_failed", &error.to_string()))?;
    if passkey_credential_id(&passkey)? != credential_id {
        return Err(auth_error(
            "passkey_user_mismatch",
            "stored credential id does not match key material",
        )
        .into());
    }
    let webauthn = webauthn_for_challenge(&api.config, &challenge)?;
    let normal_login = matches!(state, PasskeyLoginState::Discoverable(_));
    let auth_result = match state {
        PasskeyLoginState::Discoverable(state) => {
            // userHandle is unsigned routing data, never identity authority. The
            // candidate owner comes only from the exact saved credential ID;
            // its stable handle must agree, and the saved key must verify below.
            if challenge.user_id.is_some()
                || request.credential.get_user_unique_id()
                    != Some(passkey_user_handle(&user.account_id).as_bytes().as_slice())
            {
                return Err(auth_error(
                    "passkey_user_mismatch",
                    "credential owner/user handle mismatch; use explicit legacy login for old keys",
                )
                .into());
            }
            webauthn.finish_discoverable_authentication(
                &request.credential,
                state,
                &[passkey.clone().into()],
            )
        }
        PasskeyLoginState::Legacy(state) => {
            if challenge.user_id.as_deref() != Some(user.user_id.as_str()) {
                return Err(auth_error(
                    "passkey_user_mismatch",
                    "credential does not belong to the challenged user",
                )
                .into());
            }
            webauthn.finish_passkey_authentication(&request.credential, &state)
        }
    }
    .map_err(|error| auth_error("webauthn_login_verification_failed", &error.to_string()))?;
    if auth_result.cred_id().as_slice() != request.credential.get_credential_id() {
        return Err(auth_error(
            "passkey_user_mismatch",
            "verified credential differs from saved credential",
        )
        .into());
    }
    if stored.sign_count > 0
        && auth_result.counter() > 0
        && u64::from(auth_result.counter()) <= stored.sign_count
    {
        return Err(auth_error(
            "webauthn_login_verification_failed",
            "credential counter did not advance",
        )
        .into());
    }
    passkey.update_credential(&auth_result);
    let public_key_cose = serde_json::to_string(&passkey)
        .map_err(|error| auth_error("webauthn_state_serialize_failed", &error.to_string()))?;
    api.store
        .upsert_passkey_credential(&PasskeyCredentialRecord {
            credential_id: credential_id.clone(),
            user_id: user.user_id.clone(),
            public_key_cose,
            transports_json: stored.transports_json,
            sign_count: u64::from(auth_result.counter()),
            created_at: stored.created_at,
            last_used_at: Some(crate::auth::now_rfc3339()),
        })?;
    if normal_login {
        api.store
            .mark_passkey_normal_login_verified(&credential_id, &crate::auth::now_rfc3339())?;
    }
    issue_browser_session(api, user)
}

fn issue_browser_session(
    api: &ServerAuthApi,
    user: UserRecord,
) -> ApiResult<(AuthUserResponse, server_api::SetCookieHeader)> {
    let session_token = mint_secret("yoi_sess");
    api.store.create_browser_session(&BrowserSessionRecord {
        session_id: new_id("session"),
        token_hash: token_hash(&session_token),
        user_id: user.user_id.clone(),
        created_at: crate::auth::now_rfc3339(),
        expires_at: rfc3339_after(Duration::seconds(crate::auth::BROWSER_SESSION_SECONDS)),
        revoked_at: None,
    })?;
    let auth = auth_public_config(&api.config);
    let cookie = session_set_cookie(
        session_cookie_policy(&auth),
        &session_token,
        crate::auth::BROWSER_SESSION_SECONDS,
    );
    Ok((
        AuthUserResponse {
            user: user_response(user),
            authentication_reference: crate::auth::authentication_reference(&token_hash(
                &session_token,
            )),
        },
        server_api::SetCookieHeader::new(cookie),
    ))
}

async fn post_device_login_start(
    State(api): State<ServerAuthApi>,
    Json(request): Json<DeviceLoginStartRequest>,
) -> ApiResult<Json<DeviceLoginStartResponse>> {
    api.store
        .db_executor()
        .run(move || {
            const MAX_CODE_ALLOCATION_ATTEMPTS: usize = 8;

            let auth = auth_public_config(&api.config);
            let verification_uri = format!(
                "{}/login/device",
                auth.public_base_url.trim_end_matches('/')
            );
            for _ in 0..MAX_CODE_ALLOCATION_ATTEMPTS {
                let device_code = mint_secret("yoi_device");
                let user_code = new_user_code();
                let verification_uri_complete = format!("{verification_uri}?user_code={user_code}");
                let flow = DeviceLoginFlowRecord {
                    device_code: device_code.clone(),
                    user_code: user_code.clone(),
                    verification_uri: verification_uri.clone(),
                    client_name: request.client_name.clone(),
                    user_id: None,
                    api_token_id: None,
                    issued_access_token: None,
                    created_at: crate::auth::now_rfc3339(),
                    expires_at: rfc3339_after(Duration::minutes(10)),
                    approved_at: None,
                    consumed_at: None,
                };
                if !api.store.try_create_device_login_flow(&flow)? {
                    continue;
                }
                return Ok(Json(DeviceLoginStartResponse {
                    device_code,
                    user_code,
                    verification_uri,
                    verification_uri_complete,
                    expires_in: 600,
                    interval: 5,
                }));
            }

            Err(auth_error(
                "device_login_code_allocation_failed",
                "could not allocate a unique device login user code",
            )
            .into())
        })
        .await
}

fn approve_device_login(
    api: &ServerAuthApi,
    actor: RequestActor,
    request: DeviceLoginApproveRequest,
) -> ApiResult<DeviceLoginApproveResponse> {
    let flow = api
        .store
        .get_device_login_flow_by_user_code(&request.user_code.trim().to_ascii_uppercase())?
        .ok_or_else(|| {
            auth_error(
                "unknown_device_login_code",
                "device login code does not exist",
            )
        })?;
    if is_expired(&flow.expires_at) {
        return Err(auth_error("expired_device_login", "device login code expired").into());
    }
    if flow.approved_at.is_some() || flow.consumed_at.is_some() {
        return Err(auth_error(
            "device_login_already_used",
            "device login code is already used",
        )
        .into());
    }
    let access_token = mint_secret("yoi_api");
    let token_id = new_id("api-token");
    api.store.create_api_token(&ApiTokenRecord {
        token_id: token_id.clone(),
        token_hash: token_hash(&access_token),
        user_id: actor.user_id.clone(),
        label: flow
            .client_name
            .clone()
            .unwrap_or_else(|| "yoi device login".to_string()),
        created_at: crate::auth::now_rfc3339(),
        expires_at: None,
        revoked_at: None,
        last_used_at: None,
    })?;
    let approved = api.store.approve_device_login_flow(
        &flow.device_code,
        &actor.user_id,
        &token_id,
        &access_token,
        &crate::auth::now_rfc3339(),
    )?;
    if !approved {
        return Err(auth_error(
            "device_login_already_used",
            "device login code is already used",
        )
        .into());
    }
    Ok(DeviceLoginApproveResponse {
        status: DeviceLoginApprovalStatus::Approved,
        user: actor.user(),
    })
}

/// Returns the API token generated by browser approval to the device client.
///
/// Pending and expired flows return no credentials. Approved flows consume and return the
/// token, clearing the store's temporary token so normal repeated polling yields Consumed.
/// This does not guarantee retrieval of the same token after response loss and is separate
/// from browser-cookie authentication.
async fn post_device_login_poll(
    State(api): State<ServerAuthApi>,
    Json(request): Json<DeviceLoginPollRequest>,
) -> ApiResult<Json<DeviceLoginPollResponse>> {
    api.store
        .db_executor()
        .run(move || {
            let Some(flow) = api
                .store
                .get_device_login_flow_by_device_code(&request.device_code)?
            else {
                return Err(
                    auth_error("unknown_device_login", "device login flow does not exist").into(),
                );
            };
            if is_expired(&flow.expires_at) {
                return Ok(Json(DeviceLoginPollResponse {
                    status: DeviceLoginPollStatus::Expired,
                    access_token: None,
                    token_type: None,
                }));
            }
            if flow.approved_at.is_none() {
                return Ok(Json(DeviceLoginPollResponse {
                    status: DeviceLoginPollStatus::Pending,
                    access_token: None,
                    token_type: None,
                }));
            }
            let Some(consumed) = api
                .store
                .consume_device_login_token(&request.device_code, &crate::auth::now_rfc3339())?
            else {
                return Ok(Json(DeviceLoginPollResponse {
                    status: DeviceLoginPollStatus::Consumed,
                    access_token: None,
                    token_type: None,
                }));
            };
            Ok(Json(DeviceLoginPollResponse {
                status: DeviceLoginPollStatus::Approved,
                access_token: consumed.issued_access_token,
                token_type: Some(DeviceAccessTokenType::Bearer),
            }))
        })
        .await
}

fn logout_browser_session(
    api: &ServerAuthApi,
    cookie: Option<String>,
) -> ApiResult<(LogoutResponse, server_api::SetCookieHeader)> {
    let auth = auth_public_config(&api.config);
    let mut headers = HeaderMap::new();
    if let Some(cookie) = cookie {
        let value = cookie.parse::<HeaderValue>().map_err(|_| {
            auth_error(
                "invalid_session_cookie",
                "request cookie header could not be represented",
            )
        })?;
        headers.insert(axum::http::header::COOKIE, value);
    }
    if let Some(session_token) = parse_cookie(&headers, &auth.cookie_name) {
        let _ = api
            .store
            .revoke_browser_session(&token_hash(&session_token), &crate::auth::now_rfc3339())?;
    }
    // A missing auth cookie after Max-Age must not prevent explicit logout from revoking
    // the recovery reference. This hash is never accepted as an authentication credential.
    if let Some(hash) = parse_cookie(
        &headers,
        &crate::auth::session_marker_cookie_name(&auth.cookie_name),
    ) {
        let _ = api
            .store
            .revoke_browser_session(&hash, &crate::auth::now_rfc3339())?;
    }
    Ok((
        LogoutResponse {
            status: LogoutStatus::LoggedOut,
        },
        server_api::SetCookieHeader::new(session_set_cookie(session_cookie_policy(&auth), "", 0)),
    ))
}

fn request_origin(headers: &HeaderMap) -> Option<String> {
    headers
        .get(ORIGIN)
        .and_then(|value| value.to_str().ok())
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
}

fn auth_config_for_origin(
    config: &ServerConfig,
    request_origin: Option<&str>,
) -> ApiResult<AuthPublicConfig> {
    let mut auth = auth_public_config(config);
    let Some(request_origin) = request_origin else {
        return Ok(auth);
    };
    let origin = Url::parse(request_origin)
        .map_err(|error| auth_error("invalid_webauthn_request_origin", &error.to_string()))?;
    let host = origin.host_str().ok_or_else(|| {
        auth_error(
            "invalid_webauthn_request_origin",
            "request Origin header does not contain a host",
        )
    })?;
    if host != auth.rp_id {
        return Err(auth_error(
            "webauthn_origin_rp_id_mismatch",
            &format!(
                "browser origin host {host} does not match configured RP ID {}",
                auth.rp_id
            ),
        )
        .into());
    }
    auth.origin = request_origin.to_string();
    Ok(auth)
}

fn webauthn_for_challenge(
    config: &ServerConfig,
    challenge: &AuthChallengeRecord,
) -> ApiResult<Webauthn> {
    let mut auth = auth_public_config(config);
    auth.rp_id = challenge.rp_id.clone();
    auth.origin = challenge.origin.clone();
    webauthn_for_auth(&auth)
}

fn webauthn_for_auth(auth: &AuthPublicConfig) -> ApiResult<Webauthn> {
    let origin = Url::parse(&auth.origin)
        .map_err(|error| auth_error("invalid_webauthn_origin", &error.to_string()))?;
    WebauthnBuilder::new(&auth.rp_id, &origin)
        .map_err(|error| auth_error("webauthn_builder_failed", &error.to_string()))?
        .rp_name("Yoi Workspace")
        .build()
        .map_err(|error| auth_error("webauthn_builder_failed", &error.to_string()).into())
}

fn passkeys_for_user(api: &ServerAuthApi, user_id: &str) -> ApiResult<Vec<Passkey>> {
    api.store
        .list_passkey_credentials_for_user(user_id)?
        .into_iter()
        .map(|record| {
            serde_json::from_str::<Passkey>(&record.public_key_cose).map_err(|error| {
                auth_error("webauthn_passkey_deserialize_failed", &error.to_string()).into()
            })
        })
        .collect()
}

fn passkey_credential_id(passkey: &Passkey) -> ApiResult<String> {
    serde_json::to_value(passkey.cred_id())
        .ok()
        .and_then(|value| value.as_str().map(ToOwned::to_owned))
        .ok_or_else(|| {
            auth_error(
                "invalid_webauthn_credential_id",
                "verified passkey credential id was not serializable",
            )
            .into()
        })
}

fn session_cookie_policy(auth: &AuthPublicConfig) -> SessionCookiePolicy<'_> {
    let secure = [&auth.origin, &auth.public_base_url]
        .into_iter()
        .filter_map(|url| reqwest::Url::parse(url).ok())
        .any(|url| url.scheme() == "https");
    SessionCookiePolicy {
        cookie_name: &auth.cookie_name,
        path: "/",
        domain: None,
        secure,
    }
}

fn auth_public_config(config: &ServerConfig) -> AuthPublicConfig {
    match &config.auth {
        AuthConfig::Passkey {
            rp_id,
            origin,
            public_base_url,
            cookie_name,
        } => AuthPublicConfig {
            rp_id: rp_id.clone(),
            origin: origin.clone(),
            public_base_url: public_base_url.clone(),
            cookie_name: cookie_name.clone(),
        },
    }
}

fn allocate_new_user(
    api: &ServerAuthApi,
    handle: &str,
    display_name: Option<&str>,
) -> ApiResult<UserRecord> {
    let handle = normalize_handle(handle)?;
    if api.store.get_user_by_handle(&handle)?.is_some()
        || api.store.get_account_by_handle("user", &handle)?.is_some()
    {
        return Err(auth_error("auth_handle_exists", "handle is already registered").into());
    }
    let now = crate::auth::now_rfc3339();
    let display_name = display_name
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or(handle.as_str())
        .to_string();
    Ok(UserRecord {
        user_id: new_id("user"),
        account_id: new_id("acct-user"),
        handle,
        display_name,
        created_at: now.clone(),
        updated_at: now,
    })
}

fn user_response(user: UserRecord) -> AuthenticatedUser {
    AuthenticatedUser {
        user_id: user.user_id,
        account_id: user.account_id,
        handle: user.handle,
        display_name: user.display_name,
    }
}

async fn resolve_actor(
    api: &ServerAuthApi,
    headers: &HeaderMap,
) -> ApiResult<Option<RequestActor>> {
    let cookie_name = auth_public_config(&api.config).cookie_name;
    Ok(resolve_request_actor(api.store.clone(), headers, &cookie_name).await?)
}

// Hosting endpoints re-resolve actual transport credentials, not actor-like headers,
// JSON or a stale middleware snapshot. The store rechecks live admin authority in
// the write transaction. Cookie writes require Origin; non-browser bearer calls
// may omit it, but a supplied foreign Origin never becomes trusted via a bearer.
fn live_hosting_actor(
    api: &ServerAuthApi,
    context: &server_api::ServerRequestContext,
    mutating: bool,
) -> ApiResult<RequestActor> {
    let headers = contract_request_headers(context)
        .map_err(|error| Error::WorkspacePermissionDenied(error.message))?;
    let auth = auth_public_config(&api.config);
    let actor = crate::auth::resolve_request_actor_sync(
        api.store.as_ref(),
        crate::auth::parse_bearer(&headers),
        parse_cookie(&headers, &auth.cookie_name),
    )?
    .ok_or_else(|| auth_error("auth_required", "current authentication required"))?;
    let origin = request_origin(&headers);
    if mutating
        && (actor.auth_method == ActorAuthMethod::BrowserSession || origin.is_some())
        && origin.as_deref() != Some(auth.origin.as_str())
    {
        return Err(Error::WorkspacePermissionDenied(
            "hosting mutations require configured Browser origin when supplied, and for cookies"
                .into(),
        )
        .into());
    }
    Ok(actor)
}

fn require_hosting_admin(api: &ServerAuthApi, actor: &RequestActor) -> ApiResult<()> {
    if !api.store.is_hosting_admin(&actor.user_id)? {
        return Err(
            Error::WorkspacePermissionDenied("hosting administrator required".into()).into(),
        );
    }
    Ok(())
}

fn require_self_registration(api: &ServerAuthApi) -> ApiResult<()> {
    if !api.store.hosting_self_registration_enabled()? {
        return Err(Error::WorkspacePermissionDenied("self_registration_disabled".into()).into());
    }
    Ok(())
}

async fn require_actor(api: &ServerAuthApi, headers: &HeaderMap) -> ApiResult<RequestActor> {
    resolve_actor(api, headers).await?.ok_or_else(|| {
        auth_error(
            "auth_required",
            "request requires a browser session or Bearer API token",
        )
        .into()
    })
}

async fn workspace_response(
    api: &WorkspaceApi,
    actor: Option<RequestActor>,
) -> ApiResult<WorkspaceResponse> {
    let schema_version = api.store.schema_version().await?;
    let stored = api
        .store
        .get_workspace(api.workspace_id())
        .await?
        .ok_or_else(|| Error::InvalidRecordId(api.workspace_id().to_string()))?;
    let is_owner = actor
        .as_ref()
        .is_some_and(|actor| stored.owner_account_id == actor.account_id);
    let companion_status = api.companion.status();
    let companion_console = companion_console_extension_point(&companion_status);
    Ok(WorkspaceResponse {
        workspace_id: stored.workspace_id,
        display_name: stored.display_name,
        record_authority: "server_db".to_string(),
        schema_version,
        auth: api.config.auth.clone(),
        permissions: WorkspacePermissionSummary {
            manage_repositories: is_owner,
            manage_secrets: is_owner,
            manage_runtimes: is_owner,
            delete_workspace: is_owner,
            delete_subjects: is_owner,
        },
        extension_points: WorkspaceExtensionPoints {
            store: "sqlite".to_string(),
            event_stream: WorkspaceExtensionPointState {
                status: "backend_proxy".to_string(),
                note: "Worker observation streams are exposed only through the Workspace server proxy keyed by runtime_id + worker_id; browser clients never receive raw Runtime endpoints or socket paths.".to_string(),
                diagnostics: Vec::new(),
            },
            host_worker_bridge: WorkspaceExtensionPointState {
                status: "runtime_registry".to_string(),
                note: "Hosts and Workers are projected from the Workspace RuntimeRegistry; raw Runtime endpoints, sockets, and local metadata paths are not exposed.".to_string(),
                diagnostics: Vec::new(),
            },
            companion_console,
        },
    })
}

fn companion_console_extension_point(
    status: &CompanionStatusResponse,
) -> WorkspaceExtensionPointState {
    let extension_status = match status.state {
        server_api::CompanionLifecycleState::Idle => "idle",
        server_api::CompanionLifecycleState::Running => "running",
        server_api::CompanionLifecycleState::Stopped => "stopped",
    }
    .to_string();
    let diagnostic_codes = status
        .diagnostics
        .iter()
        .map(|diagnostic| diagnostic.code.as_str())
        .collect::<Vec<_>>()
        .join(", ");
    let note = if status.transport.available {
        "Workspace Companion is input-capable and browser input is dispatched through the normal Worker runtime path."
            .to_string()
    } else if diagnostic_codes.is_empty() {
        "Workspace Companion is unavailable; create or select an explicit Worker instead."
            .to_string()
    } else {
        format!("Workspace Companion is unavailable; check typed diagnostics: {diagnostic_codes}.")
    };
    WorkspaceExtensionPointState {
        status: extension_status,
        note,
        diagnostics: status.diagnostics.clone(),
    }
}

async fn list_tickets(
    State(api): State<WorkspaceApi>,
    Query(query): Query<TicketListQuery>,
) -> ApiResult<Json<crate::records::TicketListResponse>> {
    api.store
        .db_executor()
        .run(move || {
            let limit = query.limit.unwrap_or(30).clamp(1, 100);
            let states = query
                .states
                .as_deref()
                .map(|states| {
                    states
                        .split(',')
                        .filter(|state| !state.is_empty())
                        .map(str::to_string)
                        .collect::<Vec<_>>()
                })
                .unwrap_or_default();
            let crate::records::TicketSummaryPage {
                items,
                page,
                invalid_records,
                record_authority,
            } = api
                .authority
                .list_ticket_page(crate::records::TicketListProjectionRequest {
                    states,
                    limit: Some(limit),
                    cursor: query.cursor,
                })?;
            Ok(Json(crate::records::TicketListResponse {
                workspace_id: api.config.workspace_id,
                limit,
                items,
                page,
                invalid_records,
                record_authority,
            }))
        })
        .await
}

async fn get_ticket(
    State(api): State<WorkspaceApi>,
    AxumPath(id): AxumPath<String>,
) -> ApiResult<Json<TicketDetail>> {
    api.host_executors
        .host()?
        .run(move || Ok(Json(api.authority.ticket(&id)?)))
        .await
}

async fn list_objectives(
    State(api): State<WorkspaceApi>,
    Query(query): Query<server_api::ObjectiveListQuery>,
) -> ApiResult<Json<server_api::ObjectiveListResponse>> {
    api.store
        .db_executor()
        .run(move || {
            let limit = query.limit.unwrap_or(api.config.max_records).min(1000);
            let ProjectRecordList {
                items,
                invalid_records,
                record_authority,
            } = api.authority.list_objectives(limit)?;
            Ok(Json(server_api::ObjectiveListResponse {
                workspace_id: api.config.workspace_id,
                limit,
                items,
                invalid_records,
                record_authority,
            }))
        })
        .await
}

async fn get_objective(
    State(api): State<WorkspaceApi>,
    AxumPath(id): AxumPath<String>,
) -> ApiResult<Json<ObjectiveDetail>> {
    api.store
        .db_executor()
        .run(move || Ok(Json(api.authority.objective(&id)?)))
        .await
}

async fn list_repositories(
    State(api): State<WorkspaceApi>,
) -> ApiResult<Json<RepositoryListResponse>> {
    api.host_executors
        .host()?
        .run(move || {
            let RepositoryListProjection { items, diagnostics } =
                api.live_repository_reader()?.list();
            Ok(Json(RepositoryListResponse {
                workspace_id: api.config.workspace_id,
                items,
                source: "workspace-control-plane".to_string(),
                diagnostics,
            }))
        })
        .await
}

async fn repository_detail(
    State(api): State<WorkspaceApi>,
    AxumPath(repository_key): AxumPath<String>,
) -> ApiResult<Json<RepositoryDetailResponse>> {
    api.host_executors
        .host()?
        .run(move || {
            server_api::validate_repository_key(&repository_key).map_err(|error| {
                ApiError::from(Error::InvalidInput(format!(
                    "invalid Repository key: {error}"
                )))
            })?;
            let item = repository_lookup(
                api.live_repository_reader()?
                    .summary_by_key(&repository_key),
            )?;
            Ok(Json(RepositoryDetailResponse {
                workspace_id: api.config.workspace_id.clone(),
                item,
                source: "workspace-control-plane".to_string(),
            }))
        })
        .await
}

async fn repository_log(
    State(api): State<WorkspaceApi>,
    AxumPath(repository_key): AxumPath<String>,
    Query(query): Query<LogQuery>,
) -> ApiResult<Json<RepositoryLogResponse>> {
    api.host_executors
        .host()?
        .run(move || {
            server_api::validate_repository_key(&repository_key).map_err(|error| {
                ApiError::from(Error::InvalidInput(format!(
                    "invalid Repository key: {error}"
                )))
            })?;
            let RepositoryLogRead {
                repository_key,
                default_selector,
                limit,
                commits,
                diagnostics,
            } = repository_lookup(
                api.live_repository_reader()?
                    .recent_log(&repository_key, query.limit),
            )?;
            Ok(Json(RepositoryLogResponse {
                workspace_id: api.config.workspace_id,
                repository_key,
                default_selector,
                limit,
                items: commits,
                diagnostics,
            }))
        })
        .await
}

