async fn require_active_runtime_registration_identity(api: &WorkspaceApi) -> ApiResult<()> {
    let identities = api.signing_identities.clone();
    let workspace_id = api.config.workspace_id.clone();
    api.store
        .db_executor()
        .run(move || {
            let identity = identities.get_validated(&workspace_id)?;
            if identity.state != "active" {
                return Err(settings_bad_request(
                    "workspace_signing_identity_unavailable",
                    "an active Workspace signing identity is required before registering a Runtime",
                ));
            }
            Ok(())
        })
        .await
}

async fn scan_runtime_registration_workers(api: &WorkspaceApi, runtime_id: &str) -> ApiResult<()> {
    let runtime = api.runtime.clone();
    let runtime_id = runtime_id.to_owned();
    let limit = api.config.max_records.min(200);
    api.host_executors.host()?.run(move || {
        match runtime.list_workers_for_runtime(&runtime_id, limit) {
            Ok(workers) if !workers.items.is_empty() => Err(Error::RuntimeBindingConflict(format!(
                "Runtime `{runtime_id}` still has {} active worker(s) and cannot replace its connection",
                workers.items.len()
            )).into()),
            Ok(_) | Err(RuntimeRegistryError::UnknownRuntime(_)) => Ok(()),
            Err(error) => Err(error.into_error().into()),
        }
    }).await
}

fn publish_workspace_runtime_binding(
    api: &WorkspaceApi,
    binding: WorkspaceRuntimeBinding,
) -> Result<()> {
    api.runtime_binding_expectations
        .write()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .insert(
            (binding.workspace_id.clone(), binding.runtime_id.clone()),
            binding.clone(),
        );
    api.runtime_subscription_broker
        .unregister_runtime(&binding.runtime_id);
    api.register_workspace_runtime_binding(binding)
}

async fn require_current_runtime_test_binding(
    api: &WorkspaceApi,
    binding: WorkspaceRuntimeBinding,
) -> ApiResult<WorkspaceRuntimeBinding> {
    let store = api.store.clone();
    api.store
        .db_executor()
        .run(move || {
            if !store.workspace_runtime_binding_matches(&binding)? {
                return Err(Error::RuntimeBindingConflict(
                    "Runtime connection changed while the connection test was running".to_string(),
                )
                .into());
            }
            Ok(binding)
        })
        .await
}

async fn create_remote_runtime(
    State(api): State<WorkspaceApi>,
    Extension(actor): Extension<RequestActor>,
    Json(request): Json<CreateRemoteRuntimeRequest>,
) -> ApiResult<(StatusCode, Json<WorkspaceRuntimeResource>)> {
    require_workspace_owner(
        &api,
        &api.config.workspace_id,
        &actor,
        "manage Workspace Runtimes",
    )
    .await?;
    let endpoint = validate_runtime_connection_request(&request).await?;
    let runtime_id = request.public_bundle.identity_id.trim().to_string();
    if runtime_id == EMBEDDED_WORKER_RUNTIME_ID {
        return Err(settings_bad_request(
            "embedded_runtime_not_config_managed",
            "the embedded Runtime is built in and cannot be managed as a remote Runtime",
        ));
    }
    require_active_runtime_registration_identity(&api).await?;
    // Protect observed active Workers without removing the current connection.
    // This scan is not proof of idleness: an unavailable/auth-failing endpoint
    // must remain repairable by an owner using binding-ID CAS below. Replacement
    // neither stops nor deletes Workers; Runtime removal has separate preflight.
    // Rejected key/CAS mutations must leave the current registration usable.
    scan_runtime_registration_workers(&api, &runtime_id).await?;
    let now = Utc::now().to_rfc3339();
    let record = WorkspaceRuntimeBinding {
        workspace_id: api.config.workspace_id.clone(),
        runtime_id: runtime_id.clone(),
        display_name: request
            .display_name
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .unwrap_or(&runtime_id)
            .to_string(),
        base_url: endpoint.to_string().trim_end_matches('/').to_string(),
        public_key: request.public_bundle.public_key.trim().to_string(),
        public_key_fingerprint: String::new(),
        binding_id: Uuid::now_v7().to_string(),
        authentication_mode: StoredRuntimeAuthenticationMode::WorkspaceIdentity,
        created_at: now.clone(),
        updated_at: now,
        revoked_at: None,
    };
    let mutation_api = api.clone();
    // One accepted owner keeps SQL commit, local registration and its response
    // observation together even when the HTTP waiter disappears. Resource reads
    // call the on-Host helper directly, never re-admit to the occupied Host lane.
    let (mutation, resource) = run_host_workflow(api.host_executors.host()?, async move {
        let (mutation, binding) = mutation_api
            .store
            .put_workspace_runtime_binding_key(
                record,
                request.expected_binding_id.as_deref(),
                &actor.account_id,
            )
            .await?;
        publish_workspace_runtime_binding(&mutation_api, binding)?;
        let resource = workspace_runtime_resources_response_on_host(
            &mutation_api,
            mutation_api.workspace_id(),
        )
        .await?
        .items
        .into_iter()
        .find(|resource| resource.runtime.runtime_id == runtime_id)
        .ok_or_else(|| Error::UnknownRuntime(runtime_id.clone()))?;
        Ok::<_, ApiError>((mutation, resource))
    })
    .await?;
    let status = if mutation == WorkspaceRuntimeBindingMutation::Created {
        StatusCode::CREATED
    } else {
        StatusCode::OK
    };
    Ok((status, Json(resource)))
}

fn runtime_removal_response(operation: RuntimeRemovalOperation) -> RuntimeRemovalOperationResponse {
    RuntimeRemovalOperationResponse {
        operation_id: operation.operation_id,
        workspace_id: operation.workspace_id,
        runtime_id: operation.runtime_id,
        state: match operation.state {
            RuntimeRemovalOperationState::Pending => ApiRuntimeRemovalOperationState::Pending,
            RuntimeRemovalOperationState::CleanupPending => {
                ApiRuntimeRemovalOperationState::CleanupPending
            }
            RuntimeRemovalOperationState::Succeeded => ApiRuntimeRemovalOperationState::Succeeded,
            RuntimeRemovalOperationState::Failed => ApiRuntimeRemovalOperationState::Failed,
        },
        binding_removed: operation.binding_removed,
        runtime_registration_removed: operation.runtime_registration_removed,
        failure_category: operation.failure_category,
        created_at: operation.created_at,
        updated_at: operation.updated_at,
        completed_at: operation.completed_at,
    }
}

fn runtime_removal_fingerprint(
    workspace_id: &str,
    runtime_id: &str,
    expected_binding_id: &str,
) -> String {
    let digest = Sha256::digest(format!(
        "runtime-removal-v2\0{workspace_id}\0{runtime_id}\0{expected_binding_id}"
    ));
    let digest = digest
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect::<String>();
    format!("sha256:{digest}")
}

fn runtime_removal_config_guard(
    api: &WorkspaceApi,
    operation: &RuntimeRemovalOperation,
) -> Result<()> {
    let config_state = api
        .config_store
        .load_workspace_config(&operation.workspace_id)?
        .ok_or_else(|| {
            Error::RegistryInconsistency(format!(
                "Workspace {} has no active configuration",
                operation.workspace_id
            ))
        })?;
    if config_state.snapshot.digest != operation.config_digest {
        return Err(Error::RuntimeBindingConflict(
            "runtime_removal_config_digest_changed".to_string(),
        ));
    }
    let projection = crate::runtime_settings::project_runtime_from_workspace_config(
        &operation.workspace_id,
        &config_state,
    )?;
    if projection.default_runtime_id.as_deref() == Some(operation.runtime_id.as_str()) {
        return Err(Error::RuntimeBindingConflict(
            "runtime_removal_config_reference_blocked".to_string(),
        ));
    }
    Ok(())
}

async fn execute_runtime_removal(
    api: &WorkspaceApi,
    operation: RuntimeRemovalOperation,
) -> ApiResult<RuntimeRemovalOperation> {
    let api = api.clone();
    // Retain registration/commit recovery as one owned lifecycle workflow;
    // SQL transaction boundaries and commit-before-Runtime order are unchanged.
    run_host_workflow(api.host_executors.host()?, async move {
        execute_runtime_removal_on_host(&api, operation).await
    })
    .await
}

async fn execute_runtime_removal_on_host(
    api: &WorkspaceApi,
    operation: RuntimeRemovalOperation,
) -> ApiResult<RuntimeRemovalOperation> {
    if operation.state == RuntimeRemovalOperationState::Succeeded {
        return Ok(operation);
    }
    let operation = if operation.state == RuntimeRemovalOperationState::Pending {
        if let Err(error) = runtime_removal_config_guard(api, &operation) {
            let _ = api
                .store
                .mark_runtime_removal_failed(
                    &operation.operation_id,
                    "runtime_removal_config_guard_failed",
                )
                .await;
            return Err(error.into());
        }
        if api.store.has_reserved_worker_create_for_runtime(
            &operation.workspace_id,
            &operation.runtime_id,
        )? {
            let _ = api
                .store
                .mark_runtime_removal_failed(
                    &operation.operation_id,
                    "runtime_removal_reserved_worker_create_blocked",
                )
                .await;
            return Err(Error::RuntimeBindingConflict(
                "runtime_removal_reserved_worker_create_blocked".to_string(),
            )
            .into());
        }
        let binding = api
            .store
            .get_workspace_runtime_binding(&operation.workspace_id, &operation.runtime_id)
            .await?
            .ok_or_else(|| Error::UnknownRuntime(operation.runtime_id.clone()))?;
        match api
            .runtime
            .unregister_if_idle(&operation.runtime_id, api.config.max_records.min(200))
            .map_err(|error| error.into_error())?
        {
            RuntimeRegistryUnregisterResult::Removed
            | RuntimeRegistryUnregisterResult::NotFound => {}
            RuntimeRegistryUnregisterResult::BlockedByWorkers {
                worker_count,
                mut diagnostics,
            } => {
                let _ = api
                    .store
                    .mark_runtime_removal_failed(
                        &operation.operation_id,
                        "runtime_removal_active_worker_blocked",
                    )
                    .await;
                diagnostics.push(settings_diagnostic(
                    "runtime_removal_active_worker_blocked",
                    HostDiagnosticSeverity::Error,
                    format!(
                        "Remote Runtime '{}' has {worker_count} active Worker(s); stop and remove them before removing the Runtime.",
                        operation.runtime_id
                    ),
                ));
                return Err(ApiError::with_diagnostics(
                    Error::RuntimeBindingConflict(
                        "runtime_removal_active_worker_blocked".to_string(),
                    ),
                    diagnostics,
                ));
            }
        }
        match api
            .store
            .commit_runtime_binding_removal(&operation.operation_id)
            .await
        {
            Ok(operation) => operation,
            Err(error) => {
                let _ = api
                    .store
                    .mark_runtime_removal_failed(
                        &operation.operation_id,
                        "runtime_removal_commit_failed",
                    )
                    .await;
                let restore_result = api.register_workspace_runtime_binding(binding);
                if let Err(restore_error) = restore_result {
                    tracing::warn!(
                        workspace_id = %operation.workspace_id,
                        runtime_id = %operation.runtime_id,
                        operation_id = %operation.operation_id,
                        error = %restore_error,
                        "failed to restore Runtime registration after removal commit failure"
                    );
                }
                return Err(error.into());
            }
        }
    } else {
        operation
    };

    if operation.state != RuntimeRemovalOperationState::CleanupPending {
        return Err(Error::RuntimeBindingConflict(
            "runtime_removal_operation_not_cleanup_pending".to_string(),
        )
        .into());
    }
    api.runtime_binding_expectations
        .write()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .remove(&(operation.workspace_id.clone(), operation.runtime_id.clone()));
    api.runtime_subscription_broker
        .unregister_runtime(&operation.runtime_id);
    api.store
        .complete_runtime_removal(&operation.operation_id, true)
        .await
        .map_err(Into::into)
}

async fn recover_runtime_removals(api: &WorkspaceApi) {
    let operations = match api
        .store
        .list_resumable_runtime_removals(&api.config.workspace_id)
        .await
    {
        Ok(operations) => operations,
        Err(error) => {
            tracing::warn!(
                workspace_id = %api.config.workspace_id,
                error = %error,
                "failed to list resumable Runtime removal operations"
            );
            return;
        }
    };
    for operation in operations {
        let operation_id = operation.operation_id.clone();
        let runtime_id = operation.runtime_id.clone();
        if let Err(error) = execute_runtime_removal(api, operation).await {
            tracing::warn!(
                workspace_id = %api.config.workspace_id,
                runtime_id = %runtime_id,
                operation_id = %operation_id,
                error = ?error,
                "Runtime removal recovery remains incomplete"
            );
        }
    }
}

async fn remove_remote_runtime(
    State(api): State<WorkspaceApi>,
    AxumPath(runtime_id): AxumPath<String>,
    Json(request): Json<RemoveRuntimeRequest>,
) -> ApiResult<Json<RuntimeRemovalOperationResponse>> {
    if runtime_id == EMBEDDED_WORKER_RUNTIME_ID {
        return Err(settings_bad_request(
            "embedded_runtime_not_config_managed",
            "the embedded Runtime is built in and cannot be removed",
        ));
    }
    if request.operation_id.is_empty() || request.operation_id.len() > 128 {
        return Err(Error::InvalidInput(
            "operation_id must contain between 1 and 128 bytes".to_string(),
        )
        .into());
    }
    let request_fingerprint = runtime_removal_fingerprint(
        &api.config.workspace_id,
        &runtime_id,
        &request.expected_binding_id,
    );
    if let Some(existing) = api.store.get_runtime_removal(&request.operation_id).await? {
        if existing.workspace_id != api.config.workspace_id
            || existing.runtime_id != runtime_id
            || existing.request_fingerprint != request_fingerprint
            || existing.expected_binding_id != request.expected_binding_id
        {
            return Err(Error::RuntimeBindingConflict(
                "runtime_removal_operation_id_reused".to_string(),
            )
            .into());
        }
        let existing = if existing.state == RuntimeRemovalOperationState::Failed {
            api.store
                .reserve_runtime_removal(
                    &existing.workspace_id,
                    &existing.runtime_id,
                    &existing.operation_id,
                    &existing.request_fingerprint,
                    &existing.expected_binding_id,
                    &existing.config_digest,
                )
                .await?
                .operation
        } else {
            existing
        };
        let operation = execute_runtime_removal(&api, existing).await?;
        return Ok(Json(runtime_removal_response(operation)));
    }

    let config_api = api.clone();
    let config_state = api
        .store
        .db_executor()
        .run(move || {
            config_api
                .config_store
                .load_workspace_config(&config_api.config.workspace_id)
        })
        .await?
        .ok_or_else(|| {
            Error::RegistryInconsistency(format!(
                "Workspace {} has no active configuration",
                api.config.workspace_id
            ))
        })?;
    let runtime_projection = crate::runtime_settings::project_runtime_from_workspace_config(
        &api.config.workspace_id,
        &config_state,
    )?;
    if runtime_projection.default_runtime_id.as_deref() == Some(runtime_id.as_str()) {
        return Err(Error::RuntimeBindingConflict(
            "runtime_removal_config_reference_blocked".to_string(),
        )
        .into());
    }
    let reservation = api
        .store
        .reserve_runtime_removal(
            &api.config.workspace_id,
            &runtime_id,
            &request.operation_id,
            &request_fingerprint,
            &request.expected_binding_id,
            &config_state.snapshot.digest,
        )
        .await?;
    let operation = execute_runtime_removal(&api, reservation.operation).await?;
    Ok(Json(runtime_removal_response(operation)))
}

async fn test_runtime_connection(
    State(api): State<WorkspaceApi>,
    AxumPath(runtime_id): AxumPath<String>,
) -> ApiResult<Json<RuntimeConnectionTestResponse>> {
    let runtime_id = runtime_id.trim().to_string();
    if runtime_id.is_empty() {
        return Err(Error::InvalidRuntimeIdentifier {
            kind: "runtime".to_string(),
            value: runtime_id,
        }
        .into());
    }
    let binding = api
        .store
        .get_workspace_runtime_binding(api.workspace_id(), &runtime_id)
        .await?
        .filter(|binding| binding.revoked_at.is_none())
        .ok_or_else(|| Error::UnknownRuntime(runtime_id.clone()))?;

    let checked_at = Utc::now().to_rfc3339();
    let runtime = api.runtime.clone();
    let ping_runtime_id = runtime_id.clone();
    let ping = api
        .host_executors
        .host()?
        .run(move || Ok::<_, ApiError>(runtime.ping(&ping_runtime_id)))
        .await?;

    // The ping runs outside the store lock. Recheck the entire live binding on
    // the independent DB owner, never acquire its mutex on the Tokio waiter.
    let binding = require_current_runtime_test_binding(&api, binding).await?;
    let mut result =
        runtime_connection_test_response(api.workspace_id(), &runtime_id, checked_at, ping);
    // This result describes this attempt, not permission for a future request.
    result.binding_id = binding.binding_id;

    Ok(Json(result))
}

async fn get_worker_launch_options(
    State(api): State<WorkspaceApi>,
) -> ApiResult<Json<WorkerLaunchOptionsResponse>> {
    // Runtime summaries can call back into DB signing/authority. Profile config
    // reads are synchronous too, but this mixed helper must not occupy sole DB.
    api.host_executors
        .host()?
        .run(move || Ok(Json(worker_launch_options_response(&api)?)))
        .await
}

fn working_directory_request_from_repository(
    repository: &ConfiguredRepository,
    selector: Option<&str>,
) -> WorkingDirectoryRequest {
    WorkingDirectoryRequest {
        repository: WorkingDirectoryRepository {
            id: repository.id.clone(),
            provider: repository.provider.clone(),
            source: repository.source.clone(),
            source_fingerprint: repository.source_fingerprint.clone(),
            selector: selector
                .map(|selector| RuntimeRepositorySelector::from(selector.to_string()))
                .or_else(|| {
                    repository
                        .default_selector
                        .clone()
                        .map(RuntimeRepositorySelector)
                })
                .or_else(|| Some(RuntimeRepositorySelector::from("HEAD"))),
        },
        display_name: None,
        materializer: MaterializerKind::RuntimeGitClone,
        backend_workdir_id: None,
        materialization: None,
    }
}

fn configured_working_directory_request(
    api: &WorkspaceApi,
    request: &WorkerSpawnWorkingDirectoryRequest,
) -> Result<WorkingDirectoryRequest> {
    let repository = api
        .config
        .repositories
        .iter()
        .find(|repository| repository.repository_key == request.repository_key)
        .ok_or_else(|| Error::UnknownRepository(request.repository_key.clone()))?;
    Ok(working_directory_request_from_repository(
        repository,
        request.selector.as_deref(),
    ))
}

fn validate_worker_initial_submit(segments: &[Segment]) -> Result<()> {
    let flow_selectors = segments
        .iter()
        .filter_map(|segment| match segment {
            Segment::Flow { selector } => Some(selector),
            _ => None,
        })
        .collect::<Vec<_>>();
    if flow_selectors.len() > 1 {
        return Err(Error::InvalidInput(
            "initial_submit may contain at most one Flow segment".to_string(),
        ));
    }
    if let Some(selector) = flow_selectors.first() {
        selector
            .parse::<flow::FlowSelector>()
            .map_err(|error| Error::InvalidInput(error.to_string()))?;
    }
    if segments
        .iter()
        .any(|segment| matches!(segment, Segment::Unknown))
    {
        return Err(Error::InvalidInput(
            "initial_submit must not contain unknown segment variants".to_string(),
        ));
    }
    Ok(())
}

fn browser_worker_spawn_policy(
    ticket_assignment: Option<CreateWorkspaceWorkerTicketAssignmentRequest>,
    initial_submit: &[Segment],
) -> Result<(
    WorkerSpawnIntent,
    WorkerSpawnAcceptanceRequirement,
    Option<WorkerTicketAssignmentRequest>,
)> {
    let expected_segments = initial_submit.len();
    match ticket_assignment {
        Some(assignment) => {
            let ticket_id = assignment.ticket_id.trim().to_string();
            if ticket_id.is_empty() {
                return Err(Error::InvalidInput(
                    "ticket_id must not be empty".to_string(),
                ));
            }
            let operation_id = assignment.operation_id.trim().to_string();
            if operation_id.is_empty() {
                return Err(Error::InvalidInput(
                    "assignment operation_id must not be empty".to_string(),
                ));
            }
            Ok((
                WorkerSpawnIntent::TicketRole {
                    ticket_id: ticket_id.clone(),
                    role: TicketWorkerRole::Worker,
                },
                WorkerSpawnAcceptanceRequirement::RunAccepted { expected_segments },
                Some(WorkerTicketAssignmentRequest {
                    orchestrator_assignment_id: assignment.orchestrator_assignment_id,
                    ticket_id,
                    operation_id,
                }),
            ))
        }
        None => {
            if initial_submit
                .iter()
                .any(|segment| matches!(segment, Segment::Flow { .. }))
            {
                return Err(Error::InvalidInput(
                    "Workspace Worker Flow spawn requires ticket_assignment; use a typed Ticket-assigned Ticket Worker spawn"
                        .to_string(),
                ));
            }
            Ok((
                WorkerSpawnIntent::WorkspaceCoding,
                WorkerSpawnAcceptanceRequirement::RunAccepted { expected_segments },
                None,
            ))
        }
    }
}

fn browser_worker_console_href(workspace_id: &str, resource_key: &str) -> String {
    format!(
        "/w/{}/workers/{}/console",
        encode_path_segment(workspace_id),
        encode_path_segment(resource_key)
    )
}

fn validate_caller_worker_singleton_key(singleton_key: Option<&str>) -> Result<()> {
    let Some(singleton_key) = singleton_key else {
        return Ok(());
    };
    crate::store::validate_worker_singleton_key(singleton_key)?;
    if crate::hosts::is_reserved_internal_worker_singleton_key(singleton_key)
        || singleton_key.starts_with(SUBJEKTIV_SINGLETON_PREFIX)
    {
        return Err(Error::InvalidInput(format!(
            "Worker singleton key {singleton_key:?} is reserved for a Backend-managed Worker"
        )));
    }
    Ok(())
}

#[cfg(test)]
async fn create_workspace_worker(
    State(api): State<WorkspaceApi>,
    headers: HeaderMap,
    Json(request): Json<CreateWorkspaceWorkerRequest>,
) -> ApiResult<Json<BrowserCreateWorkerResponse>> {
    create_workspace_worker_inner(api, headers, request, None).await
}

#[cfg(test)]
async fn create_workspace_worker_inner(
    api: WorkspaceApi,
    headers: HeaderMap,
    request: CreateWorkspaceWorkerRequest,
    resolved_control_operation: Option<WorkerControlOperation>,
) -> ApiResult<Json<BrowserCreateWorkerResponse>> {
    create_workspace_worker_authenticated(api, headers, request, resolved_control_operation, None)
        .await
}

async fn create_workspace_worker_authenticated(
    api: WorkspaceApi,
    headers: HeaderMap,
    request: CreateWorkspaceWorkerRequest,
    resolved_control_operation: Option<WorkerControlOperation>,
    context: Option<&server_api::ServerRequestContext>,
) -> ApiResult<Json<BrowserCreateWorkerResponse>> {
    let context = context.cloned();
    run_host_workflow(api.host_executors.host()?, async move {
        create_workspace_worker_authenticated_on_host(
            api,
            headers,
            request,
            resolved_control_operation,
            context.as_ref(),
        )
        .await
    })
    .await
}

async fn create_workspace_worker_authenticated_on_host(
    api: WorkspaceApi,
    headers: HeaderMap,
    request: CreateWorkspaceWorkerRequest,
    resolved_control_operation: Option<WorkerControlOperation>,
    context: Option<&server_api::ServerRequestContext>,
) -> ApiResult<Json<BrowserCreateWorkerResponse>> {
    let claim_lock = request
        .ticket_assignment
        .as_ref()
        .map(|a| worker_control_lock(&api, &format!("ticket-claim:{}", a.operation_id)));
    let _claim_guard = match claim_lock {
        Some(lock) => Some(lock.lock_owned().await),
        None => None,
    };
    let CreateWorkspaceWorkerRequest {
        runtime_id,
        display_name,
        mut singleton_key,
        profile,
        ticket_assignment,
        initial_submit,
        workdir_attachments,
        feature_connections,
        execution_grant,
        control_operation_id: _,
    } = request;
    let delegation = ticket_assignment
        .as_ref()
        .map(|assignment| {
            ticket_spawn_delegation(
                &api,
                &headers,
                context,
                assignment.orchestrator_assignment_id.as_deref(),
            )
        })
        .transpose()?
        .flatten();
    let source = if let Some(context) = context {
        authenticated_ticket_worker_source(&headers, context)?
    } else {
        optional_worker_mutation_source(&api, &api.config.workspace_id, &headers)?
    };
    let config_state = api
        .config_store
        .load_workspace_config(&api.config.workspace_id)?
        .ok_or_else(|| Error::InvalidRecordId("virtual config source tree".into()))?;
    let profile_projection = crate::profile_settings::project_profiles_from_workspace_config(
        &api.config.workspace_id,
        &config_state,
    )?;
    let profile = profile
        .as_deref()
        .map(str::trim)
        .filter(|profile| !profile.is_empty())
        .map(ToOwned::to_owned)
        .or_else(|| profile_projection.settings.default_profile.clone())
        .ok_or_else(|| {
            settings_bad_request(
                "workspace_default_profile_missing",
                "profile is required because this Workspace has no default profile configured",
            )
        })?;
    let profile_selector =
        crate::profile_settings::selector_for_workspace_candidate(&profile_projection, &profile)
            .ok_or_else(|| {
                settings_bad_request(
                    "unsupported_worker_profile",
                    "profile must be selected from Backend-published worker profile candidates",
                )
            })?;
    let prompt_catalog = api
        .prompt_projection_cache
        .resolve(&api.config.workspace_id, &config_state)?;
    let resolved_config_bundle =
        crate::profile_settings::build_virtual_profile_config_bundle_with_prompt_projection(
            &profile_projection,
            &config_state,
            &api.config.workspace_id,
            &api.config.workspace_created_at,
            &profile,
            prompt_catalog.as_ref(),
        )?;
    let resolved_execution_grant = if let Some(source) = source.as_ref() {
        let resolved = resolved_config_bundle
            .as_ref()
            .ok_or_else(|| Error::Config("resolved Worker Profile bundle is missing".into()))?;
        let profile_digest = format!(
            "sha256:{}",
            Sha256::digest(
                serde_json::to_vec(resolved).map_err(|error| Error::Config(error.to_string()))?
            )
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<String>()
        );
        subject_authorization::prepare_delegation(
            &api,
            &RuntimeWorkerRef::new(&source.runtime_id, &source.worker_id),
            execution_grant.as_ref(),
            &runtime_id,
            &profile,
            &profile_digest,
            singleton_key.as_deref(),
            feature_connections.subjektiv.is_some(),
        )?
    } else {
        if execution_grant.is_some() {
            return Err(Error::WorkspacePermissionDenied(
                "execution grants require an authenticated delegation origin".into(),
            )
            .into());
        }
        None
    };
    // Generic creation has no authenticated-origin operation reservation or
    // control-grant recovery. A supplied ID alone must not make that path a
    // delegation API; require the normal worker-control lifecycle instead.
    if resolved_execution_grant.is_some() && resolved_control_operation.is_none() {
        return Err(Error::WorkspacePermissionDenied(
            "Subject delegation requires worker-control creation with control_operation_id; generic Worker creation is not supported".into(),
        )
        .into());
    }
    let resolved_subjektiv_attached = match feature_connections.subjektiv {
        None => {
            validate_caller_worker_singleton_key(singleton_key.as_deref())?;
            false
        }
        Some(connection) => {
            if singleton_key.is_some() {
                return Err(Error::InvalidInput(
                    "singleton_key must be omitted when a subjektiv subject connection is requested"
                        .to_string(),
                )
                .into());
            }
            let profile_manifest =
                crate::profile_settings::resolve_profile_manifest_from_config_bundle(
                    resolved_config_bundle.as_ref().ok_or_else(|| {
                        Error::Config("resolved Worker Profile bundle is missing".to_string())
                    })?,
                    &profile,
                )?;
            let attachment = open_subjektiv_store(&api)?
                .authorize_worker_attachment(&connection.subject_id, &profile_manifest)
                .map_err(subjektiv_store_error)?;
            crate::store::validate_worker_singleton_key(&attachment.singleton_key)?;
            singleton_key = Some(attachment.singleton_key);
            true
        }
    };
    let display_name = sanitize_worker_display_name(&display_name).ok_or_else(|| {
        settings_bad_request(
            "invalid_worker_display_name",
            "display_name must contain at least one non-control character",
        )
    })?;
    if display_name == crate::hosts::WORKSPACE_ORCHESTRATOR_SINGLETON_KEY {
        return Err(Error::ReservedWorkerName(display_name).into());
    }
    validate_worker_initial_submit(&initial_submit)?;
    reject_orchestrator_generic_flow_spawn(
        &api,
        source.as_ref(),
        &initial_submit,
        ticket_assignment.is_some(),
    )?;
    let resolved_workdir_attachments = workdir_attachments
        .into_iter()
        .map(|selection| {
            let alias = workdir::WorkdirAttachmentAlias::new(selection.alias).map_err(|_| {
                settings_bad_request(
                    "invalid_workdir_attachment_alias",
                    "attachment alias must be a valid Worker-local routing key",
                )
            })?;
            Ok(WorkingDirectoryAttachmentClaim {
                alias,
                working_directory_id: selection.working_directory_id,
                relative_cwd: selection.relative_cwd,
                capabilities: workdir::WorkdirSessionCapabilities::READ_ONLY,
            })
        })
        .collect::<ApiResult<Vec<_>>>()?;
    validate_working_directory_claims_for_browser(&resolved_workdir_attachments)?;
    let (intent, acceptance, ticket_assignment) =
        browser_worker_spawn_policy(ticket_assignment, &initial_submit)?;
    let request = WorkerSpawnRequest {
        requested_worker_name: Some(display_name.clone()),
        singleton_key,
        intent,
        acceptance,
        profile: profile_selector,
        ticket_assignment,
        initial_submit,
        workdir_attachment_requests: Vec::new(),
        resolved_workdir_attachment_requests: Vec::new(),
        resolved_workdir_attachments,
        resolved_config_bundle,
        resolved_worker_observation_enabled: false,
        resolved_worker_observation_grants: Vec::new(),
        resolved_control_operation,
        resolved_execution_grant,
        resolved_workspace_api: None,
        resolved_memory_settings: None,
        resolved_subjektiv_attached,
    };
    validate_ticket_assignment_spawn(&api, &runtime_id, &request)?;
    let assignment = request.ticket_assignment.clone();
    let assignment_fingerprint = crate::hosts::worker_spawn_idempotency(&request)
        .map_err(Error::Config)?
        .map(|(_, fingerprint)| fingerprint);
    let mut fresh_ticket_claim = false;
    if let (Some(assignment), Some(fingerprint)) =
        (assignment.as_ref(), assignment_fingerprint.as_deref())
    {
        fresh_ticket_claim = reserve_ticket_start(
            &api,
            &assignment.operation_id,
            &assignment.ticket_id,
            &runtime_id,
            None,
            fingerprint,
            &Utc::now().to_rfc3339_opts(SecondsFormat::Secs, true),
            delegation.as_ref(),
        )?;
        let operation = api
            .store
            .get_ticket_assignment_operation(&api.config.workspace_id, &assignment.operation_id)?
            .ok_or_else(|| {
                Error::TicketAssignmentConflict(format!(
                    "assignment operation {} disappeared after reservation",
                    assignment.operation_id
                ))
            })?;
        if let Some(worker) = existing_lifecycle_assignment_worker(&api, assignment, &runtime_id)? {
            accept_queued_ticket_after_worker_spawn(&api, assignment)?;
            return Ok(Json(browser_worker_response_for_committed_summary(
                &api,
                worker,
                display_name,
                Vec::new(),
            )?));
        }
        if operation.assignment_id.is_some() {
            return Err(Error::TicketAssignmentConflict(format!(
                "completed operation {} has no recoverable Worker",
                assignment.operation_id
            ))
            .into());
        }
    }
    if let Some(assignment) = assignment.as_ref() {
        api.store.validate_ticket_assignment_operation_fence(
            &api.config.workspace_id,
            &assignment.operation_id,
        )?;
    }
    let result = match api.spawn_workspace_worker_with_claim_admission(
        &runtime_id,
        request,
        fresh_ticket_claim,
    ) {
        Ok(result) => result,
        Err(error) => return Err(error.into()),
    };
    let result = if resolved_subjektiv_attached {
        restore_reused_subject_worker(&api, result)?
    } else {
        result
    };
    Ok(Json(record_browser_worker_spawn(
        &api,
        runtime_id,
        display_name,
        result,
        assignment.as_ref(),
    )?))
}

fn restore_reused_subject_worker(
    api: &WorkspaceApi,
    mut result: WorkerSpawnResult,
) -> ApiResult<WorkerSpawnResult> {
    if result.state != InternalWorkerOperationState::Accepted {
        return Ok(result);
    }
    let Some(worker) = result.worker.as_ref() else {
        return Ok(result);
    };
    if worker.state != "stopped" {
        return Ok(result);
    }

    let worker_ref = worker.worker.clone();
    let restored = restore_internal_observed_worker(api, worker, "subject-restore".to_owned())?;
    if restored.state != server_api::WorkerRestoreState::Accepted {
        let message = runtime_diagnostics_message(&restored.diagnostics);
        return Err(ApiError::with_diagnostics(
            Error::RuntimeOperationFailed {
                runtime_id: worker_ref.runtime_id,
                code: "subject_worker_restore_rejected".to_string(),
                message,
            },
            restored.diagnostics,
        ));
    }
    let worker = restored
        .worker
        .ok_or_else(|| Error::RuntimeOperationFailed {
            runtime_id: worker_ref.runtime_id,
            code: "subject_worker_restore_missing_summary".to_string(),
            message: "Runtime restored the existing subject Worker without returning its summary"
                .to_string(),
        })?;
    result.worker = Some(worker);
    result.diagnostics.extend(restored.diagnostics);
    result
        .acceptance_evidence
        .push(WorkerSpawnAcceptanceEvidence {
            kind: "subject_worker_restored".to_string(),
            detail: "the existing stopped subject Worker was restored".to_string(),
        });
    Ok(result)
}

fn record_browser_worker_spawn(
    api: &WorkspaceApi,
    requested_runtime_id: String,
    display_name: String,
    result: WorkerSpawnResult,
    assignment: Option<&WorkerTicketAssignmentRequest>,
) -> ApiResult<BrowserCreateWorkerResponse> {
    if result.state != InternalWorkerOperationState::Accepted {
        return Err(worker_create_not_accepted_error(
            requested_runtime_id.clone(),
            result.diagnostics,
        ));
    }
    let worker = result.worker.ok_or_else(|| Error::RuntimeOperationFailed {
        runtime_id: requested_runtime_id,
        code: "workspace_worker_create_missing_summary".to_string(),
        message: "Runtime completed worker creation without returning a Worker summary".to_string(),
    })?;
    browser_worker_response_from_summary(api, worker, display_name, result.diagnostics, assignment)
}

fn browser_worker_response_from_summary(
    api: &WorkspaceApi,
    worker: InternalWorkerSummary,
    display_name: String,
    diagnostics: Vec<RuntimeDiagnostic>,
    assignment: Option<&WorkerTicketAssignmentRequest>,
) -> ApiResult<BrowserCreateWorkerResponse> {
    let worker_record = match record_worker_summary(
        api,
        &worker,
        display_name.as_str(),
        worker.profile.clone(),
        WorkerRegistryDisplayNamePolicy::UseProvided,
    ) {
        Ok(record) => record,
        Err(error) => return Err(error.into()),
    };
    let compensation = WorkerSpawnCompensationContext {
        assignment,
        spawned_workdir_ids: &[],
    };
    if let Some(assignment) = assignment {
        if let Err(error) = api.store.bind_ticket_assignment_operation_worker(
            &api.config.workspace_id,
            &assignment.operation_id,
            &worker.worker.worker_id,
        ) {
            return finalize_worker_spawn_stage(
                api,
                &worker,
                &compensation,
                WorkerSpawnFinalizeStage::TicketAssignmentBind,
                Err(error.into()),
            );
        }
        if let Err(error) = assign_ticket_worker_from_lifecycle(
            api,
            assignment,
            &worker.worker.runtime_id,
            &worker.worker.worker_id,
        ) {
            return finalize_worker_spawn_stage(
                api,
                &worker,
                &compensation,
                WorkerSpawnFinalizeStage::TicketAssignmentBind,
                Err(error.into()),
            );
        }
    }
    finalize_spawned_worker_workdir_attachments(api, &worker, &worker_record, &compensation)?;
    if let Some(assignment) = assignment {
        finalize_worker_spawn_stage(
            api,
            &worker,
            &compensation,
            WorkerSpawnFinalizeStage::TicketStateAccept,
            accept_queued_ticket_after_worker_spawn(api, assignment).map_err(ApiError::from),
        )?;
    }
    browser_worker_response_for_committed_summary(api, worker, display_name, diagnostics)
}

fn browser_worker_response_for_committed_summary(
    api: &WorkspaceApi,
    worker: InternalWorkerSummary,
    _display_name: String,
    diagnostics: Vec<RuntimeDiagnostic>,
) -> ApiResult<BrowserCreateWorkerResponse> {
    let runtime_id = worker.worker.runtime_id.clone();
    let worker_id = worker.worker.worker_id.clone();
    let workspace_id = api.workspace_id().to_string();
    let resource_key = api
        .store
        .worker_resource_key(&workspace_id, &worker.worker)?
        .ok_or_else(|| {
            Error::Store(format!(
                "Workspace Worker `{worker_id}` has no resource key after registration"
            ))
        })?;
    let worker = worker_launch_worker_summary(worker);
    let console_href = browser_worker_console_href(&workspace_id, &resource_key);
    Ok(BrowserCreateWorkerResponse {
        workspace_id,
        runtime_id,
        worker_id,
        console_href,
        worker,
        diagnostics: diagnostics
            .into_iter()
            .map(server_api::Diagnostic::from)
            .collect(),
    })
}

fn finalize_spawned_worker_workdir_attachments(
    api: &WorkspaceApi,
    worker: &InternalWorkerSummary,
    worker_record: &WorkerRegistryRecord,
    compensation: &WorkerSpawnCompensationContext<'_>,
) -> ApiResult<()> {
    let existing_links = finalize_worker_spawn_stage(
        api,
        worker,
        compensation,
        WorkerSpawnFinalizeStage::WorkdirAttachment,
        api.store
            .list_worker_workdir_links(&api.config.workspace_id, &worker_record.worker)
            .map_err(ApiError::from),
    )?;
    for attachment in &worker.workdir_attachments {
        let summary = &attachment.working_directory.summary;
        let mut workdir_record =
            workdir_record_from_summary(api, worker.worker.runtime_id.as_str(), summary);
        let previous_record = finalize_worker_spawn_stage(
            api,
            worker,
            compensation,
            WorkerSpawnFinalizeStage::WorkdirRegistry,
            api.store
                .get_workdir_registry(&api.config.workspace_id, &summary.working_directory_id)
                .map_err(ApiError::from),
        )?;
        if previous_record.as_ref().is_some_and(|record| {
            matches!(record.source, WorkdirRegistrySource::ExternalGrant { .. })
        }) {
            // External Workdir identity and lifecycle are Backend/provider-owned;
            // a Runtime attachment projection must not rewrite it as a
            // Runtime repository materialization.
            workdir_record = previous_record
                .clone()
                .expect("External source was checked above");
        } else {
            preserve_workdir_identity_for_corrupted_summary(
                &mut workdir_record,
                previous_record.as_ref(),
            );
        }
        finalize_worker_spawn_stage(
            api,
            worker,
            compensation,
            WorkerSpawnFinalizeStage::WorkdirRegistry,
            api.store
                .upsert_workdir_registry(&workdir_record)
                .map_err(ApiError::from),
        )?;
        if !existing_links.iter().any(|link| {
            link.unlinked_at.is_none()
                && link.alias == attachment.alias.as_str()
                && link.workdir_id == summary.working_directory_id
        }) {
            finalize_worker_spawn_stage(
                api,
                worker,
                compensation,
                WorkerSpawnFinalizeStage::WorkdirAttachment,
                link_worker_to_workdir(
                    api,
                    worker_record,
                    attachment.alias.as_str(),
                    &summary.working_directory_id,
                    workdir_source_capabilities(api, &workdir_record)?,
                    None,
                ),
            )?;
        }
    }
    Ok(())
}

fn backend_resource_request_from_api(
    request: server_api::RuntimeResourceFetchRequest,
) -> BackendResourceFetchRequest {
    let handle = request.handle;
    BackendResourceFetchRequest {
        handle: worker_runtime::resource::BackendResourceHandle {
            kind: match handle.kind {
                server_api::RuntimeResourceKind::ProfileSourceArchive => {
                    worker_runtime::resource::BackendResourceKind::ProfileSourceArchive
                }
                server_api::RuntimeResourceKind::RepositorySshAccess => {
                    worker_runtime::resource::BackendResourceKind::RepositorySshAccess
                }
            },
            workspace_id: handle.workspace_id,
            scope_id: handle.scope_id,
            runtime_id: handle.runtime_id,
            worker_id: handle.worker_id,
            resource_id: handle.resource_id,
            digest: handle.digest,
            operation: match handle.operation {
                server_api::RuntimeResourceOperation::FetchArchive => {
                    worker_runtime::resource::BackendResourceOperation::FetchArchive
                }
                server_api::RuntimeResourceOperation::FetchOnce => {
                    worker_runtime::resource::BackendResourceOperation::FetchOnce
                }
            },
            expires_at_unix_seconds: handle.expires_at_unix_seconds,
            nonce: handle.nonce,
            max_bytes: handle.max_bytes,
            content_type: handle.content_type,
            redaction: match handle.redaction {
                server_api::RuntimeResourceRedactionPolicy::RuntimeInternalOnly => {
                    worker_runtime::resource::ResourceRedactionPolicy::RuntimeInternalOnly
                }
            },
            audit_correlation_id: handle.audit_correlation_id,
            profile_source_graph: handle.profile_source_graph.map(|graph| {
                worker_runtime::profile_archive::ProfileSourceGraphSummary {
                    source_count: graph.source_count,
                    total_source_bytes: graph.total_source_bytes,
                    entrypoints: graph.entrypoints,
                    import_count: graph.import_count,
                }
            }),
        },
        runtime_id: request.runtime_id,
        worker_id: request.worker_id,
        audit_correlation_id: request.audit_correlation_id,
    }
}

fn runtime_resource_error_to_api(
    error: worker_runtime::resource::BackendResourceError,
) -> server_api::RuntimeResourceFetchApiError {
    match error {
        worker_runtime::resource::BackendResourceError::Expired => {
            server_api::RuntimeResourceFetchApiError::Expired
        }
        worker_runtime::resource::BackendResourceError::Unauthorized { message } => {
            server_api::RuntimeResourceFetchApiError::Unauthorized { message }
        }
        worker_runtime::resource::BackendResourceError::UnsupportedKind => {
            server_api::RuntimeResourceFetchApiError::UnsupportedKind
        }
        worker_runtime::resource::BackendResourceError::MissingResource => {
            server_api::RuntimeResourceFetchApiError::MissingResource
        }
        worker_runtime::resource::BackendResourceError::DigestMismatch { expected, actual } => {
            server_api::RuntimeResourceFetchApiError::DigestMismatch { expected, actual }
        }
        worker_runtime::resource::BackendResourceError::Oversized {
            max_bytes,
            actual_bytes,
        } => server_api::RuntimeResourceFetchApiError::Oversized {
            max_bytes,
            actual_bytes,
        },
        worker_runtime::resource::BackendResourceError::ContentTypeMismatch {
            expected,
            actual,
        } => server_api::RuntimeResourceFetchApiError::ContentTypeMismatch { expected, actual },
        worker_runtime::resource::BackendResourceError::Timeout => {
            server_api::RuntimeResourceFetchApiError::Timeout
        }
        worker_runtime::resource::BackendResourceError::Transport { message } => {
            server_api::RuntimeResourceFetchApiError::Transport { message }
        }
        worker_runtime::resource::BackendResourceError::InvalidResponse { message } => {
            server_api::RuntimeResourceFetchApiError::InvalidResponse { message }
        }
    }
}

fn runtime_resource_response_to_api(
    mut response: worker_runtime::resource::BackendResourceFetchResponse,
) -> server_api::RuntimeResourceFetchResponse {
    server_api::RuntimeResourceFetchResponse {
        kind: match response.kind {
            worker_runtime::resource::BackendResourceKind::ProfileSourceArchive => {
                server_api::RuntimeResourceKind::ProfileSourceArchive
            }
            worker_runtime::resource::BackendResourceKind::RepositorySshAccess => {
                server_api::RuntimeResourceKind::RepositorySshAccess
            }
        },
        resource_id: response.resource_id.clone(),
        digest: response.digest.clone(),
        content_type: response.content_type.clone(),
        bytes: std::mem::take(&mut response.bytes),
        audit_correlation_id: response.audit_correlation_id.clone(),
    }
}

async fn runtime_resource_fetch_contract(
    api: &WorkspaceApi,
    context: server_api::ServerRequestContext,
    workspace_id: String,
    request: server_api::RuntimeResourceFetchRequest,
) -> std::result::Result<
    server_api::RuntimeResourceFetchResponse,
    server_api::RuntimeResourceFetchApiError,
> {
    if workspace_id != api.workspace_id() {
        return Err(server_api::RuntimeResourceFetchApiError::MissingResource);
    }
    let source = if let Some(source) = context.runtime_source {
        source
    } else {
        let proof = context
            .transport_headers
            .iter()
            .find(|(name, _)| {
                name.eq_ignore_ascii_case(worker_runtime::auth::RUNTIME_REQUEST_SOURCE_PROOF_HEADER)
            })
            .and_then(|(_, value)| std::str::from_utf8(value).ok())
            .filter(|value| !value.trim().is_empty())
            .ok_or_else(|| server_api::RuntimeResourceFetchApiError::Unauthorized {
                message: "Runtime request proof is required".to_owned(),
            })?;
        let body = serde_json::to_vec(&request).map_err(|error| {
            server_api::RuntimeResourceFetchApiError::InvalidResponse {
                message: error.to_string(),
            }
        })?;
        let path = format!("/api/runtime/v1/workspaces/{workspace_id}/resources/fetch");
        let source = crate::worker_source::verify_runtime_request_source_proof(
            api,
            proof,
            &workspace_id,
            worker_runtime::auth::BACKEND_RESOURCE_FETCH_PERMISSION,
            "POST",
            &path,
            &worker_runtime::auth::request_body_digest(&body),
        )
        .await
        .map_err(|_| server_api::RuntimeResourceFetchApiError::Unauthorized {
            message: "Runtime request proof is invalid".to_owned(),
        })?;
        server_api::ServerRuntimeSource {
            authentication_binding_id: source.authentication_binding_id,
            runtime_id: source.runtime_id,
            worker_id: source.worker_id,
        }
    };
    if source.worker_id.is_some() {
        return Err(server_api::RuntimeResourceFetchApiError::Unauthorized {
            message: "Worker-scoped proof cannot fetch Runtime resources".to_owned(),
        });
    }
    if request.runtime_id != source.runtime_id {
        return Err(server_api::RuntimeResourceFetchApiError::Unauthorized {
            message: "Runtime request proof subject does not match the request".to_owned(),
        });
    }
    let request = backend_resource_request_from_api(request);
    let response = api
        .resource_broker
        .fetch_resource(request)
        .map_err(runtime_resource_error_to_api)?;
    Ok(runtime_resource_response_to_api(response))
}

#[cfg(test)]
fn backend_resource_error_status(error: &BackendResourceError) -> StatusCode {
    match error {
        BackendResourceError::Expired => StatusCode::GONE,
        BackendResourceError::Unauthorized { .. } => StatusCode::UNAUTHORIZED,
        BackendResourceError::MissingResource => StatusCode::NOT_FOUND,
        BackendResourceError::UnsupportedKind
        | BackendResourceError::DigestMismatch { .. }
        | BackendResourceError::Oversized { .. }
        | BackendResourceError::ContentTypeMismatch { .. }
        | BackendResourceError::InvalidResponse { .. } => StatusCode::BAD_REQUEST,
        BackendResourceError::Timeout => StatusCode::GATEWAY_TIMEOUT,
        BackendResourceError::Transport { .. } => StatusCode::BAD_GATEWAY,
    }
}

