fn authenticated_browser_input_source(actor: &RequestActor) -> protocol::AuthenticatedInputSource {
    protocol::AuthenticatedInputSource::Account {
        account_id: actor.account_id.clone(),
    }
}

pub(crate) fn authorize_browser_worker_method(
    method: protocol::Method,
    source: &protocol::AuthenticatedInputSource,
) -> std::result::Result<protocol::Method, &'static str> {
    match method {
        protocol::Method::Submit {
            submission_request_id,
            input,
        } => Ok(protocol::Method::SubmitTracked {
            submission_request_id,
            input,
            source: source.clone(),
        }),
        protocol::Method::Notify {
            notification_request_id,
            message,
        } => Ok(protocol::Method::NotifyTracked {
            notification_request_id,
            message,
            source: source.clone(),
        }),
        protocol::Method::SubmitTracked { .. }
        | protocol::Method::SubmitIfIdle { .. }
        | protocol::Method::NotifyTracked { .. }
        | protocol::Method::WorkerEvent(_) => {
            Err("authenticated Worker input source is server-owned")
        }
        other @ (protocol::Method::ListPendingSubmissions
        | protocol::Method::CancelPendingSubmission { .. }
        | protocol::Method::ClearPendingSubmissions { .. }
        | protocol::Method::ContinuePending { .. }
        | protocol::Method::Resume { .. }
        | protocol::Method::Cancel { .. }
        | protocol::Method::Pause { .. }
        | protocol::Method::Compact { .. }
        | protocol::Method::RewindTo { .. }
        | protocol::Method::Shutdown { .. }
        | protocol::Method::ListCompletions { .. }
        | protocol::Method::ListWorkers
        | protocol::Method::RestoreWorker { .. }
        | protocol::Method::RegisterPeer { .. }) => Ok(other),
    }
}

async fn worker_protocol_ws(
    State(api): State<WorkspaceApi>,
    Extension(actor): Extension<RequestActor>,
    AxumPath((runtime_id, worker_id)): AxumPath<(String, String)>,
    headers: HeaderMap,
    ws: WebSocketUpgrade,
) -> Response {
    let worker = match WorkspaceWorker::resolve_async(&api, &runtime_id, &worker_id).await {
        Ok(worker) => worker,
        Err(error) => return ApiError::from(error).into_response(),
    };
    let context = WorkerOperationContext::Browser {
        headers,
        source: authenticated_browser_input_source(&actor),
    };
    ws.on_upgrade(move |mut socket| async move {
        match worker.connect_protocol(&context).await {
            Ok(connection) => workspace_worker_protocol_session(connection, socket, context).await,
            Err(error) => {
                let _ = tokio::time::timeout(WORKER_PROTOCOL_TRANSPORT_TIMEOUT, async {
                    let _ =
                        send_protocol_event(&mut socket, &protocol_error_event(error.to_string()))
                            .await;
                    let _ = socket.send(WsMessage::Close(None)).await;
                })
                .await;
            }
        }
    })
    .into_response()
}

pub(crate) async fn connect_workspace_worker_protocol(
    api: &WorkspaceApi,
    worker: &RuntimeWorkerRef,
    input_source: Option<&protocol::AuthenticatedInputSource>,
) -> Result<WorkspaceWorkerProtocolConnection> {
    let source = workspace_worker_protocol_source(api, worker).await?;
    match source {
        RuntimeObservationSource::RemoteWs(config) => {
            connect_remote_worker_protocol(config, input_source).await
        }
        RuntimeObservationSource::Embedded(source) => {
            let scope =
                worker_runtime::RuntimeWorkspaceScope::new(api.workspace_id(), "embedded-backend");
            connect_embedded_worker_protocol(source, scope, api.host_executors.host()?).await
        }
    }
}

// Cold source discovery includes live authority/signing reads. Keep the whole
// synchronous callback on its admitted DB owner, not the Tokio WS task.
async fn workspace_worker_protocol_source(
    api: &WorkspaceApi,
    worker: &RuntimeWorkerRef,
) -> Result<RuntimeObservationSource> {
    let source = match api.observation_proxy.source(worker) {
        Ok(source) => source,
        Err(ObservationProxyError::WorkerNotFound(_)) => {
            let runtime = api.runtime.clone();
            let worker = worker.clone();
            api.store
                .db_executor()
                .run(move || {
                    runtime
                        .observation_source(&worker)
                        .map_err(|error| error.into_error())
                })
                .await?
        }
        Err(error) => {
            return Err(Error::RuntimeOperationFailed {
                runtime_id: worker.runtime_id.clone(),
                code: error.code().to_string(),
                message: error.message().to_string(),
            });
        }
    };
    Ok(source)
}

fn insert_authenticated_input_source_header(
    headers: &mut HeaderMap,
    input_source: Option<&protocol::AuthenticatedInputSource>,
) -> Result<()> {
    let Some(input_source) = input_source else {
        return Ok(());
    };
    let protocol::AuthenticatedInputSource::Account { account_id } = input_source else {
        return Err(Error::Config(
            "remote Worker protocol transport supports only Account input source".into(),
        ));
    };
    headers.insert(
        protocol::AUTHENTICATED_ACCOUNT_ID_HEADER,
        account_id.parse().map_err(|error| {
            Error::Config(format!("invalid authenticated Account identity: {error}"))
        })?,
    );
    Ok(())
}

async fn connect_remote_worker_protocol(
    config: RuntimeObservationSourceConfig,
    input_source: Option<&protocol::AuthenticatedInputSource>,
) -> Result<WorkspaceWorkerProtocolConnection> {
    let mut request = config
        .endpoint
        .clone()
        .into_client_request()
        .map_err(|error| Error::Config(format!("invalid Runtime protocol endpoint: {error}")))?;
    if let Some(token) = &config.bearer_token {
        request.headers_mut().insert(
            "authorization",
            format!("Bearer {token}").parse().map_err(|error| {
                Error::Config(format!("invalid Runtime authorization: {error}"))
            })?,
        );
    }
    insert_authenticated_input_source_header(request.headers_mut(), input_source)?;
    let (socket, _) =
        tokio::time::timeout(WORKER_PROTOCOL_TRANSPORT_TIMEOUT, connect_async(request))
            .await
            .map_err(|_| Error::RuntimeOperationFailed {
                runtime_id: config.worker.runtime_id.clone(),
                code: "worker_protocol_connect_timeout".into(),
                message: "Worker protocol connection handshake timed out; no method was admitted"
                    .into(),
            })?
            .map_err(|error| Error::RuntimeOperationFailed {
                runtime_id: config.worker.runtime_id.clone(),
                code: "worker_protocol_connect_failed".into(),
                message: error.to_string(),
            })?;
    let (sink, stream) = socket.split();
    Ok(remote_worker_protocol_bridge(sink, stream))
}

async fn connect_embedded_worker_protocol(
    source: crate::observation::EmbeddedRuntimeObservationSource,
    scope: worker_runtime::RuntimeWorkspaceScope,
    executor: crate::db_executor::DbExecutor,
) -> Result<WorkspaceWorkerProtocolConnection> {
    // Endpoint capture takes Runtime operation/state locks. Keep it, and each
    // intact method (including fs-store commit/publication), off Tokio and the
    // sole DB lane. A discarded reply retains the endpoint until cleanup.
    let capture_source = source.clone();
    let capture_scope = scope.clone();
    let mut transport = executor
        .run(move || {
            capture_source
                .runtime
                .attach_worker_protocol_scoped(&capture_scope, &capture_source.worker_ref)
                .map_err(|error| Error::RuntimeOperationFailed {
                    runtime_id: capture_source.worker.runtime_id.clone(),
                    code: "embedded_worker_protocol_connect_failed".to_string(),
                    message: error.to_string(),
                })
        })
        .await?;
    Ok(spawn_worker_protocol_pump(
        move |mut methods, events| async move {
            if let Err(reason) = enqueue_worker_protocol_event(&events, transport.snapshot.clone())
            {
                return reason;
            }
            loop {
                tokio::select! {
                    method = methods.recv() => {
                        let Some(method) = method else { return WorkerProtocolEnd::Disconnected; };
                        let shutdown = matches!(&method, protocol::Method::Shutdown { .. });
                        let method_source = source.clone();
                        let method_scope = scope.clone();
                        let owned = executor.run(move || {
                            let result = method_source.runtime.send_connected_protocol_method_scoped(
                                &method_scope, &method_source.worker_ref, &transport, method,
                            );
                            // Endpoint validation is synchronous too.
                            let terminal = result.as_ref().err().is_some_and(|error|
                                embedded_protocol_dispatch_is_terminal(error, &transport));
                            Ok::<_, Error>((transport, result, terminal))
                        }).await;
                        let (returned, result, terminal) = match owned {
                            Ok(value) => value,
                            Err(error) => {
                                let _ = enqueue_worker_protocol_event(&events, protocol_error_event(error.to_string()));
                                return WorkerProtocolEnd::Disconnected;
                            }
                        };
                        transport = returned;
                        match result {
                            Ok(direct_events) => {
                                for event in direct_events {
                                    let terminal = matches!(event, protocol::Event::Shutdown);
                                    if let Err(reason) = enqueue_worker_protocol_event(&events, event) { return reason; }
                                    if terminal { return WorkerProtocolEnd::Disconnected; }
                                }
                            }
                            Err(error) => {
                                if let Err(reason) = enqueue_worker_protocol_event(&events, protocol_error_event(error.to_string())) { return reason; }
                                if terminal { return WorkerProtocolEnd::Disconnected; }
                            }
                        }
                        if shutdown { return WorkerProtocolEnd::Disconnected; }
                    }
                    event = transport.events.recv() => match event {
                        Some(event) => {
                            let terminal = matches!(event, protocol::Event::Shutdown);
                            if let Err(reason) = enqueue_worker_protocol_event(&events, event) { return reason; }
                            if terminal { return WorkerProtocolEnd::Disconnected; }
                        }
                        None => return WorkerProtocolEnd::Disconnected,
                    }
                }
            }
        },
    ))
}

fn embedded_protocol_dispatch_is_terminal(
    error: &worker_runtime::error::RuntimeError,
    transport: &worker_runtime::execution::WorkerProtocolTransport,
) -> bool {
    // A settled, side-effect-free method rejection can leave the connection
    // usable. Uncertain lifecycle/store/transport errors cannot.
    !matches!(
        error,
        worker_runtime::error::RuntimeError::WorkerExecutionRejected {
            outcome: worker_runtime::execution::WorkerExecutionOutcome::Busy
                | worker_runtime::execution::WorkerExecutionOutcome::Rejected
                | worker_runtime::execution::WorkerExecutionOutcome::Unsupported,
            ..
        }
    ) || transport.validate().is_err()
}

#[cfg(test)]
async fn worker_protocol_ws_session(
    source: RuntimeObservationSource,
    socket: WebSocket,
    input_source: protocol::AuthenticatedInputSource,
    read_only: bool,
    scope: worker_runtime::RuntimeWorkspaceScope,
) {
    match source {
        RuntimeObservationSource::RemoteWs(config) => {
            remote_worker_protocol_ws_session(config, socket, input_source, read_only).await;
        }
        RuntimeObservationSource::Embedded(source) => {
            embedded_worker_protocol_ws_session(source, socket, input_source, read_only, scope)
                .await;
        }
    }
}

#[cfg(test)]
async fn remote_worker_protocol_ws_session(
    config: RuntimeObservationSourceConfig,
    socket: WebSocket,
    input_source: protocol::AuthenticatedInputSource,
    read_only: bool,
) {
    let mut request = match config.endpoint.clone().into_client_request() {
        Ok(request) => request,
        Err(error) => {
            let mut socket = socket;
            let event = protocol_error_event(format!(
                "failed to build runtime protocol WebSocket request: {error}"
            ));
            let _ = send_protocol_event(&mut socket, &event).await;
            return;
        }
    };
    if let Some(token) = &config.bearer_token {
        match format!("Bearer {token}").parse() {
            Ok(value) => {
                request.headers_mut().insert("authorization", value);
            }
            Err(error) => {
                let mut socket = socket;
                let event = protocol_error_event(format!(
                    "failed to build runtime authorization header: {error}"
                ));
                let _ = send_protocol_event(&mut socket, &event).await;
                return;
            }
        }
    }
    if let Err(error) =
        insert_authenticated_input_source_header(request.headers_mut(), Some(&input_source))
    {
        let mut socket = socket;
        let event = protocol_error_event(format!(
            "failed to build authenticated Account identity header: {error}"
        ));
        let _ = send_protocol_event(&mut socket, &event).await;
        return;
    }

    let (upstream, _) = match connect_async(request).await {
        Ok(connection) => connection,
        Err(error) => {
            let mut socket = socket;
            let event = protocol_error_event(format!(
                "failed to connect runtime protocol WebSocket: {error}"
            ));
            let _ = send_protocol_event(&mut socket, &event).await;
            return;
        }
    };

    let (mut client_sink, mut client_stream) = socket.split();
    let (mut upstream_sink, mut upstream_stream) = upstream.split();

    loop {
        tokio::select! {
            inbound = client_stream.next() => {
                match inbound {
                    Some(Ok(WsMessage::Text(text))) => {
                        if read_only {
                            if let Ok(event) = protocol::stream::encode_event(&protocol_error_event(
                                "Backend Job Worker Console is read-only",
                            )) {
                                let _ = client_sink.send(WsMessage::Text(event.into())).await;
                            }
                            continue;
                        }
                        let method = match protocol::stream::decode_method(text.as_ref()) {
                            Ok(method) => match authorize_browser_worker_method(method, &input_source) {
                                Ok(method) => method,
                                Err(message) => {
                                    if let Ok(event) = protocol::stream::encode_event(&protocol_error_event(message)) {
                                        let _ = client_sink.send(WsMessage::Text(event.into())).await;
                                    }
                                    break;
                                }
                            },
                            Err(error) => {
                                if let Ok(event) = protocol::stream::encode_event(&protocol_error_event(error.to_string())) {
                                    let _ = client_sink.send(WsMessage::Text(event.into())).await;
                                }
                                break;
                            }
                        };
                        let Ok(method) = protocol::stream::encode_method(&method) else { break };
                        if upstream_sink.send(TungsteniteMessage::Text(method.into())).await.is_err() {
                            break;
                        }
                    }
                    Some(Ok(WsMessage::Binary(_))) => {
                        if let Ok(event) = protocol::stream::encode_event(&protocol_error_event("binary Worker methods are not accepted")) {
                            let _ = client_sink.send(WsMessage::Text(event.into())).await;
                        }
                        break;
                    }
                    Some(Ok(WsMessage::Close(_))) | None => {
                        let _ = upstream_sink.send(TungsteniteMessage::Close(None)).await;
                        break;
                    }
                    Some(Ok(WsMessage::Ping(payload))) => {
                        if upstream_sink.send(TungsteniteMessage::Ping(payload.to_vec().into())).await.is_err() {
                            break;
                        }
                    }
                    Some(Ok(WsMessage::Pong(payload))) => {
                        if upstream_sink.send(TungsteniteMessage::Pong(payload.to_vec().into())).await.is_err() {
                            break;
                        }
                    }
                    Some(Err(_)) => break,
                }
            }
            outbound = upstream_stream.next() => {
                match outbound {
                    Some(Ok(TungsteniteMessage::Text(text))) => {
                        if client_sink.send(WsMessage::Text(text.to_string().into())).await.is_err() {
                            break;
                        }
                    }
                    Some(Ok(TungsteniteMessage::Binary(binary))) => {
                        if client_sink.send(WsMessage::Binary(binary.to_vec().into())).await.is_err() {
                            break;
                        }
                    }
                    Some(Ok(TungsteniteMessage::Close(_))) | None => {
                        let _ = client_sink.send(WsMessage::Close(None)).await;
                        break;
                    }
                    Some(Ok(TungsteniteMessage::Ping(payload))) => {
                        if client_sink.send(WsMessage::Ping(payload.to_vec().into())).await.is_err() {
                            break;
                        }
                    }
                    Some(Ok(TungsteniteMessage::Pong(payload))) => {
                        if client_sink.send(WsMessage::Pong(payload.to_vec().into())).await.is_err() {
                            break;
                        }
                    }
                    Some(Ok(TungsteniteMessage::Frame(_))) => {}
                    Some(Err(_)) => break,
                }
            }
        }
    }
}

#[cfg(test)]
async fn embedded_worker_protocol_ws_session(
    source: crate::observation::EmbeddedRuntimeObservationSource,
    mut socket: WebSocket,
    input_source: protocol::AuthenticatedInputSource,
    read_only: bool,
    scope: worker_runtime::RuntimeWorkspaceScope,
) {
    let mut transport = match source
        .runtime
        .attach_worker_protocol_scoped(&scope, &source.worker_ref)
    {
        Ok(transport) => transport,
        Err(error) => {
            let event = protocol_error_event(error.to_string());
            let _ = send_protocol_event(&mut socket, &event).await;
            let _ = socket.send(WsMessage::Close(None)).await;
            return;
        }
    };
    if !send_protocol_event(&mut socket, &transport.snapshot).await {
        return;
    }

    loop {
        tokio::select! {
            inbound = socket.next() => {
                match inbound {
                    Some(Ok(WsMessage::Text(_))) if read_only => {
                        let event = protocol_error_event("Backend Job Worker Console is read-only");
                        if !send_protocol_event(&mut socket, &event).await {
                            return;
                        }
                    }
                    Some(Ok(WsMessage::Text(text))) => match decode_method(&text) {
                        Ok(method) => match authorize_browser_worker_method(method, &input_source) {
                            Ok(method) => {
                                let shutdown = matches!(&method, protocol::Method::Shutdown { .. });
                                match source.runtime.send_connected_protocol_method_scoped(
                                    &scope, &source.worker_ref, &transport, method,
                                ) {
                                    Ok(events) => {
                                        for event in events {
                                            let terminal = matches!(event, protocol::Event::Shutdown);
                                            if !send_protocol_event(&mut socket, &event).await {
                                                return;
                                            }
                                            if terminal {
                                                let _ = socket.send(WsMessage::Close(None)).await;
                                                return;
                                            }
                                        }
                                    }
                                    Err(error) => {
                                        let terminal = embedded_protocol_dispatch_is_terminal(&error, &transport);
                                        let event = protocol_error_event(error.to_string());
                                        if !send_protocol_event(&mut socket, &event).await {
                                            return;
                                        }
                                        if terminal {
                                            let _ = socket.send(WsMessage::Close(None)).await;
                                            return;
                                        }
                                    }
                                }
                                if shutdown {
                                    let _ = socket.send(WsMessage::Close(None)).await;
                                    return;
                                }
                            },
                            Err(message) => {
                                let event = protocol_error_event(message);
                                let _ = send_protocol_event(&mut socket, &event).await;
                                let _ = socket.send(WsMessage::Close(None)).await;
                                return;
                            }
                        },
                        Err(error) => {
                            let event = protocol_error_event(format!(
                                "malformed protocol method frame: {error}"
                            ));
                            if !send_protocol_event(&mut socket, &event).await {
                                return;
                            }
                        }
                    },
                    Some(Ok(WsMessage::Close(_))) | None => return,
                    Some(Ok(WsMessage::Ping(payload))) => {
                        if socket.send(WsMessage::Pong(payload)).await.is_err() {
                            return;
                        }
                    }
                    Some(Ok(WsMessage::Pong(_))) | Some(Ok(WsMessage::Binary(_))) => {}
                    Some(Err(error)) => {
                        let event = protocol_error_event(format!("protocol WebSocket error: {error}"));
                        let _ = send_protocol_event(&mut socket, &event).await;
                        return;
                    }
                }
            }
            upstream_event = transport.events.recv() => {
                match upstream_event {
                    Some(event) => {
                        let terminal = matches!(event, protocol::Event::Shutdown);
                        if !send_protocol_event(&mut socket, &event).await {
                            return;
                        }
                        if terminal {
                            let _ = socket.send(WsMessage::Close(None)).await;
                            return;
                        }
                    }
                    // Stop/disconnect/lag closes the execution-owned relay.
                    // Never follow the WorkerRef to a restored Controller.
                    None => {
                        let _ = socket.send(WsMessage::Close(None)).await;
                        return;
                    }
                }
            }
        }
    }
}
async fn send_protocol_event(socket: &mut WebSocket, event: &protocol::Event) -> bool {
    match encode_event(event) {
        Ok(text) => socket.send(WsMessage::Text(text.into())).await.is_ok(),
        Err(error) => {
            let fallback = protocol_error_event(format!(
                "failed to serialize protocol response event: {error}"
            ));
            let Ok(text) = encode_event(&fallback) else {
                return false;
            };
            socket.send(WsMessage::Text(text.into())).await.is_ok()
        }
    }
}

fn protocol_error_event(message: impl Into<String>) -> protocol::Event {
    protocol::Event::Error {
        code: protocol::ErrorCode::Internal,
        message: message.into(),
    }
}

async fn list_host_workers(
    State(api): State<WorkspaceApi>,
    AxumPath(host_id): AxumPath<String>,
) -> ApiResult<Json<server_api::HostWorkerListResponse>> {
    api.host_executors
        .host()?
        .run(move || {
            let limit = api.config.max_records.min(200);
            let runtime_workers = api
                .runtime
                .list_workers_for_host(&host_id, limit)
                .map_err(|err| err.into_error())?;
            let items = project_observed_workspace_workers(&api, runtime_workers.items)?;
            Ok(Json(server_api::HostWorkerListResponse {
                workspace_id: api.workspace_id().to_string(),
                limit,
                items,
                source: "worker_runtime_registry".to_string(),
                diagnostics: runtime_workers
                    .diagnostics
                    .into_iter()
                    .map(Into::into)
                    .collect(),
            }))
        })
        .await
}

fn project_workspace_worker_with_attachments(
    api: &WorkspaceApi,
    mut summary: InternalWorkerSummary,
    workdir_attachments: Vec<server_api::WorkerWorkdirAttachmentSummary>,
) -> ApiResult<server_api::WorkerSummary> {
    match api
        .store
        .require_current_worker_singleton_owner(&api.config.workspace_id, &summary.worker)
    {
        Ok(lease) => summary.singleton_key = lease.map(|lease| lease.key),
        Err(Error::RepositoryConflict(message))
            if message.starts_with("worker_singleton_fenced:") =>
        {
            summary.singleton_key = None;
            summary.availability =
                protocol::subscription::SubscriptionWorkerAvailability::Unavailable;
            summary.state = "unavailable".to_string();
            summary.worker_state = None;
            summary.diagnostics.push(RuntimeDiagnostic {
                code: "worker_singleton_fenced".to_string(),
                severity: HostDiagnosticSeverity::Warning,
                message: "This historical singleton generation is fenced by Backend ownership."
                    .to_string(),
            });
        }
        Err(error) => return Err(error.into()),
    }
    let resource_key = api
        .store
        .worker_resource_key(&api.config.workspace_id, &summary.worker)?
        .ok_or_else(|| {
            Error::Store(format!(
                "Workspace Worker `{}` has no resource key",
                summary.worker.worker_id
            ))
        })?;
    Ok(workspace_worker_summary(
        summary,
        resource_key,
        workdir_attachments,
    ))
}

fn project_observed_workspace_workers(
    api: &WorkspaceApi,
    workers: Vec<InternalWorkerSummary>,
) -> ApiResult<Vec<server_api::WorkerSummary>> {
    let workdirs = api
        .store
        .list_workdir_registry(&api.config.workspace_id, 500)?;
    workers
        .into_iter()
        .map(|worker| {
            let record = sync_worker_observation(api, &worker)?;
            let links = api
                .store
                .list_worker_workdir_links(&api.config.workspace_id, &record.worker)?;
            project_worker_registry_projection(api, Some(&worker), &record, links, &workdirs)
        })
        .collect()
}

fn workers_response(api: WorkspaceApi) -> ApiResult<server_api::WorkerListResponse> {
    let limit = api.config.max_records.min(200);
    let projections = api
        .store
        .worker_registry_projection_snapshot(&api.config.workspace_id, limit)?;
    let workdir_records = api
        .store
        .list_workdir_registry(&api.config.workspace_id, 500)?;
    let mut items = Vec::new();
    for projection in projections {
        let links = api
            .store
            .list_worker_workdir_links(&api.config.workspace_id, &projection.registry.worker)?;
        let observed = worker_summary_from_projection(&projection);
        items.push(project_worker_registry_projection(
            &api,
            observed.as_ref(),
            &projection.registry,
            links,
            &workdir_records,
        )?);
    }
    Ok(server_api::WorkerListResponse {
        workspace_id: api.config.workspace_id,
        limit,
        items,
        source: "backend_worker_registry_projection".to_string(),
        diagnostics: Vec::new(),
    })
}

async fn workspace_runtime_resources_response(
    api: &WorkspaceApi,
    workspace_id: &str,
) -> ApiResult<server_api::WorkspaceRuntimeListResponse> {
    let api = api.clone();
    let workspace_id = workspace_id.to_owned();
    run_host_workflow(api.host_executors.host()?, async move {
        workspace_runtime_resources_response_on_host(&api, &workspace_id).await
    })
    .await
}

// Already-owned Runtime workflows call this directly; re-admission to Host would
// wait behind the same parents. DB binding helpers still use their own DB owner.
async fn workspace_runtime_resources_response_on_host(
    api: &WorkspaceApi,
    workspace_id: &str,
) -> ApiResult<server_api::WorkspaceRuntimeListResponse> {
    let limit = api.config.max_records.min(200);
    let runtimes = api.runtime.list_runtimes(limit);
    let bindings = api
        .store
        .list_workspace_runtime_bindings(workspace_id, true)
        .await?;
    let mut items = runtimes
        .items
        .into_iter()
        .map(|runtime| {
            let binding = bindings
                .iter()
                .find(|binding| binding.runtime_id == runtime.runtime_id);
            let built_in = runtime.runtime_id == EMBEDDED_WORKER_RUNTIME_ID;
            let mut runtime: server_api::RuntimeSummary = runtime.into();
            if binding.is_some_and(|binding| binding.revoked_at.is_some()) {
                runtime.worker_creation_available = false;
            }
            WorkspaceRuntimeResource {
                runtime,
                management: RuntimeManagementSummary {
                    built_in,
                    config_managed: binding.is_some(),
                    removable: binding.is_some() && !built_in,
                    endpoint_configured: binding
                        .is_some_and(|binding| !binding.base_url.trim().is_empty()),
                    token_ref_configured: false,
                    binding: binding.map(|binding| runtime_binding_summary(binding)),
                },
                http_status: StatusCode::OK.as_u16(),
            }
        })
        .collect::<Vec<_>>();

    for binding in &bindings {
        if items
            .iter()
            .any(|resource| resource.runtime.runtime_id == binding.runtime_id)
        {
            continue;
        }
        items.push(WorkspaceRuntimeResource {
            runtime: server_api::RuntimeSummary {
                runtime_id: binding.runtime_id.clone(),
                label: binding.display_name.clone(),
                kind: "remote_http".to_string(),
                status: "unavailable".to_string(),
                source: server_api::RuntimeSourceSummary {
                    kind: server_api::RuntimeSourceKind::RemoteHttp,
                    status: server_api::RuntimeSourceStatus::Reserved,
                    identity_authority:
                        server_api::RuntimeIdentityAuthority::ServerRuntimeConfiguration,
                    note: "The registered Runtime is not present in the active Runtime registry."
                        .to_string(),
                },
                host_ids: Vec::new(),
                worker_creation_available: false,
                os: String::new(),
                arch: String::new(),
                diagnostics: vec![
                    settings_diagnostic(
                        "registered_runtime_unavailable",
                        HostDiagnosticSeverity::Warning,
                        "The registered Runtime is not present in the active Runtime registry.",
                    )
                    .into(),
                ],
            },
            management: RuntimeManagementSummary {
                built_in: false,
                config_managed: true,
                removable: true,
                endpoint_configured: !binding.base_url.trim().is_empty(),
                token_ref_configured: false,
                binding: Some(runtime_binding_summary(binding)),
            },
            http_status: StatusCode::OK.as_u16(),
        });
    }

    Ok(server_api::WorkspaceRuntimeListResponse {
        workspace_id: workspace_id.to_string(),
        limit,
        items,
        source: "workspace-runtime-bindings".to_string(),
        diagnostics: runtimes.diagnostics.into_iter().map(Into::into).collect(),
    })
}

fn runtime_binding_summary(binding: &WorkspaceRuntimeBinding) -> WorkspaceRuntimeBindingSummary {
    WorkspaceRuntimeBindingSummary {
        binding_id: binding.binding_id.clone(),
        revoked_at: binding.revoked_at.clone(),
    }
}

async fn workspace_runtime_detail(
    api: &WorkspaceApi,
    workspace_id: &str,
    runtime_id: &str,
) -> ApiResult<WorkspaceRuntimeDetail> {
    let api = api.clone();
    let workspace_id = workspace_id.to_owned();
    let runtime_id = runtime_id.to_owned();
    run_host_workflow(api.host_executors.host()?, async move {
        workspace_runtime_detail_on_host(&api, &workspace_id, &runtime_id).await
    })
    .await
}

async fn workspace_runtime_detail_on_host(
    api: &WorkspaceApi,
    workspace_id: &str,
    runtime_id: &str,
) -> ApiResult<WorkspaceRuntimeDetail> {
    let binding = api
        .store
        .get_workspace_runtime_binding(workspace_id, runtime_id)
        .await?;
    let mut resource = workspace_runtime_resources_response_on_host(api, workspace_id)
        .await?
        .items
        .into_iter()
        .find(|resource| resource.runtime.runtime_id == runtime_id);
    if resource.is_none() {
        resource = binding.as_ref().map(|binding| WorkspaceRuntimeResource {
            runtime: server_api::RuntimeSummary {
                runtime_id: binding.runtime_id.clone(),
                label: binding.display_name.clone(),
                kind: "remote_http".to_string(),
                status: "unavailable".to_string(),
                source: server_api::RuntimeSourceSummary {
                    kind: server_api::RuntimeSourceKind::RemoteHttp,
                    status: server_api::RuntimeSourceStatus::Reserved,
                    identity_authority:
                        server_api::RuntimeIdentityAuthority::ServerRuntimeConfiguration,
                    note: "The Runtime trust binding is not active in the Runtime registry."
                        .to_string(),
                },
                host_ids: Vec::new(),
                worker_creation_available: false,
                os: String::new(),
                arch: String::new(),
                diagnostics: Vec::new(),
            },
            management: RuntimeManagementSummary {
                built_in: false,
                config_managed: true,
                removable: false,
                endpoint_configured: !binding.base_url.trim().is_empty(),
                token_ref_configured: false,
                binding: Some(runtime_binding_summary(binding)),
            },
            http_status: StatusCode::OK.as_u16(),
        });
    }
    let mut resource = resource.ok_or_else(|| Error::UnknownRuntime(runtime_id.to_string()))?;
    if let Some(binding) = &binding {
        resource.management.config_managed = true;
        resource.management.endpoint_configured = !binding.base_url.trim().is_empty();
    }
    let endpoint = binding
        .as_ref()
        .map(|binding| binding.base_url.clone())
        .or_else(|| {
            api.config
                .remote_runtime_sources
                .iter()
                .find(|source| {
                    source.runtime_id == runtime_id
                        && source.workspace_id.as_deref() == Some(workspace_id)
                })
                .map(|source| source.base_url.clone())
        });
    let trust_key = binding.as_ref().map_or(
        RuntimeTrustKeyState {
            status: RuntimeTrustKeyStatus::Unconfigured,
            fingerprint: None,
            binding_id: None,
            created_at: None,
            updated_at: None,
            revoked_at: None,
        },
        |binding| RuntimeTrustKeyState {
            status: if binding.revoked_at.is_some() {
                RuntimeTrustKeyStatus::Revoked
            } else {
                RuntimeTrustKeyStatus::Active
            },
            fingerprint: Some(binding.public_key_fingerprint.clone()),
            binding_id: Some(binding.binding_id.clone()),
            created_at: Some(binding.created_at.clone()),
            updated_at: Some(binding.updated_at.clone()),
            revoked_at: binding.revoked_at.clone(),
        },
    );
    let recent_audit = api
        .store
        .list_workspace_runtime_binding_audit(workspace_id, runtime_id, 20)
        .await?
        .into_iter()
        .map(project_runtime_trust_audit)
        .collect::<Result<Vec<_>>>()?;
    Ok(WorkspaceRuntimeDetail {
        workspace_id: workspace_id.to_string(),
        runtime: resource,
        endpoint,
        trust_key,
        recent_audit,
    })
}

fn project_runtime_trust_audit(
    record: WorkspaceRuntimeBindingAuditRecord,
) -> Result<RuntimeTrustAuditEntry> {
    let action = match record.action.as_str() {
        "created" => RuntimeTrustAuditAction::Created,
        "replaced" => RuntimeTrustAuditAction::Replaced,
        "reactivated" => RuntimeTrustAuditAction::Reactivated,
        "revoked" => RuntimeTrustAuditAction::Revoked,
        other => {
            return Err(Error::Store(format!(
                "unsupported Runtime trust audit action {other}"
            )));
        }
    };
    Ok(RuntimeTrustAuditEntry {
        action,
        actor_account_id: record.actor_account_id,
        old_fingerprint: record.old_fingerprint,
        new_fingerprint: record.new_fingerprint,
        binding_id: record.binding_id,
        at: record.at,
    })
}

async fn validate_runtime_connection_request(
    request: &CreateRemoteRuntimeRequest,
) -> ApiResult<Url> {
    validate_public_runtime_id(request.public_bundle.identity_id.trim())?;
    if request.public_bundle.public_key.trim().is_empty() {
        return Err(settings_bad_request(
            "runtime_public_key_required",
            "Runtime public bundle must contain a public key",
        ));
    }
    if request
        .expected_binding_id
        .as_deref()
        .is_some_and(|id| id.trim().is_empty() || id.len() > 256)
    {
        return Err(settings_bad_request(
            "invalid_runtime_binding_id",
            "expected_binding_id must be a bounded binding identity",
        ));
    }
    validate_runtime_metadata(request.display_name.as_deref(), &request.endpoint).await
}

async fn validate_runtime_metadata(display_name: Option<&str>, endpoint: &str) -> ApiResult<Url> {
    let endpoint = Url::parse(endpoint.trim()).map_err(|_| {
        settings_bad_request(
            "invalid_remote_runtime_endpoint",
            "endpoint must be an absolute HTTP or HTTPS URL",
        )
    })?;
    let local_loopback = is_loopback_runtime_origin(endpoint.as_str());
    if endpoint.host_str().is_none()
        || !endpoint.username().is_empty()
        || endpoint.password().is_some()
        || endpoint.query().is_some()
        || endpoint.fragment().is_some()
        || endpoint.path() != "/"
        || (!local_loopback && endpoint.scheme() != "https")
    {
        return Err(settings_bad_request(
            "remote_runtime_endpoint_not_allowed",
            "Runtime endpoint must be a public HTTPS origin or a loopback HTTP origin without credentials, path, query, or fragment",
        ));
    }
    if !local_loopback {
        let host = endpoint.host_str().expect("checked above");
        if host.eq_ignore_ascii_case("localhost")
            || host.ends_with(".localhost")
            || host
                .parse::<IpAddr>()
                .is_ok_and(is_disallowed_remote_runtime_address)
        {
            return Err(settings_bad_request(
                "remote_runtime_endpoint_not_allowed",
                "Runtime endpoint resolves to a loopback, private, link-local, metadata, or otherwise non-public address",
            ));
        }
        let port = endpoint.port_or_known_default().unwrap_or(443);
        let addresses = tokio::time::timeout(
            std::time::Duration::from_secs(3),
            tokio::net::lookup_host((host, port)),
        )
        .await
        .map_err(|_| {
            settings_bad_request(
                "remote_runtime_endpoint_dns_timeout",
                "Runtime endpoint DNS resolution timed out",
            )
        })?
        .map_err(|_| {
            settings_bad_request(
                "remote_runtime_endpoint_dns_failed",
                "Runtime endpoint DNS resolution failed",
            )
        })?
        .collect::<Vec<_>>();
        if addresses.is_empty()
            || addresses
                .iter()
                .any(|address| is_disallowed_remote_runtime_address(address.ip()))
        {
            return Err(settings_bad_request(
                "remote_runtime_endpoint_not_allowed",
                "Runtime endpoint resolves to a loopback, private, link-local, metadata, or otherwise non-public address",
            ));
        }
    }
    if display_name.is_some_and(|value| value.is_empty() || value.chars().any(char::is_control)) {
        return Err(settings_bad_request(
            "invalid_remote_runtime_display_name",
            "display_name must be non-empty when supplied and cannot contain control characters",
        ));
    }
    Ok(endpoint)
}

fn validate_public_runtime_id(runtime_id: &str) -> ApiResult<()> {
    if runtime_id.is_empty() {
        return Err(settings_bad_request(
            "invalid_runtime_id",
            "runtime_id must not be empty",
        ));
    }
    if runtime_id.len() > 96
        || !runtime_id
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_' | '.'))
    {
        return Err(settings_bad_request(
            "invalid_runtime_id",
            "runtime_id may contain only ASCII letters, digits, '-', '_' and '.' and must be at most 96 characters",
        ));
    }
    Ok(())
}

fn remote_runtime_config_from_binding(
    binding: &crate::store::WorkspaceRuntimeBinding,
) -> std::result::Result<RemoteRuntimeConfig, RuntimeDiagnostic> {
    let remote = RemoteRuntimeConfig::new(
        binding.runtime_id.clone(),
        binding.display_name.clone(),
        binding.base_url.clone(),
        None,
    )
    .with_workspace_id(binding.workspace_id.clone())
    .with_strict_public_egress(
        binding.authentication_mode == StoredRuntimeAuthenticationMode::WorkspaceIdentity
            && !is_loopback_runtime_origin(&binding.base_url),
    );
    Ok(remote)
}

fn runtime_connection_test_response(
    workspace_id: &str,
    runtime_id: &str,
    checked_at: String,
    ping: std::result::Result<
        worker_runtime::http_server::RuntimeHttpPingResponse,
        crate::hosts::RuntimePingFailure,
    >,
) -> RuntimeConnectionTestResponse {
    match ping {
        Ok(ping) if ping.runtime_id != runtime_id => runtime_connection_test_failure(
            workspace_id,
            runtime_id,
            checked_at,
            RuntimeConnectionTestFailureKind::RuntimeIdentityMismatch,
            None,
            RuntimeDiagnostic::new(
                "runtime_ping_identity_mismatch",
                "error",
                "Runtime ping identity does not match the registered Runtime",
            ),
        ),
        Ok(ping)
            if !(RUNTIME_HTTP_PROTOCOL_MIN_VERSION..=RUNTIME_HTTP_PROTOCOL_MAX_VERSION)
                .contains(&ping.protocol_version) =>
        {
            let code = if ping.protocol_version > RUNTIME_HTTP_PROTOCOL_MAX_VERSION {
                "runtime_ping_protocol_newer"
            } else {
                "runtime_ping_protocol_older"
            };
            runtime_connection_test_failure(
                workspace_id,
                runtime_id,
                checked_at,
                RuntimeConnectionTestFailureKind::ProtocolVersionMismatch,
                Some(ping.protocol_version),
                RuntimeDiagnostic::new(
                    code,
                    "error",
                    "Runtime protocol version is incompatible with this Server",
                ),
            )
        }
        Ok(ping) => RuntimeConnectionTestResponse {
            workspace_id: workspace_id.to_string(),
            runtime_id: runtime_id.to_string(),
            binding_id: String::new(),

            checked_at,
            status: RuntimeConnectionTestStatus::Compatible,
            failure_kind: None,
            expected_protocol_version: RUNTIME_HTTP_PROTOCOL_VERSION,
            actual_protocol_version: Some(ping.protocol_version),
            diagnostics: Vec::new(),
        },
        Err(failure) => runtime_connection_test_failure(
            workspace_id,
            runtime_id,
            checked_at,
            match failure.kind {
                RuntimePingFailureKind::Authentication => {
                    RuntimeConnectionTestFailureKind::Authentication
                }
                RuntimePingFailureKind::Authorization => {
                    RuntimeConnectionTestFailureKind::Authorization
                }
                RuntimePingFailureKind::NetworkUnreachable => {
                    RuntimeConnectionTestFailureKind::NetworkUnreachable
                }
                RuntimePingFailureKind::Timeout => RuntimeConnectionTestFailureKind::Timeout,
                RuntimePingFailureKind::TlsOrTransport => {
                    RuntimeConnectionTestFailureKind::TlsOrTransport
                }
                RuntimePingFailureKind::MalformedResponse => {
                    RuntimeConnectionTestFailureKind::MalformedResponse
                }
                RuntimePingFailureKind::Configuration | RuntimePingFailureKind::Unsupported => {
                    RuntimeConnectionTestFailureKind::Configuration
                }
            },
            None,
            failure.diagnostic,
        ),
    }
}

fn runtime_connection_test_failure(
    workspace_id: &str,
    runtime_id: &str,
    checked_at: String,
    failure_kind: RuntimeConnectionTestFailureKind,
    actual_protocol_version: Option<u32>,
    diagnostic: RuntimeDiagnostic,
) -> RuntimeConnectionTestResponse {
    RuntimeConnectionTestResponse {
        workspace_id: workspace_id.to_string(),
        runtime_id: runtime_id.to_string(),
        binding_id: String::new(),

        checked_at,
        status: RuntimeConnectionTestStatus::Failed,
        failure_kind: Some(failure_kind),
        expected_protocol_version: RUNTIME_HTTP_PROTOCOL_VERSION,
        actual_protocol_version,
        diagnostics: vec![diagnostic.into()],
    }
}

fn worker_launch_options_response(api: &WorkspaceApi) -> ApiResult<WorkerLaunchOptionsResponse> {
    let runtimes = api
        .runtime
        .list_runtimes(api.config.max_records.min(200))
        .items
        .into_iter()
        .map(|runtime| {
            let built_in = runtime.runtime_id == EMBEDDED_WORKER_RUNTIME_ID;
            WorkerLaunchRuntimeOption {
                runtime_id: runtime.runtime_id,
                display_name: runtime.label,
                built_in,
                worker_creation_available: runtime.worker_creation_available,
                supports_workdir_attachments: !built_in,
                status: runtime.status,
                diagnostics: runtime
                    .diagnostics
                    .into_iter()
                    .map(server_api::Diagnostic::from)
                    .collect(),
            }
        })
        .collect();
    let config_state = api
        .config_store
        .load_workspace_config(&api.config.workspace_id)?
        .ok_or_else(|| {
            ApiError::from(Error::InvalidRecordId("virtual config source tree".into()))
        })?;
    let profile_projection = crate::profile_settings::project_profiles_from_workspace_config(
        &api.config.workspace_id,
        &config_state,
    )?;
    let prompt_catalog = api
        .prompt_projection_cache
        .resolve(&api.config.workspace_id, &config_state)?;
    let profiles = profile_projection
        .settings
        .profiles
        .iter()
        .filter(|profile| {
            !profile
                .diagnostics
                .iter()
                .any(|diagnostic| diagnostic.severity == server_api::DiagnosticSeverity::Error)
        })
        .map(|profile| {
            let bundle =
                crate::profile_settings::build_virtual_profile_config_bundle_with_prompt_projection(
                    &profile_projection,
                    &config_state,
                    &api.config.workspace_id,
                    &api.config.workspace_created_at,
                    &profile.profile_id,
                    prompt_catalog.as_ref(),
                )?
                .ok_or_else(|| Error::Config("resolved Worker Profile bundle is missing".into()))?;
            let manifest = crate::profile_settings::resolve_profile_manifest_from_config_bundle(
                &bundle,
                &profile.profile_id,
            )?;
            Ok(WorkerLaunchProfileCandidate {
                id: profile.profile_id.clone(),
                label: profile.label.clone(),
                description: profile
                    .description
                    .clone()
                    .unwrap_or_else(|| "Workspace profile.".to_string()),
                feature_connections: server_api::WorkerLaunchFeatureConnectionOptions {
                    subjektiv: manifest.feature.subjektiv.profile.enabled,
                },
            })
        })
        .collect::<ApiResult<Vec<_>>>()?;
    Ok(WorkerLaunchOptionsResponse {
        workspace_id: api.config.workspace_id.clone(),
        runtimes,
        default_profile: profile_projection.settings.default_profile.clone(),
        profiles,
        repositories: working_directory_repository_options(api),
        working_directories: available_working_directory_summaries(api)
            .unwrap_or_default()
            .into_iter()
            .map(Into::into)
            .collect(),
        diagnostics: Vec::new(),
    })
}

fn working_directory_repository_options(
    api: &WorkspaceApi,
) -> Vec<WorkingDirectoryRepositoryOption> {
    api.config
        .repositories
        .iter()
        .map(|repository| WorkingDirectoryRepositoryOption {
            repository_key: repository.repository_key.clone(),
            default_selector: repository.default_selector.clone(),
        })
        .collect()
}

// Inventory reads must not reinterpret legacy grants as broader permissions or
// let one unsupported grant prevent unrelated Workdirs from being listed.
fn legacy_external_workdir_grant_id(
    api: &WorkspaceApi,
    record: &WorkdirRegistryRecord,
) -> Result<Option<String>> {
    let WorkdirRegistrySource::ExternalGrant { grant_id } = &record.source else {
        return Ok(None);
    };
    let grant = api
        .store
        .get_external_workdir_grant(&record.workspace_id, grant_id)?
        .ok_or_else(|| Error::Store("External Workdir grant is unavailable".to_string()))?;
    Ok(
        matches!(grant.permissions.as_str(), "command_only" | "read_command")
            .then(|| grant_id.clone()),
    )
}

fn working_directory_summaries(
    api: &WorkspaceApi,
) -> ApiResult<(Vec<WorkingDirectorySummary>, Vec<RuntimeDiagnostic>)> {
    let mut diagnostics = sync_all_runtime_workdir_observations(api);
    let records = api
        .store
        .list_workdir_registry(&api.config.workspace_id, 200)?;
    let mut items = Vec::new();
    for record in records {
        if matches!(record.source, WorkdirRegistrySource::WorkspaceConfig { .. }) {
            continue;
        }
        if let Some(grant_id) = legacy_external_workdir_grant_id(api, &record)? {
            diagnostics.push(RuntimeDiagnostic {
                code: "external_workdir_legacy_permissions".to_string(),
                severity: HostDiagnosticSeverity::Warning,
                message: format!(
                    "Workdir {} was omitted because External grant {} uses legacy non-hierarchical permissions; revoke the old grant and share again with READ, WRITE, or COMMAND",
                    record.workdir_id, grant_id,
                ),
            });
            continue;
        }
        items.push(projected_workdir_summary_from_record(api, &record)?);
    }
    Ok((items, diagnostics))
}

fn available_working_directory_summaries(
    api: &WorkspaceApi,
) -> ApiResult<Vec<WorkingDirectorySummary>> {
    let limit = api.config.max_records.min(200);
    for worker in api.runtime.list_workers(limit).items {
        let _ = sync_worker_observation(api, &worker);
    }
    let records = api
        .store
        .list_workdir_registry(&api.config.workspace_id, 200)?;
    let mut available = Vec::new();
    for record in records {
        if matches!(record.source, WorkdirRegistrySource::WorkspaceConfig { .. }) {
            continue;
        }
        if legacy_external_workdir_grant_id(api, &record)?.is_some() {
            continue;
        }
        let summary = projected_workdir_summary_from_record(api, &record)?;
        let source_is_available = match record.source {
            WorkdirRegistrySource::Repository { .. } => {
                summary.cleanliness.as_deref() == Some("clean")
            }
            WorkdirRegistrySource::ExternalGrant { .. } => true,
            WorkdirRegistrySource::WorkspaceConfig { .. } => false,
        };
        if summary.status != WorkingDirectoryStatusKind::Active || !source_is_available {
            continue;
        }
        if summary.occupied_by.is_none() {
            available.push(summary);
        }
    }
    Ok(available)
}

fn runtime_working_directory_summaries(
    api: &WorkspaceApi,
    runtime_id: &str,
) -> ApiResult<(Vec<WorkingDirectorySummary>, Vec<RuntimeDiagnostic>)> {
    let diagnostics = sync_runtime_workdir_observations(api, runtime_id)?;
    let records = api
        .store
        .list_workdir_registry(&api.config.workspace_id, 200)?;
    let items = records
        .iter()
        .filter(|record| record.source.runtime_id() == Some(runtime_id))
        .map(|record| projected_workdir_summary_from_record(api, record))
        .collect::<Result<Vec<_>>>()
        .map_err(ApiError::from)?;
    Ok((items, diagnostics))
}

static BACKEND_WORKDIR_ID_SEQUENCE: AtomicU64 = AtomicU64::new(0);

fn now_registry_timestamp() -> String {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|duration| duration.as_millis().to_string())
        .unwrap_or_else(|_| "0".to_string())
}

fn next_backend_workdir_id(_repository_id: &str) -> String {
    let timestamp_ms = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|duration| duration.as_millis() as u64)
        .unwrap_or(0);
    let sequence = BACKEND_WORKDIR_ID_SEQUENCE.fetch_add(1, Ordering::Relaxed) & 0x00ff_ffff;
    format!("{timestamp_ms:013x}{sequence:06x}")
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum WorkerRegistryDisplayNamePolicy {
    PreserveExisting,
    UseProvided,
}

fn record_worker_summary(
    api: &WorkspaceApi,
    worker: &InternalWorkerSummary,
    display_name: &str,
    profile: Option<String>,
    display_name_policy: WorkerRegistryDisplayNamePolicy,
) -> ApiResult<WorkerRegistryRecord> {
    let timestamp = now_registry_timestamp();
    parse_runtime_worker_id_for_registry(worker.worker.worker_id.as_str())?;
    let worker_ref = worker.worker.clone();
    let existing = api
        .store
        .get_worker_registry(&api.config.workspace_id, &worker_ref)?;
    let display_name = match (display_name_policy, existing.as_ref()) {
        (WorkerRegistryDisplayNamePolicy::PreserveExisting, Some(record)) => {
            record.display_name.clone()
        }
        _ => display_name.to_string(),
    };
    let record = WorkerRegistryRecord {
        workspace_id: api.config.workspace_id.clone(),
        worker: worker_ref.clone(),
        display_name,
        profile,
        retention_state: existing
            .as_ref()
            .map(|record| record.retention_state.clone())
            .unwrap_or_else(|| "normal".to_string()),
        transcript_ref: Some(format!(
            "runtime://{}/workers/{}/transcript",
            worker.worker.runtime_id.as_str(),
            worker.worker.worker_id.as_str()
        )),
        session_ref: None,
        summary_ref: None,
        diagnostics_ref: None,
        created_at: timestamp.clone(),
        updated_at: timestamp,
    };
    api.worker_projection
        .publish_ordered(|| {
            api.store
                .upsert_worker_registry(&record)
                .map(|commit| ((), commit))
        })
        .map_err(ApiError::from)?;
    if let Ok(worker_id) =
        protocol::subscription::SubscriptionWorkerId::new(worker.worker.worker_id.clone())
    {
        let state = match worker.state.as_str() {
            "running" => protocol::subscription::SubscriptionWorkerState::Running,
            "paused" => protocol::subscription::SubscriptionWorkerState::Paused,
            "stopped" => protocol::subscription::SubscriptionWorkerState::Stopped,
            _ => protocol::subscription::SubscriptionWorkerState::Idle,
        };
        let observation = protocol::subscription::SubscriptionWorker {
            restore_observation_token: worker.restore_observation_token.clone(),
            worker_id,
            runtime_id: Some(worker.worker.runtime_id.clone()),
            resource_key: None,
            availability: protocol::subscription::SubscriptionWorkerAvailability::Observed,
            worker_state: worker.worker_state.clone(),
            state,
            has_running_internal_workers: false,
            workspace_id: worker.workspace.workspace_id.clone(),
            display_name: Some(worker.display_name.clone()),
            profile: worker.profile.clone(),
            job: None,
            workdir_attachments: Vec::new(),
        };
        api.worker_projection
            .seed_observation(
                worker.worker.runtime_id.as_str(),
                &observation,
                worker
                    .last_seen_at
                    .as_deref()
                    .unwrap_or(record.updated_at.as_str()),
            )
            .map_err(ApiError::from)?;
    }
    Ok(api
        .store
        .get_worker_registry(&api.config.workspace_id, &worker_ref)?
        .unwrap_or(record))
}

fn worker_summary_from_registry(record: &WorkerRegistryRecord) -> InternalWorkerSummary {
    InternalWorkerSummary {
        restore_observation_token: None,
        worker: record.worker.clone(),
        host_id: "backend-registry".to_string(),
        display_name: record.display_name.clone(),
        label: record.display_name.clone(),
        singleton_key: None,
        tags: Vec::new(),
        state: "missing".to_string(),
        execution_reconstructed: false,
        worker_state: None,
        last_seen_at: Some(record.updated_at.clone()),
        pinned: record.retention_state == "pinned",
        retention_state: record.retention_state.clone(),
        workspace: InternalWorkerWorkspaceSummary {
            visibility: "backend_registry".to_string(),
            identity: record.workspace_id.clone(),
            workspace_id: Some(record.workspace_id.clone()),
        },
        availability: protocol::subscription::SubscriptionWorkerAvailability::Unavailable,
        profile: record.profile.clone(),
        implementation: InternalWorkerImplementationSummary {
            kind: "backend_worker_registry".to_string(),
            display_hint: "Missing Worker".to_string(),
        },
        workdir_attachments: Vec::new(),
        diagnostics: vec![RuntimeDiagnostic {
            code: "backend_worker_missing".to_string(),
            severity: HostDiagnosticSeverity::Info,
            message:
                "Worker is preserved in the Backend registry but the Runtime did not find it by id"
                    .to_string(),
        }],
    }
}

fn worker_summary_from_projection(
    projection: &crate::store::WorkerRegistryProjectionRecord,
) -> Option<InternalWorkerSummary> {
    let observation = projection.observation.as_ref()?;
    let mut summary = worker_summary_from_registry(&projection.registry);
    let observed = observation.availability
        == protocol::subscription::SubscriptionWorkerAvailability::Observed;
    summary.availability = observation.availability;
    summary.restore_observation_token = observed
        .then(|| observation.worker.restore_observation_token.clone())
        .flatten();
    summary.state = if observed {
        match observation.worker.state {
            protocol::subscription::SubscriptionWorkerState::Idle => "idle",
            protocol::subscription::SubscriptionWorkerState::Running => "running",
            protocol::subscription::SubscriptionWorkerState::Paused => "paused",
            protocol::subscription::SubscriptionWorkerState::Stopped => "stopped",
        }
    } else {
        "unavailable"
    }
    .to_string();
    summary.worker_state = observed
        .then(|| observation.worker.worker_state.clone())
        .flatten();
    summary.last_seen_at = Some(observation.observed_at.clone());
    summary.implementation.display_hint = if observed {
        "Runtime-backed Worker".to_string()
    } else {
        "Worker observation unavailable".to_string()
    };
    summary.diagnostics = if observed {
        Vec::new()
    } else {
        vec![RuntimeDiagnostic {
            code: "worker_observation_unavailable".to_string(),
            severity: HostDiagnosticSeverity::Info,
            message: "The Worker remains in the Backend catalog, but its Runtime observation is currently unavailable.".to_string(),
        }]
    };
    Some(summary)
}

fn project_worker_registry_projection(
    api: &WorkspaceApi,
    live: Option<&InternalWorkerSummary>,
    record: &WorkerRegistryRecord,
    links: Vec<WorkerWorkdirLinkRecord>,
    workdirs: &[WorkdirRegistryRecord],
) -> ApiResult<server_api::WorkerSummary> {
    let summary = merge_worker_registry_summary(live, record);
    let mut workdir_attachments = Vec::with_capacity(links.len());
    for link in links {
        let Some(workdir) = workdirs
            .iter()
            .find(|workdir| workdir.workdir_id == link.workdir_id)
        else {
            continue;
        };
        if let WorkdirRegistrySource::WorkspaceConfig { grant_id } = &workdir.source {
            if !workspace_config::granted_to(api, &record.worker, grant_id) {
                continue;
            }
            let grant = api
                .store
                .get_workspace_config_grant(&api.config.workspace_id, grant_id)?
                .ok_or_else(|| {
                    Error::WorkspacePermissionDenied("Workspace config grant unavailable".into())
                })?;
            workdir_attachments.push(server_api::WorkerWorkdirAttachmentSummary {
                alias: link.alias,
                effective_permissions: workdir_permission_summary(
                    effective_worker_workdir_capabilities(
                        api,
                        &record.worker,
                        workdir,
                        link.capabilities,
                    )?,
                ),
                working_directory: workspace_config::summary(&grant, workdir),
            });
            continue;
        }
        let effective_permissions = workdir_permission_summary(
            effective_worker_workdir_capabilities(api, &record.worker, workdir, link.capabilities)?,
        );
        workdir_attachments.push(server_api::WorkerWorkdirAttachmentSummary {
            alias: workdir::WorkdirAttachmentAlias::new(link.alias)
                .expect("persisted attachment aliases are validated on write")
                .to_string(),
            effective_permissions,
            working_directory: projected_workdir_summary_from_record(api, workdir)?.into(),
        });
    }
    project_workspace_worker_with_attachments(api, summary, workdir_attachments)
}

fn merge_worker_registry_summary(
    live: Option<&InternalWorkerSummary>,
    record: &WorkerRegistryRecord,
) -> InternalWorkerSummary {
    let mut summary = live
        .cloned()
        .unwrap_or_else(|| worker_summary_from_registry(record));
    summary.label = record.display_name.clone();
    summary.profile = record.profile.clone();
    summary.pinned = record.retention_state == "pinned";
    summary.retention_state = record.retention_state.clone();
    summary.workdir_attachments.clear();
    summary
}

fn sync_worker_observation(
    api: &WorkspaceApi,
    worker: &InternalWorkerSummary,
) -> ApiResult<WorkerRegistryRecord> {
    let record = record_worker_summary(
        api,
        worker,
        worker.label.as_str(),
        worker.profile.clone(),
        WorkerRegistryDisplayNamePolicy::PreserveExisting,
    )?;
    for attachment in &worker.workdir_attachments {
        let working_directory = &attachment.working_directory.summary;
        let workdir_record =
            workdir_record_from_summary(api, worker.worker.runtime_id.as_str(), working_directory);
        api.store.upsert_workdir_registry(&workdir_record)?;
        let links = api
            .store
            .list_worker_workdir_links(&api.config.workspace_id, &record.worker)?;
        if !links.iter().any(|link| {
            link.unlinked_at.is_none()
                && link.alias == attachment.alias.as_str()
                && link.workdir_id == working_directory.working_directory_id
        }) {
            let capabilities =
                ticket_target_capabilities_for_workdir(api, &record.worker, &workdir_record)?;
            link_worker_to_workdir(
                api,
                &record,
                attachment.alias.as_str(),
                &working_directory.working_directory_id,
                capabilities,
                None,
            )?;
        }
    }
    Ok(record)
}

fn upsert_pending_backend_workdir(
    api: &WorkspaceApi,
    runtime_id: &str,
    request: &mut WorkingDirectoryRequest,
) -> ApiResult<String> {
    let workdir_id = request
        .backend_workdir_id
        .clone()
        .unwrap_or_else(|| next_backend_workdir_id(&request.repository.id));
    request.backend_workdir_id = Some(workdir_id.clone());
    let timestamp = now_registry_timestamp();
    api.store.upsert_workdir_registry(&WorkdirRegistryRecord {
        workspace_id: api.config.workspace_id.clone(),
        workdir_id: workdir_id.clone(),
        display_name: request.display_name.clone(),
        source: WorkdirRegistrySource::Repository {
            runtime_id: runtime_id.to_string(),
            repository_id: request.repository.id.clone(),
        },
        creation_selector: request
            .repository
            .selector
            .as_ref()
            .map(|selector| selector.as_ref().to_string()),
        creation_ref: None,
        creation_tree: None,
        current_selector: None,
        current_ref: None,
        current_tree: None,
        observed_at_epoch_seconds: None,
        materialization_status: "pending".to_string(),
        cleanliness: "unknown".to_string(),
        created_at: timestamp.clone(),
        updated_at: timestamp,
    })?;
    Ok(workdir_id)
}

fn reconcile_runtime_workdir_observations(
    api: &WorkspaceApi,
    runtime_id: &str,
    items: &[worker_runtime::catalog::WorkingDirectoryStatus],
) -> ApiResult<std::collections::BTreeSet<String>> {
    let mut observed = std::collections::BTreeSet::new();
    for status in items {
        let Some(existing) = api.store.get_workdir_registry(
            &api.config.workspace_id,
            &status.summary.working_directory_id,
        )?
        else {
            continue;
        };
        if existing.source.runtime_id() != Some(runtime_id) {
            continue;
        }
        observed.insert(status.summary.working_directory_id.clone());
        if status.summary.status == WorkingDirectoryStatusKind::NotFound {
            persist_workdir_not_found(api, existing)?;
            continue;
        }
        let mut record = workdir_record_from_summary(api, runtime_id, &status.summary);
        preserve_workdir_identity_for_corrupted_summary(&mut record, Some(&existing));
        api.store.upsert_workdir_registry(&record)?;
    }
    Ok(observed)
}

fn sync_runtime_workdir_observations(
    api: &WorkspaceApi,
    runtime_id: &str,
) -> ApiResult<Vec<RuntimeDiagnostic>> {
    let response = api
        .runtime
        .list_working_directories(runtime_id)
        .map_err(|err| err.into_error())?;
    let observed = reconcile_runtime_workdir_observations(api, runtime_id, &response.items)?;
    for mut record in api
        .store
        .list_workdir_registry(&api.config.workspace_id, 500)?
        .into_iter()
        .filter(|record| {
            record.source.runtime_id() == Some(runtime_id) && !observed.contains(&record.workdir_id)
        })
    {
        match api
            .runtime
            .working_directory(runtime_id, record.workdir_id.as_str())
        {
            Ok(result) => {
                if let Some(status) = result.working_directory {
                    if status.summary.status == WorkingDirectoryStatusKind::NotFound {
                        persist_workdir_not_found(api, record)?;
                    } else {
                        let mut updated =
                            workdir_record_from_summary(api, runtime_id, &status.summary);
                        preserve_workdir_identity_for_corrupted_summary(
                            &mut updated,
                            Some(&record),
                        );
                        api.store.upsert_workdir_registry(&updated)?;
                    }
                } else {
                    persist_workdir_runtime_miss(api, record, result.diagnostics.as_slice())?;
                }
            }
            Err(_) => {
                record.materialization_status = "unknown".to_string();
                record.cleanliness = "unknown".to_string();
                record.updated_at = now_registry_timestamp();
                api.store.upsert_workdir_registry(&record)?;
            }
        }
    }
    Ok(response.diagnostics)
}

fn workdir_runtime_miss_is_not_found(diagnostics: &[RuntimeDiagnostic]) -> bool {
    diagnostics
        .iter()
        .any(|diagnostic| diagnostic.code == "working_directory_not_found")
}

fn workdir_status_from_runtime_miss(diagnostics: &[RuntimeDiagnostic]) -> &'static str {
    if workdir_runtime_miss_is_not_found(diagnostics) {
        "not_found"
    } else {
        "unknown"
    }
}

fn persist_workdir_not_found(
    api: &WorkspaceApi,
    mut record: WorkdirRegistryRecord,
) -> ApiResult<()> {
    record.materialization_status = "not_found".to_string();
    record.cleanliness = "unknown".to_string();
    record.observed_at_epoch_seconds = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .ok()
        .map(|duration| duration.as_secs());
    record.updated_at = now_registry_timestamp();
    api.store.upsert_workdir_registry(&record)?;
    Ok(())
}

fn persist_workdir_runtime_miss(
    api: &WorkspaceApi,
    mut record: WorkdirRegistryRecord,
    diagnostics: &[RuntimeDiagnostic],
) -> ApiResult<()> {
    if workdir_runtime_miss_is_not_found(diagnostics) {
        persist_workdir_not_found(api, record)?;
    } else {
        record.materialization_status = "unknown".to_string();
        record.cleanliness = "unknown".to_string();
        record.updated_at = now_registry_timestamp();
        api.store.upsert_workdir_registry(&record)?;
    }
    Ok(())
}

fn sync_all_runtime_workdir_observations(api: &WorkspaceApi) -> Vec<RuntimeDiagnostic> {
    let mut diagnostics = Vec::new();
    let runtimes = api.runtime.list_runtimes(api.config.max_records.min(200));
    for runtime in runtimes.items {
        match sync_runtime_workdir_observations(api, runtime.runtime_id.as_str()) {
            Ok(mut runtime_diagnostics) => diagnostics.append(&mut runtime_diagnostics),
            Err(err) => diagnostics.extend(err.diagnostics),
        }
    }
    diagnostics
}

fn sync_linked_workdir_after_worker_stop(
    api: &WorkspaceApi,
    runtime_id: &str,
    worker_record: &WorkerRegistryRecord,
) -> ApiResult<()> {
    let links = api
        .store
        .list_worker_workdir_links(&api.config.workspace_id, &worker_record.worker)?;
    for link in links {
        let result = api
            .runtime
            .working_directory(runtime_id, link.workdir_id.as_str())
            .map_err(|err| err.into_error())?;
        if let Some(status) = result.working_directory {
            let record = workdir_record_from_summary(api, runtime_id, &status.summary);
            api.store.upsert_workdir_registry(&record)?;
        } else if let Some(mut record) = api
            .store
            .get_workdir_registry(&api.config.workspace_id, link.workdir_id.as_str())?
        {
            record.materialization_status =
                workdir_status_from_runtime_miss(result.diagnostics.as_slice()).to_string();
            record.cleanliness = "unknown".to_string();
            record.updated_at = now_registry_timestamp();
            api.store.upsert_workdir_registry(&record)?;
        }
    }
    Ok(())
}

fn workdir_record_from_summary(
    api: &WorkspaceApi,
    runtime_id: &str,
    summary: &worker_runtime::catalog::WorkingDirectorySummary,
) -> WorkdirRegistryRecord {
    let timestamp = now_registry_timestamp();
    WorkdirRegistryRecord {
        workspace_id: api.config.workspace_id.clone(),
        workdir_id: summary.working_directory_id.clone(),
        display_name: summary.display_name.clone(),
        source: WorkdirRegistrySource::Repository {
            runtime_id: runtime_id.to_string(),
            repository_id: summary.repository_id.clone(),
        },
        creation_selector: summary.creation_selector.clone(),
        creation_ref: summary.creation_ref.clone(),
        creation_tree: summary.creation_tree.clone(),
        current_selector: summary.current_selector.clone(),
        current_ref: summary.current_ref.clone(),
        current_tree: summary.current_tree.clone(),
        observed_at_epoch_seconds: summary.observed_at_epoch_seconds,
        materialization_status: match summary.status {
            WorkingDirectoryStatusKind::Active => "present",
            WorkingDirectoryStatusKind::CleanupPending => "pending",
            WorkingDirectoryStatusKind::Corrupted => "corrupted",
            WorkingDirectoryStatusKind::NotFound => "not_found",
            WorkingDirectoryStatusKind::Unknown => "unknown",
        }
        .to_string(),
        cleanliness: summary
            .cleanliness
            .clone()
            .unwrap_or_else(|| "unknown".to_string()),
        created_at: timestamp.clone(),
        updated_at: timestamp,
    }
}

fn preserve_workdir_identity_for_corrupted_summary(
    record: &mut WorkdirRegistryRecord,
    existing: Option<&WorkdirRegistryRecord>,
) {
    if record.materialization_status != "corrupted" {
        return;
    }
    let Some(existing) = existing else {
        return;
    };
    if matches!(
        &record.source,
        WorkdirRegistrySource::Repository { repository_id, .. } if repository_id == "unknown"
    ) {
        record.source = existing.source.clone();
    }
    if record.creation_selector.is_none() {
        record.creation_selector = existing.creation_selector.clone();
    }
    if record.creation_ref.is_none() {
        record.creation_ref = existing.creation_ref.clone();
    }
    if record.creation_tree.is_none() {
        record.creation_tree = existing.creation_tree.clone();
    }
    if record.current_selector.is_none() {
        record.current_selector = existing.current_selector.clone();
    }
    if record.current_ref.is_none() {
        record.current_ref = existing.current_ref.clone();
    }
    if record.current_tree.is_none() {
        record.current_tree = existing.current_tree.clone();
    }
    if record.observed_at_epoch_seconds.is_none() {
        record.observed_at_epoch_seconds = existing.observed_at_epoch_seconds;
    }
}

#[cfg(test)]
fn runtime_workdir_summary_from_record(
    record: &WorkdirRegistryRecord,
) -> worker_runtime::catalog::WorkingDirectorySummary {
    let status = match record.materialization_status.as_str() {
        "present" => WorkingDirectoryStatusKind::Active,
        "pending" => WorkingDirectoryStatusKind::CleanupPending,
        "corrupted" => WorkingDirectoryStatusKind::Corrupted,
        "not_found" | "missing" => WorkingDirectoryStatusKind::NotFound,
        _ => WorkingDirectoryStatusKind::Unknown,
    };
    let repository_id = record
        .source
        .repository_id()
        .expect("Runtime Workdir projection requires Repository source")
        .to_string();
    worker_runtime::catalog::WorkingDirectorySummary {
        working_directory_id: record.workdir_id.clone(),
        display_name: record.display_name.clone(),
        repository_id: repository_id.clone(),
        creation_selector: record.creation_selector.clone(),
        creation_ref: record.creation_ref.clone(),
        creation_tree: record.creation_tree.clone(),
        current_selector: record.current_selector.clone(),
        current_ref: record.current_ref.clone(),
        current_tree: record.current_tree.clone(),
        observed_at_epoch_seconds: record.observed_at_epoch_seconds,
        materializer_kind: MaterializerKind::RuntimeGitClone,
        cleanup_target: Some(worker_runtime::catalog::WorkingDirectoryCleanupTarget {
            kind: "runtime_git_clone".to_string(),
            working_directory_id: record.workdir_id.clone(),
            repository_id,
        }),
        status,
        cleanliness: Some(record.cleanliness.clone()),
        occupied_by: None,
    }
}

fn workdir_summary_from_record(
    record: &WorkdirRegistryRecord,
    repository_key: Option<&str>,
    external_grant_permissions: Option<workdir::workspace::WorkdirPermissionSummary>,
) -> WorkingDirectorySummary {
    let status = match record.materialization_status.as_str() {
        "present" => WorkingDirectoryStatusKind::Active,
        "pending" => WorkingDirectoryStatusKind::CleanupPending,
        "corrupted" => WorkingDirectoryStatusKind::Corrupted,
        "not_found" | "missing" => WorkingDirectoryStatusKind::NotFound,
        "unknown" => WorkingDirectoryStatusKind::Unknown,
        _ => WorkingDirectoryStatusKind::Unknown,
    };
    let (source, materializer_kind, cleanup_target) = match &record.source {
        WorkdirRegistrySource::WorkspaceConfig { .. } => {
            unreachable!("logical config never enters filesystem summary")
        }
        WorkdirRegistrySource::Repository { .. } => {
            let repository_key =
                repository_key.expect("Repository Workdir projection requires key");
            (
                WorkingDirectorySource::Repository {
                    repository_key: repository_key.to_string(),
                },
                MaterializerKind::RuntimeGitClone,
                Some(WorkingDirectoryCleanupTarget {
                    kind: "runtime_git_clone".to_string(),
                    working_directory_id: record.workdir_id.clone(),
                    repository_key: repository_key.to_string(),
                }),
            )
        }
        WorkdirRegistrySource::ExternalGrant { grant_id } => (
            WorkingDirectorySource::ExternalGrant {
                grant_id: grant_id.clone(),
                grant_permissions: external_grant_permissions
                    .expect("External Workdir projection requires grant permissions"),
            },
            MaterializerKind::ClientHostedExternal,
            None,
        ),
    };
    WorkingDirectorySummary {
        working_directory_id: record.workdir_id.clone(),
        display_name: record.display_name.clone(),
        source,
        creation_selector: record.creation_selector.clone(),
        creation_ref: record.creation_ref.clone(),
        creation_tree: record.creation_tree.clone(),
        current_selector: record.current_selector.clone(),
        current_ref: record.current_ref.clone(),
        current_tree: record.current_tree.clone(),
        observed_at_epoch_seconds: record.observed_at_epoch_seconds,
        materializer_kind,
        cleanup_target,
        status,
        cleanliness: Some(record.cleanliness.clone()),
        occupied_by: None,
    }
}

fn apply_workdir_occupancy_projection(
    api: &WorkspaceApi,
    summary: &mut WorkingDirectorySummary,
) -> Result<()> {
    let links = api
        .store
        .list_workdir_worker_links(&api.config.workspace_id, &summary.working_directory_id)?;
    let Some(link) = links.first() else {
        summary.occupied_by = None;
        return Ok(());
    };

    let worker = api
        .store
        .get_worker_registry(&api.config.workspace_id, &link.worker)?
        .ok_or_else(|| {
            Error::RegistryInconsistency(format!(
                "Workdir {} attachment references missing Worker {}:{}",
                link.workdir_id, link.worker.runtime_id, link.worker.worker_id
            ))
        })?;
    summary.occupied_by = Some(WorkingDirectoryOccupancy {
        runtime_id: link.worker.runtime_id.clone(),
        worker_id: link.worker.worker_id.clone(),
        display_name: worker.display_name,
        linked_at: link.linked_at.clone(),
    });
    Ok(())
}

fn projected_workdir_summary_from_record(
    api: &WorkspaceApi,
    record: &WorkdirRegistryRecord,
) -> Result<WorkingDirectorySummary> {
    let (repository_key, external_grant_permissions) = match &record.source {
        WorkdirRegistrySource::WorkspaceConfig { .. } => {
            return Err(Error::WorkspacePermissionDenied(
                "Logical config is not a filesystem Workdir".into(),
            ));
        }
        WorkdirRegistrySource::Repository { repository_id, .. } => (
            Some(
                api.store
                    .get_repository(&record.workspace_id, repository_id)?
                    .ok_or_else(|| Error::UnknownRepository(repository_id.clone()))?
                    .repository_key,
            ),
            None,
        ),
        WorkdirRegistrySource::ExternalGrant { grant_id } => (
            None,
            Some({
                let permissions = api
                    .store
                    .get_external_workdir_grant(&record.workspace_id, grant_id)?
                    .ok_or_else(|| {
                        Error::Store("External Workdir grant is unavailable".to_string())
                    })
                    .and_then(|grant| external_workdir_permissions(&grant.permissions))?;
                workdir::workspace::WorkdirPermissionSummary {
                    read: permissions.read,
                    write: permissions.write,
                    command: permissions.command,
                }
            }),
        ),
    };
    let mut summary = workdir_summary_from_record(
        record,
        repository_key.as_deref(),
        external_grant_permissions,
    );
    apply_workdir_occupancy_projection(api, &mut summary)?;
    Ok(summary)
}

fn link_worker_to_workdir(
    api: &WorkspaceApi,
    worker_record: &WorkerRegistryRecord,
    alias: &str,
    workdir_id: &str,
    capabilities: workdir::WorkdirSessionCapabilities,
    reservation_id: Option<&str>,
) -> ApiResult<()> {
    let timestamp = now_registry_timestamp();
    let record = WorkerWorkdirLinkRecord {
        connection_id: String::new(),
        workspace_id: api.config.workspace_id.clone(),
        worker: worker_record.worker.clone(),
        workdir_id: workdir_id.to_string(),
        alias: alias.to_string(),
        capabilities,
        linked_at: timestamp,
        unlinked_at: None,
    };
    if let Some(reservation_id) = reservation_id {
        api.store
            .finalize_reserved_worker_workdir_attachment(&record, reservation_id)?;
    } else {
        api.store.attach_worker_workdir(&record)?;
    }
    api.worker_projection
        .refresh(&worker_record.worker)
        .map_err(ApiError::from)?;
    Ok(())
}

fn validate_working_directory_claims_for_browser(
    claims: &[WorkingDirectoryAttachmentClaim],
) -> ApiResult<()> {
    let mut aliases = HashSet::new();
    let mut workdir_ids = HashSet::new();
    for claim in claims {
        if !aliases.insert(claim.alias.as_str()) {
            return Err(settings_bad_request(
                "duplicate_workdir_attachment_alias",
                "attachment aliases must be unique within one Worker",
            ));
        }
        if !workdir_ids.insert(claim.working_directory_id.as_str()) {
            return Err(settings_bad_request(
                "duplicate_workdir_attachment",
                "a Workdir cannot be attached more than once to one Worker",
            ));
        }
        if let Some(relative_cwd) = claim.relative_cwd.as_deref() {
            let path = Path::new(relative_cwd);
            if path.is_absolute()
                || path
                    .components()
                    .any(|component| !matches!(component, Component::CurDir | Component::Normal(_)))
            {
                return Err(ApiError::with_diagnostics(
                    Error::RuntimeOperationFailed {
                        runtime_id: EMBEDDED_WORKER_RUNTIME_ID.to_string(),
                        code: "working_directory_relative_cwd_invalid".to_string(),
                        message: "working directory relative_cwd must stay inside the Runtime-owned working directory".to_string(),
                    },
                    vec![RuntimeDiagnostic {
                        code: "working_directory_relative_cwd_invalid".to_string(),
                        severity: HostDiagnosticSeverity::Error,
                        message: "relative_cwd must be a relative path without parent traversal".to_string(),
                    }],
                ));
            }
        }
    }
    Ok(())
}

fn repository_ssh_lease_candidates(
    api: &WorkspaceApi,
    primary: crate::repository_access::LeasedRepositorySshAccess,
) -> ApiResult<Vec<crate::repository_access::LeasedRepositorySshAccess>> {
    let workspace_default = api
        .repository_secrets
        .ensure_workspace_default_credential(&api.config.workspace_id)?;
    if primary.credential_id
        == crate::repository_access::WORKSPACE_DEFAULT_REPOSITORY_SSH_CREDENTIAL_ID
    {
        return Ok(vec![primary]);
    }
    let workspace_default = api
        .repository_secrets
        .lease_ssh_materialization_access_fingerprints(
            &api.config.workspace_id,
            crate::repository_access::WORKSPACE_DEFAULT_REPOSITORY_SSH_CREDENTIAL_ID,
            &workspace_default.public_key_fingerprint,
            &primary.host_trust_id,
            &primary.host_trust_fingerprint,
        )?;
    Ok(vec![primary, workspace_default])
}

fn authorize_repository_materialization_operation(
    api: &WorkspaceApi,
    operation: &WorkdirCreateOperationRecord,
    request_fingerprint: &str,
    request: &mut WorkingDirectoryRequest,
) -> ApiResult<()> {
    let context = if request.repository.source.kind == server_api::RepositorySourceKind::Ssh {
        if let (
            Some(_credential_id),
            Some(_credential_fingerprint),
            Some(_host_trust_id),
            Some(_host_trust_fingerprint),
            Some(access_mode),
        ) = (
            operation.credential_id.as_deref(),
            operation.credential_fingerprint.as_deref(),
            operation.host_trust_id.as_deref(),
            operation.host_trust_fingerprint.as_deref(),
            operation.repository_access_mode.as_deref(),
        ) {
            let leases = repository_ssh_lease_candidates_from_operation(api, operation, request)?;
            let primary_lease = leases.first().ok_or_else(|| {
                settings_bad_request(
                    "working_directory_repository_access_invalid",
                    "Repository SSH access has no credential candidates",
                )
            })?;
            let primary_host_trust_id = primary_lease.host_trust_id.clone();
            let primary_host_trust_fingerprint = primary_lease.host_trust_fingerprint.clone();
            let known_hosts_entry = primary_lease.known_hosts_entry.clone();
            let access = match access_mode {
                "read_only" => server_api::RepositoryAccessMode::ReadOnly,
                "read_write" => server_api::RepositoryAccessMode::ReadWrite,
                _ => {
                    return Err(settings_bad_request(
                        "working_directory_repository_access_invalid",
                        "persisted Repository access mode is invalid",
                    ));
                }
            };
            let expires_at_epoch_seconds = repository_access_expiry();
            let secret_resource = api
                .resource_broker
                .issue_repository_ssh_access_handle(
                    &api.config.workspace_id,
                    &operation.resolved_runtime_id,
                    format!("repository-ssh-access:{}", operation.operation_id),
                    i64::try_from(expires_at_epoch_seconds).unwrap_or(i64::MAX),
                    worker_runtime::resource::RepositorySshAccessSecret {
                        credential_candidates: leases
                            .iter()
                            .map(|lease| {
                                worker_runtime::resource::RepositorySshAccessSecretCandidate {
                                    credential_id: lease.credential_id.clone(),
                                    public_key_fingerprint: lease.credential_fingerprint.clone(),
                                    private_key: lease.private_key.as_str().to_string(),
                                }
                            })
                            .collect(),
                        known_hosts_entry: known_hosts_entry.clone(),
                    },
                )
                .map_err(|_| {
                    settings_bad_request(
                        "working_directory_repository_access_resource_failed",
                        "Repository SSH access resource could not be issued",
                    )
                })?;
            RepositoryMaterializationContext {
                workspace_id: api.config.workspace_id.clone(),
                runtime_id: operation.resolved_runtime_id.clone(),
                operation_id: operation.operation_id.clone(),
                config_projection_digest: operation.config_projection_digest.clone(),
                ssh: Some(RepositorySshMaterializationAccess {
                    credential_candidates: leases
                        .into_iter()
                        .map(|lease| RepositorySshCredentialCandidate {
                            credential_id: lease.credential_id,
                            public_key_fingerprint: lease.credential_fingerprint.clone(),
                            private_key: SensitiveString::default(),
                        })
                        .collect(),
                    host_trust_id: primary_host_trust_id,
                    host_key_fingerprint: primary_host_trust_fingerprint,
                    access,
                    expires_at_epoch_seconds,
                    repository_id: request.repository.id.clone(),
                    repository_source_fingerprint: request.repository.source_fingerprint.clone(),
                    repository_uri: request.repository.source.uri.clone(),
                    secret_resource,
                    known_hosts_entry: SensitiveString::default(),
                }),
            }
        } else {
            let projection = active_repository_access_projection(api, &api.config.workspace_id)?;
            if projection.projection_digest != operation.config_projection_digest {
                return Err(settings_bad_request(
                    "working_directory_repository_access_content_changed",
                    "Workspace Repository access content changed before operation reservation was bound",
                ));
            }
            authorize_repository_materialization(
                api,
                &operation.resolved_runtime_id,
                &operation.operation_id,
                &projection,
                request,
            )?;
            let context = request.materialization.take().ok_or_else(|| {
                settings_bad_request(
                    "working_directory_remote_repository_access_required",
                    "SSH Repository access authority is unavailable",
                )
            })?;
            let ssh = context.ssh.as_ref().ok_or_else(|| {
                settings_bad_request(
                    "working_directory_remote_repository_access_required",
                    "SSH Repository access authority is unavailable",
                )
            })?;
            let primary_credential = ssh.credential_candidates.first().ok_or_else(|| {
                settings_bad_request(
                    "working_directory_repository_access_invalid",
                    "Repository SSH access has no credential candidates",
                )
            })?;
            let credential_candidates = ssh
                .credential_candidates
                .iter()
                .enumerate()
                .map(|(index, candidate)| WorkdirCreateCredentialCandidate {
                    role: if index == 0 {
                        WorkdirCreateCredentialCandidateRole::Primary
                    } else {
                        WorkdirCreateCredentialCandidateRole::WorkspaceDefaultFallback
                    },
                    credential_id: candidate.credential_id.clone(),
                    credential_fingerprint: candidate.public_key_fingerprint.clone(),
                })
                .collect::<Vec<_>>();
            api.config_store.bind_workdir_create_repository_access(
                &api.config.workspace_id,
                &operation.operation_id,
                request_fingerprint,
                &primary_credential.credential_id,
                &primary_credential.public_key_fingerprint,
                &ssh.host_trust_id,
                &ssh.host_key_fingerprint,
                match ssh.access {
                    server_api::RepositoryAccessMode::ReadOnly => "read_only",
                    server_api::RepositoryAccessMode::ReadWrite => "read_write",
                },
                &credential_candidates,
                &now_registry_timestamp(),
            )?;
            context
        }
    } else {
        RepositoryMaterializationContext {
            workspace_id: api.config.workspace_id.clone(),
            runtime_id: operation.resolved_runtime_id.clone(),
            operation_id: operation.operation_id.clone(),
            config_projection_digest: operation.config_projection_digest.clone(),
            ssh: None,
        }
    };
    request.materialization = Some(context);
    Ok(())
}

fn repository_access_expiry() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
        .saturating_add(300)
}

fn authorize_worker_spawn_workdir_materialization(
    api: &WorkspaceApi,
    runtime_id: &str,
    operation_id: &str,
    request: &mut WorkingDirectoryRequest,
) -> ApiResult<()> {
    let projection = active_repository_access_projection(api, &api.config.workspace_id)?;
    authorize_repository_materialization(api, runtime_id, operation_id, &projection, request)
}

fn repository_ssh_lease_candidates_from_operation(
    api: &WorkspaceApi,
    operation: &WorkdirCreateOperationRecord,
    request: &WorkingDirectoryRequest,
) -> ApiResult<Vec<crate::repository_access::LeasedRepositorySshAccess>> {
    if operation.repository_id != request.repository.id
        || operation.source_kind.as_deref() != Some(request.repository.source.kind.as_str())
        || operation.source_uri.as_deref() != Some(request.repository.source.uri.as_str())
        || operation.source_fingerprint.as_deref()
            != Some(request.repository.source_fingerprint.as_str())
    {
        return Err(settings_bad_request(
            "working_directory_repository_access_snapshot_mismatch",
            "persisted Workdir Repository access snapshot does not match the create request",
        ));
    }
    let host_trust_id = operation.host_trust_id.as_deref().ok_or_else(|| {
        settings_bad_request(
            "working_directory_repository_access_snapshot_missing",
            "persisted Workdir Repository access snapshot is incomplete",
        )
    })?;
    let host_trust_fingerprint = operation.host_trust_fingerprint.as_deref().ok_or_else(|| {
        settings_bad_request(
            "working_directory_repository_access_snapshot_missing",
            "persisted Workdir Repository access snapshot is incomplete",
        )
    })?;
    if operation.credential_candidates.is_empty() {
        return Err(settings_bad_request(
            "working_directory_repository_access_snapshot_missing",
            "persisted Workdir credential candidate snapshot is unavailable",
        ));
    }
    let primary_credential_id = operation.credential_id.as_deref().ok_or_else(|| {
        settings_bad_request(
            "working_directory_repository_access_snapshot_missing",
            "persisted Workdir primary credential evidence is unavailable",
        )
    })?;
    let primary_credential_fingerprint =
        operation.credential_fingerprint.as_deref().ok_or_else(|| {
            settings_bad_request(
                "working_directory_repository_access_snapshot_missing",
                "persisted Workdir primary credential evidence is unavailable",
            )
        })?;
    crate::workdir_create_operations::validate_workdir_create_credential_candidates(
        primary_credential_id,
        primary_credential_fingerprint,
        &operation.credential_candidates,
    )
    .map_err(|_error| {
        settings_bad_request(
            "working_directory_repository_access_snapshot_invalid",
            "persisted Workdir credential candidate snapshot is invalid",
        )
    })?;
    let _access_mode = operation
        .repository_access_mode
        .as_deref()
        .map(|access_mode| match access_mode {
            "read_only" => Ok(server_api::RepositoryAccessMode::ReadOnly),
            "read_write" => Ok(server_api::RepositoryAccessMode::ReadWrite),
            _other => Err(settings_bad_request(
                "working_directory_repository_access_snapshot_invalid",
                "persisted Repository access mode is invalid",
            )),
        })
        .transpose()?
        .ok_or_else(|| {
            settings_bad_request(
                "working_directory_repository_access_snapshot_missing",
                "persisted Workdir Repository access mode is unavailable",
            )
        })?;

    let mut leases = Vec::with_capacity(operation.credential_candidates.len());
    for candidate in &operation.credential_candidates {
        let lease = api
            .repository_secrets
            .lease_ssh_materialization_access_fingerprints(
                &api.config.workspace_id,
                &candidate.credential_id,
                &candidate.credential_fingerprint,
                host_trust_id,
                host_trust_fingerprint,
            )
            .map_err(|_| {
                settings_bad_request(
                    "working_directory_repository_access_snapshot_unavailable",
                    "persisted Workdir credential or host-key identity is unavailable",
                )
            })?;
        if lease.host_trust_id != host_trust_id
            || lease.host_trust_fingerprint != host_trust_fingerprint
        {
            return Err(settings_bad_request(
                "working_directory_repository_access_snapshot_mismatch",
                "persisted Workdir host-trust snapshot does not match the credential candidate",
            ));
        }
        leases.push(lease);
    }
    Ok(leases)
}

fn authorize_repository_materialization(
    api: &WorkspaceApi,
    runtime_id: &str,
    operation_id: &str,
    projection: &RepositoryAccessProjection,
    request: &mut WorkingDirectoryRequest,
) -> ApiResult<()> {
    let repository_key = api
        .config
        .repositories
        .iter()
        .find(|repository| repository.id == request.repository.id)
        .map(|repository| repository.repository_key.as_str())
        .ok_or_else(|| Error::UnknownRepository(request.repository.id.clone()))?;
    let ssh = if request.repository.source.kind == server_api::RepositorySourceKind::Ssh {
        let binding = match projection
            .bindings
            .iter()
            .find(|binding| binding.repository_key == repository_key)
            .cloned()
        {
            Some(binding) => binding,
            None => api
                .repository_secrets
                .default_ssh_binding_for_repository(
                    &api.config.workspace_id,
                    repository_key,
                    &request.repository.source.uri,
                )?
                .ok_or_else(|| {
                    settings_bad_request(
                        "working_directory_remote_repository_host_trust_required",
                        "SSH Repository has no pinned host trust matching its URI",
                    )
                })?,
        };
        let lease = api
            .repository_secrets
            .lease_ssh_materialization_access(&api.config.workspace_id, &binding)?;
        let leases = repository_ssh_lease_candidates(api, lease)?;
        let primary_lease = leases.first().ok_or_else(|| {
            settings_bad_request(
                "working_directory_repository_access_invalid",
                "Repository SSH access has no credential candidates",
            )
        })?;
        let primary_host_trust_id = primary_lease.host_trust_id.clone();
        let primary_host_trust_fingerprint = primary_lease.host_trust_fingerprint.clone();
        let known_hosts_entry = primary_lease.known_hosts_entry.clone();
        let expires_at_epoch_seconds = repository_access_expiry();
        let secret_resource = api
            .resource_broker
            .issue_repository_ssh_access_handle(
                &api.config.workspace_id,
                runtime_id,
                format!("repository-ssh-access:{operation_id}"),
                i64::try_from(expires_at_epoch_seconds).unwrap_or(i64::MAX),
                worker_runtime::resource::RepositorySshAccessSecret {
                    credential_candidates: leases
                        .iter()
                        .map(
                            |lease| worker_runtime::resource::RepositorySshAccessSecretCandidate {
                                credential_id: lease.credential_id.clone(),
                                public_key_fingerprint: lease.credential_fingerprint.clone(),
                                private_key: lease.private_key.as_str().to_string(),
                            },
                        )
                        .collect(),
                    known_hosts_entry: known_hosts_entry.clone(),
                },
            )
            .map_err(|_| {
                settings_bad_request(
                    "working_directory_repository_access_resource_failed",
                    "Repository SSH access resource could not be issued",
                )
            })?;
        Some(RepositorySshMaterializationAccess {
            credential_candidates: leases
                .into_iter()
                .map(|lease| RepositorySshCredentialCandidate {
                    credential_id: lease.credential_id,
                    public_key_fingerprint: lease.credential_fingerprint.clone(),
                    private_key: SensitiveString::default(),
                })
                .collect(),
            host_trust_id: primary_host_trust_id,
            host_key_fingerprint: primary_host_trust_fingerprint,
            access: binding.access,
            expires_at_epoch_seconds,
            repository_id: request.repository.id.clone(),
            repository_source_fingerprint: request.repository.source_fingerprint.clone(),
            repository_uri: request.repository.source.uri.clone(),
            secret_resource,
            known_hosts_entry: SensitiveString::default(),
        })
    } else {
        None
    };
    request.materialization = Some(RepositoryMaterializationContext {
        workspace_id: api.config.workspace_id.clone(),
        runtime_id: runtime_id.to_string(),
        operation_id: operation_id.to_string(),
        config_projection_digest: projection.projection_digest.clone(),
        ssh,
    });
    Ok(())
}

fn repository_access_request_for_workdir(
    api: &WorkspaceApi,
    runtime_id: &str,
    working_directory_id: &str,
    operation_id: &str,
) -> ApiResult<Option<worker_runtime::catalog::WorkingDirectoryRepositoryAccessRequest>> {
    let record = api
        .config_store
        .get_workdir_registry(&api.config.workspace_id, working_directory_id)?
        .ok_or_else(|| {
            settings_bad_request(
                "working_directory_not_found",
                "Working directory is not registered in this Workspace",
            )
        })?;
    let WorkdirRegistrySource::Repository {
        runtime_id: record_runtime_id,
        repository_id,
    } = &record.source
    else {
        return Ok(None);
    };
    if record_runtime_id != runtime_id {
        return Err(settings_bad_request(
            "working_directory_runtime_mismatch",
            "Working directory is owned by a different Runtime",
        ));
    }
    let repository = api.require_configured_workspace_repository(repository_id)?;
    if repository.source.kind != server_api::RepositorySourceKind::Ssh {
        return Ok(None);
    }
    let projection = active_repository_access_projection(api, &api.config.workspace_id)?;
    let mut request = working_directory_request_from_repository(&repository, None);
    authorize_repository_materialization(api, runtime_id, operation_id, &projection, &mut request)?;
    Ok(Some(
        worker_runtime::catalog::WorkingDirectoryRepositoryAccessRequest {
            working_directory_id: working_directory_id.to_string(),
            materialization: request.materialization.ok_or_else(|| {
                settings_bad_request(
                    "working_directory_remote_repository_access_required",
                    "SSH Repository access authority is unavailable",
                )
            })?,
        },
    ))
}

fn working_directory_request_for_browser(
    api: &WorkspaceApi,
    request: BrowserWorkingDirectoryCreateRequest,
) -> ApiResult<WorkingDirectoryRequest> {
    let repository = api.require_configured_workspace_repository_by_key(&request.repository_key)?;
    let display_name = request
        .display_name
        .as_deref()
        .map(str::trim)
        .filter(|name| !name.is_empty())
        .map(str::to_string);
    if display_name
        .as_deref()
        .is_some_and(|name| name.len() > 120 || name.chars().any(char::is_control))
    {
        return Err(settings_bad_request(
            "working_directory_display_name_invalid",
            "display_name must be at most 120 bytes and contain no control characters",
        ));
    }
    let selector = request
        .selector
        .or_else(|| repository.default_selector.clone())
        .filter(|selector| !selector.trim().is_empty());
    Ok(WorkingDirectoryRequest {
        repository: WorkingDirectoryRepository {
            id: repository.id.clone(),
            provider: "git".to_string(),
            source: repository.source.clone(),
            source_fingerprint: repository.source_fingerprint.clone(),
            selector: selector.map(RuntimeRepositorySelector),
        },
        display_name,
        materializer: MaterializerKind::RuntimeGitClone,
        backend_workdir_id: None,
        materialization: None,
    })
}

fn parse_runtime_worker_id_for_registry(worker_id: &str) -> ApiResult<WorkerId> {
    worker_id.parse::<WorkerId>().map_err(|_| {
        settings_bad_request(
            "workspace_worker_id_invalid",
            "Workspace Worker id must be a UUIDv7",
        )
    })
}

fn sanitize_worker_display_name(value: &str) -> Option<String> {
    let display_name = value.trim();
    if display_name.chars().any(char::is_control) {
        None
    } else if display_name.is_empty() {
        Some("Worker".to_string())
    } else {
        Some(display_name.chars().take(80).collect())
    }
}

fn encode_path_segment(value: &str) -> String {
    value
        .bytes()
        .flat_map(|byte| match byte {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                vec![byte as char]
            }
            _ => format!("%{byte:02X}").chars().collect(),
        })
        .collect()
}

fn worker_create_not_accepted_error(
    runtime_id: String,
    mut diagnostics: Vec<RuntimeDiagnostic>,
) -> ApiError {
    diagnostics.push(settings_diagnostic(
        "workspace_worker_create_not_accepted",
        HostDiagnosticSeverity::Error,
        "Runtime did not accept worker creation; see diagnostics for sanitized Runtime compatibility details.",
    ));
    ApiError::with_diagnostics(
        Error::RuntimeOperationFailed {
            runtime_id,
            code: "workspace_worker_create_failed".to_string(),
            message: "Runtime did not accept worker creation".to_string(),
        },
        diagnostics,
    )
}

fn settings_bad_request(code: &'static str, message: &'static str) -> ApiError {
    ApiError::with_diagnostics(
        Error::InvalidInput(format!("{code}: {message}")),
        vec![settings_diagnostic(
            code,
            HostDiagnosticSeverity::Error,
            message,
        )],
    )
}

fn settings_diagnostic(
    code: impl Into<String>,
    severity: HostDiagnosticSeverity,
    message: impl Into<String>,
) -> RuntimeDiagnostic {
    RuntimeDiagnostic {
        code: code.into(),
        severity,
        message: message.into(),
    }
}

fn sanitize_backend_error(message: &str) -> String {
    message.to_string()
}

fn repository_lookup<T>(result: std::result::Result<T, RepositoryLookupError>) -> ApiResult<T> {
    result.map_err(|error| match error {
        RepositoryLookupError::UnknownRepository { id } => {
            let message = format!("repository `{id}` is not configured for this workspace");
            ApiError::with_diagnostics(
                Error::RuntimeOperationFailed {
                    runtime_id: "workspace-repository-registry".to_string(),
                    code: "repository_not_configured".to_string(),
                    message: message.clone(),
                },
                vec![RuntimeDiagnostic {
                    code: "repository_not_configured".to_string(),
                    severity: HostDiagnosticSeverity::Error,
                    message,
                }],
            )
        }
        RepositoryLookupError::UnsupportedProvider { id, provider } => {
            let message = format!(
                "repository `{id}` uses unsupported provider `{provider}` for this operation"
            );
            ApiError::with_diagnostics(
                Error::RuntimeOperationFailed {
                    runtime_id: "workspace-repository-registry".to_string(),
                    code: "repository_provider_unsupported".to_string(),
                    message: message.clone(),
                },
                vec![RuntimeDiagnostic {
                    code: "repository_provider_unsupported".to_string(),
                    severity: HostDiagnosticSeverity::Error,
                    message,
                }],
            )
        }
        other => {
            let message = format!("repository evidence validation failed: {other:?}");
            ApiError::with_diagnostics(
                Error::RuntimeOperationFailed {
                    runtime_id: "workspace-repository-registry".to_string(),
                    code: "repository_evidence_invalid".to_string(),
                    message: message.clone(),
                },
                vec![RuntimeDiagnostic {
                    code: "repository_evidence_invalid".to_string(),
                    severity: HostDiagnosticSeverity::Error,
                    message,
                }],
            )
        }
    })
}

async fn static_or_spa_fallback(State(api): State<WorkspaceApi>, uri: Uri) -> Response {
    if uri.path().starts_with("/api/") || uri.path() == "/api" {
        return (
            StatusCode::NOT_FOUND,
            [(CONTENT_TYPE, "application/json")],
            Json(serde_json::json!({
                "error": "not_found",
                "message": "unknown api route"
            }))
            .to_string(),
        )
            .into_response();
    }

    if let Some(workspace_id) = workspace_id_from_ui_path(uri.path()) {
        if workspace_id != api.workspace_id() {
            return workspace_id_mismatch_error().into_response();
        }
    }

    if let Some(location) =
        unscoped_workspace_ui_redirect(uri.path(), uri.query(), api.workspace_id())
    {
        return (StatusCode::TEMPORARY_REDIRECT, [(LOCATION, location)]).into_response();
    }

    let Some(static_root) = api.config.static_assets_dir.as_ref() else {
        return StatusCode::NOT_FOUND.into_response();
    };

    static_file_or_spa_response(static_root, scoped_workspace_static_path(uri.path())).await
}

fn unscoped_workspace_ui_redirect(
    path: &str,
    query: Option<&str>,
    workspace_id: &str,
) -> Option<String> {
    let scoped_tail = if ["/repositories", "/objectives", "/settings", "/runtimes"]
        .iter()
        .any(|prefix| path == *prefix || path.starts_with(&format!("{prefix}/")))
    {
        path
    } else {
        return None;
    };

    let mut location = format!("/w/{}{}", encode_path_segment(workspace_id), scoped_tail);
    if let Some(query) = query.filter(|query| !query.is_empty()) {
        location.push('?');
        location.push_str(query);
    }
    Some(location)
}

fn workspace_id_from_ui_path(path: &str) -> Option<&str> {
    let tail = path.strip_prefix("/w/")?;
    let workspace_id = tail.split('/').next().unwrap_or_default();
    if workspace_id.is_empty() {
        None
    } else {
        Some(workspace_id)
    }
}

struct StaticAsset {
    bytes: Vec<u8>,
    content_type: &'static str,
}

async fn static_file_or_spa_response(static_root: &Path, request_path: &str) -> Response {
    match read_static_or_index(static_root, request_path).await {
        Ok(StaticAsset {
            bytes,
            content_type,
        }) => (StatusCode::OK, [(CONTENT_TYPE, content_type)], bytes).into_response(),
        Err(error) => {
            tracing::debug!(%error, path = request_path, "failed to serve static asset");
            StatusCode::NOT_FOUND.into_response()
        }
    }
}

fn scoped_workspace_static_path(path: &str) -> &str {
    let Some(scoped) = path.strip_prefix("/w/") else {
        return path;
    };
    match scoped.find('/') {
        Some(index) => &scoped[index..],
        None => "/",
    }
}

async fn read_static_or_index(root: &Path, request_path: &str) -> Result<StaticAsset> {
    let candidate = safe_static_candidate(root, request_path)?;
    let file = if tokio::fs::metadata(&candidate)
        .await
        .map(|m| m.is_file())
        .unwrap_or(false)
    {
        candidate
    } else {
        root.join("index.html")
    };
    let content_type = content_type_for(&file);
    let bytes = tokio::fs::read(file).await?;
    Ok(StaticAsset {
        bytes,
        content_type,
    })
}

fn safe_static_candidate(root: &Path, request_path: &str) -> Result<PathBuf> {
    let mut path = root.to_path_buf();
    let clean = request_path.trim_start_matches('/');
    if clean.is_empty() {
        path.push("index.html");
        return Ok(path);
    }
    for component in Path::new(clean).components() {
        match component {
            Component::Normal(part) => path.push(part),
            Component::CurDir => {}
            _ => return Err(Error::Store("static path escape rejected".to_string())),
        }
    }
    Ok(path)
}

fn content_type_for(path: &Path) -> &'static str {
    match path
        .extension()
        .and_then(|ext| ext.to_str())
        .unwrap_or_default()
    {
        "css" => "text/css; charset=utf-8",
        "js" => "text/javascript; charset=utf-8",
        "json" => "application/json",
        "svg" => "image/svg+xml",
        "html" | "" => "text/html; charset=utf-8",
        _ => "application/octet-stream",
    }
}

type ApiResult<T> = std::result::Result<T, ApiError>;

fn workspace_id_mismatch_error() -> ApiError {
    let message = "workspace id does not match this Workspace backend".to_string();
    ApiError::with_diagnostics(
        Error::WorkspaceIdMismatch,
        vec![RuntimeDiagnostic {
            code: "workspace_id_mismatch".to_string(),
            severity: HostDiagnosticSeverity::Error,
            message,
        }],
    )
}

#[derive(Debug)]
struct ApiError {
    error: Error,
    diagnostics: Vec<RuntimeDiagnostic>,
}

#[derive(Debug, Clone)]
struct ApiErrorLog {
    kind: String,
    message: String,
    diagnostics: Vec<RuntimeDiagnostic>,
    workdir_log: Option<server_api::WorkdirOperationLogContext>,
    denial_reason: Option<workdir::WorkdirDenialReason>,
    failure_reason: Option<workdir::WorkdirFailureReason>,
}

impl ApiErrorLog {
    fn from_workdir_operation_error(
        error: &server_api::WorkdirOperationApiError,
        status: StatusCode,
    ) -> Self {
        if let Some(code) = error.code {
            return Self {
                kind: format!("workdir_session_operation_{}", code.as_str()),
                message: sanitize_backend_error(&error.message),
                diagnostics: Vec::new(),
                workdir_log: error.workdir_log.clone(),
                denial_reason: error.denial_reason,
                failure_reason: error.failure_reason,
            };
        }
        let mut log = Self::from_repository_error(&server_api::RepositoryApiError::new(
            status.as_u16(),
            error.error.as_deref().unwrap_or_else(|| {
                status
                    .canonical_reason()
                    .unwrap_or("Workdir operation failed")
            }),
            &error.message,
            error.diagnostics.clone().unwrap_or_default(),
        ));
        log.workdir_log = error.workdir_log.clone();
        log.denial_reason = error.denial_reason;
        log.failure_reason = error.failure_reason;
        if log.workdir_log.is_some() {
            // Public classification and arbitrary diagnostic text are not safe
            // operational causes. Keep only the separately typed reason/stage;
            // never infer a reason by parsing request- or provider-authored text.
            log.kind = format!("workdir_session_operation_api_{}", status.as_u16());
            // This can also fail after a command was dispatched. Do not claim
            // a pre-dispatch refusal or absence of effects in the safe message.
            log.message = "Workdir operation failed".to_string();
            log.diagnostics.clear();
        }
        log
    }

    fn from_repository_error(error: &server_api::RepositoryApiError) -> Self {
        Self {
            workdir_log: None,
            denial_reason: None,
            failure_reason: None,
            kind: error
                .diagnostics
                .first()
                .map(|diagnostic| diagnostic.code.clone())
                .unwrap_or_else(|| error.error.to_ascii_lowercase().replace(' ', "_")),
            message: sanitize_backend_error(&error.message),
            diagnostics: error
                .diagnostics
                .iter()
                .map(|diagnostic| RuntimeDiagnostic {
                    code: diagnostic.code.clone(),
                    severity: match diagnostic.severity {
                        server_api::DiagnosticSeverity::Info => HostDiagnosticSeverity::Info,
                        server_api::DiagnosticSeverity::Warning => HostDiagnosticSeverity::Warning,
                        server_api::DiagnosticSeverity::Error => HostDiagnosticSeverity::Error,
                    },
                    message: sanitize_backend_error(&diagnostic.message),
                })
                .collect(),
        }
    }
}

impl From<merge_request::MergeRequestError> for ApiError {
    fn from(error: merge_request::MergeRequestError) -> Self {
        Error::MergeRequest(error).into()
    }
}

impl From<Error> for server_api::RepositoryApiError {
    fn from(error: Error) -> Self {
        ApiError::from(error).into_repository_api_error()
    }
}

impl From<Error> for server_api::RuntimeManagementApiError {
    fn from(error: Error) -> Self {
        Self::from(server_api::RepositoryApiError::from(error))
    }
}

impl From<Error> for ApiError {
    fn from(error: Error) -> Self {
        let diagnostics = match &error {
            Error::DbCapacityExceeded
            | Error::DbExecutorUnavailable
            | Error::DbOperationOutcomeUnknown => vec![RuntimeDiagnostic {
                code: match &error {
                    Error::DbCapacityExceeded => "db_capacity_exceeded",
                    Error::DbExecutorUnavailable => "db_executor_unavailable",
                    _ => "db_operation_outcome_unknown",
                }
                .into(),
                severity: HostDiagnosticSeverity::Error,
                message: error.to_string(),
            }],
            Error::WorkdirSessionOpenFailed { transport, .. } => vec![RuntimeDiagnostic {
                code: "workdir_session_open_failed".to_string(),
                severity: HostDiagnosticSeverity::Error,
                message: transport.message.clone(),
            }],
            Error::RuntimeOperationFailed { code, message, .. } => vec![RuntimeDiagnostic {
                code: code.clone(),
                severity: HostDiagnosticSeverity::Error,
                message: sanitize_backend_error(message),
            }],
            Error::WorkspaceSigningIdentity { code, message } => vec![RuntimeDiagnostic {
                code: code.clone(),
                severity: HostDiagnosticSeverity::Error,
                message: sanitize_backend_error(message),
            }],
            Error::Ticket(ticket_error) => vec![RuntimeDiagnostic {
                code: match ticket_error {
                    ticket::TicketError::NotFound(_) => "ticket_not_found",
                    ticket::TicketError::Ambiguous { .. } => "ticket_ambiguous",
                    ticket::TicketError::Locked { .. } => "ticket_locked",
                    ticket::TicketError::Conflict(_)
                    | ticket::TicketError::StaleWorkflowState { .. }
                    | ticket::TicketError::StaleClosureOperationKey { .. }
                    | ticket::TicketError::StaleContent { .. }
                    | ticket::TicketError::InvalidWorkflowTransition { .. }
                    | ticket::TicketError::BlockingRelations(_)
                    | ticket::TicketError::OperationFingerprintMismatch { .. } => "ticket_conflict",
                    ticket::TicketError::MissingTargetRepository => {
                        "ticket_target_repository_missing"
                    }
                    ticket::TicketError::UnknownTargetRepository(_) => {
                        "ticket_target_repository_unknown"
                    }
                    ticket::TicketError::MissingTargetSelector(_) => {
                        "ticket_target_selector_missing"
                    }
                    ticket::TicketError::InvalidTargetSelector { .. } => {
                        "ticket_target_selector_invalid"
                    }
                    ticket::TicketError::DuplicateTargetRepository(_) => {
                        "ticket_target_repository_duplicate"
                    }
                    ticket::TicketError::InvalidReadWriteTargetCount(_) => {
                        "ticket_target_read_write_count_invalid"
                    }
                    ticket::TicketError::TargetAuthorityUnavailable => {
                        "ticket_target_authority_unavailable"
                    }
                    ticket::TicketError::InvalidPathComponent(_)
                    | ticket::TicketError::PathEscapesRoot { .. } => "invalid_ticket_request",
                    ticket::TicketError::Io { .. }
                    | ticket::TicketError::Parse { .. }
                    | ticket::TicketError::Sqlite(_) => "ticket_backend_error",
                }
                .to_string(),
                severity: HostDiagnosticSeverity::Error,
                message: sanitize_backend_error(&ticket_error.to_string()),
            }],
            Error::RepositoryConflict(message) | Error::WorkspacePermissionDenied(message) => {
                subjektiv_diagnostic_code(message)
                    .map(|code| {
                        vec![RuntimeDiagnostic {
                            code: code.to_string(),
                            severity: HostDiagnosticSeverity::Error,
                            message: sanitize_backend_error(message),
                        }]
                    })
                    .unwrap_or_default()
            }
            _ => Vec::new(),
        };
        Self { error, diagnostics }
    }
}

fn subjektiv_diagnostic_code(message: &str) -> Option<&'static str> {
    [
        "change_conflict",
        "stale_cursor",
        "candidate_decision_conflict",
        "subject_scope_mismatch",
    ]
    .into_iter()
    .find(|code| message.starts_with(code))
}

impl ApiError {
    fn with_diagnostics(error: Error, diagnostics: Vec<RuntimeDiagnostic>) -> Self {
        Self { error, diagnostics }
    }

    fn into_repository_api_error(self) -> server_api::RepositoryApiError {
        let status = api_error_status(&self.error);
        let message = api_error_response_message(&self.error);
        server_api::RepositoryApiError::new(
            status.as_u16(),
            match self.error {
                Error::RestoreObservationConflict => "restore_observation_conflict",
                Error::RuntimeBindingIdConflict { .. } => "stale_binding",
                Error::RuntimeBindingFingerprintConflict { .. } => "fingerprint_in_use",
                _ => status.canonical_reason().unwrap_or("error"),
            },
            message,
            working_directory_diagnostics(self.diagnostics),
        )
    }
}

fn api_error_status(error: &Error) -> StatusCode {
    match error {
        Error::RuntimeOperationFailed {
            runtime_id, code, ..
        } if runtime_id == "workspace-auth" && code == "auth_required" => StatusCode::FORBIDDEN,
        Error::RuntimeOperationFailed { runtime_id, .. } if runtime_id == "workspace-auth" => {
            StatusCode::BAD_REQUEST
        }
        Error::BrowserReopenConfirmationRequired | Error::WorkspacePermissionDenied(_) => {
            StatusCode::FORBIDDEN
        }
        Error::TicketAssignmentConflict(_)
        | Error::WorkdirAttachmentConflict(_)
        | Error::WorkspaceConfigConflict(_)
        | Error::RuntimeBindingConflict(_)
        | Error::RuntimeBindingIdConflict { .. }
        | Error::RuntimeBindingFingerprintConflict { .. }
        | Error::RepositoryConflict(_)
        | Error::RestoreObservationConflict => StatusCode::CONFLICT,
        Error::WorkerSourceIdentity(_) => StatusCode::BAD_REQUEST,
        Error::InvalidInput(message)
            if message.starts_with("memory_not_found:")
                || message.starts_with("memory_change_not_found:") =>
        {
            StatusCode::NOT_FOUND
        }
        Error::InvalidInput(_) => StatusCode::BAD_REQUEST,
        Error::InvalidRuntimeIdentifier { .. } | Error::ReservedWorkerName(_) => {
            StatusCode::BAD_REQUEST
        }
        Error::Ticket(ticket::TicketError::NotFound(_))
        | Error::MergeRequest(merge_request::MergeRequestError::NotFound) => StatusCode::NOT_FOUND,
        Error::MergeRequest(merge_request::MergeRequestError::Validation(_)) => {
            StatusCode::BAD_REQUEST
        }
        Error::MergeRequest(_) => StatusCode::CONFLICT,
        Error::Ticket(
            ticket::TicketError::Ambiguous { .. }
            | ticket::TicketError::Locked { .. }
            | ticket::TicketError::Conflict(_)
            | ticket::TicketError::StaleContent { .. }
            | ticket::TicketError::StaleWorkflowState { .. }
            | ticket::TicketError::StaleClosureOperationKey { .. }
            | ticket::TicketError::OperationFingerprintMismatch { .. },
        ) => StatusCode::CONFLICT,
        Error::Ticket(
            ticket::TicketError::InvalidPathComponent(_)
            | ticket::TicketError::PathEscapesRoot { .. },
        ) => StatusCode::BAD_REQUEST,
        Error::InvalidRecordId(_)
        | Error::MissingFrontmatter(_)
        | Error::UnknownHost(_)
        | Error::UnknownRuntime(_)
        | Error::UnknownWorker { .. }
        | Error::UnknownRepository(_)
        | Error::SubjektivSubjectNotFound(_)
        | Error::RuntimeBindingNotFound { .. }
        | Error::WorkspaceIdMismatch => StatusCode::NOT_FOUND,
        Error::RuntimeOperationFailed { code, .. } if code == "skill_not_found" => {
            StatusCode::NOT_FOUND
        }
        Error::RuntimeCapabilityUnsupported { .. } => StatusCode::NOT_IMPLEMENTED,
        Error::RuntimeOperationFailed { code, .. } if code == "repository_not_configured" => {
            StatusCode::NOT_FOUND
        }
        Error::RuntimeOperationFailed { code, .. } if code == "repository_provider_unsupported" => {
            StatusCode::BAD_REQUEST
        }
        Error::RuntimeOperationFailed { code, .. } if code == "remote_runtime_auth_failed" => {
            StatusCode::UNAUTHORIZED
        }
        Error::RuntimeOperationFailed { code, .. } if code == "remote_runtime_timeout" => {
            StatusCode::GATEWAY_TIMEOUT
        }
        Error::RuntimeOperationFailed { code, .. } if code == "remote_runtime_unsupported" => {
            StatusCode::NOT_IMPLEMENTED
        }
        Error::RuntimeOperationFailed { code, .. }
            if code == "workspace_metadata_updated_at_conflict"
                || code == "workspace_cleanup_plan_stale"
                || code == "workspace_cleanup_worker_blocked"
                || code == "workspace_cleanup_workdir_blocked"
                || code == "workspace_cleanup_worker_pinned" =>
        {
            StatusCode::CONFLICT
        }
        Error::RuntimeOperationFailed { code, .. }
            if code == "unknown_profile_source"
                || code == "unknown_profile_selector"
                || code == "unknown_objective" =>
        {
            StatusCode::NOT_FOUND
        }
        Error::RuntimeOperationFailed { code, .. }
            if code == "workspace_display_name_invalid" || code.starts_with("profile_") =>
        {
            StatusCode::BAD_REQUEST
        }
        Error::RuntimeOperationFailed { code, .. } if code.ends_with("_blocked") => {
            StatusCode::CONFLICT
        }
        Error::RuntimeOperationFailed { code, .. }
            if code.starts_with("workspace_settings_")
                || code.starts_with("invalid_")
                || code.starts_with("unsupported_worker_profile")
                || code.starts_with("working_directory_")
                || code.starts_with("workspace_cleanup_")
                || code == "default_runtime_not_configured"
                || code == "workspace_worker_workdir_required"
                || code.ends_with("_already_exists")
                || code.ends_with("_not_config_managed")
                || code.ends_with("_unsupported") =>
        {
            StatusCode::BAD_REQUEST
        }
        Error::RuntimeOperationFailed { code, .. }
            if code == "runtime_capacity_unavailable"
                || code == "runtime_workdir_capacity_unavailable" =>
        {
            StatusCode::SERVICE_UNAVAILABLE
        }
        Error::DbCapacityExceeded | Error::DbExecutorUnavailable => StatusCode::SERVICE_UNAVAILABLE,
        Error::DbOperationOutcomeUnknown => StatusCode::SERVICE_UNAVAILABLE,
        Error::WorkspaceSigningIdentity { .. } => StatusCode::SERVICE_UNAVAILABLE,
        Error::WorkdirSessionOpenFailed { .. } | Error::RuntimeOperationFailed { .. } => {
            StatusCode::BAD_GATEWAY
        }
        _ => StatusCode::INTERNAL_SERVER_ERROR,
    }
}

fn api_error_response_message(error: &Error) -> String {
    match error {
        Error::WorkdirSessionOpenFailed { transport, .. } => {
            format!("workdir_session_open_failed: {}", transport.message)
        }
        Error::RuntimeOperationFailed { code, message, .. } => {
            format!("{code}: {}", sanitize_backend_error(message))
        }
        _ => sanitize_backend_error(&error.to_string()),
    }
}

impl IntoResponse for ApiError {
    fn into_response(self) -> Response {
        let status = api_error_status(&self.error);
        let response_message = api_error_response_message(&self.error);
        let log = ApiErrorLog {
            workdir_log: None,
            denial_reason: None,
            failure_reason: None,
            kind: self
                .diagnostics
                .first()
                .map(|diagnostic| diagnostic.code.clone())
                .unwrap_or_else(|| {
                    status
                        .canonical_reason()
                        .unwrap_or("api_error")
                        .to_ascii_lowercase()
                        .replace(' ', "_")
                }),
            message: response_message.clone(),
            diagnostics: self.diagnostics.clone(),
        };
        let mut response = (
            status,
            [(CONTENT_TYPE, "application/json")],
            Json(serde_json::json!({
                "error": status.canonical_reason().unwrap_or("error"),
                "message": response_message,
                "diagnostics": self.diagnostics,
            }))
            .to_string(),
        )
            .into_response();
        response.extensions_mut().insert(log);
        response
    }
}

