    fn valid_gif_with_len(target_len: usize) -> Vec<u8> {
        let fixture = include_bytes!("../../tools/tests/fixtures/view-image/valid.gif");
        assert_eq!(fixture.last(), Some(&0x3b));
        let mut bytes = fixture[..fixture.len() - 1].to_vec();
        bytes.extend_from_slice(&[0x21, 0xfe]);
        let mut remaining = target_len.checked_sub(bytes.len() + 2).unwrap();
        while remaining > 0 {
            let mut block = remaining.min(256);
            if remaining - block == 1 {
                block -= 1;
            }
            bytes.push((block - 1) as u8);
            bytes.extend(std::iter::repeat_n(b'x', block - 1));
            remaining -= block;
        }
        bytes.extend_from_slice(&[0, 0x3b]);
        assert_eq!(bytes.len(), target_len);
        bytes
    }

    #[test]
    fn resident_summary_transport_preserves_ready_empty_state() {
        let output = resident_summary_output(crate::subjektiv::ResidentSurface {
            availability: crate::subjektiv::SurfaceAvailability::Ready,
            snapshot: Some(crate::subjektiv::SurfaceSnapshot {
                schema_version: 1,
                id: "surface-empty".into(),
                subject_id: "subject-a".into(),
                body_md: String::new(),
                memory_refs: Vec::new(),
                built_from_memory_fingerprint: "memory-empty".into(),
                created_at: "2026-10-02T00:00:00Z".into(),
            }),
        });

        assert_eq!(
            output.availability,
            memory::backend::MemoryResidentSummaryAvailability::Ready
        );
        assert_eq!(output.content, None);

        for (surface, expected) in [
            (
                crate::subjektiv::SurfaceAvailability::Ungenerated,
                memory::backend::MemoryResidentSummaryAvailability::Ungenerated,
            ),
            (
                crate::subjektiv::SurfaceAvailability::Stale,
                memory::backend::MemoryResidentSummaryAvailability::Stale,
            ),
            (
                crate::subjektiv::SurfaceAvailability::Failed,
                memory::backend::MemoryResidentSummaryAvailability::Failed,
            ),
        ] {
            let output = resident_summary_output(crate::subjektiv::ResidentSurface {
                availability: surface,
                snapshot: None,
            });
            assert_eq!(output.availability, expected);
            assert_eq!(output.content, None);
        }
    }

    #[test]
    fn external_permission_levels_map_to_existing_bits_and_reject_legacy_partial_grants() {
        let bits = |capabilities| {
            serde_json::to_value(capabilities).unwrap()["bits"]
                .as_u64()
                .unwrap()
        };
        assert_eq!(
            bits(external_workdir_capabilities("read_only").unwrap()),
            25
        );
        assert_eq!(
            bits(external_workdir_capabilities("read_write").unwrap()),
            31
        );
        assert_eq!(
            bits(external_workdir_capabilities("read_write_command").unwrap()),
            63
        );

        for legacy in ["command_only", "read_command"] {
            let error = external_workdir_capabilities(legacy).unwrap_err();
            assert!(error.to_string().contains("revoke it and share"));
        }
        for invalid in [
            server_api::ExternalWorkdirPermissions {
                read: false,
                write: false,
                command: true,
            },
            server_api::ExternalWorkdirPermissions {
                read: false,
                write: true,
                command: false,
            },
            server_api::ExternalWorkdirPermissions {
                read: true,
                write: false,
                command: true,
            },
        ] {
            let error = persist_external_workdir_permissions(invalid).unwrap_err();
            assert!(error.to_string().contains("exactly one level"));
        }
    }

    #[test]
    fn worker_projection_does_not_expose_unavailable_snapshot_as_current() {
        let availability = protocol::subscription::SubscriptionWorkerAvailability::Unavailable;
        let worker_ref = RuntimeWorkerRef::new("runtime-a", "worker-a");
        let projection = WorkerRegistryProjectionRecord {
            registry: WorkerRegistryRecord {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
                worker: worker_ref,
                display_name: "Worker A".to_string(),
                profile: Some("builtin:coder".to_string()),
                retention_state: "normal".to_string(),
                transcript_ref: None,
                session_ref: None,
                summary_ref: None,
                diagnostics_ref: None,
                created_at: "2026-09-24T00:00:00Z".to_string(),
                updated_at: "2026-09-24T00:00:00Z".to_string(),
            },
            resource_key: Some("W-1".to_string()),
            observation: Some(WorkerRegistryObservationRecord {
                worker: protocol::subscription::SubscriptionWorker {
                    restore_observation_token: None,
                    worker_id: protocol::subscription::SubscriptionWorkerId::new("worker-a")
                        .unwrap(),
                    runtime_id: Some("runtime-a".to_string()),
                    resource_key: Some("W-1".to_string()),
                    availability,
                    worker_state: Some(protocol::WorkerStateSnapshot::initial()),
                    state: protocol::subscription::SubscriptionWorkerState::Idle,
                    has_running_internal_workers: false,
                    workspace_id: Some(TEST_WORKSPACE_ID.to_string()),
                    display_name: Some("Worker A".to_string()),
                    profile: Some("builtin:coder".to_string()),
                    job: None,
                    workdir_attachments: Vec::new(),
                },
                availability,
                observed_at: "2026-09-24T00:00:01Z".to_string(),
            }),
            job: None,
        };

        let unavailable = worker_summary_from_projection(&projection).unwrap();
        assert_eq!(unavailable.availability, availability);
        assert_eq!(unavailable.state, "unavailable");
        assert_eq!(unavailable.worker_state, None);
        assert!(
            serde_json::to_value(&unavailable)
                .unwrap()
                .get("capabilities")
                .is_none()
        );

        let mut observed_stopped = projection;
        let observation = observed_stopped.observation.as_mut().unwrap();
        observation.availability = protocol::subscription::SubscriptionWorkerAvailability::Observed;
        observation.worker.availability =
            protocol::subscription::SubscriptionWorkerAvailability::Observed;
        observation.worker.state = protocol::subscription::SubscriptionWorkerState::Stopped;
        observation.worker.worker_state = None;
        let observed_stopped = worker_summary_from_projection(&observed_stopped).unwrap();
        assert_eq!(
            observed_stopped.availability,
            protocol::subscription::SubscriptionWorkerAvailability::Observed
        );
        assert_eq!(observed_stopped.state, "stopped");
        assert_eq!(observed_stopped.worker_state, None);
    }

    #[tokio::test]
    async fn external_provider_session_reuses_operation_contract_and_read_only_capabilities() {
        let (sender, mut commands) = tokio::sync::mpsc::channel(1);
        let connection = Arc::new(ExternalProviderConnection {
            grant_id: "grant-a".to_string(),
            workdir_id: "external-a".to_string(),
            provider_instance_id: "provider-a".to_string(),
            generation: 4,
            expires_at: Some(Utc::now() + Duration::minutes(1)),
            capabilities: workdir::WorkdirSessionCapabilities::READ_ONLY,
            admission: Arc::new(tokio::sync::Semaphore::new(16)),
            shutdown_confirmed: Arc::new(std::sync::atomic::AtomicBool::new(false)),
            sender,
        });
        let session = Arc::new(ExternalProviderWorkdirSession::new(connection, None));
        assert_eq!(
            session.capabilities(),
            workdir::WorkdirSessionCapabilities::READ_ONLY
        );
        let reader = {
            let session = session.clone();
            tokio::spawn(async move {
                session
                    .read(workdir::ReadRequest {
                        path: workdir::WorkdirPath::new("events.jsonl").unwrap(),
                        offset: 0,
                        limit: 10,
                        max_bytes: 1024,
                    })
                    .await
            })
        };
        let Some(ExternalProviderCommand::Operation {
            operation,
            response,
            ..
        }) = commands.recv().await
        else {
            panic!("expected provider operation");
        };
        assert!(matches!(operation, WorkdirSessionOperation::Read(_)));
        response
            .send(Err(WorkdirTransportError {
                failure_reason: None,
                denial_reason: None,
                code: workdir::http::WorkdirTransportErrorCode::NotFound,
                message: "logical file was not found".to_string(),
            }))
            .unwrap();
        assert!(matches!(
            reader.await.unwrap(),
            Err(workdir::WorkdirError::NotFound(_))
        ));
        assert!(matches!(
            session
                .write(workdir::WriteRequest {
                    path: workdir::WorkdirPath::new("events.jsonl").unwrap(),
                    content: Vec::new(),
                    expected_hash: None,
                })
                .await,
            Err(workdir::WorkdirError::Unsupported(
                workdir::WorkdirSessionCapability::Write
            ))
        ));
    }

