    #[tokio::test]
    async fn checkout_external_provider_typed_boundary_and_unknown_response() {
        let (sender, mut commands) = tokio::sync::mpsc::channel(1);
        let connection = Arc::new(ExternalProviderConnection {
            grant_id: "checkout-grant".into(),
            workdir_id: "checkout-external".into(),
            provider_instance_id: "checkout-provider".into(),
            generation: 7,
            expires_at: None,
            capabilities: workdir::WorkdirSessionCapabilities::READ_WRITE,
            admission: Arc::new(tokio::sync::Semaphore::new(16)),
            shutdown_confirmed: Arc::new(std::sync::atomic::AtomicBool::new(false)),
            sender,
        });
        let session = Arc::new(ExternalProviderWorkdirSession::new(connection, None));
        let path = workdir::WorkdirPath::new("file.txt").unwrap();
        let observe = {
            let session = session.clone();
            let path = path.clone();
            tokio::spawn(async move { session.checkout_observe(path).await })
        };
        let Some(ExternalProviderCommand::Operation {
            operation,
            response,
            ..
        }) = commands.recv().await
        else {
            panic!("expected operation")
        };
        assert!(matches!(
            operation,
            WorkdirSessionOperation::CheckoutObserve(_)
        ));
        response
            .send(Ok(WorkdirSessionOperationResult::CheckoutObserve(
                workdir::CheckoutObservation {
                    path: path.clone(),
                    kind: workdir::EntryKind::File,
                    size: 4,
                    validator: vec![1],
                    capabilities: workdir::WorkdirSessionCapabilities::READ_WRITE,
                },
            )))
            .unwrap();
        let observed = observe.await.unwrap().unwrap();
        for lose_response in [false, true] {
            let request = workdir::CheckoutRequest {
                target: path.clone(),
                validator: observed.validator.clone(),
                operation: workdir::CheckoutOperation::Write {
                    content: b"next".to_vec(),
                    expected_hash: [0; 32],
                },
            };
            let write = {
                let session = session.clone();
                tokio::spawn(async move { session.checkout_execute(request).await })
            };
            let Some(ExternalProviderCommand::Operation {
                operation,
                response,
                ..
            }) = commands.recv().await
            else {
                panic!("expected operation")
            };
            assert!(matches!(
                operation,
                WorkdirSessionOperation::CheckoutExecute(_)
            ));
            if lose_response {
                drop(response);
            } else {
                // A valid ordinary result is still the wrong subject/operation for this checked call.
                response
                    .send(Ok(WorkdirSessionOperationResult::Write(
                        workdir::WriteResult {
                            bytes_written: 4,
                            created: false,
                        },
                    )))
                    .unwrap();
            }
            let error = write
                .await
                .unwrap()
                .expect_err("mismatched or lost mutation response must remain outcome-unknown");
            assert!(matches!(
                error.classification_source(),
                workdir::WorkdirError::OutcomeUnknown(_)
            ));
            assert_eq!(
                error.failure_reason(),
                Some(if lose_response {
                    workdir::WorkdirFailureReason::ProviderResponseLost
                } else {
                    workdir::WorkdirFailureReason::OperationResultMismatch
                })
            );
        }
    }

    #[tokio::test]
    async fn external_operation_cancel_retries_without_blocking_a_saturated_provider_queue() {
        let (sender, mut commands) = tokio::sync::mpsc::channel(1);
        let queued_id = ExternalWorkdirOperationId::new("op-queued").unwrap();
        sender
            .send(ExternalProviderCommand::Cancel {
                operation_id: queued_id.clone(),
            })
            .await
            .unwrap();

        let retried_id = ExternalWorkdirOperationId::new("op-retried").unwrap();
        enqueue_external_operation_cancel(sender, retried_id.clone());

        let Some(ExternalProviderCommand::Cancel { operation_id }) = commands.recv().await else {
            panic!("expected pre-existing queued cancellation");
        };
        assert_eq!(operation_id, queued_id);
        let retried = tokio::time::timeout(std::time::Duration::from_secs(1), commands.recv())
            .await
            .expect("cancellation retry should not be lost");
        let Some(ExternalProviderCommand::Cancel { operation_id }) = retried else {
            panic!("expected retried cancellation");
        };
        assert_eq!(operation_id, retried_id);
    }

