    impl crate::hosts::WorkspaceWorkerRuntime for WorkdirlessFixtureRuntime {
        fn open_workdir_session<'a>(
            &'a self,
            working_directory_id: &'a str,
            _owner_worker_id: Option<&'a str>,
        ) -> std::pin::Pin<
            Box<
                dyn std::future::Future<
                        Output = std::result::Result<WorkdirSessionHandle, workdir::WorkdirError>,
                    > + Send
                    + 'a,
            >,
        > {
            Box::pin(async move {
                self.workdir_session_factory.as_ref().ok_or_else(|| {
                    workdir::WorkdirError::Unavailable(
                        "Runtime does not expose Workdir operation sessions".to_string(),
                    )
                })?(working_directory_id)
            })
        }

        fn send_input(
            &self,
            worker_id: &str,
            request: WorkerInputRequest,
        ) -> crate::hosts::WorkerInputResult {
            let idle_only = request.kind == WorkerInputKind::UserIfIdle;
            self.input_requests.lock().unwrap().push(request);
            crate::hosts::WorkerInputResult {
                state: if idle_only {
                    InternalWorkerOperationState::Rejected
                } else {
                    InternalWorkerOperationState::Accepted
                },
                disposition: if idle_only {
                    crate::hosts::WorkerInputDisposition::Rejected
                } else {
                    crate::hosts::WorkerInputDisposition::Accepted
                },
                worker: RuntimeWorkerRef::new(Self::RUNTIME_ID, worker_id),
                runtime_run_id: None,
                diagnostics: Vec::new(),
            }
        }

        fn runtime_id(&self) -> &str {
            Self::RUNTIME_ID
        }

        fn runtime_summary(&self, _limit: usize) -> crate::hosts::InternalRuntimeSummary {
            crate::hosts::InternalRuntimeSummary {
                runtime_id: Self::RUNTIME_ID.to_string(),
                label: "Workdirless Runtime".to_string(),
                kind: "fixture".to_string(),
                status: "active".to_string(),
                source: crate::hosts::InternalRuntimeSourceSummary::remote_http(),
                host_ids: vec!["workdirless-host".to_string()],
                worker_creation_available: true,
                os: "linux".to_string(),
                arch: "x86_64".to_string(),
                diagnostics: Vec::new(),
            }
        }

        fn list_hosts(&self, _limit: usize) -> crate::hosts::RuntimeList<InternalHostSummary> {
            crate::hosts::RuntimeList {
                items: Vec::new(),
                diagnostics: Vec::new(),
            }
        }

        fn list_workers(&self, limit: usize) -> crate::hosts::RuntimeList<InternalWorkerSummary> {
            crate::hosts::RuntimeList {
                items: self
                    .workers
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                    .iter()
                    .take(limit)
                    .cloned()
                    .collect(),
                diagnostics: Vec::new(),
            }
        }

        fn worker(&self, worker_id: &str) -> crate::hosts::WorkerLookupResult {
            crate::hosts::WorkerLookupResult {
                worker: self
                    .workers
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                    .iter()
                    .find(|worker| worker.worker.worker_id == worker_id)
                    .cloned(),
                diagnostics: Vec::new(),
            }
        }

        fn working_directory(
            &self,
            working_directory_id: &str,
        ) -> crate::hosts::RuntimeWorkingDirectoryResult {
            crate::hosts::RuntimeWorkingDirectoryResult {
                state: InternalWorkerOperationState::Accepted,
                working_directory: Some(self.configured_workdir_status(working_directory_id)),
                diagnostics: Vec::new(),
            }
        }

        fn cleanup_working_directory(
            &self,
            _working_directory_id: &str,
        ) -> crate::hosts::RuntimeWorkingDirectoryResult {
            crate::hosts::RuntimeWorkingDirectoryResult {
                state: InternalWorkerOperationState::Accepted,
                working_directory: None,
                diagnostics: Vec::new(),
            }
        }

        fn spawn_worker(
            &self,
            binding: WorkerCreateBinding,
            request: WorkerSpawnRequest,
        ) -> WorkerSpawnResult {
            self.spawn_requests
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .push(request.clone());
            if std::mem::take(
                &mut *self
                    .reject_next_spawn
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner),
            ) {
                return WorkerSpawnResult {
                    state: InternalWorkerOperationState::Rejected,
                    worker: None,
                    acceptance_evidence: Vec::new(),
                    diagnostics: vec![RuntimeDiagnostic {
                        code: "fixture_runtime_rejected".to_string(),
                        severity: HostDiagnosticSeverity::Error,
                        message: "fixture rejected Worker create".to_string(),
                    }],
                };
            }
            if let Some(callback) = &self.lifecycle_callback {
                callback(&binding.worker_id.to_string());
            }
            assert!(request.workdir_attachment_requests.is_empty());
            assert!(request.resolved_workdir_attachment_requests.is_empty());
            let mut worker = Self::worker_summary(binding, &request);
            worker.workdir_attachments = request
                .resolved_workdir_attachments
                .iter()
                .map(|attachment| WorkingDirectoryAttachmentStatus {
                    alias: attachment.alias.clone(),
                    working_directory: self
                        .configured_workdir_status(&attachment.working_directory_id),
                })
                .collect();
            self.workers
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .push(worker.clone());
            WorkerSpawnResult {
                state: InternalWorkerOperationState::Accepted,
                worker: Some(worker),
                acceptance_evidence: Vec::new(),
                diagnostics: Vec::new(),
            }
        }

        fn stop_worker(
            &self,
            worker_id: &str,
            _request: WorkerLifecycleRequest,
        ) -> WorkerLifecycleResult {
            if let Some(callback) = &self.stop_callback {
                callback();
            }
            WorkerLifecycleResult {
                state: InternalWorkerOperationState::Accepted,
                worker: RuntimeWorkerRef::new(Self::RUNTIME_ID, worker_id),
                diagnostics: Vec::new(),
            }
        }

        fn cancel_worker(
            &self,
            worker_id: &str,
            _request: WorkerLifecycleRequest,
        ) -> WorkerLifecycleResult {
            WorkerLifecycleResult {
                state: InternalWorkerOperationState::Accepted,
                worker: RuntimeWorkerRef::new(Self::RUNTIME_ID, worker_id),
                diagnostics: Vec::new(),
            }
        }

        fn delete_worker(&self, worker_id: &str) -> crate::hosts::WorkerDeleteResult {
            let mut workers = self
                .workers
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            let previous_len = workers.len();
            workers.retain(|worker| worker.worker.worker_id != worker_id);
            crate::hosts::WorkerDeleteResult {
                state: InternalWorkerOperationState::Accepted,
                worker: RuntimeWorkerRef::new(Self::RUNTIME_ID, worker_id),
                deleted: workers.len() != previous_len,
                diagnostics: Vec::new(),
            }
        }

        fn authorize_working_directory_repository_access(
            &self,
            request: worker_runtime::catalog::WorkingDirectoryRepositoryAccessRequest,
        ) -> std::result::Result<(), Error> {
            assert_eq!(request.materialization.runtime_id, Self::RUNTIME_ID);
            self.repository_access_requests
                .lock()
                .unwrap()
                .push(request);
            if *self.reject_repository_access.lock().unwrap() {
                Err(Error::InvalidInput("repository access unavailable".into()))
            } else {
                Ok(())
            }
        }

        fn coordinate_worker_restore(
            &self,
            worker_id: &str,
            request: runtime_api::WorkerRestoreCoordinationRequest,
        ) -> std::result::Result<
            (
                Option<InternalWorkerRestoreResult>,
                Option<runtime_api::WorkerRestorePreparation>,
            ),
            RuntimeDiagnostic,
        > {
            if self.worker(worker_id).worker.is_none() {
                return Ok((
                    Some(InternalWorkerRestoreResult {
                        state: server_api::WorkerRestoreState::Rejected,
                        worker: None,
                        diagnostics: Vec::new(),
                    }),
                    None,
                ));
            }
            Ok((None, request.preparation))
        }

        fn restore_worker(
            &self,
            worker_id: &str,
            _request: runtime_api::WorkerRestoreRequest,
        ) -> InternalWorkerRestoreResult {
            *self.restore_attempts.lock().unwrap() += 1;
            if let Some(callback) = &self.lifecycle_callback {
                callback(worker_id);
            }
            let worker = self.worker(worker_id).worker;
            InternalWorkerRestoreResult {
                state: if let Some(outcome) = self.next_restore_outcome.lock().unwrap().take() {
                    outcome
                } else if worker.is_some() {
                    server_api::WorkerRestoreState::Accepted
                } else {
                    server_api::WorkerRestoreState::Rejected
                },
                worker,
                diagnostics: Vec::new(),
            }
        }

        fn replace_worker_workspace_api(
            &self,
            worker_id: &str,
            _workspace_api: WorkspaceApiRef,
        ) -> crate::hosts::WorkerWorkspaceApiResult {
            crate::hosts::WorkerWorkspaceApiResult {
                state: InternalWorkerOperationState::Accepted,
                worker: self.worker(worker_id).worker,
                diagnostics: Vec::new(),
            }
        }

        fn replace_worker_workdir_attachments(
            &self,
            worker_id: &str,
            attachments: Vec<LogicalWorkdirAttachment>,
        ) -> crate::hosts::WorkerWorkspaceApiResult {
            self.logical_attachments
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .insert(worker_id.to_string(), attachments);
            crate::hosts::WorkerWorkspaceApiResult {
                state: InternalWorkerOperationState::Accepted,
                worker: self.worker(worker_id).worker,
                diagnostics: Vec::new(),
            }
        }
    }

