    #[tokio::test]
    async fn workdir_operation_errors_preserve_typed_public_status_and_code() {
        for (code, expected_status) in [
            (
                workdir::http::WorkdirTransportErrorCode::InvalidRequest,
                StatusCode::BAD_REQUEST,
            ),
            (
                workdir::http::WorkdirTransportErrorCode::NotFound,
                StatusCode::NOT_FOUND,
            ),
            (
                workdir::http::WorkdirTransportErrorCode::UnknownCommand,
                StatusCode::NOT_FOUND,
            ),
            (
                workdir::http::WorkdirTransportErrorCode::Conflict,
                StatusCode::CONFLICT,
            ),
            (
                workdir::http::WorkdirTransportErrorCode::Unsupported,
                StatusCode::BAD_REQUEST,
            ),
            (
                workdir::http::WorkdirTransportErrorCode::Denied,
                StatusCode::FORBIDDEN,
            ),
            (
                workdir::http::WorkdirTransportErrorCode::OutOfScope,
                StatusCode::FORBIDDEN,
            ),
            (
                workdir::http::WorkdirTransportErrorCode::SymlinkOutOfScope,
                StatusCode::FORBIDDEN,
            ),
            (
                workdir::http::WorkdirTransportErrorCode::BrokenSymlink,
                StatusCode::BAD_REQUEST,
            ),
            (
                workdir::http::WorkdirTransportErrorCode::SymlinkTargetIsDirectory,
                StatusCode::BAD_REQUEST,
            ),
            (
                workdir::http::WorkdirTransportErrorCode::ReadOnly,
                StatusCode::FORBIDDEN,
            ),
            (
                workdir::http::WorkdirTransportErrorCode::IsDirectory,
                StatusCode::BAD_REQUEST,
            ),
            (
                workdir::http::WorkdirTransportErrorCode::SymlinkDirectoryNotTraversed,
                StatusCode::BAD_REQUEST,
            ),
            (
                workdir::http::WorkdirTransportErrorCode::Unavailable,
                StatusCode::SERVICE_UNAVAILABLE,
            ),
            (
                workdir::http::WorkdirTransportErrorCode::Io,
                StatusCode::INTERNAL_SERVER_ERROR,
            ),
            (
                workdir::http::WorkdirTransportErrorCode::Transport,
                StatusCode::BAD_GATEWAY,
            ),
            (
                workdir::http::WorkdirTransportErrorCode::Internal,
                StatusCode::INTERNAL_SERVER_ERROR,
            ),
        ] {
            let response = InternalWorkdirOperationError::Provider(WorkdirTransportError {
                failure_reason: None,
                denial_reason: None,
                code,
                message: "safe provider message".to_string(),
            })
            .into_response();
            assert_eq!(response.status(), expected_status);
            let log = response.extensions().get::<ApiErrorLog>().unwrap();
            assert_eq!(
                log.kind,
                format!("workdir_session_operation_{}", code.as_str())
            );
            let body = to_bytes(response.into_body(), usize::MAX).await.unwrap();
            let decoded: WorkdirTransportError = serde_json::from_slice(&body).unwrap();
            assert_eq!(decoded.code, code);
            assert_eq!(decoded.message, "safe provider message");
        }
    }

    #[tokio::test]
    async fn local_and_remote_validation_errors_share_workspace_classification() {
        let local =
            workdir_operation_transport_error(workdir::WorkdirError::InvalidGlob("[".to_string()));
        let remote = workdir_operation_transport_error(
            WorkdirTransportError {
                failure_reason: None,
                denial_reason: None,
                code: workdir::http::WorkdirTransportErrorCode::InvalidRequest,
                message: "Workdir operation request is invalid".to_string(),
            }
            .into_workdir_error(),
        );
        assert_eq!(local, remote);

        for public in [local, remote] {
            let response = InternalWorkdirOperationError::Provider(public).into_response();
            assert_eq!(response.status(), StatusCode::BAD_REQUEST);
            let body = to_bytes(response.into_body(), usize::MAX).await.unwrap();
            let decoded: WorkdirTransportError = serde_json::from_slice(&body).unwrap();
            assert_eq!(
                decoded.code,
                workdir::http::WorkdirTransportErrorCode::InvalidRequest
            );
        }
    }

    #[tokio::test]
    async fn workdir_operation_error_response_redacts_provider_internal_details() {
        let error = workdir::WorkdirError::Io {
            path: PathBuf::from("/host/private/worktree/secret.txt"),
            source: std::io::Error::other("token=secret"),
        };
        let public = workdir_operation_transport_error(error);
        let response = InternalWorkdirOperationError::Provider(public).into_response();
        let body = to_bytes(response.into_body(), usize::MAX).await.unwrap();
        let text = String::from_utf8(body.to_vec()).unwrap();
        assert!(!text.contains("/host/private"));
        assert!(!text.contains("token=secret"));
        let decoded: WorkdirTransportError = serde_json::from_str(&text).unwrap();
        assert_eq!(decoded.code, workdir::http::WorkdirTransportErrorCode::Io);

        let remote = workdir_operation_transport_error(workdir::WorkdirError::OperationFailed);
        let response = InternalWorkdirOperationError::Provider(remote).into_response();
        assert_eq!(response.status(), StatusCode::INTERNAL_SERVER_ERROR);
    }

