    #[tokio::test]
    async fn flow_source_resolution_returns_immutable_workspace_and_builtin_snapshots() {
        let workspace = tempfile::tempdir().unwrap();
        init_clean_git_workspace(workspace.path());
        let api = test_api(workspace.path()).await;
        let source = r#"{
            schema_version = 1;
            name = "browser-flow";
            initial = "work";
            states = {
                work = {
                    instructions = "Implement and validate the requested change.";
                    transitions = {
                        done = { target = "done"; condition = "The work is complete."; };
                    };
                };
                done = { instructions = ""; terminal = true; };
            };
        }"#;
        let stored = api
            .store
            .put_flow_source_for_kind(
                &api.config.workspace_id,
                FlowSourceKind::Workspace,
                "flows/browser-flow.dcdl",
                source,
                "2026-08-06T00:00:00Z",
            )
            .unwrap();

        let Json(resolved) = scoped_resolve_flow_source(
            State(api.clone()),
            AxumPath(ScopedWorkspacePath {
                workspace_id: api.config.workspace_id.clone(),
            }),
            Json(FlowSourceResolveRequest {
                selector: "workspace:browser-flow".parse().unwrap(),
            }),
        )
        .await
        .unwrap();
        assert_eq!(resolved.flow_id, stored.flow_id);
        assert_eq!(resolved.content_digest, stored.content_digest);
        assert_eq!(resolved.definition.name, "browser-flow");

        let Json(builtin) = scoped_resolve_flow_source(
            State(api.clone()),
            AxumPath(ScopedWorkspacePath {
                workspace_id: api.config.workspace_id.clone(),
            }),
            Json(FlowSourceResolveRequest {
                selector: "builtin:coder-review".parse().unwrap(),
            }),
        )
        .await
        .unwrap();
        assert_eq!(builtin.definition.name, "coder-review");
        assert_eq!(builtin.selector.to_string(), "builtin:coder-review");
        assert_eq!(builtin.flow_id, "builtin:coder-review");
        assert_eq!(
            builtin.content_digest,
            flow::builtin_flow_source(flow::CODER_REVIEW_FLOW_SLUG)
                .unwrap()
                .compile()
                .unwrap()
                .content_digest
        );
        assert_eq!(
            api.store
                .list_flow_sources(&api.config.workspace_id)
                .unwrap(),
            vec![stored],
            "built-in resolution must not mutate Workspace source authority",
        );
    }

    #[test]
    fn worker_initial_submit_validate_flow_shape_before_spawn() {
        let valid = vec![
            Segment::Flow {
                selector: "builtin:coder-review".to_string(),
            },
            Segment::text("Implement Ticket 00001"),
        ];
        assert!(validate_worker_initial_submit(&valid).is_ok());
        assert!(validate_worker_initial_submit(&[]).is_ok());

        let duplicate = vec![
            Segment::Flow {
                selector: "builtin:coder-review".to_string(),
            },
            Segment::Flow {
                selector: "workspace:coder-review".to_string(),
            },
        ];
        assert!(matches!(
            validate_worker_initial_submit(&duplicate),
            Err(Error::InvalidInput(message)) if message.contains("at most one")
        ));
        assert!(matches!(
            validate_worker_initial_submit(&[Segment::Flow {
                selector: "coder-review".to_string(),
            }]),
            Err(Error::InvalidInput(_))
        ));
        assert!(matches!(
            validate_worker_initial_submit(&[Segment::Unknown]),
            Err(Error::InvalidInput(message)) if message.contains("unknown")
        ));
        assert!(
            serde_json::from_value::<CreateWorkspaceWorkerRequest>(serde_json::json!({
                "runtime_id": "runtime-1",
                "display_name": "coder",
                "initial_text": "legacy parallel authority",
                "working_directory": { "kind": "without_workspace" }
            }))
            .is_err()
        );
    }

    #[test]
    fn repository_ssh_probe_distinguishes_untrusted_verified_and_changed_keys() {
        let candidates = vec![RepositorySshHostKeyCandidate {
            algorithm: "ssh-ed25519".to_string(),
            host_key: "ssh-ed25519 AAAA".to_string(),
            fingerprint: "SHA256:observed".to_string(),
        }];

        assert_eq!(
            repository_ssh_connection_trust_state(&candidates, None),
            RepositorySshConnectionTrustState::Untrusted
        );
        assert_eq!(
            repository_ssh_connection_trust_state(&candidates, Some("SHA256:observed")),
            RepositorySshConnectionTrustState::Verified
        );
        assert_eq!(
            repository_ssh_connection_trust_state(&candidates, Some("SHA256:old")),
            RepositorySshConnectionTrustState::Changed
        );
    }

    #[tokio::test]
    async fn repository_ssh_clone_leases_specific_then_workspace_default_credentials() {
        let dir = tempfile::tempdir().unwrap();
        let api = test_api(dir.path()).await;
        let specific = api
            .repository_secrets
            .generate_credential(
                &api.config.workspace_id,
                GenerateRepositorySshCredentialRequest {
                    operation_id: "generate-repository-specific".to_string(),
                    credential_id: "repository-specific".to_string(),
                    name: "Repository specific".to_string(),
                },
                "owner-account",
            )
            .unwrap();
        let host_public_key = api
            .repository_secrets
            .credential_public_key(&api.config.workspace_id, &specific.credential_id)
            .unwrap()
            .unwrap()
            .public_key;
        let host_trust = api
            .repository_secrets
            .put_host_trust(
                &api.config.workspace_id,
                PutRepositorySshHostTrustRequest {
                    operation_id: "trust-example-host".to_string(),
                    host_trust_id: "example-host".to_string(),
                    hostname: "example.test".to_string(),
                    port: 22,
                    host_key: host_public_key,
                    expected_fingerprint: None,
                },
                "owner-account",
            )
            .unwrap();
        let binding = server_api::RepositorySshAccessBinding {
            repository_key: "test-repository".to_string(),
            credential_id: specific.credential_id.clone(),
            host_trust_id: host_trust.host_trust_id,
            access: server_api::RepositoryAccessMode::ReadOnly,
        };
        let primary = api
            .repository_secrets
            .lease_ssh_materialization_access(&api.config.workspace_id, &binding)
            .unwrap();

        let candidates = repository_ssh_lease_candidates(&api, primary).unwrap();

        assert_eq!(candidates.len(), 2);
        assert_eq!(candidates[0].credential_id, "repository-specific");
        assert_eq!(
            candidates[1].credential_id,
            crate::repository_access::WORKSPACE_DEFAULT_REPOSITORY_SSH_CREDENTIAL_ID
        );
        assert_ne!(
            candidates[0].private_key.as_str(),
            candidates[1].private_key.as_str()
        );
        assert_eq!(
            candidates[0].known_hosts_entry,
            candidates[1].known_hosts_entry
        );

        let source = server_api::RepositorySource {
            kind: server_api::RepositorySourceKind::Ssh,
            uri: "ssh://git@example.test/org/repository.git".to_string(),
        };
        let source_fingerprint = repository_source_fingerprint(&source);
        let request = WorkingDirectoryRequest {
            repository: worker_runtime::catalog::WorkingDirectoryRepository {
                id: "repository-a".to_string(),
                provider: "git".to_string(),
                source: source.clone(),
                source_fingerprint: source_fingerprint.clone(),
                selector: None,
            },
            display_name: None,
            materializer: Default::default(),
            backend_workdir_id: Some("workdir-a".to_string()),
            materialization: None,
        };
        let operation = WorkdirCreateOperationRecord {
            workspace_id: api.config.workspace_id.clone(),
            operation_id: "retry-workdir-a".to_string(),
            request_fingerprint: "sha256:request".to_string(),
            repository_id: "repository-a".to_string(),
            selector: None,
            requested_runtime_id: Some("runtime-1".to_string()),
            resolved_runtime_id: "runtime-1".to_string(),
            config_projection_digest: "sha256:projection".to_string(),
            source_kind: Some(source.kind.as_str().to_string()),
            source_uri: Some(source.uri.clone()),
            source_fingerprint: Some(source_fingerprint),
            credential_id: Some(candidates[0].credential_id.clone()),
            credential_fingerprint: Some(candidates[0].credential_fingerprint.clone()),
            host_trust_id: Some(candidates[0].host_trust_id.clone()),
            host_trust_fingerprint: Some(candidates[0].host_trust_fingerprint.clone()),
            repository_access_mode: Some("read_only".to_string()),
            credential_candidates: candidates
                .iter()
                .enumerate()
                .map(|(index, candidate)| WorkdirCreateCredentialCandidate {
                    role: if index == 0 {
                        WorkdirCreateCredentialCandidateRole::Primary
                    } else {
                        WorkdirCreateCredentialCandidateRole::WorkspaceDefaultFallback
                    },
                    credential_id: candidate.credential_id.clone(),
                    credential_fingerprint: candidate.credential_fingerprint.clone(),
                })
                .collect(),
            working_directory_id: "workdir-a".to_string(),
            state: "failed".to_string(),
            failure: Some("runtime unavailable".to_string()),
            created_at: "2026-08-24T00:00:00Z".to_string(),
            updated_at: "2026-08-24T00:00:01Z".to_string(),
        };
        let retry_candidates =
            repository_ssh_lease_candidates_from_operation(&api, &operation, &request).unwrap();
        assert_eq!(retry_candidates.len(), 2);
        assert_eq!(
            retry_candidates
                .iter()
                .map(|candidate| (
                    candidate.credential_id.as_str(),
                    candidate.credential_fingerprint.as_str()
                ))
                .collect::<Vec<_>>(),
            operation
                .credential_candidates
                .iter()
                .map(|candidate| (
                    candidate.credential_id.as_str(),
                    candidate.credential_fingerprint.as_str()
                ))
                .collect::<Vec<_>>()
        );
        let mut missing_snapshot = operation.clone();
        missing_snapshot.credential_candidates.clear();
        assert!(
            repository_ssh_lease_candidates_from_operation(&api, &missing_snapshot, &request)
                .is_err()
        );

        let default_binding = server_api::RepositorySshAccessBinding {
            credential_id: crate::repository_access::WORKSPACE_DEFAULT_REPOSITORY_SSH_CREDENTIAL_ID
                .to_string(),
            ..binding
        };
        let primary_default = api
            .repository_secrets
            .lease_ssh_materialization_access(&api.config.workspace_id, &default_binding)
            .unwrap();
        let default_only = repository_ssh_lease_candidates(&api, primary_default).unwrap();
        assert_eq!(default_only.len(), 1);
    }

