    #[tokio::test]
    async fn production_profile_backend_restores_zero_input_orchestrator() {
        let workspace = tempfile::tempdir().unwrap();
        init_clean_git_workspace(workspace.path());
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let mut config = test_server_config(workspace.path());
        config.backend_base_url = Some(format!("http://{}", listener.local_addr().unwrap()));
        let store =
            Arc::new(SqliteWorkspaceStore::open_for_test(config.database_path.clone()).unwrap());
        seed_test_registered_workspace(store.as_ref(), &config)
            .await
            .unwrap();
        let api = WorkspaceApi::new_for_test(config, store).await.unwrap();
        let workspace_id = api.config.workspace_id.clone();
        let _callback_server =
            AuthorizationCallbackServer::start(listener, build_router(api.clone()));

        let result = scoped_start_workspace_orchestrator(
            State(api.clone()),
            AxumPath(ScopedWorkspacePath {
                workspace_id: workspace_id.clone(),
            }),
        )
        .await;

        let Json(started) = result.unwrap_or_else(|error| {
            panic!(
                "production Workspace Orchestrator launch failed: error={:?}, diagnostics={:?}",
                error.error, error.diagnostics
            )
        });
        assert_eq!(started.disposition, "created");
        assert!(started.online);
        let worker = started
            .worker
            .expect("production Workspace Orchestrator Worker");
        let worker = RuntimeWorkerRef::new(&worker.runtime_id, &worker.worker_id);

        let stopped = api
            .runtime
            .stop_worker(
                &worker,
                WorkerLifecycleRequest {
                    reason: Some("production Orchestrator restore regression test".to_string()),
                    ticket_assignment: None,
                },
            )
            .unwrap();
        assert_eq!(stopped.state, InternalWorkerOperationState::Accepted);
        let Json(restored) = scoped_start_workspace_orchestrator(
            State(api.clone()),
            AxumPath(ScopedWorkspacePath {
                workspace_id: workspace_id.clone(),
            }),
        )
        .await
        .expect("zero-input Workspace Orchestrator should restore from its durable session head");
        assert_eq!(restored.disposition, "restored");
        assert!(restored.online);
        let restored_worker = restored.worker.expect("restored Orchestrator Worker");
        assert_eq!(restored_worker.runtime_id, worker.runtime_id);
        assert_eq!(restored_worker.worker_id, worker.worker_id);
    }

    #[tokio::test]
    async fn rejected_orchestrator_spawn_stays_offline_and_can_be_retried() {
        let workspace = tempfile::tempdir().unwrap();
        init_clean_git_workspace(workspace.path());
        let config = test_server_config(workspace.path());
        let store = SqliteWorkspaceStore::open_for_test(config.database_path.clone()).unwrap();
        let api = WorkspaceApi::new_with_execution_backend(
            config,
            Arc::new(store),
            Arc::new(DeterministicExecutionBackend::fail_first_spawn(
                "provider setup rejected safe-root /tmp/private token=private-token session_id=private-session",
            )),
        )
        .await
        .unwrap();
        let workspace_id = api.config.workspace_id.clone();

        let error = scoped_start_workspace_orchestrator(
            State(api.clone()),
            AxumPath(ScopedWorkspacePath {
                workspace_id: workspace_id.clone(),
            }),
        )
        .await
        .unwrap_err();
        assert!(matches!(
            error.error,
            Error::RuntimeOperationFailed {
                ref code,
                ..
            } if code == "workspace_orchestrator_spawn_rejected"
        ));
        assert!(error.diagnostics.iter().any(|diagnostic| {
            diagnostic.code == "embedded_worker_execution_rejected"
                && diagnostic
                    .message
                    .contains("provider setup rejected safe-root")
                && !diagnostic.message.contains("/tmp/private")
                && !diagnostic.message.contains("private-token")
                && !diagnostic.message.contains("private-session")
        }));
        assert!(find_workspace_orchestrator(&api).is_none());
        assert!(!workspace_orchestrator_response(&api, "failed").online);
        let (reserved_creates, worker_resource_keys): (i64, i64) = api
            .config_store
            .with_conn(|conn| {
                Ok((
                    conn.query_row(
                        "SELECT COUNT(*) FROM worker_create_reservations WHERE state = 'reserved'",
                        [],
                        |row| row.get(0),
                    )?,
                    conn.query_row(
                        "SELECT COUNT(*) FROM workspace_resource_keys WHERE resource_kind = 'worker'",
                        [],
                        |row| row.get(0),
                    )?,
                ))
            })
            .unwrap();
        assert_eq!(reserved_creates, 0);
        assert_eq!(worker_resource_keys, 0);

        let Json(retried) = scoped_start_workspace_orchestrator(
            State(api),
            AxumPath(ScopedWorkspacePath { workspace_id }),
        )
        .await
        .unwrap();
        assert_eq!(retried.disposition, "created");
        assert!(retried.online);
    }

