    #[tokio::test]
    async fn worker_control_input_is_idle_only_and_returns_rejection_as_http_error() {
        let fixture = guarded_spawn_fixture().await;
        let response = post_guarded_spawn(
            &fixture,
            guarded_spawn_payload(&fixture, "idle-only-control"),
        )
        .await;
        assert_eq!(response.status(), StatusCode::OK);
        let bytes = to_bytes(response.into_body(), usize::MAX).await.unwrap();
        let created: BrowserCreateWorkerResponse = serde_json::from_slice(&bytes).unwrap();
        let mut headers = HeaderMap::new();
        headers.insert(
            "x-yoi-runtime-id",
            fixture.controller.runtime_id.parse().unwrap(),
        );
        headers.insert(
            "x-yoi-worker-id",
            fixture.controller.worker_id.parse().unwrap(),
        );
        let path = || ScopedRuntimeWorkerPath {
            workspace_id: TEST_WORKSPACE_ID.to_string(),
            worker: RuntimeWorkerRef::new(&created.runtime_id, &created.worker_id),
        };
        let request = |kind: &str| server_api::RuntimeWorkerInputRequest {
            kind: Some(kind.to_string()),
            content: "follow-up".to_string(),
            segments: None,
        };
        let error = send_known_worker_input(
            State(fixture.api.clone()),
            AxumPath(path()),
            headers.clone(),
            Json(request("user")),
        )
        .await
        .unwrap_err();
        let response = error.into_response();
        assert_eq!(response.status(), StatusCode::BAD_REQUEST);
        let bytes = to_bytes(response.into_body(), usize::MAX).await.unwrap();
        assert!(String::from_utf8_lossy(&bytes).contains("WorkerNotify"));
        // Machine Notify is unchanged; the human endpoint must still use User.
        let Json(notify) = send_known_worker_input(
            State(fixture.api.clone()),
            AxumPath(path()),
            headers,
            Json(request("notify")),
        )
        .await
        .unwrap();
        assert_eq!(notify.state, server_api::WorkerOperationState::Accepted);
        let Json(human) = scoped_send_runtime_worker_input(
            State(fixture.api.clone()),
            AxumPath(path()),
            Json(request("user")),
        )
        .await
        .unwrap();
        assert_eq!(human.state, server_api::WorkerOperationState::Accepted);
        let requests = fixture.runtime.input_requests.lock().unwrap();
        assert_eq!(
            requests.iter().map(|r| r.kind.clone()).collect::<Vec<_>>(),
            vec![
                WorkerInputKind::UserIfIdle,
                WorkerInputKind::Notify,
                WorkerInputKind::User
            ]
        );
    }

    #[tokio::test]
    async fn worker_control_spawn_retry_converges_on_one_worker_and_one_grant() {
        let workspace = tempfile::tempdir().unwrap();
        init_clean_git_workspace(workspace.path());
        let api = test_api(workspace.path()).await;
        let workspace_id = api.config.workspace_id.clone();
        let Json(controller_worker) = create_workspace_worker(
            State(api.clone()),
            HeaderMap::new(),
            Json(CreateWorkspaceWorkerRequest {
                runtime_id: EMBEDDED_WORKER_RUNTIME_ID.to_string(),
                display_name: "Control caller".to_string(),
                singleton_key: None,
                profile: None,
                ticket_assignment: None,
                initial_submit: Vec::new(),
                workdir_attachments: Vec::new(),
                feature_connections: Default::default(),
                control_operation_id: None,
                execution_grant: None,
            }),
        )
        .await
        .unwrap();
        let controller =
            RuntimeWorkerRef::new(&controller_worker.runtime_id, &controller_worker.worker_id);
        assert_ne!(
            scoped_worker_control_operation_id(&controller, "same-operation"),
            scoped_worker_control_operation_id(
                &RuntimeWorkerRef::new(&controller.runtime_id, "different-controller"),
                "same-operation",
            ),
            "Runtime idempotency keys are scoped to the authenticated controller"
        );
        let mut headers = HeaderMap::new();
        headers.insert(
            "x-yoi-runtime-id",
            axum::http::HeaderValue::from_str(&controller.runtime_id).unwrap(),
        );
        headers.insert(
            "x-yoi-worker-id",
            axum::http::HeaderValue::from_str(&controller.worker_id).unwrap(),
        );
        let request = || CreateWorkspaceWorkerRequest {
            runtime_id: EMBEDDED_WORKER_RUNTIME_ID.to_string(),
            display_name: "Idempotent controlled child".to_string(),
            singleton_key: None,
            profile: None,
            ticket_assignment: None,
            initial_submit: Vec::new(),
            workdir_attachments: Vec::new(),
            feature_connections: Default::default(),
            control_operation_id: Some("control-spawn-retry".to_string()),
            execution_grant: None,
        };

        let Json(first) = spawn_known_worker(
            State(api.clone()),
            AxumPath(ScopedWorkspacePath {
                workspace_id: workspace_id.clone(),
            }),
            headers.clone(),
            Json(request()),
        )
        .await
        .unwrap();
        let Json(retried) = spawn_known_worker(
            State(api.clone()),
            AxumPath(ScopedWorkspacePath {
                workspace_id: workspace_id.clone(),
            }),
            headers,
            Json(request()),
        )
        .await
        .unwrap();

        assert_eq!(retried.runtime_id, first.runtime_id);
        assert_eq!(retried.worker_id, first.worker_id);
        let mut conflicting_request = request();
        conflicting_request.display_name = "Different controlled child".to_string();
        let conflict = spawn_known_worker(
            State(api.clone()),
            AxumPath(ScopedWorkspacePath {
                workspace_id: workspace_id.clone(),
            }),
            {
                let mut headers = HeaderMap::new();
                headers.insert(
                    "x-yoi-runtime-id",
                    axum::http::HeaderValue::from_str(&controller.runtime_id).unwrap(),
                );
                headers.insert(
                    "x-yoi-worker-id",
                    axum::http::HeaderValue::from_str(&controller.worker_id).unwrap(),
                );
                headers
            },
            Json(conflicting_request),
        )
        .await
        .unwrap_err();
        assert_eq!(conflict.into_response().status(), StatusCode::BAD_GATEWAY);
        let grants = api
            .store
            .list_active_worker_control_grants(&workspace_id, &controller, 10)
            .unwrap();
        assert_eq!(grants.len(), 1);
        assert_eq!(
            grants[0].subject,
            RuntimeWorkerRef::new(&first.runtime_id, &first.worker_id)
        );
        assert_eq!(grants[0].operation_id, "control-spawn-retry");
    }

    #[tokio::test]
    async fn arbitrary_singleton_exact_retry_replays_while_competing_create_conflicts() {
        let workspace = tempfile::tempdir().unwrap();
        init_clean_git_workspace(workspace.path());
        let api = test_api(workspace.path()).await;
        let request = || CreateWorkspaceWorkerRequest {
            runtime_id: EMBEDDED_WORKER_RUNTIME_ID.to_string(),
            display_name: "Subject Worker".to_string(),
            singleton_key: Some("custom:subject-42".to_string()),
            profile: Some("builtin:companion".to_string()),
            ticket_assignment: None,
            initial_submit: Vec::new(),
            workdir_attachments: Vec::new(),
            feature_connections: Default::default(),
            control_operation_id: None,
            execution_grant: None,
        };

        let Json(created) =
            create_workspace_worker(State(api.clone()), HeaderMap::new(), Json(request()))
                .await
                .unwrap();
        assert_eq!(
            created.worker.singleton_key.as_deref(),
            Some("custom:subject-42")
        );
        let Json(duplicate) =
            create_workspace_worker(State(api.clone()), HeaderMap::new(), Json(request()))
                .await
                .unwrap();
        assert_eq!(duplicate.worker_id, created.worker_id);
        let mut competing_request = request();
        competing_request.display_name = "Competing Subject Worker".to_string();
        let competing = create_workspace_worker(
            State(api.clone()),
            HeaderMap::new(),
            Json(competing_request),
        )
        .await
        .unwrap_err();
        assert!(
            matches!(competing.error, Error::RepositoryConflict(message) if message.contains("worker_singleton_owned"))
        );

        let worker = RuntimeWorkerRef::new(&created.runtime_id, &created.worker_id);
        let stopped = api
            .runtime
            .stop_worker(
                &worker,
                WorkerLifecycleRequest {
                    reason: Some("singleton restore test".to_string()),
                    ticket_assignment: None,
                },
            )
            .unwrap();
        assert_eq!(stopped.state, InternalWorkerOperationState::Accepted);
        let Json(stopped_retry) =
            create_workspace_worker(State(api.clone()), HeaderMap::new(), Json(request()))
                .await
                .unwrap();
        assert_eq!(stopped_retry.worker_id, created.worker_id);
        let mut stopped_competing_request = request();
        stopped_competing_request.display_name = "Stopped competing Worker".to_string();
        let stopped_competing = create_workspace_worker(
            State(api.clone()),
            HeaderMap::new(),
            Json(stopped_competing_request),
        )
        .await
        .unwrap_err();
        assert!(matches!(
            stopped_competing.error,
            Error::RepositoryConflict(_)
        ));

        let restored = restore_internal_worker_intent(
            &api,
            &worker,
            format!("restore-internal:{}", WorkerId::now_v7()),
        )
        .unwrap();
        assert_eq!(restored.state, server_api::WorkerRestoreState::Rejected);
        assert_eq!(
            api.store
                .current_worker_singleton_owner(&api.config.workspace_id, "custom:subject-42",)
                .unwrap()
                .unwrap()
                .worker,
            worker
        );
    }

    #[test]
    fn subjektiv_session_cursor_is_bounded_and_rejects_non_ascii_payloads() {
        let cursor = SubjektivSessionListCursor {
            workspace_id: "workspace-a".to_string(),
            subject_id: "subject-a".to_string(),
            controller_runtime_id: "runtime-a".to_string(),
            controller_worker_id: worker_runtime::identity::WorkerId::now_v7().to_string(),
            session_id: Some("session-a".to_string()),
            storage: server_api::SubjektivSessionStorageFilter::Retained,
            snapshot_at: "2026-10-02T00:00:00Z".to_string(),
            after_attributed_at: "2026-10-01T00:00:00Z".to_string(),
            after_session_id: "session-a".to_string(),
        };
        let encoded = encode_subjektiv_cursor("session-list", &cursor).unwrap();
        let decoded: SubjektivSessionListCursor =
            decode_subjektiv_session_cursor("session-list", &encoded).unwrap();
        assert_eq!(decoded.workspace_id, cursor.workspace_id);
        assert_eq!(decoded.subject_id, cursor.subject_id);
        assert_eq!(decoded.controller_worker_id, cursor.controller_worker_id);
        assert!(matches!(
            decode_subjektiv_session_cursor::<SubjektivSessionListCursor>(
                "session-list",
                "subjektiv.session-list.éé"
            ),
            Err(server_api::SubjektivSessionBackendResponse::Error {
                error: server_api::SubjektivSessionErrorResponse {
                    code: server_api::SubjektivSessionDiagnosticCode::StaleCursor,
                    ..
                }
            })
        ));
    }

    #[test]
    fn subjektiv_session_search_exact_boundaries_are_complete() {
        assert_eq!(
            subjektiv_session_search_completion(
                false,
                20,
                20,
                SUBJEKTIV_SESSION_MAX_SCANNED_SESSIONS,
                true,
            ),
            (false, false),
            "exactly limit results at the end must not invent a continuation"
        );
        assert_eq!(
            subjektiv_session_search_completion(
                false,
                0,
                20,
                SUBJEKTIV_SESSION_MAX_SCANNED_SESSIONS,
                true,
            ),
            (false, false),
            "exactly 20 exhausted Sessions must remain complete"
        );
        assert_eq!(
            subjektiv_session_search_completion(
                true,
                0,
                20,
                SUBJEKTIV_SESSION_MAX_SCANNED_SESSIONS,
                true,
            ),
            (true, true),
            "a real unscanned twenty-first Session must remain partial"
        );
    }

