    #[tokio::test]
    async fn subjektiv_session_search_preserves_later_session_after_runtime_resume() {
        use session_store::{
            LogEntry, LoggedContentPart, LoggedHistoryEntry, LoggedItem, LoggedRole,
            LoggedSessionHistoryEntryId, LoggedSessionHistoryMetadata, LoggedSessionHistoryOrigin,
            Store as _, WorkerSessionStore,
        };

        fn public_message(id: &str, text: &str) -> LoggedHistoryEntry {
            LoggedHistoryEntry {
                item: LoggedItem::Message {
                    role: LoggedRole::User,
                    content: vec![LoggedContentPart::Text { text: text.into() }],
                },
                metadata: LoggedSessionHistoryMetadata {
                    input_metadata: None,
                    entry_id: LoggedSessionHistoryEntryId(id.to_string()),
                    origin: LoggedSessionHistoryOrigin::HumanInput {
                        account_id: "account-1".to_string(),
                    },
                    derivation: None,
                },
            }
        }

        let workspace = tempfile::tempdir().unwrap();
        init_clean_git_workspace(workspace.path());
        let api = test_api(workspace.path()).await;
        let create = |display_name: &str| CreateWorkspaceWorkerRequest {
            runtime_id: EMBEDDED_WORKER_RUNTIME_ID.to_string(),
            display_name: display_name.to_string(),
            singleton_key: None,
            profile: None,
            ticket_assignment: None,
            initial_submit: Vec::new(),
            workdir_attachments: Vec::new(),
            feature_connections: Default::default(),
            control_operation_id: None,
            execution_grant: None,
        };
        let Json(controller) = create_workspace_worker(
            State(api.clone()),
            HeaderMap::new(),
            Json(create("Session search controller")),
        )
        .await
        .unwrap();
        let Json(first_worker) = create_workspace_worker(
            State(api.clone()),
            HeaderMap::new(),
            Json(create("Large Session source")),
        )
        .await
        .unwrap();
        let Json(second_worker) = create_workspace_worker(
            State(api.clone()),
            HeaderMap::new(),
            Json(create("Later Session source")),
        )
        .await
        .unwrap();
        let controller = RuntimeWorkerRef::new(&controller.runtime_id, &controller.worker_id);
        let first_worker = RuntimeWorkerRef::new(&first_worker.runtime_id, &first_worker.worker_id);
        let second_worker =
            RuntimeWorkerRef::new(&second_worker.runtime_id, &second_worker.worker_id);

        let first_session = session_store::new_session_id();
        let first_root = workspace
            .path()
            .join(".test-embedded-runtime-store/workers")
            .join(&first_worker.worker_id)
            .join("session");
        let first_store = WorkerSessionStore::new(&first_root).unwrap();
        for index in 0..65_u128 {
            first_store
                .create_segment(
                    first_session,
                    uuid::Uuid::from_u128(20_000 + index),
                    &[LogEntry::AnnotatedSegmentStart {
                        ts: 1,
                        session_id: first_session,
                        system_prompt: None,
                        config: agen::llm_client::RequestConfig::default(),
                        history: vec![public_message(
                            &format!("first-{index}"),
                            if index == 64 { "needle" } else { "ordinary" },
                        )],
                        forked_from: None,
                        compacted_from: None,
                    }],
                )
                .unwrap();
        }
        let second_session = session_store::new_session_id();
        let second_root = workspace
            .path()
            .join(".test-embedded-runtime-store/workers")
            .join(&second_worker.worker_id)
            .join("session");
        WorkerSessionStore::new(&second_root)
            .unwrap()
            .create_segment(
                second_session,
                uuid::Uuid::from_u128(30_000),
                &[LogEntry::AnnotatedSegmentStart {
                    ts: 1,
                    session_id: second_session,
                    system_prompt: None,
                    config: agen::llm_client::RequestConfig::default(),
                    history: vec![public_message("second", "needle in later Session")],
                    forked_from: None,
                    compacted_from: None,
                }],
            )
            .unwrap();

        let store = open_subjektiv_store(&api).unwrap();
        let subject = store
            .create_subject(crate::subjektiv::SubjectRole::new("companion").unwrap())
            .unwrap();
        for (worker, session_id, attributed_at) in [
            (&first_worker, first_session, "2026-10-02T00:00:02Z"),
            (&second_worker, second_session, "2026-10-02T00:00:01Z"),
        ] {
            let mut attribution = crate::subjektiv::SubjectSessionAttribution::new(
                &subject.id,
                &worker.runtime_id,
                &worker.worker_id,
                session_id.to_string(),
            )
            .unwrap();
            attribution.attributed_at = attributed_at.to_string();
            store.record_session_attribution(attribution).unwrap();
            api.store
                .create_worker_control_grant(&WorkerControlGrantRecord {
                    workspace_id: TEST_WORKSPACE_ID.to_string(),
                    grant_id: format!("search-observe-{}", worker.worker_id),
                    controller: controller.clone(),
                    subject: worker.clone(),
                    relation: "subject_session".to_string(),
                    origin: "test".to_string(),
                    permissions: vec!["observe".to_string()],
                    operation_id: format!("search-observe-{}", worker.worker_id),
                    created_at: Utc::now().to_rfc3339(),
                    revoked_at: None,
                })
                .unwrap();
        }

        let search = |cursor| {
            subjektiv_session_search(
                &api,
                &store,
                TEST_WORKSPACE_ID,
                &subject.id,
                &controller,
                server_api::SubjektivSessionSearchRequest {
                    query: Some("needle".to_string()),
                    session_id: None,
                    kind: None,
                    tool_name: None,
                    tool_part: server_api::SubjektivSessionToolPart::Both,
                    limit: Some(1),
                    cursor,
                },
            )
        };
        let page = |response| match response {
            server_api::SubjektivSessionBackendResponse::Ok {
                result: server_api::SubjektivSessionBackendResult::Search(page),
            } => page,
            other => panic!("unexpected Session search response: {other:?}"),
        };

        let first = page(search(None));
        assert!(first.items.is_empty());
        assert!(first.has_more);
        let second = page(search(first.next_cursor));
        assert_eq!(second.items.len(), 1);
        assert_eq!(second.items[0].session_id, first_session.to_string());
        assert!(
            second.has_more,
            "the outer attribution continuation must survive a resumed Runtime page"
        );
        let third = page(search(second.next_cursor));
        assert_eq!(third.items.len(), 1);
        assert_eq!(third.items[0].session_id, second_session.to_string());
        assert!(!third.has_more);
        assert!(third.next_cursor.is_none());
    }

    #[tokio::test]
    async fn archived_session_search_and_read_reauthorize_after_grant_revocation() {
        use session_store::{
            LogEntry, LoggedContentPart, LoggedHistoryEntry, LoggedItem, LoggedRole,
            LoggedSessionHistoryEntryId, LoggedSessionHistoryMetadata, LoggedSessionHistoryOrigin,
            Store as _, WorkerSessionStore,
        };

        fn public_message(id: &str, text: &str) -> LoggedHistoryEntry {
            LoggedHistoryEntry {
                item: LoggedItem::Message {
                    role: LoggedRole::User,
                    content: vec![LoggedContentPart::Text { text: text.into() }],
                },
                metadata: LoggedSessionHistoryMetadata {
                    input_metadata: None,
                    entry_id: LoggedSessionHistoryEntryId(id.to_string()),
                    origin: LoggedSessionHistoryOrigin::HumanInput {
                        account_id: "account-1".to_string(),
                    },
                    derivation: None,
                },
            }
        }

        let workspace = tempfile::tempdir().unwrap();
        init_clean_git_workspace(workspace.path());
        let api = test_api(workspace.path()).await;
        let Json(orchestrator) = scoped_start_workspace_orchestrator(
            State(api.clone()),
            AxumPath(ScopedWorkspacePath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
            }),
        )
        .await
        .unwrap();
        let controller = orchestrator.worker.unwrap();
        let controller = RuntimeWorkerRef::new(&controller.runtime_id, &controller.worker_id);
        let spawned = api
            .spawn_workspace_worker(
                EMBEDDED_WORKER_RUNTIME_ID,
                WorkerSpawnRequest {
                    intent: WorkerSpawnIntent::WorkspaceCompanion,
                    requested_worker_name: Some("archived Session source".to_string()),
                    singleton_key: None,
                    acceptance: WorkerSpawnAcceptanceRequirement::RunAccepted {
                        expected_segments: 0,
                    },
                    profile: worker_runtime::catalog::ProfileSelector::Builtin(
                        "builtin:companion".to_string(),
                    ),
                    ticket_assignment: None,
                    initial_submit: Vec::new(),
                    workdir_attachment_requests: Vec::new(),
                    resolved_workdir_attachment_requests: Vec::new(),
                    resolved_workdir_attachments: Vec::new(),
                    resolved_config_bundle: Some(runtime_test_bundle()),
                    resolved_worker_observation_enabled: false,
                    resolved_worker_observation_grants: Vec::new(),
                    resolved_workspace_api: None,
                    resolved_memory_settings: None,
                    resolved_subjektiv_attached: false,
                    resolved_control_operation: None,
                    resolved_execution_grant: None,
                },
            )
            .unwrap();
        let target = spawned.worker.unwrap().worker;
        let stopped = api
            .runtime
            .stop_worker(
                &target,
                WorkerLifecycleRequest {
                    reason: Some("prepare archive revocation regression".to_string()),
                    ticket_assignment: None,
                },
            )
            .unwrap();
        assert_eq!(stopped.state, InternalWorkerOperationState::Accepted);

        let session_id = session_store::new_session_id();
        let segment_id = uuid::Uuid::from_u128(40_000);
        let session_root = workspace
            .path()
            .join(".test-embedded-runtime-store/workers")
            .join(&target.worker_id)
            .join("session");
        WorkerSessionStore::new(&session_root)
            .unwrap()
            .create_segment(
                session_id,
                segment_id,
                &[LogEntry::AnnotatedSegmentStart {
                    ts: 1,
                    session_id,
                    system_prompt: None,
                    config: agen::llm_client::RequestConfig::default(),
                    history: vec![
                        public_message("archive-a", "archived first entry"),
                        public_message("archive-b", "archived second entry"),
                    ],
                    forked_from: None,
                    compacted_from: None,
                }],
            )
            .unwrap();
        let subjektiv_store = open_subjektiv_store(&api).unwrap();
        let subject = subjektiv_store
            .create_subject(crate::subjektiv::SubjectRole::new("companion").unwrap())
            .unwrap();
        subjektiv_store
            .record_session_attribution(
                crate::subjektiv::SubjectSessionAttribution::new(
                    &subject.id,
                    &target.runtime_id,
                    &target.worker_id,
                    session_id.to_string(),
                )
                .unwrap(),
            )
            .unwrap();
        let grant_id = "archive-revocable-observe";
        api.store
            .create_worker_control_grant(&WorkerControlGrantRecord {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
                grant_id: grant_id.to_string(),
                controller: controller.clone(),
                subject: target.clone(),
                relation: "subject_session".to_string(),
                origin: "test".to_string(),
                permissions: vec!["observe".to_string(), "remove".to_string()],
                operation_id: "archive-revocation-proof".to_string(),
                created_at: Utc::now().to_rfc3339(),
                revoked_at: None,
            })
            .unwrap();
        let summary = api.runtime.worker(&target).unwrap();
        sync_worker_observation(&api, &summary).unwrap();
        let removal = WorkerRemovalService::new(&api)
            .execute_async(
                crate::worker_source::VerifiedWorkerMutationSource {
                    runtime_id: controller.runtime_id.clone(),
                    worker_id: controller.worker_id.clone(),
                    actor_kind: worker_runtime::auth::WorkerMutationActorKind::Worker,
                    permission: worker_runtime::auth::WORKER_REMOVE_PERMISSION.to_string(),
                    jti: "archive-revocation-proof".to_string(),
                },
                &target.runtime_id,
                &target.worker_id,
                "archive Session for revocation regression",
            )
            .await
            .unwrap();
        assert_eq!(removal.status, StatusCode::OK.as_u16(), "{}", removal.body);
        assert!(
            api.config_store
                .worker_session_archive(TEST_WORKSPACE_ID, &target, &session_id.to_string())
                .unwrap()
                .is_some(),
            "removal must commit the archive catalog before backend reads"
        );

        let search_request = |cursor| server_api::SubjektivSessionSearchRequest {
            query: None,
            session_id: Some(session_id.to_string()),
            kind: None,
            tool_name: None,
            tool_part: server_api::SubjektivSessionToolPart::Both,
            limit: Some(1),
            cursor,
        };
        let first = subjektiv_session_search(
            &api,
            &subjektiv_store,
            TEST_WORKSPACE_ID,
            &subject.id,
            &controller,
            search_request(None),
        );
        let cursor = match first {
            server_api::SubjektivSessionBackendResponse::Ok {
                result: server_api::SubjektivSessionBackendResult::Search(page),
            } => {
                assert_eq!(page.items.len(), 1);
                assert!(page.has_more);
                page.next_cursor.unwrap()
            }
            other => panic!("unexpected archived Session search response: {other:?}"),
        };

        assert!(
            api.store
                .revoke_worker_control_grant(TEST_WORKSPACE_ID, grant_id, &Utc::now().to_rfc3339())
                .unwrap()
        );
        assert!(matches!(
            subjektiv_session_search(
                &api,
                &subjektiv_store,
                TEST_WORKSPACE_ID,
                &subject.id,
                &controller,
                search_request(Some(cursor)),
            ),
            server_api::SubjektivSessionBackendResponse::Error {
                error: server_api::SubjektivSessionErrorResponse {
                    code: server_api::SubjektivSessionDiagnosticCode::NotFoundOrNotAuthorized,
                    ..
                }
            }
        ));
        assert!(matches!(
            subjektiv_session_read(
                &api,
                &subjektiv_store,
                TEST_WORKSPACE_ID,
                &subject.id,
                &controller,
                server_api::SubjektivSessionReadRequest {
                    session_id: session_id.to_string(),
                    segment_id: segment_id.to_string(),
                    entry_ref: "Earchive-a".to_string(),
                    mode: server_api::SubjektivSessionReadMode::Full,
                    cursor: None,
                },
            ),
            server_api::SubjektivSessionBackendResponse::Error {
                error: server_api::SubjektivSessionErrorResponse {
                    code: server_api::SubjektivSessionDiagnosticCode::NotFoundOrNotAuthorized,
                    ..
                }
            }
        ));
    }

    #[test]
    fn subjektiv_session_read_budget_uses_serialized_json_and_preserves_pages() {
        fn response(
            content: String,
            has_more: bool,
        ) -> server_api::SubjektivSessionBackendResponse {
            server_api::SubjektivSessionBackendResponse::Ok {
                result: server_api::SubjektivSessionBackendResult::Read(
                    server_api::SubjektivSessionReadResponse {
                        session_id: "session-a".into(),
                        segment_id: "segment-a".into(),
                        entry_ref: "Eentry-a".into(),
                        kind: server_api::SubjektivSessionEntryKind::User,
                        origin: protocol::SessionEntryProvenance::HumanInput,
                        lineage: server_api::SubjektivSessionLineage {
                            kind: server_api::SubjektivSessionLineageKind::Root,
                            parent_segment_id: None,
                            at_turn_index: None,
                        },
                        mode: server_api::SubjektivSessionReadMode::Full,
                        content,
                        truncated: has_more,
                        next_cursor: has_more.then(|| "opaque-cursor".into()),
                        has_more,
                    },
                ),
            }
        }

        let content = "\0".repeat(server_api::SUBJEKTIV_SESSION_MAX_READ_CONTENT_BYTES);
        assert!(
            !subjektiv_session_response_fits_model_budget(&response(content.clone(), true))
                .unwrap(),
            "the raw 16 KiB limit is not safe for JSON-escaped content"
        );
        let split = content.len() / 2;
        let first = response(content[..split].to_string(), true);
        let second = response(content[split..].to_string(), false);
        assert!(subjektiv_session_response_fits_model_budget(&first).unwrap());
        assert!(subjektiv_session_response_fits_model_budget(&second).unwrap());
        let chunks = [first, second]
            .into_iter()
            .map(|response| match response {
                server_api::SubjektivSessionBackendResponse::Ok {
                    result: server_api::SubjektivSessionBackendResult::Read(read),
                } => read.content,
                _ => unreachable!(),
            })
            .collect::<String>();
        assert_eq!(chunks, content);
    }

    #[tokio::test]
    async fn legacy_memory_reset_requires_owner_confirmation_and_preserves_subjektiv() {
        let workspace = tempfile::tempdir().unwrap();
        init_clean_git_workspace(workspace.path());
        let api = test_api(workspace.path()).await;
        api.store
            .upsert_memory_document(&crate::store::MemoryDocumentRecord {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
                body_md: "# Legacy Memory\n\nRetained until explicit reset.\n".to_string(),
                created_at: "2026-10-02T00:00:00Z".to_string(),
                updated_at: "2026-10-02T00:00:00Z".to_string(),
            })
            .unwrap();
        api.store
            .upsert_memory_staging_record(&crate::store::MemoryStagingRecord {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
                candidate_id: "legacy-pending".to_string(),
                raw_json: r#"{"claim":"pending"}"#.to_string(),
                source_path: None,
                imported_at: "2026-10-02T00:00:00Z".to_string(),
            })
            .unwrap();
        api.store
            .insert_memory_staging_resolution(&crate::store::MemoryStagingResolutionRecord {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
                candidate_id: "legacy-resolved".to_string(),
                action: "discarded".to_string(),
                reason: "fixture".to_string(),
                affected_refs_json: "[]".to_string(),
                staging_raw_json: r#"{"claim":"resolved"}"#.to_string(),
                source_path: None,
                imported_at: "2026-10-02T00:00:00Z".to_string(),
                resolved_at: "2026-10-02T00:01:00Z".to_string(),
            })
            .unwrap();

        let subjektiv = open_subjektiv_store(&api).unwrap();
        let subject = subjektiv
            .create_subject(crate::subjektiv::SubjectRole::new("companion").unwrap())
            .unwrap();
        let memory = subjektiv
            .create_memory(
                &subject.id,
                crate::subjektiv::MemoryDraft::active(
                    memory::extract::CandidateKind::Decision,
                    "Preserve feature Memory",
                    "This record is outside the legacy reset scope.",
                    "Proves reset isolation",
                    "fixture",
                ),
            )
            .unwrap();

        let incorrect = scoped_reset_legacy_memory(
            State(api.clone()),
            AxumPath(ScopedWorkspacePath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
            }),
            Extension(test_owner_actor()),
            Json(server_api::LegacyMemoryResetRequest {
                confirmation: "RESET LEGACY MEMORY wrong-workspace".to_string(),
            }),
        )
        .await
        .unwrap_err();
        assert_eq!(incorrect.into_response().status(), StatusCode::BAD_REQUEST);
        assert!(
            api.store
                .get_memory_document(TEST_WORKSPACE_ID)
                .unwrap()
                .is_some()
        );

        let mut non_owner = test_owner_actor();
        non_owner.account_id = "another-account".to_string();
        let forbidden = scoped_reset_legacy_memory(
            State(api.clone()),
            AxumPath(ScopedWorkspacePath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
            }),
            Extension(non_owner),
            Json(server_api::LegacyMemoryResetRequest {
                confirmation: format!("RESET LEGACY MEMORY {TEST_WORKSPACE_ID}"),
            }),
        )
        .await
        .unwrap_err();
        assert_eq!(forbidden.into_response().status(), StatusCode::FORBIDDEN);

        let Json(reset) = scoped_reset_legacy_memory(
            State(api.clone()),
            AxumPath(ScopedWorkspacePath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
            }),
            Extension(test_owner_actor()),
            Json(server_api::LegacyMemoryResetRequest {
                confirmation: format!("RESET LEGACY MEMORY {TEST_WORKSPACE_ID}"),
            }),
        )
        .await
        .unwrap();
        assert_eq!(reset.documents_deleted, 1);
        assert_eq!(reset.staging_records_deleted, 1);
        assert_eq!(reset.staging_resolutions_deleted, 1);
        assert!(
            api.store
                .get_memory_document(TEST_WORKSPACE_ID)
                .unwrap()
                .is_none()
        );
        assert_eq!(
            subjektiv
                .memory(&subject.id, &memory.id)
                .unwrap()
                .unwrap()
                .change_id,
            memory.change_id
        );

        let Json(repeated) = scoped_reset_legacy_memory(
            State(api),
            AxumPath(ScopedWorkspacePath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
            }),
            Extension(test_owner_actor()),
            Json(server_api::LegacyMemoryResetRequest {
                confirmation: format!("RESET LEGACY MEMORY {TEST_WORKSPACE_ID}"),
            }),
        )
        .await
        .unwrap();
        assert_eq!(repeated.documents_deleted, 0);
        assert_eq!(repeated.staging_records_deleted, 0);
        assert_eq!(repeated.staging_resolutions_deleted, 0);
    }

    #[tokio::test]
    async fn subjektiv_browser_routes_enforce_router_auth_scope_and_owner_reset() {
        let workspace = tempfile::tempdir().unwrap();
        init_clean_git_workspace(workspace.path());
        let api = test_api(workspace.path()).await;
        let owner_token = seed_test_api_token(api.store.as_ref(), TEST_WORKSPACE_ID);
        let non_owner_token = seed_test_api_token(api.store.as_ref(), "subjektiv-non-owner");
        let store = open_subjektiv_store(&api).unwrap();
        let subject = store
            .create_subject(crate::subjektiv::SubjectRole::new("companion").unwrap())
            .unwrap();
        let memory = store
            .create_memory(
                &subject.id,
                crate::subjektiv::MemoryDraft::active(
                    memory::extract::CandidateKind::Lesson,
                    "Router contract",
                    "Browser routes cross the generated Axum boundary.",
                    "Proves route wiring",
                    "fixture",
                ),
            )
            .unwrap();
        api.store
            .upsert_memory_document(&crate::store::MemoryDocumentRecord {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
                body_md: "# Legacy reset fixture\n".to_string(),
                created_at: "2026-10-02T00:00:00Z".to_string(),
                updated_at: "2026-10-02T00:00:00Z".to_string(),
            })
            .unwrap();
        let app = build_router(api.clone());
        let subject_root = format!(
            "/api/w/{TEST_WORKSPACE_ID}/subjektiv/subjects/{}",
            subject.id
        );
        let memory_root = format!("{subject_root}/memories/{}", memory.id);

        request_json_authenticated(
            app.clone(),
            "POST",
            &format!("{subject_root}/worker"),
            Some(serde_json::json!({})),
            &owner_token,
            StatusCode::METHOD_NOT_ALLOWED,
        )
        .await;
        request_json(
            app.clone(),
            "GET",
            &format!("/api/w/{TEST_WORKSPACE_ID}/subjektiv/subjects?limit=1"),
            None,
            StatusCode::UNAUTHORIZED,
        )
        .await;
        let subjects = request_json_authenticated(
            app.clone(),
            "GET",
            &format!("/api/w/{TEST_WORKSPACE_ID}/subjektiv/subjects?limit=1"),
            None,
            &owner_token,
            StatusCode::OK,
        )
        .await;
        assert_eq!(subjects["items"][0]["id"], subject.id);

        request_json(
            app.clone(),
            "POST",
            &format!("/api/w/{TEST_WORKSPACE_ID}/subjektiv/subjects"),
            Some(serde_json::json!({ "role": "Browser author" })),
            StatusCode::UNAUTHORIZED,
        )
        .await;
        let created = request_json_authenticated(
            app.clone(),
            "POST",
            &format!("/api/w/{TEST_WORKSPACE_ID}/subjektiv/subjects"),
            Some(serde_json::json!({
                "role": "  Browser author  ",
                "behavior_md": "Prefer explicit evidence.\nAsk when uncertain."
            })),
            &owner_token,
            StatusCode::CREATED,
        )
        .await;
        assert_eq!(created["role"], "  Browser author  ");
        assert_eq!(
            created["behavior_md"],
            "Prefer explicit evidence.\nAsk when uncertain."
        );
        assert_eq!(created["state"], "active");
        assert!(created.get("current_worker").is_none());
        let created_id = created["id"].as_str().unwrap();
        let persisted = store.subject(created_id).unwrap().unwrap();
        assert_eq!(persisted.role.as_str(), "  Browser author  ");
        assert_eq!(
            persisted.behavior_md,
            created["behavior_md"].as_str().unwrap()
        );
        let behavior_uri =
            format!("/api/w/{TEST_WORKSPACE_ID}/subjektiv/subjects/{created_id}/behavior");
        request_json(
            app.clone(),
            "PATCH",
            &behavior_uri,
            Some(serde_json::json!({
                "expected_behavior_md": "Prefer explicit evidence.\nAsk when uncertain.",
                "behavior_md": "Updated without rewriting history."
            })),
            StatusCode::UNAUTHORIZED,
        )
        .await;
        let updated = request_json_authenticated(
            app.clone(),
            "PATCH",
            &behavior_uri,
            Some(serde_json::json!({
                "expected_behavior_md": "Prefer explicit evidence.\nAsk when uncertain.",
                "behavior_md": "Updated without rewriting history."
            })),
            &owner_token,
            StatusCode::OK,
        )
        .await;
        assert_eq!(updated["behavior_md"], "Updated without rewriting history.");
        request_json_authenticated(
            app.clone(),
            "PATCH",
            &behavior_uri,
            Some(serde_json::json!({
                "expected_behavior_md": "Prefer explicit evidence.\nAsk when uncertain.",
                "behavior_md": "stale write"
            })),
            &owner_token,
            StatusCode::CONFLICT,
        )
        .await;
        let cleared = request_json_authenticated(
            app.clone(),
            "PATCH",
            &behavior_uri,
            Some(serde_json::json!({
                "expected_behavior_md": "Updated without rewriting history.",
                "behavior_md": ""
            })),
            &owner_token,
            StatusCode::OK,
        )
        .await;
        assert_eq!(cleared["behavior_md"], "");
        assert!(
            api.store
                .current_worker_singleton_owner(
                    TEST_WORKSPACE_ID,
                    &crate::subjektiv::subject_worker_singleton_key(created_id).unwrap(),
                )
                .unwrap()
                .is_none()
        );
        let subject_count_after_create = store.list_subjects(100).unwrap().items.len();
        request_json_authenticated(
            app.clone(),
            "POST",
            &format!("/api/w/{TEST_WORKSPACE_ID}/subjektiv/subjects"),
            Some(serde_json::json!({ "role": "   " })),
            &owner_token,
            StatusCode::BAD_REQUEST,
        )
        .await;
        assert_eq!(
            store.list_subjects(100).unwrap().items.len(),
            subject_count_after_create
        );
        request_json_authenticated(
            app.clone(),
            "POST",
            "/api/w/another-workspace/subjektiv/subjects",
            Some(serde_json::json!({ "role": "Cross Workspace" })),
            &owner_token,
            StatusCode::NOT_FOUND,
        )
        .await;
        assert_eq!(
            store.list_subjects(100).unwrap().items.len(),
            subject_count_after_create
        );
        for uri in [
            subject_root.clone(),
            format!("{subject_root}/surface"),
            format!("{subject_root}/memories?limit=1"),
            memory_root.clone(),
            format!("{memory_root}/changes?limit=1"),
        ] {
            request_json_authenticated(
                app.clone(),
                "GET",
                &uri,
                None,
                &owner_token,
                StatusCode::OK,
            )
            .await;
        }
        request_json_authenticated(
            app.clone(),
            "GET",
            "/api/w/another-workspace/subjektiv/subjects?limit=1",
            None,
            &owner_token,
            StatusCode::NOT_FOUND,
        )
        .await;
        request_json_authenticated(
            app.clone(),
            "POST",
            &format!("/api/w/{TEST_WORKSPACE_ID}/memory/reset"),
            Some(serde_json::json!({
                "confirmation": format!("RESET LEGACY MEMORY {TEST_WORKSPACE_ID}"),
            })),
            &non_owner_token,
            StatusCode::FORBIDDEN,
        )
        .await;
        assert!(
            api.store
                .get_memory_document(TEST_WORKSPACE_ID)
                .unwrap()
                .is_some()
        );
        let reset = request_json_authenticated(
            app,
            "POST",
            &format!("/api/w/{TEST_WORKSPACE_ID}/memory/reset"),
            Some(serde_json::json!({
                "confirmation": format!("RESET LEGACY MEMORY {TEST_WORKSPACE_ID}"),
            })),
            &owner_token,
            StatusCode::OK,
        )
        .await;
        assert_eq!(reset["documents_deleted"], 1);
        assert_eq!(
            store
                .scoped_memory(&subject.id, &memory.id)
                .unwrap()
                .change_id,
            memory.change_id
        );
    }

    #[tokio::test]
    async fn subjektiv_browser_behavior_create_update_clear_and_conflict_are_typed() {
        let workspace = tempfile::tempdir().unwrap();
        init_clean_git_workspace(workspace.path());
        let api = test_api(workspace.path()).await;

        let (status, Json(created)) = scoped_create_subjektiv_subject(
            State(api.clone()),
            AxumPath(ScopedWorkspacePath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
            }),
            Json(server_api::SubjektivSubjectCreateRequest {
                role: "companion".to_string(),
                behavior_md: "Prefer explicit evidence.".to_string(),
            }),
        )
        .await
        .unwrap();
        assert_eq!(status, StatusCode::CREATED);

        assert_eq!(created.behavior_md, "Prefer explicit evidence.");

        let Json(updated) = scoped_update_subjektiv_subject_behavior(
            State(api.clone()),
            AxumPath(ScopedSubjektivSubjectPath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
                subject_id: created.id.clone(),
            }),
            Json(server_api::SubjektivSubjectBehaviorUpdateRequest {
                expected_behavior_md: created.behavior_md.clone(),
                behavior_md: "Ask when uncertain.".to_string(),
            }),
        )
        .await
        .unwrap();

        assert_eq!(updated.behavior_md, "Ask when uncertain.");

        let conflict = scoped_update_subjektiv_subject_behavior(
            State(api.clone()),
            AxumPath(ScopedSubjektivSubjectPath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
                subject_id: created.id.clone(),
            }),
            Json(server_api::SubjektivSubjectBehaviorUpdateRequest {
                expected_behavior_md: created.behavior_md.clone(),
                behavior_md: "Stale edit".to_string(),
            }),
        )
        .await
        .unwrap_err();
        assert_eq!(conflict.into_response().status(), StatusCode::CONFLICT);

        let Json(cleared) = scoped_update_subjektiv_subject_behavior(
            State(api.clone()),
            AxumPath(ScopedSubjektivSubjectPath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
                subject_id: created.id,
            }),
            Json(server_api::SubjektivSubjectBehaviorUpdateRequest {
                expected_behavior_md: updated.behavior_md.clone(),
                behavior_md: String::new(),
            }),
        )
        .await
        .unwrap();

        assert!(cleared.behavior_md.is_empty());

        let oversized = scoped_create_subjektiv_subject(
            State(api),
            AxumPath(ScopedWorkspacePath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
            }),
            Json(server_api::SubjektivSubjectCreateRequest {
                role: "reviewer".to_string(),
                behavior_md: "x".repeat(server_api::SUBJEKTIV_MAX_BEHAVIOR_BYTES + 1),
            }),
        )
        .await
        .unwrap_err();
        assert_eq!(oversized.into_response().status(), StatusCode::BAD_REQUEST);
    }

    #[tokio::test]
    async fn subjektiv_browser_reads_are_bounded_scoped_and_change_id_exact() {
        let workspace = tempfile::tempdir().unwrap();
        init_clean_git_workspace(workspace.path());
        let api = test_api(workspace.path()).await;
        let store = open_subjektiv_store(&api).unwrap();
        let first_subject = store
            .create_subject(crate::subjektiv::SubjectRole::new("companion").unwrap())
            .unwrap();
        let second_subject = store
            .create_subject(crate::subjektiv::SubjectRole::new("reviewer").unwrap())
            .unwrap();

        let invalid_limit = scoped_list_subjektiv_subjects(
            State(api.clone()),
            AxumPath(ScopedWorkspacePath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
            }),
            Query(server_api::SubjektivSubjectListQuery {
                limit: Some(0),
                cursor: None,
            }),
        )
        .await
        .unwrap_err();
        assert_eq!(
            invalid_limit.into_response().status(),
            StatusCode::BAD_REQUEST
        );

        let Json(subjects) = scoped_list_subjektiv_subjects(
            State(api.clone()),
            AxumPath(ScopedWorkspacePath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
            }),
            Query(server_api::SubjektivSubjectListQuery {
                limit: Some(1),
                cursor: None,
            }),
        )
        .await
        .unwrap();
        assert_eq!(subjects.items.len(), 1);
        assert!(subjects.has_more);
        let Json(next_subjects) = scoped_list_subjektiv_subjects(
            State(api.clone()),
            AxumPath(ScopedWorkspacePath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
            }),
            Query(server_api::SubjektivSubjectListQuery {
                limit: Some(1),
                cursor: subjects.next_cursor.clone(),
            }),
        )
        .await
        .unwrap();
        assert_eq!(next_subjects.items.len(), 1);
        assert_ne!(next_subjects.items[0].id, subjects.items[0].id);
        assert!(!next_subjects.has_more);
        assert!(next_subjects.next_cursor.is_none());

        let missing = scoped_get_subjektiv_subject(
            State(api.clone()),
            AxumPath(ScopedSubjektivSubjectPath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
                subject_id: "missing-subject".to_string(),
            }),
        )
        .await
        .unwrap_err();
        assert_eq!(missing.into_response().status(), StatusCode::NOT_FOUND);
        assert_eq!(store.list_subjects(100).unwrap().items.len(), 2);

        let Json(subject_detail) = scoped_get_subjektiv_subject(
            State(api.clone()),
            AxumPath(ScopedSubjektivSubjectPath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
                subject_id: first_subject.id.clone(),
            }),
        )
        .await
        .unwrap();
        assert_eq!(subject_detail.id, first_subject.id);
        let Json(ungenerated) = scoped_get_subjektiv_resident_surface(
            State(api.clone()),
            AxumPath(ScopedSubjektivSubjectPath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
                subject_id: first_subject.id.clone(),
            }),
        )
        .await
        .unwrap();
        assert_eq!(
            ungenerated.availability,
            server_api::SubjektivResidentSurfaceAvailability::Ungenerated
        );
        assert!(ungenerated.snapshot.is_none());

        let memory = store
            .create_memory(
                &first_subject.id,
                crate::subjektiv::MemoryDraft::active(
                    memory::extract::CandidateKind::Lesson,
                    "Keep exact changes",
                    "first body",
                    "Supports historical reads",
                    "initial",
                ),
            )
            .unwrap();
        let revised = store
            .revise_memory(
                &first_subject.id,
                &memory.id,
                memory.change_id.clone(),
                crate::subjektiv::MemoryDraft::active(
                    memory::extract::CandidateKind::Lesson,
                    "Keep exact changes",
                    "second body",
                    "Supports historical reads",
                    "correction",
                ),
            )
            .unwrap();
        let other_memory = store
            .create_memory(
                &second_subject.id,
                crate::subjektiv::MemoryDraft::active(
                    memory::extract::CandidateKind::Decision,
                    "Keep subjects isolated",
                    "other body",
                    "Prevents cross-subject reads",
                    "initial",
                ),
            )
            .unwrap();

        let Json(memories) = scoped_list_subjektiv_memories(
            State(api.clone()),
            AxumPath(ScopedSubjektivSubjectPath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
                subject_id: first_subject.id.clone(),
            }),
            Query(server_api::SubjektivMemoryQueryRequest {
                query: None,
                kinds: None,
                states: None,
                limit: Some(1),
                cursor: None,
            }),
        )
        .await
        .unwrap();
        assert_eq!(memories.items.len(), 1);
        assert_eq!(memories.items[0].id, memory.id);
        assert_eq!(memories.items[0].change_id, revised.change_id);

        let missing_memory = scoped_get_subjektiv_memory(
            State(api.clone()),
            AxumPath(ScopedSubjektivMemoryPath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
                subject_id: first_subject.id.clone(),
                memory_id: "missing-memory".to_string(),
            }),
            Query(server_api::SubjektivMemoryDetailQuery::default()),
        )
        .await
        .unwrap_err();
        assert_eq!(
            missing_memory.into_response().status(),
            StatusCode::NOT_FOUND
        );

        let missing_change_id = scoped_get_subjektiv_memory(
            State(api.clone()),
            AxumPath(ScopedSubjektivMemoryPath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
                subject_id: first_subject.id.clone(),
                memory_id: memory.id.clone(),
            }),
            Query(server_api::SubjektivMemoryDetailQuery {
                change_id: Some("missing-change".into()),
                ..Default::default()
            }),
        )
        .await
        .unwrap_err();
        assert_eq!(
            missing_change_id.into_response().status(),
            StatusCode::NOT_FOUND
        );

        let invalid_change_id = scoped_get_subjektiv_memory(
            State(api.clone()),
            AxumPath(ScopedSubjektivMemoryPath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
                subject_id: first_subject.id.clone(),
                memory_id: memory.id.clone(),
            }),
            Query(server_api::SubjektivMemoryDetailQuery {
                change_id: Some(String::new()),
                ..Default::default()
            }),
        )
        .await
        .unwrap_err();
        assert_eq!(
            invalid_change_id.into_response().status(),
            StatusCode::BAD_REQUEST
        );

        let cross_subject = scoped_get_subjektiv_memory(
            State(api.clone()),
            AxumPath(ScopedSubjektivMemoryPath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
                subject_id: first_subject.id.clone(),
                memory_id: other_memory.id,
            }),
            Query(server_api::SubjektivMemoryDetailQuery::default()),
        )
        .await
        .unwrap_err();
        assert_eq!(
            cross_subject.into_response().status(),
            StatusCode::FORBIDDEN
        );

        let Json(historical) = scoped_get_subjektiv_memory(
            State(api.clone()),
            AxumPath(ScopedSubjektivMemoryPath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
                subject_id: first_subject.id.clone(),
                memory_id: memory.id.clone(),
            }),
            Query(server_api::SubjektivMemoryDetailQuery {
                change_id: Some(memory.change_id.clone()),
                ..Default::default()
            }),
        )
        .await
        .unwrap();
        assert_eq!(historical.change_id, memory.change_id);
        assert_eq!(historical.current_change_id, revised.change_id);
        assert_eq!(historical.body_md, "first body");

        let Json(changes) = scoped_list_subjektiv_memory_changes(
            State(api.clone()),
            AxumPath(ScopedSubjektivMemoryPath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
                subject_id: first_subject.id.clone(),
                memory_id: memory.id.clone(),
            }),
            Query(server_api::SubjektivMemoryChangesQuery {
                limit: Some(1),
                cursor: None,
            }),
        )
        .await
        .unwrap();
        assert_eq!(changes.current_change_id, revised.change_id);
        assert_eq!(changes.items[0].change_id, revised.change_id);
        assert!(changes.has_more);

        let generation = store.prepare_surface_generation(&first_subject.id).unwrap();
        let expected_ref = crate::subjektiv::MemoryChangeRef {
            memory_id: revised.id.clone(),
            change_id: revised.change_id.clone(),
        };
        store
            .publish_surface_generation(
                &first_subject.id,
                &generation.id,
                vec![crate::subjektiv::SurfacePoint {
                    body_md: "- Keep exact changes".to_string(),
                    memory_refs: vec![expected_ref.clone()],
                }],
            )
            .unwrap();
        let Json(surface) = scoped_get_subjektiv_resident_surface(
            State(api),
            AxumPath(ScopedSubjektivSubjectPath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
                subject_id: first_subject.id,
            }),
        )
        .await
        .unwrap();
        assert_eq!(
            surface.availability,
            server_api::SubjektivResidentSurfaceAvailability::Ready
        );
        let snapshot = surface.snapshot.unwrap();
        assert_eq!(snapshot.memory_refs.len(), 1);
        assert_eq!(snapshot.memory_refs[0].memory_id, expected_ref.memory_id);
        assert_eq!(snapshot.memory_refs[0].change_id, expected_ref.change_id);
    }

    #[tokio::test]
    async fn ordinary_worker_launch_validates_optional_subjektiv_connection() {
        let workspace = tempfile::tempdir().unwrap();
        init_clean_git_workspace(workspace.path());
        let (api, execution) = test_api_with_recording_backend(workspace.path()).await;
        let store = open_subjektiv_store(&api).unwrap();
        let active = store
            .create_subject(crate::subjektiv::SubjectRole::new("companion").unwrap())
            .unwrap();
        let retired = store
            .create_subject(crate::subjektiv::SubjectRole::new("retired").unwrap())
            .unwrap();
        // Frozen lifecycle fixture: migration preserves old inactive Subjects; there is
        // intentionally no public operation that creates this historical state anymore.
        api.feature_storage.open(&api.subjektiv_registration).unwrap()
            .try_transaction::<_, feature_storage::FeatureStorageError>(|tx| {
                tx.execute("UPDATE subjects SET state='retired', record_json=json_set(record_json,'$.state','retired') WHERE subject_id=?1", [&retired.id])?;
                Ok(())
            }).unwrap();

        let request = |subject_id: Option<&str>, profile: &str, singleton_key: Option<&str>| {
            CreateWorkspaceWorkerRequest {
                runtime_id: EMBEDDED_WORKER_RUNTIME_ID.to_string(),
                display_name: "Ordinary launch".to_string(),
                singleton_key: singleton_key.map(ToOwned::to_owned),
                profile: Some(profile.to_string()),
                ticket_assignment: None,
                initial_submit: Vec::new(),
                workdir_attachments: Vec::new(),
                feature_connections: server_api::WorkspaceWorkerFeatureConnectionsRequest {
                    subjektiv: subject_id.map(|subject_id| {
                        server_api::SubjektivWorkerConnectionRequest {
                            subject_id: subject_id.to_string(),
                        }
                    }),
                },
                control_operation_id: None,
                execution_grant: None,
            }
        };

        let Json(ordinary) = create_workspace_worker(
            State(api.clone()),
            HeaderMap::new(),
            Json(request(None, "builtin:companion", None)),
        )
        .await
        .unwrap();
        assert!(ordinary.worker.singleton_key.is_none());

        for (candidate, profile, singleton_key, expected_status) in [
            (
                "missing-subject",
                "builtin:companion",
                None,
                StatusCode::NOT_FOUND,
            ),
            (
                retired.id.as_str(),
                "builtin:companion",
                None,
                StatusCode::BAD_REQUEST,
            ),
            (
                active.id.as_str(),
                "builtin:standalone",
                None,
                StatusCode::BAD_REQUEST,
            ),
            (
                active.id.as_str(),
                "builtin:companion",
                Some("caller-key"),
                StatusCode::BAD_REQUEST,
            ),
        ] {
            let response = create_workspace_worker(
                State(api.clone()),
                HeaderMap::new(),
                Json(request(Some(candidate), profile, singleton_key)),
            )
            .await
            .unwrap_err()
            .into_response();
            assert_eq!(response.status(), expected_status, "candidate={candidate}");
        }

        let Json(first) = create_workspace_worker(
            State(api.clone()),
            HeaderMap::new(),
            Json(request(Some(&active.id), "builtin:companion", None)),
        )
        .await
        .unwrap();
        let Json(retried) = create_workspace_worker(
            State(api.clone()),
            HeaderMap::new(),
            Json(request(Some(&active.id), "builtin:companion", None)),
        )
        .await
        .unwrap();
        assert_eq!(retried.worker_id, first.worker_id);
        assert_eq!(
            first.worker.singleton_key.as_deref(),
            Some(format!("subjektiv:{}", active.id).as_str())
        );

        let worker = RuntimeWorkerRef::new(&first.runtime_id, &first.worker_id);
        let stopped = api
            .runtime
            .stop_worker(
                &worker,
                WorkerLifecycleRequest {
                    reason: Some("test subject Worker restart".to_string()),
                    ticket_assignment: None,
                },
            )
            .unwrap();
        assert_eq!(stopped.state, InternalWorkerOperationState::Accepted);
        assert_eq!(api.runtime.worker(&worker).unwrap().state, "stopped");
        execution.accept_restores();

        let Json(restored) = create_workspace_worker(
            State(api.clone()),
            HeaderMap::new(),
            Json(request(Some(&active.id), "builtin:companion", None)),
        )
        .await
        .unwrap();
        assert_eq!(restored.worker_id, first.worker_id);
        assert_eq!(restored.worker.state, "idle");
    }

    #[tokio::test]
    async fn bound_authorization_rechecks_host_subject_and_exact_parent_without_target_lookup() {
        use server_api::authorization::{
            PermissionResource, ScopedPermission, SubjectPermissionsUpdate,
        };

        // Real signed router, Host binding and permission storage; only Runtime
        // execution is substituted. No child or protected-data fixture is created.
        let workspace = tempfile::tempdir().unwrap();
        let mut api = test_api(workspace.path()).await;
        register_test_runtime(&api, WorkdirlessFixtureRuntime::RUNTIME_ID).await;
        api.runtime
            .register_or_replace(WorkdirlessFixtureRuntime::default());
        let store = open_subjektiv_store(&api).unwrap();
        let subject = store
            .create_subject_with_behavior(
                crate::subjektiv::SubjectRole::new("bound-authorization").unwrap(),
                "Protected behavior must not appear in authorization responses.".into(),
            )
            .unwrap();
        let Json(created) = create_workspace_worker(
            State(api.clone()),
            HeaderMap::new(),
            Json(CreateWorkspaceWorkerRequest {
                runtime_id: WorkdirlessFixtureRuntime::RUNTIME_ID.into(),
                display_name: "Bound authorization source".into(),
                singleton_key: None,
                profile: Some("builtin:companion".into()),
                ticket_assignment: None,
                initial_submit: vec![],
                workdir_attachments: vec![],
                feature_connections: server_api::WorkspaceWorkerFeatureConnectionsRequest {
                    subjektiv: Some(server_api::SubjektivWorkerConnectionRequest {
                        subject_id: subject.id.clone(),
                    }),
                },
                control_operation_id: None,
                execution_grant: None,
            }),
        )
        .await
        .unwrap();
        let identity = RuntimeIdentityMaterial::generate(&created.runtime_id).unwrap();
        configure_runtime_request_auth(&mut api, &identity, &created.runtime_id);
        let path = format!("/api/w/{TEST_WORKSPACE_ID}/authorization/bound-check");
        let subject_request =
            json!({"operation":"memory.resident.supply", "target":{"kind":"subject"}});
        let check = |body: Value| {
            runtime_source_request(
                &identity,
                Some(&created.worker_id),
                "POST",
                &path,
                serde_json::to_vec(&body).unwrap(),
            )
        };
        let denied = build_router(api.clone())
            .oneshot(check(subject_request.clone()))
            .await
            .unwrap();
        assert_eq!(denied.status(), StatusCode::FORBIDDEN);
        let subject_resource = PermissionResource::Subject {
            workspace_id: TEST_WORKSPACE_ID.into(),
            subject_id: subject.id.clone(),
        };
        let child_resource = PermissionResource::SubWorker {
            runtime_id: created.runtime_id.clone(),
            worker_id: created.worker_id.clone(),
            name: "not-started-child".into(),
        };
        let policy = store
            .set_subject_permissions(
                &subject.id,
                &SubjectPermissionsUpdate {
                    operation_id: Uuid::now_v7().to_string(),
                    expected_change_id: None,
                    execution: vec![
                        ScopedPermission {
                            operation: "memory.resident.supply".into(),
                            resource: subject_resource.clone(),
                        },
                        ScopedPermission {
                            operation: "worker.session.read".into(),
                            resource: child_resource.clone(),
                        },
                    ],
                    delegation: vec![],
                },
            )
            .unwrap();
        for (body, expected) in [
            (subject_request.clone(), subject_resource),
            (
                json!({"operation":"worker.session.read", "target":{"kind":"sub_worker", "name":"not-started-child"}}),
                child_resource,
            ),
        ] {
            let response = build_router(api.clone())
                .oneshot(check(body))
                .await
                .unwrap();
            assert_eq!(response.status(), StatusCode::OK);
            let bytes = to_bytes(response.into_body(), 16 * 1024).await.unwrap();
            let value: Value = serde_json::from_slice(&bytes).unwrap();
            assert_eq!(value, json!({"scope": expected}));
        }
        // A different child name cannot inherit this grant. Caller-provided Subject
        // identities are rejected at the wire boundary, not used as selectors.
        for body in [
            json!({"operation":"worker.session.read", "target":{"kind":"sub_worker", "name":"other-child"}}),
            json!({"operation":"memory.resident.supply", "target":{"kind":"subject", "subject_id":"other-subject"}}),
        ] {
            let response = build_router(api.clone())
                .oneshot(check(body))
                .await
                .unwrap();
            assert!(response.status().is_client_error());
        }
        store
            .set_subject_permissions(
                &subject.id,
                &SubjectPermissionsUpdate {
                    operation_id: Uuid::now_v7().to_string(),
                    expected_change_id: Some(policy.change_id),
                    execution: vec![],
                    delegation: vec![],
                },
            )
            .unwrap();
        let revoked = build_router(api.clone())
            .oneshot(check(subject_request))
            .await
            .unwrap();
        assert_eq!(revoked.status(), StatusCode::FORBIDDEN);
        let unsigned = Request::builder()
            .method("POST")
            .uri(&path)
            .header(CONTENT_TYPE, "application/json")
            .body(Body::from(
                json!({"operation":"memory.resident.supply", "target":{"kind":"subject"}})
                    .to_string(),
            ))
            .unwrap();
        let response = build_router(api).oneshot(unsigned).await.unwrap();
        assert!(response.status().is_client_error());
    }

