    #[tokio::test]
    async fn ticket_decisions_allow_verified_workers_without_target_assignment() {
        let dir = tempfile::tempdir().unwrap();
        let api = test_api(dir.path()).await;
        let backend = browser_ticket_backend(&api).unwrap();
        let mut input = ticket::NewTicket::new("Assigned investigation");
        input.workflow_state = Some(TicketState::Open);
        let ticket = backend.create(input.clone()).unwrap();
        let _owner = seed_live_test_coder_assignment(&api, &ticket.id, "owner").await;
        let other_ticket = backend.create(input).unwrap();
        let other = seed_live_test_coder_assignment(&api, &other_ticket.id, "other").await;
        let before = backend.show(ticket.id.clone().into()).unwrap();
        let request = ticket::TicketCaseUpdate {
            action: ticket::TicketCaseAction::Close {
                reason: ticket::TicketClosureReason::Completed,
            },
            expected_closure_operation_key: None,
            author: None,
            operation_key: "authorized-case-decision".into(),
            expected_content_digest: ticket::ticket_content_digest(&before),
            expected_state: TicketState::Open,
            explanation: "Authorized case decision independent of assignment".into(),
            references: Vec::new(),
        };
        let Json(closed) = scoped_ticket_case_update(
            State(api.clone()),
            ticket_check_headers(&other),
            AxumPath((TEST_WORKSPACE_ID.into(), ticket.id.clone())),
            Json(request),
        )
        .await
        .unwrap();
        assert_eq!(closed.meta.workflow_state, TicketState::Closed);
        assert_eq!(
            closed.events.last().unwrap().attributes["source_actor_role"],
            "worker"
        );
        assert_eq!(backend.show(ticket.id.into()).unwrap(), closed);
    }

    #[tokio::test]
    async fn assigned_coder_completion_without_mr_replays_and_rejects_changed_decisions() {
        let dir = tempfile::tempdir().unwrap();
        let api = test_api(dir.path()).await;
        let backend = browser_ticket_backend(&api).unwrap();
        let mut input = ticket::NewTicket::new("Research complete without repository");
        input.workflow_state = Some(TicketState::Open);
        let reference = backend.create(input).unwrap();
        let coder = seed_live_test_coder_assignment(&api, &reference.id, "completed-coder").await;
        let before = backend.show(reference.id.clone().into()).unwrap();
        let request = ticket::TicketCaseUpdate {
            action: ticket::TicketCaseAction::Close {
                reason: ticket::TicketClosureReason::Completed,
            },
            expected_closure_operation_key: None,
            author: None,
            operation_key: "research-done".into(),
            expected_content_digest: ticket::ticket_content_digest(&before),
            expected_state: TicketState::Open,
            explanation: "## 完了理由\n\n日本語の長い検証結果を省略せず記録する。\n<!-- 完了 -->\n"
                .repeat(1024),
            references: Vec::new(),
        };
        let call = |request| {
            scoped_ticket_case_update(
                State(api.clone()),
                ticket_check_headers(&coder),
                AxumPath((TEST_WORKSPACE_ID.into(), reference.id.clone())),
                Json(request),
            )
        };
        let Json(completed) = call(request.clone()).await.unwrap();
        assert_eq!(completed.meta.workflow_state, TicketState::Closed);
        let event = completed.events.last().unwrap();
        assert_eq!(event.reason.as_deref(), Some(request.explanation.as_str()));
        assert_eq!(event.body.as_str(), request.explanation);
        assert_eq!(
            backend.show(reference.id.clone().into()).unwrap(),
            completed
        );
        assert!(
            merge_request_store(&api, TEST_WORKSPACE_ID)
                .unwrap()
                .list_for_ticket(TEST_WORKSPACE_ID, &reference.id)
                .unwrap()
                .is_empty()
        );
        let Json(replayed) = call(request.clone()).await.unwrap();
        assert_eq!(replayed.events, completed.events);
        for field in ["reason", "content_digest", "state", "references"] {
            let mut changed = request.clone();
            match field {
                "reason" => changed.explanation = "different judgment".into(),
                "content_digest" => changed.expected_content_digest = "stale".into(),
                "state" => changed.expected_state = TicketState::Closed,
                "references" => changed.references.push(ticket::TicketReference {
                    kind: "document".into(),
                    target: "other".into(),
                }),
                _ => unreachable!(),
            }
            let response = call(changed).await.unwrap_err().into_response();
            let status = response.status();
            let bytes = to_bytes(response.into_body(), usize::MAX).await.unwrap();
            assert_eq!(
                status,
                StatusCode::CONFLICT,
                "{field}: {}",
                String::from_utf8_lossy(&bytes)
            );
        }
        assert!(
            api.store
                .get_active_ticket_worker_assignment(TEST_WORKSPACE_ID, &reference.id)
                .unwrap()
                .is_none()
        );
        assert!(
            api.store
                .get_current_ticket_worker_assignment(TEST_WORKSPACE_ID, &reference.id)
                .unwrap()
                .is_some()
        );
        let mut fresh = request;
        fresh.operation_key = "unassigned-new-operation".into();
        fresh.expected_state = TicketState::Closed;
        assert!(call(fresh).await.is_err());
    }

    #[tokio::test]
    async fn close_and_reopen_api_preserves_responsibility_but_requires_fresh_routing_identity() {
        let dir = tempfile::tempdir().unwrap();
        let (api, execution) = test_api_with_recording_backend(dir.path()).await;
        let mut input = ticket::NewTicket::new("Close and reopen responsibility");
        input.workflow_state = Some(TicketState::Open);
        set_test_ticket_target(&mut input, "test-repository", "develop");
        let ticket = browser_ticket_backend(&api).unwrap().create(input).unwrap();
        // The retained delegation precedes actual Coder work. A new Assign
        // during that work would be a different operation and must be refused.
        assign_test_orchestrator(&api, &ticket.id);
        let old_coder = seed_live_test_coder_assignment(&api, &ticket.id, "old-coder").await;
        let old_orchestrator_id = format!("orchestrator-{}", ticket.id);
        let Json(started) = scoped_start_workspace_orchestrator(
            State(api.clone()),
            AxumPath(ScopedWorkspacePath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
            }),
        )
        .await
        .unwrap();
        let orchestrator = started.worker.unwrap();
        let orchestrator = RuntimeWorkerRef::new(orchestrator.runtime_id, orchestrator.worker_id);
        merge_request_store(&api, TEST_WORKSPACE_ID)
            .unwrap()
            .open_merge_request(merge_request::OpenMergeRequest {
                merge_request_id: "retained-review-context".into(),
                ticket_id: ticket.id.clone(),
                repository_id: test_repository_id(&api),
                selector_from: "work/old-coder".into(),
                selector_to: "develop".into(),
                summary: String::new(),
                auth: merge_request::MergeRequestAuth {
                    workspace_id: TEST_WORKSPACE_ID.into(),
                    repository_id: test_repository_id(&api),
                    runtime_id: old_coder.runtime_id.clone(),
                    worker_id: old_coder.worker_id.clone(),
                    assignment_id: "old-coder".into(),
                },
                now: Utc::now(),
            })
            .unwrap();
        execution.take_inputs();
        let before = browser_ticket_backend(&api)
            .unwrap()
            .show(ticket.id.clone().into())
            .unwrap();
        let Json(closed) = scoped_ticket_case_update(
            State(api.clone()),
            HeaderMap::new(),
            AxumPath((TEST_WORKSPACE_ID.into(), ticket.id.clone())),
            Json(case_test_request(
                &before,
                "normal-close",
                ticket::TicketCaseAction::Close {
                    reason: ticket::TicketClosureReason::NotPlanned,
                },
            )),
        )
        .await
        .unwrap();
        assert!(execution.take_inputs().is_empty());
        for state in ["closed", "open"] {
            if state == "open" {
                let _ = scoped_ticket_case_update(
                    State(api.clone()),
                    HeaderMap::new(),
                    AxumPath((TEST_WORKSPACE_ID.into(), ticket.id.clone())),
                    Json(case_test_request(
                        &closed,
                        "reopen",
                        ticket::TicketCaseAction::Reopen,
                    )),
                )
                .await
                .unwrap();
            }
            let path = || {
                AxumPath(ScopedRecordPath {
                    workspace_id: TEST_WORKSPACE_ID.to_string(),
                    id: ticket.id.clone(),
                })
            };
            let Json(detail) = scoped_get_ticket(State(api.clone()), path()).await.unwrap();
            assert_eq!(detail.state.as_str(), state);
            assert_eq!(detail.current_worker.unwrap().assignment_id, "old-coder");
            assert!(
                detail
                    .assignments
                    .iter()
                    .any(|assignment| assignment.assignment_id == old_orchestrator_id)
            );
            assert!(
                detail.action_eligibility.can_assign_orchestrator,
                "retained responsibility alone is not an active assignment: state={state}"
            );
            let Json(assignments) = scoped_list_ticket_assignments(State(api.clone()), path())
                .await
                .unwrap();
            assert!(
                assignments
                    .assignments
                    .iter()
                    .any(|assignment| assignment.assignment_id == "old-coder")
            );
            assert!(
                api.store
                    .list_active_ticket_role_assignments(TEST_WORKSPACE_ID, &ticket.id)
                    .unwrap()
                    .is_empty(),
                "state={state}"
            );
            let status = scoped_add_ticket_thread_event(
                State(api.clone()),
                AxumPath((TEST_WORKSPACE_ID.to_string(), ticket.id.clone())),
                HeaderMap::new(),
                Json(NewTicketEvent::new(
                    TicketEventKind::Comment,
                    "Browser activity",
                )),
            )
            .await
            .unwrap();
            assert_eq!(status, StatusCode::NO_CONTENT);
            assert!(execution.take_inputs().is_empty(), "state={state}");
            scoped_add_ticket_thread_event(
                State(api.clone()),
                AxumPath((TEST_WORKSPACE_ID.to_string(), ticket.id.clone())),
                ticket_check_headers(&old_coder),
                Json(NewTicketEvent::new(
                    TicketEventKind::Comment,
                    "Former Coder activity is ordinary Worker activity",
                )),
            )
            .await
            .unwrap();
            let activity = browser_ticket_backend(&api)
                .unwrap()
                .show(TicketIdOrSlug::Id(ticket.id.clone()))
                .unwrap();
            let attributes = &activity.events.last().unwrap().attributes;
            assert_eq!(
                attributes.get("source_actor_role").map(String::as_str),
                Some("worker"),
                "state={state}"
            );
            assert!(
                !attributes.contains_key("source_assignment_id"),
                "state={state}"
            );
            assert!(execution.take_inputs().is_empty(), "state={state}");
            let response = scoped_open_merge_request(
                State(api.clone()),
                ticket_check_headers(&old_coder),
                AxumPath((TEST_WORKSPACE_ID.to_string(), ticket.id.clone())),
                Json(server_api::OpenMergeRequestRequest {
                    repository_key: "test-repository".to_string(),
                    selector_from: "work/old-coder".to_string(),
                    selector_to: "develop".to_string(),
                    summary: "Retained context supports MR processing after closure".to_string(),
                }),
            )
            .await
            .unwrap_err()
            .into_response();
            let status = response.status();
            let bytes = to_bytes(response.into_body(), usize::MAX).await.unwrap();
            let body = String::from_utf8_lossy(&bytes);
            assert_eq!(status, StatusCode::BAD_GATEWAY, "state={state}: {body}");
            assert!(
                body.contains("source_ref_provider_unavailable"),
                "state={state}: {body}"
            );
            // The Orchestrator can initiate review itself after close/reopen.
            // This backend deliberately lacks ref observation: failure must be
            // at the provider, not a Coder-only or active-assignment guard.
            let response = scoped_register_merge_request_review_capability(
                State(api.clone()),
                ticket_check_headers(&orchestrator),
                AxumPath((TEST_WORKSPACE_ID.into(), "retained-review-context".into())),
                Json(server_api::RegisterMergeRequestReviewCapabilityRequest {
                    ticket_id: ticket.id.clone(),
                    child_session_id: "orchestrator-reviewer".into(),
                    capability_token: "test-review-token".into(),
                }),
            )
            .await
            .unwrap_err()
            .into_response();
            assert_eq!(response.status(), StatusCode::BAD_GATEWAY);
            let bytes = to_bytes(response.into_body(), usize::MAX).await.unwrap();
            assert!(String::from_utf8_lossy(&bytes).contains("source_ref_provider_unavailable"));
        }
        execute_ticket_rest_operation(
            &api,
            TEST_WORKSPACE_ID,
            HeaderMap::new(),
            TicketBackendOperation::MarkReady {
                id: TicketIdOrSlug::Id(ticket.id.clone()),
                request: ticket::TicketMarkReady {
                    operation_key: "reopened-ready".to_string(),
                    reason: Some("Fresh implementation cycle".to_string()),
                    author: None,
                    intake_summary: None,
                },
            },
        )
        .await
        .unwrap();
        assert!(execution.take_inputs().is_empty());
        let Json(assigned) = scoped_set_ticket_assignment(
            State(api.clone()),
            AxumPath((
                TEST_WORKSPACE_ID.to_string(),
                ticket.id.clone(),
                "orchestrator".to_string(),
            )),
            Json(server_api::SetTicketRoleAssignmentRequest {
                orchestrator_assignment_id: None,
                workdir_bindings: Vec::new(),
                operation_id: "fresh-orchestrator-cycle".to_string(),
                principal: server_api::TicketAssignmentPrincipal::WorkspaceAgent {
                    agent_key: "workspace-orchestrator".to_string(),
                },
                expected_assignment_id: None,
            }),
        )
        .await
        .unwrap();
        let fresh_id = assigned.assignment.unwrap().assignment_id;
        assert_ne!(fresh_id, old_orchestrator_id);
        let Json(detail) = scoped_get_ticket(
            State(api.clone()),
            AxumPath(ScopedRecordPath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
                id: ticket.id.clone(),
            }),
        )
        .await
        .unwrap();
        assert!(detail.action_eligibility.can_queue);
        assert_eq!(detail.current_worker.unwrap().assignment_id, "old-coder");
        let _ = scoped_queue_ticket_record(
            State(api.clone()),
            AxumPath((TEST_WORKSPACE_ID.to_string(), ticket.id.clone())),
            HeaderMap::new(),
        )
        .await
        .unwrap();
        let queued = browser_ticket_backend(&api)
            .unwrap()
            .show(TicketIdOrSlug::Id(ticket.id.clone()))
            .unwrap();
        assert_eq!(queued.meta.workflow_state, TicketState::Open);
        assert_eq!(
            queued
                .events
                .iter()
                .rev()
                .find_map(|event| event.attributes.get("orchestrator_assignment_id")),
            Some(&fresh_id)
        );
        let inputs = execution.take_inputs();
        assert_eq!(inputs.len(), 1);
        assert_eq!(inputs[0].0.worker_id.to_string(), orchestrator.worker_id);
        assert!(
            inputs[0]
                .1
                .starts_with("Assigned Tickets have unreceived input:")
        );
        assert!(inputs[0].1.contains(&fresh_id));
        assert!(
            api.store
                .get_active_ticket_worker_assignment(TEST_WORKSPACE_ID, &ticket.id)
                .unwrap()
                .is_none()
        );
    }

