    #[tokio::test]
    async fn skills_endpoints_use_active_virtual_config_and_ignore_repository_yoi() {
        let dir = tempfile::tempdir().unwrap();
        let skill_dir = dir.path().join(".yoi/skills/triage-errors");
        fs::create_dir_all(&skill_dir).unwrap();
        fs::write(
            skill_dir.join("SKILL.md"),
            "---\nname: triage-errors\ndescription: stale filesystem authority\n---\nfilesystem body",
        )
        .unwrap();
        let api = test_api(dir.path()).await;
        let current = api
            .config_store
            .load_workspace_config(TEST_WORKSPACE_ID)
            .unwrap()
            .unwrap();
        let main_path = config_source::VirtualPath::parse("main.dcdl").unwrap();
        let skill_path =
            config_source::VirtualPath::parse("skills/triage-errors/SKILL.md").unwrap();
        let main = format!(
            r#"{{ skills = {{ triage_errors = import "./skills/triage-errors/SKILL.md" as {}; }}; }}"#,
            skills::SKILL_DOCUMENT_SCHEMA_SOURCE
        );
        let request = crate::config_source::ConfigCommitRequest {

            base_digest: current.snapshot.digest.clone(),
            changes: vec![
                config_source::ConfigTreeChange::Update {
                    path: main_path.clone(),
                    expected_digest: current.snapshot.entries[&main_path]
                        .content_digest
                        .clone(),
                    content: main,
                },
                config_source::ConfigTreeChange::Create {
                    path: skill_path,
                    content_type: config_source::ConfigContentType::Text,
                    content: "---\nname: triage-errors\ndescription: Use the active DB-backed virtual config when triaging errors.\n---\n# Triage Errors\n\nInspect logs before changing code."
                        .to_string(),
                },
            ],
            entrypoints: current.contract.entrypoints.clone(),
        };
        let candidate = api
            .config_store
            .evaluate_workspace_config_candidate_with_schema(
                TEST_WORKSPACE_ID,
                &request,
                api.config_schema_registry.compose().unwrap(),
            )
            .unwrap();
        api.config_store
            .commit_evaluated_workspace_config(TEST_WORKSPACE_ID, &candidate)
            .unwrap();

        let Json(catalog) = scoped_list_skills(
            State(api.clone()),
            AxumPath(ScopedWorkspacePath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
            }),
        )
        .await
        .unwrap_or_else(|error| panic!("skill catalog failed: {}", error.error));
        let entry = catalog
            .entries
            .iter()
            .find(|entry| entry.name == "triage-errors")
            .expect("workspace Skill catalog entry");
        assert_eq!(entry.provenance.id, "workspace:triage-errors");
        assert_eq!(
            entry.provenance.virtual_path.as_deref(),
            Some("skills/triage-errors/SKILL.md")
        );
        assert!(entry.provenance.tree_digest.is_some());
        assert!(entry.provenance.source_digest.is_some());
        assert_ne!(entry.description, "stale filesystem authority");
        assert!(
            !serde_json::to_string(&catalog)
                .unwrap()
                .contains("# Triage Errors")
        );

        let Json(detail) = scoped_get_skill(
            State(api),
            AxumPath(ScopedSkillPath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
                name: "triage-errors".to_string(),
            }),
        )
        .await
        .unwrap_or_else(|error| panic!("skill detail failed: {}", error.error));
        assert!(detail.body.contains("# Triage Errors"));
        assert_eq!(detail.provenance.id, "workspace:triage-errors");
    }

    #[tokio::test]
    async fn workspace_runtime_trust_reveal_and_revoke_are_owner_only() {
        let temp = tempfile::tempdir().unwrap();
        let api = test_api(temp.path()).await;
        let owner_account_id = format!("account-{TEST_WORKSPACE_ID}");
        let owner = RequestActor {
            user_id: "owner-user".to_owned(),
            account_id: owner_account_id.clone(),
            handle: "owner".to_owned(),
            display_name: "Owner".to_owned(),
            auth_method: ActorAuthMethod::BrowserSession,
        };
        let non_owner = RequestActor {
            user_id: "other-user".to_owned(),
            account_id: "other-account".to_owned(),
            handle: "other".to_owned(),
            display_name: "Other".to_owned(),
            auth_method: ActorAuthMethod::ApiToken,
        };
        let identity =
            worker_runtime::auth::RuntimeIdentityMaterial::generate("runtime-a").unwrap();
        let now = Utc::now().to_rfc3339();
        api.store
            .put_workspace_runtime_binding_key(
                WorkspaceRuntimeBinding {
                    workspace_id: TEST_WORKSPACE_ID.to_owned(),
                    runtime_id: "runtime-a".to_owned(),
                    display_name: "Runtime A".to_owned(),
                    base_url: "https://runtime.example".to_owned(),
                    public_key: identity.public_key,
                    public_key_fingerprint: String::new(),
                    binding_id: "binding-test".to_string(),
                    authentication_mode: StoredRuntimeAuthenticationMode::WorkspaceIdentity,
                    created_at: now.clone(),
                    updated_at: now,
                    revoked_at: None,
                },
                None,
                &owner_account_id,
            )
            .await
            .unwrap();

        let Json(revealed) = scoped_reveal_runtime_trust_key(
            State(api.clone()),
            AxumPath(ScopedRuntimePath {
                workspace_id: TEST_WORKSPACE_ID.to_owned(),
                runtime_id: "runtime-a".to_owned(),
            }),
            Extension(owner.clone()),
        )
        .await
        .unwrap();
        assert!(revealed.public_key.starts_with("yoi-ed25519-pub:v1:"));
        let denied = scoped_reveal_runtime_trust_key(
            State(api.clone()),
            AxumPath(ScopedRuntimePath {
                workspace_id: TEST_WORKSPACE_ID.to_owned(),
                runtime_id: "runtime-a".to_owned(),
            }),
            Extension(non_owner.clone()),
        )
        .await
        .unwrap_err();
        assert_eq!(denied.into_response().status(), StatusCode::FORBIDDEN);

        let original_binding_id = api
            .store
            .get_workspace_runtime_binding(TEST_WORKSPACE_ID, "runtime-a")
            .await
            .unwrap()
            .unwrap()
            .binding_id;
        let contract_service = ServerApiContractService::Workspace(api.clone());
        let denied = <ServerApiContractService as server_api::ServerApi>::runtime_trust_key_revoke(
            &contract_service,
            non_owner,
            TEST_WORKSPACE_ID.to_owned(),
            "runtime-a".to_owned(),
            server_api::RevokeRuntimeTrustKeyRequest {
                expected_binding_id: original_binding_id.clone(),
            },
        )
        .await
        .unwrap_err();
        assert_eq!(denied.error, "Forbidden");
        <ServerApiContractService as server_api::ServerApi>::runtime_trust_key_revoke(
            &contract_service,
            owner,
            TEST_WORKSPACE_ID.to_owned(),
            "runtime-a".to_owned(),
            server_api::RevokeRuntimeTrustKeyRequest {
                expected_binding_id: original_binding_id.clone(),
            },
        )
        .await
        .unwrap();
        let binding = api
            .store
            .get_workspace_runtime_binding(TEST_WORKSPACE_ID, "runtime-a")
            .await
            .unwrap()
            .unwrap();
        assert_ne!(binding.binding_id, original_binding_id);
        assert!(binding.revoked_at.is_some());
    }

    #[tokio::test]
    async fn ssh_rotation_http_fences_key_identity_and_replays_exact_operations() {
        let temp = tempfile::tempdir().unwrap();
        let api = test_api(temp.path()).await;
        let app = build_inner_router(api).layer(Extension(test_owner_actor()));
        let base = format!("/api/w/{TEST_WORKSPACE_ID}/settings/repository-access/credentials");
        let private_key = |seed| {
            ssh_key::PrivateKey::from(ssh_key::private::Ed25519Keypair::from_seed(&[seed; 32]))
                .to_openssh(ssh_key::LineEnding::LF)
                .unwrap()
                .to_string()
        };
        let created = request_json(
            app.clone(),
            "POST",
            &base,
            Some(json!({
                "operation_id": "http-key-create", "credential_id": "http-key", "name": "HTTP key",
                "private_key": private_key(11),
            })),
            StatusCode::CREATED,
        )
        .await;
        let original_fingerprint = created["public_key_fingerprint"].clone();
        let rotate_path = format!("{base}/http-key/rotate");
        let reseal = json!({"operation_id":"http-key-reseal", "expected_public_key_fingerprint":original_fingerprint, "private_key":private_key(11)});
        let resealed = request_json(
            app.clone(),
            "POST",
            &rotate_path,
            Some(reseal.clone()),
            StatusCode::OK,
        )
        .await;
        assert_eq!(resealed["public_key_fingerprint"], original_fingerprint);
        let replayed = request_json(
            app.clone(),
            "POST",
            &rotate_path,
            Some(reseal),
            StatusCode::OK,
        )
        .await;
        assert_eq!(replayed, resealed);
        request_json(app.clone(), "POST", &rotate_path, Some(json!({
            "operation_id":"http-key-reseal", "expected_public_key_fingerprint":original_fingerprint, "private_key":private_key(12),
        })), StatusCode::CONFLICT).await;
        let rotated = request_json(app.clone(), "POST", &rotate_path, Some(json!({
            "operation_id":"http-key-rotate", "expected_public_key_fingerprint":original_fingerprint, "private_key":private_key(12),
        })), StatusCode::OK).await;
        assert_ne!(rotated["public_key_fingerprint"], original_fingerprint);
        request_json(app.clone(), "POST", &rotate_path, Some(json!({
            "operation_id":"http-key-stale", "expected_public_key_fingerprint":original_fingerprint, "private_key":private_key(13),
        })), StatusCode::CONFLICT).await;
        let current = get_json(app, &format!("{base}/http-key")).await;
        assert_eq!(
            current["public_key_fingerprint"],
            rotated["public_key_fingerprint"]
        );
        assert!(current.get("private_key").is_none());
    }

