    #[tokio::test]
    async fn destructive_worker_remove_rejects_browser_and_legacy_source_headers() {
        let headers = HeaderMap::new();
        assert!(matches!(
            crate::worker_source::presented_worker_remove_source(&headers, None),
            Err(crate::worker_source::WorkerMutationSourceProofError::Missing)
        ));

        let mut spoofed = HeaderMap::new();
        spoofed.insert("x-yoi-runtime-id", "runtime-spoofed".parse().unwrap());
        spoofed.insert("x-yoi-worker-id", "worker-spoofed".parse().unwrap());
        assert!(matches!(
            crate::worker_source::presented_worker_remove_source(&spoofed, None),
            Err(crate::worker_source::WorkerMutationSourceProofError::Missing)
        ));

        let temp = tempfile::tempdir().unwrap();
        let app = build_inner_router(test_api(temp.path()).await);
        let body = r#"{"target_runtime_id":"runtime-target","target_worker_id":"target-worker","reason":"retire target Worker"}"#;
        let browser = app
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri(format!("/api/w/{TEST_WORKSPACE_ID}/workers/remove"))
                    .header(CONTENT_TYPE, "application/json")
                    .body(Body::from(body))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(browser.status(), StatusCode::UNAUTHORIZED);
        let legacy = app
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri(format!("/api/w/{TEST_WORKSPACE_ID}/workers/remove"))
                    .header(CONTENT_TYPE, "application/json")
                    .header("x-yoi-runtime-id", "runtime-spoofed")
                    .header("x-yoi-worker-id", "worker-spoofed")
                    .body(Body::from(body))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(legacy.status(), StatusCode::UNAUTHORIZED);
        let body_spoof = app
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri(format!("/api/w/{TEST_WORKSPACE_ID}/workers/remove"))
                    .header(CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"target_runtime_id":"runtime-target","target_worker_id":"target-worker","reason":"retire target Worker","source_proof":"browser-controlled","actor":"orchestrator","policy":"purge"}"#,
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(body_spoof.status(), StatusCode::UNPROCESSABLE_ENTITY);
    }

    #[tokio::test]
    async fn embedded_worker_remove_proof_derives_source_and_rejects_replay_and_wrong_target() {
        let temp = tempfile::tempdir().unwrap();
        let api = test_api(temp.path()).await;
        seed_worker_source_member(&api, EMBEDDED_RUNTIME_ID, "7");
        let scope = worker_runtime::RuntimeWorkspaceScope::new(
            api.config.workspace_id.clone(),
            "server-unused-for-embedded",
        );
        let authority = RuntimeWorkerMutationSourceAuthority::embedded(
            EMBEDDED_RUNTIME_ID,
            &api.config.workspace_id,
        );
        let RuntimeOwnedWorkerMutationProof::InProcess(proof) = authority
            .issue_worker_remove(&scope, "7", "runtime-target", "target-worker")
            .unwrap()
        else {
            panic!("embedded Runtime must produce in-process claims");
        };

        let wrong_target = crate::worker_source::verify_worker_remove_source(
            &api,
            crate::worker_source::PresentedWorkerMutationSourceProof::InProcess(proof.clone()),
            "runtime-target",
            "different-worker",
        )
        .await;
        assert!(matches!(
            wrong_target,
            Err(crate::worker_source::WorkerMutationSourceProofError::Invalid)
        ));

        let verified = crate::worker_source::verify_worker_remove_source(
            &api,
            crate::worker_source::PresentedWorkerMutationSourceProof::InProcess(proof.clone()),
            "runtime-target",
            "target-worker",
        )
        .await
        .unwrap();
        assert_eq!(verified.runtime_id, EMBEDDED_RUNTIME_ID);
        assert_eq!(verified.worker_id, "7");
        assert_eq!(verified.permission, WORKER_REMOVE_PERMISSION);

        let replay = crate::worker_source::verify_worker_remove_source(
            &api,
            crate::worker_source::PresentedWorkerMutationSourceProof::InProcess(proof),
            "runtime-target",
            "target-worker",
        )
        .await;
        assert!(matches!(
            replay,
            Err(crate::worker_source::WorkerMutationSourceProofError::Replay)
        ));

        let RuntimeOwnedWorkerMutationProof::InProcess(fresh_proof) = authority
            .issue_worker_remove(&scope, "7", "runtime-target", "target-worker")
            .unwrap()
        else {
            panic!("embedded Runtime must produce in-process claims");
        };
        let dispatcher = crate::worker_source::EmbeddedServerWorkerMutationDispatcher::new(
            api.config.clone(),
            api.store.clone(),
        );
        let error =
            worker_runtime::worker_source::EmbeddedWorkerMutationDispatcher::execute_worker_remove(
                &dispatcher,
                fresh_proof,
                "runtime-target",
                "target-worker",
                "retire target Worker",
            )
            .unwrap_err();
        assert!(error.to_string().contains("executor is unavailable"));
    }

    #[tokio::test]
    async fn worker_remove_rejects_self_and_running_at_caller_boundary() {
        let temp = tempfile::tempdir().unwrap();
        let api = test_api(temp.path()).await;
        let Json(orchestrator) = scoped_start_workspace_orchestrator(
            State(api.clone()),
            AxumPath(ScopedWorkspacePath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
            }),
        )
        .await
        .unwrap();
        let source = orchestrator.worker.unwrap();
        let source = RuntimeWorkerRef::new(&source.runtime_id, &source.worker_id);
        let verified_source = || crate::worker_source::VerifiedWorkerMutationSource {
            runtime_id: source.runtime_id.clone(),
            worker_id: source.worker_id.clone(),
            actor_kind: worker_runtime::auth::WorkerMutationActorKind::Worker,
            permission: worker_runtime::auth::WORKER_REMOVE_PERMISSION.to_string(),
            jti: "caller-guard-proof".to_string(),
        };
        let executor = WorkerRemovalService::new(&api);
        let self_response = executor
            .execute_async(
                verified_source(),
                &source.runtime_id,
                &source.worker_id,
                "must reject self",
            )
            .await
            .unwrap();
        assert_eq!(self_response.status, StatusCode::CONFLICT.as_u16());
        assert!(self_response.body.contains("self_removal_forbidden"));

        let spawned = api
            .spawn_workspace_worker(
                EMBEDDED_WORKER_RUNTIME_ID,
                WorkerSpawnRequest {
                    intent: WorkerSpawnIntent::WorkspaceCompanion,
                    requested_worker_name: Some("guard-target".to_string()),
                    singleton_key: None,
                    acceptance: WorkerSpawnAcceptanceRequirement::RunAccepted {
                        expected_segments: 0,
                    },
                    profile: worker_runtime::catalog::ProfileSelector::Builtin(
                        "builtin:companion".to_string(),
                    ),
                    ticket_assignment: None,
                    initial_submit: Vec::new(),
                    workdir_attachment_requests: Vec::new(),
                    resolved_workdir_attachment_requests: Vec::new(),
                    resolved_workdir_attachments: Vec::new(),
                    resolved_config_bundle: Some(runtime_test_bundle()),
                    resolved_worker_observation_enabled: false,
                    resolved_worker_observation_grants: Vec::new(),
                    resolved_workspace_api: None,
                    resolved_memory_settings: None,
                    resolved_subjektiv_attached: false,
                    resolved_control_operation: None,
                    resolved_execution_grant: None,
                },
            )
            .unwrap();
        let target = spawned.worker.unwrap().worker;
        let target_summary = api.runtime.worker(&target).unwrap();
        sync_worker_observation(&api, &target_summary).unwrap();
        seed_worker_control_grant(&api, &source, &target, "caller-guard-target");
        let running_response = executor
            .execute_async(
                verified_source(),
                &target.runtime_id,
                &target.worker_id,
                "must reject a live Worker",
            )
            .await
            .unwrap();
        assert_eq!(running_response.status, StatusCode::CONFLICT.as_u16());
        assert!(running_response.body.contains("worker_not_stopped"));
    }

    #[tokio::test]
    async fn embedded_worker_remove_executes_retention_and_returns_bounded_result() {
        let temp = tempfile::tempdir().unwrap();
        let config = test_server_config(temp.path());
        let store = Arc::new(test_control_store(&config));
        seed_test_registered_workspace(store.as_ref(), &config)
            .await
            .unwrap();
        let dispatcher = Arc::new(
            crate::worker_source::EmbeddedServerWorkerMutationDispatcher::new(
                config.clone(),
                store.clone(),
            ),
        );
        // Use the same constructor-installed executor as the production embedded factory.
        let api = WorkspaceApi::new_with_execution_backend_and_broker(
            config,
            store,
            Arc::new(DeterministicExecutionBackend::default()),
            BackendResourceBroker::default(),
            HostExecutors::default(),
            Some(dispatcher.clone()),
        )
        .await
        .unwrap();
        let Json(orchestrator) = scoped_start_workspace_orchestrator(
            State(api.clone()),
            AxumPath(ScopedWorkspacePath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
            }),
        )
        .await
        .unwrap();
        let source = orchestrator.worker.unwrap();
        let source = RuntimeWorkerRef::new(&source.runtime_id, &source.worker_id);

        let spawned = api
            .spawn_workspace_worker(
                EMBEDDED_WORKER_RUNTIME_ID,
                WorkerSpawnRequest {
                    intent: WorkerSpawnIntent::WorkspaceCompanion,
                    requested_worker_name: Some("remove-target".to_string()),
                    singleton_key: None,
                    acceptance: WorkerSpawnAcceptanceRequirement::RunAccepted {
                        expected_segments: 0,
                    },
                    profile: worker_runtime::catalog::ProfileSelector::Builtin(
                        "builtin:companion".to_string(),
                    ),
                    ticket_assignment: None,
                    initial_submit: Vec::new(),
                    workdir_attachment_requests: Vec::new(),
                    resolved_workdir_attachment_requests: Vec::new(),
                    resolved_workdir_attachments: Vec::new(),
                    resolved_config_bundle: Some(runtime_test_bundle()),
                    resolved_worker_observation_enabled: false,
                    resolved_worker_observation_grants: Vec::new(),
                    resolved_workspace_api: None,
                    resolved_memory_settings: None,
                    resolved_subjektiv_attached: false,
                    resolved_control_operation: None,
                    resolved_execution_grant: None,
                },
            )
            .unwrap();
        let target = spawned.worker.unwrap().worker;
        seed_worker_control_grant(&api, &source, &target, "embedded-valid-proof");
        let target_key = api
            .store
            .worker_resource_key(TEST_WORKSPACE_ID, &target)
            .unwrap()
            .unwrap();
        let forwarder = worker_runtime::worker_source::RuntimeWorkerMutationForwarder::embedded(
            &source.runtime_id,
            worker_runtime::RuntimeWorkspaceScope::new(TEST_WORKSPACE_ID, "embedded-backend"),
            &source.worker_id,
            dispatcher,
        );
        let running = forwarder
            .execute_worker_remove(
                &target.runtime_id,
                &target_key,
                "must retain running Worker",
            )
            .unwrap();
        assert_eq!(running.status, StatusCode::CONFLICT.as_u16());
        assert!(running.body.contains("worker_not_stopped"));
        let stopped = api
            .runtime
            .stop_worker(
                &target,
                WorkerLifecycleRequest {
                    reason: Some("prepare WorkerRemove regression".to_string()),
                    ticket_assignment: None,
                },
            )
            .unwrap();
        assert_eq!(stopped.state, InternalWorkerOperationState::Accepted);
        let worker_root = temp
            .path()
            .join(".test-embedded-runtime-store/workers")
            .join(&target.worker_id);
        fs::create_dir_all(worker_root.join("session/segments")).unwrap();
        fs::write(
            worker_root.join("session/session.json"),
            serde_json::to_vec_pretty(&json!({
                "schema_version": 1,
                "session_id": session_store::new_session_id()
            }))
            .unwrap(),
        )
        .unwrap();
        fs::write(
            worker_root.join("session/segments/segment-a.jsonl"),
            b"retained evidence\n",
        )
        .unwrap();
        let summary = api.runtime.worker(&target).unwrap();
        sync_worker_observation(&api, &summary).unwrap();

        let mut subscriber = api.worker_projection.subscribe_ordered(10).unwrap();
        let _ = subscriber.take_snapshot();

        let handle = WorkspaceWorker::resolve(&api, &target.runtime_id, &target_key).unwrap();
        handle
            .set_pinned(&WorkerOperationContext::Backend, true)
            .await
            .unwrap();
        let pinned = forwarder
            .execute_worker_remove(&target.runtime_id, &target_key, "must retain pinned Worker")
            .unwrap();
        assert_eq!(pinned.status, StatusCode::CONFLICT.as_u16());
        assert!(pinned.body.contains("worker_removal_blocked"));
        handle
            .set_pinned(&WorkerOperationContext::Backend, false)
            .await
            .unwrap();

        // A resource key must be normalized by common reception after its exact
        // target-bound proof is verified; the old raw service executor cannot do this.
        let response = forwarder
            .execute_worker_remove(&target.runtime_id, &target_key, "retire completed Worker")
            .unwrap();
        assert_eq!(
            response.status,
            StatusCode::OK.as_u16(),
            "{}",
            response.body
        );
        assert!(response.body.contains("\"removed\":true"));
        assert!(!response.body.contains("disposition"));
        assert!(!response.body.contains("stage"));
        assert!(!response.body.contains("path"));
        assert!(
            api.store
                .get_worker_registry(TEST_WORKSPACE_ID, &target)
                .unwrap()
                .is_none()
        );
        tokio::time::timeout(std::time::Duration::from_secs(1), async {
            loop {
                let event = subscriber.recv().await.expect("projection event");
                if event.changes.iter().any(|change| {
                    matches!(change, crate::store::WorkerCatalogChange::Removed(worker) if worker == &target)
                }) {
                    return event;
                }
            }
        })
        .await
        .expect("WorkerRemove catalog removal broadcast");
    }

    #[tokio::test]
    async fn published_spawn_compensation_uses_catalog_removal_commit() {
        let temp = tempfile::tempdir().unwrap();
        let api = test_api(temp.path()).await;
        let spawned = api
            .spawn_workspace_worker(
                EMBEDDED_WORKER_RUNTIME_ID,
                WorkerSpawnRequest {
                    intent: WorkerSpawnIntent::WorkspaceCompanion,
                    requested_worker_name: Some("compensation-target".to_string()),
                    singleton_key: None,
                    acceptance: WorkerSpawnAcceptanceRequirement::RunAccepted {
                        expected_segments: 0,
                    },
                    profile: worker_runtime::catalog::ProfileSelector::Builtin(
                        "builtin:companion".to_string(),
                    ),
                    ticket_assignment: None,
                    initial_submit: Vec::new(),
                    workdir_attachment_requests: Vec::new(),
                    resolved_workdir_attachment_requests: Vec::new(),
                    resolved_workdir_attachments: Vec::new(),
                    resolved_config_bundle: Some(runtime_test_bundle()),
                    resolved_worker_observation_enabled: false,
                    resolved_worker_observation_grants: Vec::new(),
                    resolved_workspace_api: None,
                    resolved_memory_settings: None,
                    resolved_subjektiv_attached: false,
                    resolved_control_operation: None,
                    resolved_execution_grant: None,
                },
            )
            .unwrap();
        let worker = spawned.worker.unwrap().worker;
        let summary = api.runtime.worker(&worker).unwrap();
        sync_worker_observation(&api, &summary).unwrap();
        let mut subscriber = api.worker_projection.subscribe_ordered(10).unwrap();
        let _ = subscriber.take_snapshot();
        let diagnostics = compensate_failed_worker_spawn(
            &api,
            &summary,
            &WorkerSpawnCompensationContext {
                assignment: None,
                spawned_workdir_ids: &[],
            },
        );
        assert!(diagnostics.is_empty(), "{diagnostics:?}");
        assert!(
            api.store
                .get_worker_registry(TEST_WORKSPACE_ID, &worker)
                .unwrap()
                .is_none()
        );
        tokio::time::timeout(std::time::Duration::from_secs(1), async {
            loop {
                let event = subscriber.recv().await.expect("projection event");
                if event.changes.iter().any(|change| {
                    matches!(change, crate::store::WorkerCatalogChange::Removed(removed) if removed == &worker)
                }) {
                    return event;
                }
            }
        })
        .await
        .expect("spawn compensation catalog removal broadcast");
        sync_worker_observation(&api, &summary).unwrap();
        assert!(
            api.store
                .get_worker_registry(TEST_WORKSPACE_ID, &worker)
                .unwrap()
                .is_none(),
            "a late pre-compensation observation must not clear the removal fence"
        );
    }

    #[tokio::test]
    async fn remote_worker_remove_proof_requires_current_runtime_trust_scope_and_catalog_member() {
        let temp = tempfile::tempdir().unwrap();
        let identity = RuntimeIdentityMaterial::generate("runtime-remote").unwrap();
        let mut config = test_server_config(temp.path());
        config.backend_base_url = Some("server-main".to_owned());
        config.remote_runtime_sources.push(RemoteRuntimeConfig {
            runtime_id: "runtime-remote".to_string(),
            workspace_id: Some(TEST_WORKSPACE_ID.to_string()),
            display_name: "Remote Runtime".to_string(),
            base_url: "https://runtime.invalid".to_string(),
            bearer_token: None,
            workspace_authorization: None,
            strict_public_egress: false,
            cached_worker_creation_available: true,
            cached_os: "test".to_string(),
            cached_arch: "test".to_string(),
            cached_status: "connected".to_string(),
            timeout: std::time::Duration::from_secs(1),
        });
        let store = SqliteWorkspaceStore::open_for_test(config.database_path.clone()).unwrap();
        let owner_account_id = format!("account-{TEST_WORKSPACE_ID}");
        store
            .upsert_account(&crate::store::AccountRecord {
                account_id: owner_account_id.clone(),
                kind: "user".to_string(),
                handle: format!("owner-{TEST_WORKSPACE_ID}"),
                display_name: "Workspace Owner".to_string(),
                created_at: "2026-08-11T00:00:00Z".to_string(),
                updated_at: "2026-08-11T00:00:00Z".to_string(),
            })
            .unwrap();
        store
            .upsert_workspace(&WorkspaceRecord {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
                owner_account_id,
                display_name: "Test Workspace".to_string(),
                state: "active".to_string(),
                created_at: "2026-08-11T00:00:00Z".to_string(),
                updated_at: "2026-08-11T00:00:00Z".to_string(),
            })
            .await
            .unwrap();
        let trust = crate::store::WorkspaceRuntimeBinding {
            workspace_id: TEST_WORKSPACE_ID.to_string(),
            runtime_id: "runtime-remote".to_string(),
            display_name: "Remote Runtime".to_string(),
            base_url: "https://runtime.invalid".to_string(),
            public_key: identity.public_key.clone(),
            public_key_fingerprint: String::new(),
            binding_id: "binding-test".to_string(),
            authentication_mode: StoredRuntimeAuthenticationMode::LegacyServerIssuer,
            created_at: "2026-08-11T00:00:00Z".to_string(),
            updated_at: "2026-08-11T00:00:00Z".to_string(),
            revoked_at: None,
        };
        store
            .upsert_workspace_runtime_binding(trust.clone(), false)
            .unwrap();
        let api = WorkspaceApi::new_with_execution_backend(
            config,
            Arc::new(store),
            Arc::new(DeterministicExecutionBackend::default()),
        )
        .await
        .unwrap();
        seed_worker_source_member(&api, "runtime-remote", "7");

        let signer = RuntimeWorkerMutationSourceSigner::from_identity(&identity);
        let token = signer
            .issue_worker_remove(
                "server-main",
                &api.config.workspace_id,
                "7",
                "runtime-target",
                "target-worker",
                60,
            )
            .unwrap();
        let verified = crate::worker_source::verify_worker_remove_source(
            &api,
            crate::worker_source::PresentedWorkerMutationSourceProof::Remote(&token),
            "runtime-target",
            "target-worker",
        )
        .await
        .unwrap();
        assert_eq!(verified.runtime_id, "runtime-remote");
        assert_eq!(verified.worker_id, "7");

        let wrong_scope = signer
            .issue_worker_remove(
                "server-wrong",
                &api.config.workspace_id,
                "7",
                "runtime-target",
                "target-worker",
                60,
            )
            .unwrap();
        assert!(matches!(
            crate::worker_source::verify_worker_remove_source(
                &api,
                crate::worker_source::PresentedWorkerMutationSourceProof::Remote(&wrong_scope),
                "runtime-target",
                "target-worker",
            )
            .await,
            Err(crate::worker_source::WorkerMutationSourceProofError::WrongAudience)
        ));

        let wrong_workspace = signer
            .issue_worker_remove(
                "server-main",
                "workspace-other",
                "7",
                "runtime-target",
                "target-worker",
                60,
            )
            .unwrap();
        assert!(matches!(
            crate::worker_source::verify_worker_remove_source(
                &api,
                crate::worker_source::PresentedWorkerMutationSourceProof::Remote(&wrong_workspace),
                "runtime-target",
                "target-worker",
            )
            .await,
            Err(crate::worker_source::WorkerMutationSourceProofError::WrongWorkspace)
        ));

        let missing_worker = signer
            .issue_worker_remove(
                "server-main",
                &api.config.workspace_id,
                "999",
                "runtime-target",
                "target-worker",
                60,
            )
            .unwrap();
        assert!(matches!(
            crate::worker_source::verify_worker_remove_source(
                &api,
                crate::worker_source::PresentedWorkerMutationSourceProof::Remote(&missing_worker),
                "runtime-target",
                "target-worker",
            )
            .await,
            Err(crate::worker_source::WorkerMutationSourceProofError::WorkerCatalogMembership)
        ));

        let mut expired_claims = decode_worker_mutation_source_claims(&token).unwrap();
        expired_claims.iat = 1;
        expired_claims.exp = 2;
        expired_claims.jti = "expired-proof".to_string();
        let expired = signer.sign(&expired_claims).unwrap();
        assert!(matches!(
            crate::worker_source::verify_worker_remove_source(
                &api,
                crate::worker_source::PresentedWorkerMutationSourceProof::Remote(&expired),
                "runtime-target",
                "target-worker",
            )
            .await,
            Err(crate::worker_source::WorkerMutationSourceProofError::Expired)
        ));

        let route_token = signer
            .issue_worker_remove(
                "server-main",
                &api.config.workspace_id,
                "7",
                "runtime-target",
                "target-worker",
                60,
            )
            .unwrap();
        let route_response = build_inner_router(api.clone())
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri(format!("/api/w/{TEST_WORKSPACE_ID}/workers/remove"))
                    .header(CONTENT_TYPE, "application/json")
                    .header(
                        worker_runtime::auth::WORKER_MUTATION_SOURCE_PROOF_HEADER,
                        route_token,
                    )
                    .body(Body::from(
                        r#"{"target_runtime_id":"runtime-target","target_worker_id":"target-worker","reason":"retire target Worker"}"#,
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(route_response.status(), StatusCode::NOT_FOUND);
        let route_body = axum::body::to_bytes(route_response.into_body(), usize::MAX)
            .await
            .unwrap();
        let route_body = String::from_utf8(route_body.to_vec()).unwrap();
        assert!(route_body.contains("unknown_worker"));
        assert!(!route_body.contains("source"));
        assert!(!route_body.contains("proof"));

        let outer_path = format!("/api/w/{TEST_WORKSPACE_ID}/workers/remove");
        let outer_request_body = r#"{"target_runtime_id":"runtime-target","target_worker_id":"target-worker","reason":"retire target Worker"}"#;
        let outer_mutation_token = signer
            .issue_worker_remove(
                "server-main",
                &api.config.workspace_id,
                "7",
                "runtime-target",
                "target-worker",
                60,
            )
            .unwrap();
        let outer_request_token =
            worker_runtime::auth::RuntimeRequestSourceSigner::from_identity(&identity)
                .issue(
                    "server-main",
                    &api.config.workspace_id,
                    Some("7"),
                    worker_runtime::auth::WORKSPACE_REQUEST_PERMISSION,
                    "POST",
                    &outer_path,
                    outer_request_body.as_bytes(),
                    i64::try_from(worker_runtime::auth::unix_now_seconds()).unwrap_or(i64::MAX),
                    30,
                )
                .unwrap();
        let outer_response = build_router(api.clone())
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri(&outer_path)
                    .header(CONTENT_TYPE, "application/json")
                    .header(
                        worker_runtime::auth::RUNTIME_REQUEST_SOURCE_PROOF_HEADER,
                        outer_request_token,
                    )
                    .header(
                        worker_runtime::auth::WORKER_MUTATION_SOURCE_PROOF_HEADER,
                        outer_mutation_token,
                    )
                    .body(Body::from(outer_request_body))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(outer_response.status(), StatusCode::NOT_FOUND);
        let outer_response_body = axum::body::to_bytes(outer_response.into_body(), usize::MAX)
            .await
            .unwrap();
        assert!(
            String::from_utf8(outer_response_body.to_vec())
                .unwrap()
                .contains("unknown_worker")
        );

        let missing_outer_mutation_token = signer
            .issue_worker_remove(
                "server-main",
                &api.config.workspace_id,
                "7",
                "runtime-target",
                "target-worker",
                60,
            )
            .unwrap();
        let missing_outer_response = build_router(api.clone())
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri(&outer_path)
                    .header(CONTENT_TYPE, "application/json")
                    .header(
                        worker_runtime::auth::WORKER_MUTATION_SOURCE_PROOF_HEADER,
                        missing_outer_mutation_token,
                    )
                    .body(Body::from(outer_request_body))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(missing_outer_response.status(), StatusCode::UNAUTHORIZED);

        let missing_mutation_request_token =
            worker_runtime::auth::RuntimeRequestSourceSigner::from_identity(&identity)
                .issue(
                    "server-main",
                    &api.config.workspace_id,
                    Some("7"),
                    worker_runtime::auth::WORKSPACE_REQUEST_PERMISSION,
                    "POST",
                    &outer_path,
                    outer_request_body.as_bytes(),
                    i64::try_from(worker_runtime::auth::unix_now_seconds()).unwrap_or(i64::MAX),
                    30,
                )
                .unwrap();
        let missing_mutation_response = build_router(api.clone())
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri(&outer_path)
                    .header(CONTENT_TYPE, "application/json")
                    .header(
                        worker_runtime::auth::RUNTIME_REQUEST_SOURCE_PROOF_HEADER,
                        missing_mutation_request_token,
                    )
                    .body(Body::from(outer_request_body))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(missing_mutation_response.status(), StatusCode::UNAUTHORIZED);

        let mut revoked = trust;
        revoked.revoked_at = Some("2026-08-11T00:01:00Z".to_string());
        let authority =
            SqliteWorkspaceStore::open_for_test(api.config.database_path.clone()).unwrap();
        authority
            .upsert_workspace_runtime_binding(revoked, true)
            .unwrap();
        let revoked_token = signer
            .issue_worker_remove(
                "server-main",
                &api.config.workspace_id,
                "7",
                "runtime-target",
                "target-worker",
                60,
            )
            .unwrap();
        let revoked_result = crate::worker_source::verify_worker_remove_source(
            &api,
            crate::worker_source::PresentedWorkerMutationSourceProof::Remote(&revoked_token),
            "runtime-target",
            "target-worker",
        )
        .await;
        assert!(
            matches!(
                revoked_result,
                Err(crate::worker_source::WorkerMutationSourceProofError::RevokedRuntimeTrust)
            ),
            "unexpected revoked trust result: {revoked_result:?}"
        );
    }

