    #[tokio::test]
    async fn provider_not_found_observation_is_retained_until_durable_removal_commits() {
        let workspace = tempfile::tempdir().unwrap();
        init_clean_git_workspace(workspace.path());
        let api = test_api(workspace.path()).await;
        seed_cleanup_workdir(&api, "deleted-workdir", "present", "clean");
        let deleted = api
            .store
            .get_workdir_registry(TEST_WORKSPACE_ID, "deleted-workdir")
            .unwrap()
            .unwrap();

        persist_workdir_runtime_miss(
            &api,
            deleted,
            &[RuntimeDiagnostic {
                code: "working_directory_not_found".to_string(),
                severity: HostDiagnosticSeverity::Warning,
                message: "missing".to_string(),
            }],
        )
        .unwrap();

        assert_eq!(
            api.store
                .get_workdir_registry(TEST_WORKSPACE_ID, "deleted-workdir")
                .unwrap()
                .unwrap()
                .materialization_status,
            "not_found"
        );

        seed_cleanup_workdir(&api, "unknown-workdir", "present", "clean");
        let unknown = api
            .store
            .get_workdir_registry(TEST_WORKSPACE_ID, "unknown-workdir")
            .unwrap()
            .unwrap();
        persist_workdir_runtime_miss(
            &api,
            unknown,
            &[RuntimeDiagnostic {
                code: "runtime_unavailable".to_string(),
                severity: HostDiagnosticSeverity::Warning,
                message: "temporarily unavailable".to_string(),
            }],
        )
        .unwrap();
        assert_eq!(
            api.store
                .get_workdir_registry(TEST_WORKSPACE_ID, "unknown-workdir")
                .unwrap()
                .unwrap()
                .materialization_status,
            "unknown"
        );
    }

