    #[tokio::test]
    async fn cleanup_plan_reports_pinned_running_dirty_not_found_and_redacts_paths() {
        let workspace = tempfile::tempdir().unwrap();
        init_clean_git_workspace(workspace.path());
        let api = test_api(workspace.path()).await;
        let pinned = seed_cleanup_worker(&api, 1, "pinned");
        let unobserved = seed_cleanup_worker(&api, 2, "normal");
        seed_cleanup_workdir(&api, "workdir-dirty", "present", "dirty");
        seed_cleanup_workdir(&api, "workdir-not-found", "not_found", "clean");
        seed_cleanup_link(&api, pinned.as_str(), "workdir-dirty");
        seed_cleanup_link(&api, unobserved.as_str(), "workdir-not-found");

        let plan = build_runtime_cleanup_plan(&api, "runtime-test")
            .unwrap_or_else(|err| panic!("cleanup plan: {}", err.error));
        let pinned_worker = plan
            .workers
            .iter()
            .find(|candidate| candidate.worker_id == pinned)
            .unwrap();
        assert!(pinned_worker.pinned);
        assert_eq!(
            pinned_worker.blocking_reason.as_deref(),
            Some("worker is pinned")
        );
        let running_linked_workdir = plan
            .workdirs
            .iter()
            .find(|candidate| candidate.workdir_id == "workdir-not-found")
            .unwrap();
        assert_eq!(
            running_linked_workdir.file_status,
            CleanupWorkdirFileStatus::NotFound
        );
        assert_eq!(
            running_linked_workdir.action,
            CleanupTargetKind::WorkdirRecordDelete
        );
        assert!(!running_linked_workdir.running_linked);
        assert_eq!(running_linked_workdir.blocking_reason.as_deref(), None);
        let dirty_workdir = plan
            .workdirs
            .iter()
            .find(|candidate| candidate.workdir_id == "workdir-dirty")
            .unwrap();
        assert_eq!(dirty_workdir.action, CleanupTargetKind::WorkdirDirtyDiscard);
        assert!(dirty_workdir.pinned_linked);
        let serialized = serde_json::to_string(&plan).unwrap();
        assert!(!serialized.contains("/tmp/secret-runtime-path"));
    }

    #[tokio::test]
    async fn cleanup_execution_rejects_stale_plan_and_pinned_worker_delete() {
        let workspace = tempfile::tempdir().unwrap();
        init_clean_git_workspace(workspace.path());
        let api = test_api(workspace.path()).await;
        let worker = seed_cleanup_worker(&api, 1, "pinned");
        let plan = build_runtime_cleanup_plan(&api, "runtime-test")
            .unwrap_or_else(|err| panic!("cleanup plan: {}", err.error));
        let target = plan
            .workers
            .iter()
            .find(|candidate| candidate.worker_id == worker)
            .unwrap()
            .target_id
            .clone();
        // Change the candidate set after preview, without changing the requested target.
        seed_cleanup_worker(&api, 2, "normal");
        let stale = ExecuteRuntimeCleanupRequest {
            expected_plan_digest: plan.digest.clone(),
            worker_target_ids: vec![target.clone()],
            workdir_target_ids: Vec::new(),
            confirm_dirty_discard_target_ids: Vec::new(),
        };
        let error = execute_runtime_cleanup(&api, "runtime-test", stale)
            .await
            .err()
            .expect("changed candidates must reject the old preview");
        assert!(
            matches!(error.error, Error::RuntimeOperationFailed { code, .. } if code == "workspace_cleanup_plan_stale")
        );

        let refreshed = build_runtime_cleanup_plan(&api, "runtime-test").unwrap();
        assert_ne!(plan.digest, refreshed.digest);
        let pinned = ExecuteRuntimeCleanupRequest {
            expected_plan_digest: refreshed.digest,
            worker_target_ids: vec![target],
            workdir_target_ids: Vec::new(),
            confirm_dirty_discard_target_ids: Vec::new(),
        };
        let error = execute_runtime_cleanup(&api, "runtime-test", pinned)
            .await
            .err()
            .expect("current preview must still enforce target protection");
        assert!(
            matches!(error.error, Error::RuntimeOperationFailed { code, .. } if code == "workspace_cleanup_worker_blocked")
        );
    }

    #[tokio::test]
    async fn cleanup_service_deletes_stopped_singleton_worker() {
        let workspace = tempfile::tempdir().unwrap();
        init_clean_git_workspace(workspace.path());
        let api = test_api(workspace.path()).await;
        let Json(orchestrator) = scoped_start_workspace_orchestrator(
            State(api.clone()),
            AxumPath(ScopedWorkspacePath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
            }),
        )
        .await
        .unwrap();
        let worker = orchestrator.worker.unwrap();
        let worker = RuntimeWorkerRef::new(worker.runtime_id, worker.worker_id);
        let mut stop_events = api.worker_projection.subscribe_ordered(10).unwrap();
        let _ = stop_events.take_snapshot();
        api.runtime
            .stop_worker(
                &worker,
                WorkerLifecycleRequest {
                    reason: Some("prepare singleton cleanup".to_string()),
                    ticket_assignment: None,
                },
            )
            .unwrap();
        // A synchronous Runtime stop no longer implies that its queued SQL
        // projection was published. Observe stopped before taking the removal
        // baseline, rather than mistaking its Upsert for the atomic removal.
        tokio::time::timeout(std::time::Duration::from_secs(5), async {
            loop {
                let event = stop_events.recv().await.unwrap();
                if event.changes.iter().any(|change| matches!(
                    change,
                    crate::store::WorkerCatalogChange::Upsert(record)
                        if record.registry.worker == worker
                            && record.observation.as_ref().is_some_and(|observation|
                                observation.worker.state == protocol::subscription::SubscriptionWorkerState::Stopped)
                )) {
                    break;
                }
            }
        })
        .await
        .expect("stopped Runtime observation must commit before removal baseline");
        let worker_root = workspace
            .path()
            .join(".test-embedded-runtime-store/workers")
            .join(&worker.worker_id);
        fs::create_dir_all(worker_root.join("session/segments")).unwrap();
        fs::write(
            worker_root.join("session/session.json"),
            serde_json::to_vec_pretty(&json!({
                "schema_version": 1,
                "session_id": session_store::new_session_id()
            }))
            .unwrap(),
        )
        .unwrap();
        fs::write(
            worker_root.join("session/segments/segment-a.jsonl"),
            b"singleton cleanup retention evidence\n",
        )
        .unwrap();
        let plan = build_runtime_cleanup_plan(&api, worker.runtime_id.as_str())
            .unwrap_or_else(|error| panic!("cleanup plan: {}", error.error));
        let candidate = plan
            .workers
            .iter()
            .find(|candidate| candidate.runtime_worker_id == worker.worker_id)
            .expect("singleton Worker cleanup candidate")
            .clone();
        assert_eq!(candidate.blocking_reason, None);
        let mut subscriber = api.worker_projection.subscribe_ordered(10).unwrap();
        let _ = subscriber.take_snapshot();

        WorkerRemovalService::new(&api)
            .execute_cleanup_removal(&candidate)
            .await
            .unwrap();

        assert!(api.runtime.worker(&worker).is_err());
        assert!(
            api.store
                .get_worker_registry(TEST_WORKSPACE_ID, &worker)
                .unwrap()
                .is_none()
        );
        let event = subscriber.try_recv().expect("singleton catalog removal");
        assert!(matches!(
            event.changes.as_slice(),
            [crate::store::WorkerCatalogChange::Removed(removed)] if removed == &worker
        ));

        let Json(recreated) = scoped_start_workspace_orchestrator(
            State(api.clone()),
            AxumPath(ScopedWorkspacePath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
            }),
        )
        .await
        .unwrap();
        let recreated = recreated.worker.expect("recreated Orchestrator");
        assert_ne!(recreated.worker_id, worker.worker_id);
    }

    #[tokio::test]
    async fn cleanup_http_entry_publishes_atomic_catalog_removal_without_runtime_event() {
        let workspace = tempfile::tempdir().unwrap();
        init_clean_git_workspace(workspace.path());
        let api = test_api(workspace.path()).await;
        let spawned = api
            .spawn_workspace_worker(
                EMBEDDED_WORKER_RUNTIME_ID,
                WorkerSpawnRequest {
                    intent: WorkerSpawnIntent::WorkspaceCompanion,
                    requested_worker_name: Some("cleanup-projection-target".to_string()),
                    singleton_key: None,
                    acceptance: WorkerSpawnAcceptanceRequirement::RunAccepted {
                        expected_segments: 0,
                    },
                    profile: worker_runtime::catalog::ProfileSelector::Builtin(
                        "builtin:companion".to_string(),
                    ),
                    ticket_assignment: None,
                    initial_submit: Vec::new(),
                    workdir_attachment_requests: Vec::new(),
                    resolved_workdir_attachment_requests: Vec::new(),
                    resolved_workdir_attachments: Vec::new(),
                    resolved_config_bundle: Some(runtime_test_bundle()),
                    resolved_worker_observation_enabled: false,
                    resolved_worker_observation_grants: Vec::new(),
                    resolved_workspace_api: None,
                    resolved_memory_settings: None,
                    resolved_subjektiv_attached: false,
                    resolved_control_operation: None,
                    resolved_execution_grant: None,
                },
            )
            .unwrap();
        let worker = spawned.worker.unwrap().worker;
        let stopped = api
            .runtime
            .stop_worker(
                &worker,
                WorkerLifecycleRequest {
                    reason: Some("prepare cleanup projection regression".to_string()),
                    ticket_assignment: None,
                },
            )
            .unwrap();
        assert_eq!(stopped.state, InternalWorkerOperationState::Accepted);
        let worker_root = workspace
            .path()
            .join(".test-embedded-runtime-store/workers")
            .join(&worker.worker_id);
        fs::create_dir_all(worker_root.join("session/segments")).unwrap();
        fs::write(
            worker_root.join("session/session.json"),
            serde_json::to_vec_pretty(&json!({
                "schema_version": 1,
                "session_id": session_store::new_session_id()
            }))
            .unwrap(),
        )
        .unwrap();
        fs::write(
            worker_root.join("session/segments/segment-a.jsonl"),
            b"cleanup retention evidence\n",
        )
        .unwrap();
        let summary = api.runtime.worker(&worker).unwrap();
        sync_worker_observation(&api, &summary).unwrap();
        // Deliberately drop Runtime observation delivery: catalog removal itself
        // must drive every connected Workspace subscription.
        api.worker_projection.shutdown();
        let worker_id = worker.worker_id.clone();
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let address = listener.local_addr().unwrap();
        let app = build_inner_router(api.clone()).layer(Extension(test_browser_request_actor()));
        let server = tokio::spawn(async move {
            let _ = axum::serve(listener, app).await;
        });
        let subscription_url = format!("ws://{address}/api/w/{TEST_WORKSPACE_ID}/protocol/ws");
        let (mut acting_socket, _) = connect_async(subscription_url.as_str()).await.unwrap();
        let (mut observing_socket, _) = connect_async(subscription_url.as_str()).await.unwrap();
        let acting_snapshot =
            subscribe_workspace_worker_snapshot(&mut acting_socket, "cleanup-acting").await;
        let observing_snapshot =
            subscribe_workspace_worker_snapshot(&mut observing_socket, "cleanup-observing").await;
        assert!(
            acting_snapshot
                .iter()
                .any(|item| item.worker_id.as_str() == worker_id)
        );
        assert!(
            observing_snapshot
                .iter()
                .any(|item| item.worker_id.as_str() == worker_id)
        );
        let mut subscriber = api.worker_projection.subscribe_ordered(10).unwrap();
        let _ = subscriber.take_snapshot();
        let plan = build_runtime_cleanup_plan(&api, EMBEDDED_WORKER_RUNTIME_ID)
            .unwrap_or_else(|error| panic!("cleanup plan: {}", error.error));
        let candidate = plan
            .workers
            .iter()
            .find(|candidate| candidate.worker_id == worker_id)
            .unwrap();
        let request = ExecuteRuntimeCleanupRequest {
            expected_plan_digest: plan.digest,
            worker_target_ids: vec![candidate.target_id.clone()],
            workdir_target_ids: Vec::new(),
            confirm_dirty_discard_target_ids: Vec::new(),
        };

        let Json(response) = scoped_execute_runtime_cleanup(
            State(api.clone()),
            AxumPath(ScopedRuntimePath {
                workspace_id: TEST_WORKSPACE_ID.to_string(),
                runtime_id: EMBEDDED_WORKER_RUNTIME_ID.to_string(),
            }),
            Json(request),
        )
        .await
        .unwrap();
        assert_eq!(response.results[0].status, "deleted");

        let event = tokio::time::timeout(std::time::Duration::from_secs(1), async {
            loop {
                let event = subscriber.recv().await.expect("projection event");
                if event.changes.iter().any(|change| {
                    matches!(change, crate::store::WorkerCatalogChange::Removed(removed) if removed == &worker)
                }) {
                    return event;
                }
            }
        })
        .await
        .expect("catalog removal broadcast");
        assert!(matches!(
            event.changes.as_slice(),
            [crate::store::WorkerCatalogChange::Removed(removed)] if removed == &worker
        ));
        tokio::time::timeout(
            std::time::Duration::from_secs(1),
            next_workspace_worker_removal(&mut acting_socket, worker_id.as_str()),
        )
        .await
        .expect("acting Workspace Worker subscription removal");
        tokio::time::timeout(
            std::time::Duration::from_secs(1),
            next_workspace_worker_removal(&mut observing_socket, worker_id.as_str()),
        )
        .await
        .expect("independent Workspace Worker subscription removal");
        assert!(
            api.store
                .get_worker_registry(&api.config.workspace_id, &worker)
                .unwrap()
                .is_none()
        );
        let recovered = api
            .store
            .recover_worker_removal_execution(&api.config.workspace_id, &worker)
            .unwrap()
            .expect("Browser cleanup uses durable retention removal");
        assert_eq!(
            recovered.plan.state,
            crate::retention::WorkerRemovalPlanState::Succeeded
        );
        let snapshot = api
            .store
            .worker_registry_projection_snapshot(&api.config.workspace_id, 100)
            .unwrap();
        assert!(
            snapshot
                .iter()
                .all(|record| record.registry.worker != worker)
        );
        let rest_workers = workers_response(api.clone()).unwrap();
        assert!(
            rest_workers
                .items
                .iter()
                .all(|item| item.worker_id != worker_id)
        );
        let (mut fresh_socket, _) = connect_async(subscription_url.as_str()).await.unwrap();
        let fresh_snapshot =
            subscribe_workspace_worker_snapshot(&mut fresh_socket, "cleanup-fresh").await;
        assert!(
            fresh_snapshot
                .iter()
                .all(|item| item.worker_id.as_str() != worker_id)
        );

        // A retry replays the durable fence, healing an in-process broadcast
        // omitted after the first DB commit.
        WorkerRemovalService::new(&api)
            .commit_catalog_removal(&worker)
            .unwrap();
        let replay = tokio::time::timeout(std::time::Duration::from_secs(1), subscriber.recv())
            .await
            .expect("catalog removal replay")
            .expect("projection replay");
        assert!(matches!(
            replay.changes.as_slice(),
            [crate::store::WorkerCatalogChange::Removed(removed)] if removed == &worker
        ));
        server.abort();
    }

